insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'GEN', $b$Nau Ntơm$b$, $b$["NAU NTƠM", "Y-Môis Chih"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','GEN',1,1,null,$b$Ntơm sa ơm Brah Ndu rhăk njêng trôk jêh ri neh ntu.$b$,true),
('bunong-vn','GEN',1,2,null,$b$Neh ntu geh lŭk rlăk jêh ri hŏng, jêh ri nau ngo nkŭm ta klơ mpiăt dak jru; jêh ri Brah Huêng Ueh Brah Ndu păn ta klơ mpiăt dak.$b$,false),
('bunong-vn','GEN',1,3,null,$b$Brah Ndu lah: “Ăn geh nau ang;” jêh ri geh ro nau ang.$b$,true),
('bunong-vn','GEN',1,4,null,$b$Brah Ndu saơ nau ang nây jêng ueh; jêh ri Brah Ndu tâm pă nau ang bơh nau ngo.$b$,false),
('bunong-vn','GEN',1,5,null,$b$Brah Ndu rnha “nar” ma nau ang; jêh ri păng rnha “măng” ma nau ngo. Geh mhaơ jêh ri geh ôi, jêng nar tal nguay.$b$,false),
('bunong-vn','GEN',1,6,null,$b$Jêh ri Brah Ndu lah: “Ăn geh ntŭk hŏng ta nklang dak, jêh ri ăn păng tâm pă dak.”$b$,true),
('bunong-vn','GEN',1,7,null,$b$Brah Ndu njêng ntŭk hŏng gay ma tâm pă dak tâm dâng bơh dak klơ ntŭk hŏng. Jêh ri nau nây jêng ro.$b$,true),
('bunong-vn','GEN',1,8,null,$b$Brah Ndu rnha “trôk” ma ntŭk hŏng. Geh mhaơ jêh ri geh ôi jêng nar tal bar.$b$,false),
('bunong-vn','GEN',1,9,null,$b$Brah Ndu lah: “Ăn dak gŭ tâm dâng trôk rgum tâm du ntŭk, jêh ri ăn neh sơh mpơl.” Pô ri nau nây jêng ro.$b$,true),
('bunong-vn','GEN',1,10,null,$b$Brah Ndu rnha “Neh” ma ntŭk sơh; jêh ri păng rnha “dak mƀŭt” ta ntŭk dak tâm rƀŭn. Brah Ndu saơ nau nây jêng ueh.$b$,false),
('bunong-vn','GEN',1,11,null,$b$Jêh ri Brah Ndu lah: “Ăn neh hon gơ̆ nse, trau geh rnih ntil, jêh ri tơm si play, geh ntil tĭng nâm ntil khân păng ta klơ neh”. Pô ri nau nây jêng ro.$b$,false),
('bunong-vn','GEN',1,12,null,$b$Neh hon gơ̆ nse, trau geh ntil tĭng nâm ntil khân păng. Brah Ndu saơ nau nây jêng ueh.$b$,false),
('bunong-vn','GEN',1,13,null,$b$Geh mhaơ jêh ri geh ôi, jêng nar tal pe.$b$,false),
('bunong-vn','GEN',1,14,null,$b$Brah Ndu lah: “Ăn geh rplay nau ang ta ntŭk hŏng tâm trôk, gay tâm pă nar bơh măng; ăn khân păng jêng ndơ dŏng tâm mpơl nau mbên, yăn, nar jêh ri năm.$b$,true),
('bunong-vn','GEN',1,15,null,$b$Nđâp ma ăn khân păng jêng rplay ang ta ntŭk hŏng tâm trôk gay ma sol neh ntu.” Pô ri nau nây jêng ro.$b$,true),
('bunong-vn','GEN',1,16,null,$b$Brah Ndu njêng bar rplay ang toyh, rplay ang toyh lơn chiă tâm nôk nar, rplay ang jê̆ lơn chiă dôl măng. Păng njêng nđâp lĕ rngôch mănh.$b$,false),
('bunong-vn','GEN',1,17,null,$b$Brah Ndu dơm khân păng tâm ntŭk tâm trôk prăp sol ang neh ntu,$b$,false),
('bunong-vn','GEN',1,18,null,$b$gay chiă dôl nôk nar jêh ri măng, jêh ri tâm pă nau ang bơh nau ngo. Brah Ndu saơ nau nây jêng ueh.$b$,false),
('bunong-vn','GEN',1,19,null,$b$Geh mhaơ jêh ri geh ôi, jêng nar tal puăn.$b$,true),
('bunong-vn','GEN',1,20,null,$b$Brah Ndu lah: “Ăn dak geh âk ndơ rêh jêh ri geh sĭm mpăr ta klơ neh ntu tâm ntŭk hŏng tâm trôk.”$b$,true),
('bunong-vn','GEN',1,21,null,$b$Pô ri Brah Ndu rhăk njêng ka toyh jêh ri lĕ rngôch ndơ rêh mpât nsong tâm dak bĭk rơ̆ tĭng nâm ntil khân păng. Brah Ndu saơ nau nây jêng ueh.$b$,false),
('bunong-vn','GEN',1,22,null,$b$Brah Ndu mât ton ma khân păng, lah: “Ăn lĕ rngôch deh kon ăn âk ăn bĭk, ăn bêng dak mƀŭt, jêh ri ăn sĭm ăn bĭk ta neh ntu.”$b$,false),
('bunong-vn','GEN',1,23,null,$b$Geh mhaơ jêh ri geh ôi, jêng nar tal prăm.$b$,false),
('bunong-vn','GEN',1,24,null,$b$Brah Ndu lah: “Ăn neh ntu geh mpa rêh tĭng nâm ntil khân păng.” Pô ri, nau nây jêng ro.$b$,false),
('bunong-vn','GEN',1,25,null,$b$Brah Ndu njêng mpa bri ta neh ntu tĭng nâm ntil khân păng, jêh ri mpô mpa rong tĭng nâm ntil khân păng, jêh ri lĕ rngôch mpô mpa vơr ta neh tĭng nâm ntil khân păng. Brah Ndu saơ nau nây jêng ueh.$b$,false),
('bunong-vn','GEN',1,26,null,$b$Dôl nây Brah Ndu lah: “Ăn he njêng bunuyh tĭng nâm rup he, tâm ban ma he nơm; jêh ri ăn khân păng chiă uănh ka tâm dak mƀŭt, sĭm ta klơ trôk, mpô mpa rong lam bri neh, jêh ri lĕ rngôch mpa vơr ta neh ntu.”$b$,true),
('bunong-vn','GEN',1,27,null,$b$Pô ri Brah Ndu rhăk njêng bunuyh tĭng nâm rup păng nơm; păng njêng kơt nâm rup Brah Ndu nơm. Păng njêng bu ur bu klâu.$b$,true),
('bunong-vn','GEN',1,28,null,$b$Brah Ndu mât ton nau ueh uĭn ma khân păng, jêh ri lah: “Khân ay may geh kon ăn bĭk ăn rơ̆ , ăn bêng neh ntu, jêh ri ăn khân ay may jêng Kôranh ma neh ntu; ăn khân ay may chiă uănh ka tâm dak mƀŭt, sĭm ta klơ trôk, jêh ri lĕ rngôch mpô mpa rêh nsong, mpât ta neh ntu.”$b$,false),
('bunong-vn','GEN',1,29,null,$b$Brah Ndu lah: “Aơ, gâp ăn jêh ma ay may lam bri neh lĕ rngôch trau geh ntil jêh ri lĕ rngôch tơm si geh play ma ntil, ndơ nây mra jêng ndơ khân may sông sa.$b$,false),
('bunong-vn','GEN',1,30,null,$b$Ma lĕ rngôch mpô mpa ta neh ntu, ma lĕ sĭm tâm trôk, ma lĕ rngôch mpô mpa vơr ta klơ neh ntu, ma lĕ mpa geh suh n'hâm nau rêh, gâp ăn jêh lĕ rngôch trau rêh nse jêng ndơ khân păng sa.” Pô ri nau nây jêng ro.$b$,false),
('bunong-vn','GEN',1,31,null,$b$Brah Ndu saơ lĕ rngôch ndơ păng njêng jêh, jêh ri aơ, khân păng jêng ueh ngăn. Geh mhaơ jêh ri geh ôi jêng nar tal prao.$b$,false),
('bunong-vn','GEN',2,1,null,$b$Pô nây yơh kan rhăk njêng trôk jêh ri neh ntu nđâp ma lĕ rngôch mpa tâm păng lôch jêh.$b$,true),
('bunong-vn','GEN',2,2,null,$b$Ta nar tal pơh Brah Ndu lôch kan păng ƀư jêh, jêh ri păng rlu nar tal pơh bơh lĕ rngôch kan păng ƀư jêh.$b$,false),
('bunong-vn','GEN',2,3,null,$b$Pô ri Brah Ndu mât ton nau ueh uĭn ma nar pơh jêh ri prăp nar nây jêng nar kloh ueh, yor lah nar nây jêng nar Brah Ndu rlu bơh lĕ kan păng rhăk njêng.$b$,false),
('bunong-vn','GEN',2,4,null,$b$Aơ nau nkoch bri ma nau rhăk njêng trôk jêh ri neh ntu tơ lah Brah Ndu rhăk njêng khân păng. Dôl tâm rnôk Yêhôva Brah Ndu njêng neh ntu jêh ri trôk,$b$,true),
('bunong-vn','GEN',2,5,null,$b$ê geh ndơ hon ôh tâm bri ta neh ntu, mâu lĕ hŏ geh tơm trau biăp hon yor lah Yêhôva Brah Ndu ê ăn ôh dak mih ta neh ntu, jêh ri mâu hŏ geh bunuyh ƀư lŏ mir ôh.$b$,false),
('bunong-vn','GEN',2,6,null,$b$Ƀiă lah geh dak ngom hao tă bơh neh jêh ri ƀư bĕ lam neh ntu.$b$,false),
('bunong-vn','GEN',2,7,null,$b$Pô ri Yêhôva mon bunuyh ma ndruyh neh; păng khôm n'hâm nau rêh tâm trôm muh păng, jêh ri bunuyh jêng huêng rêh.$b$,false),
('bunong-vn','GEN',2,8,null,$b$Yêhôva Brah Ndu tăm đang trau ta Êđen pa lơ, jêh ri păng dơm ta nây bunuyh păng hŏ mon jêh.$b$,true),
('bunong-vn','GEN',2,9,null,$b$Yêhôva Brah Ndu ăn hon ăp ntil tơm play ueh uănh jêh ri geh play kah. Nđâp tơm si nau rêh ta nklang đang trau jêh ri tơm play gĭt năl nau ueh jêh ri nau mhĭk.$b$,false),
('bunong-vn','GEN',2,10,null,$b$Du n'hor dak krong hoch tă bơh Êđen gay ma ăn bĕ đang play, ntơm bơh nây păng tâm nkhah jêh ri jêng puăn ntŭk n'hor.$b$,false),
('bunong-vn','GEN',2,11,null,$b$Amoh n'hor tal nguay Pisôn n'hor nây hoch jŭm n'gor Havila, ntŭk geh mah.$b$,false),
('bunong-vn','GEN',2,12,null,$b$Mah n'gor nây ueh geh đŏng lŭ khlay bêdêlium jêh ri lŭ khlay ônik.$b$,true),
('bunong-vn','GEN',2,13,null,$b$Amoh n'hor tal bar Gihôn, n'hor nây hoch jŭm n'gor Kus.$b$,false),
('bunong-vn','GEN',2,14,null,$b$Amoh n'hor tal pe Tigris hoch leo pa lơ n'gor Asiri. N'hor tal puăn Ơphrat.$b$,false),
('bunong-vn','GEN',2,15,null,$b$Yêhôva Brah Ndu dơm bu klâu nây tâm đang trau Êđen ăn păng nkra jêh ri chiă uănh.$b$,true),
('bunong-vn','GEN',2,16,null,$b$Yêhôva Brah Ndu ntăm ma bu klâu nây pô aơ: “May dơi sa lĕ rngôch play tâm đang aơ;$b$,false),
('bunong-vn','GEN',2,17,null,$b$ƀiă lah lơi ta may sa ôh play tơm si gĭt năl nau ueh đah nau mhĭk; yor lah tơ lah may sa play nây, may mra khĭt ngăn.”$b$,false),
('bunong-vn','GEN',2,18,null,$b$Jêh ri Yêhôva Brah Ndu lah: “Mâu ueh ôh bu klâu nây gŭ êng; gâp mra njêng an ma păng du huê nơm kơl khư ma păng.”$b$,true),
('bunong-vn','GEN',2,19,null,$b$Pô ri Yêhôva Brah Ndu njêng jêh ma ueh lĕ rngôch mpô mpa tâm bri jêh ri lĕ rngôch sĭm och tâm trôk. Păng njŭn leo mpa nây ta năp bu klâu nây gay gĭt mâm păng mra amoh lĕ rngôch mpô mpa nây. Lĕ rngôch mpa rêh ndjôt prăp amoh khân păng tĭng nâm bu klâu nây hŏ moh jêh.$b$,true),
('bunong-vn','GEN',2,20,null,$b$Bu klâu nây moh an lĕ rngôch mpô mpa rong, sĭm tâm trôk, ƀiă lah bu mâu saơ ôh du huê khư dơi jêng nơm dơi kơl păng.$b$,false),
('bunong-vn','GEN',2,21,null,$b$Pô ri Yêhôva Brah Ndu ăn păng lêt bêch; jêh ri dôl păng bêch, Brah Ndu sŏk du mlâm nting rpaih, jêh ri nsĭr đŏng ma nglay ntŭk sŏk nây.$b$,false),
('bunong-vn','GEN',2,22,null,$b$Ma nting păng sŏk tă bơh bu klâu nây, Yêhôva Brah Ndu njêng du huê bu ur, jêh ri păng njŭn leo ma bu klâu nây.$b$,true),
('bunong-vn','GEN',2,23,null,$b$Jêh ri bu klâu nây lah: “Aƀaơ̆ aơ bunuyh aơ jêng nting bơh nting gâp, jêh ri nglay bơh nglay gâp; bu mra rnha păng ‘bu ur’. Yor lah bu sŏk păng tă bơh bu klâu.”$b$,false),
('bunong-vn','GEN',2,24,null,$b$Yor nây yơh bu klâu mra lơi mbơ̆ me păng, jêh ri mra gŭ ndrel ma ur păng, jêh ri khân păng mra jêng du nglay săk.$b$,true),
('bunong-vn','GEN',2,25,null,$b$Lĕ khân păng bar hê, bu klâu jêh ri ur păng, gŭ rhôk mâu geh nau prêng ôh.$b$,false),
('bunong-vn','GEN',3,1,null,$b$Bêh jêng ƀlăch ƀlêr lơn ma lĕ rngôch mpô mpa bri Yêhôva Brah Ndu njêng jêh. Păng lah ma bu ur: “Ngăn hĕ Brah Ndu lah: ‘Lơi khân ay may sa ôh play lĕ tơm play tâm đang aơ?’ ”$b$,true),
('bunong-vn','GEN',3,2,null,$b$Bu ur lah ma bêh: “Hên dơi sa play bơh lĕ rngôch tơm play tâm đang aơ;$b$,false),
('bunong-vn','GEN',3,3,null,$b$ƀiă lah Brah Ndu lah: ‘Lơi sa ôh play tơm si ta nklang đang trau, mâu lĕ dơi pah play nây, klach lah khân ay may khĭt.’ ”$b$,false),
('bunong-vn','GEN',3,4,null,$b$Ƀiă lah bêh lah ma bu ur, khân ay mâu mra khĭt ngăn ôh,$b$,false),
('bunong-vn','GEN',3,5,null,$b$yor lah Brah Ndu gĭt nar khân ay sa play nây măt khân ay mra lin, jêh ri khân ay mra jêng nâm bu Brah Ndu, gĭt năl nau ueh jêh ri nau mhĭk.”$b$,false),
('bunong-vn','GEN',3,6,null,$b$Pô ri tơ lah bu ur saơ play nây sa kah, ueh măt uănh, khlay dơi ăn nau blau mĭn, păng pĕ play nây jêh ri sa. Jêh ri păng ăn đŏng ma sai păng sa.$b$,false),
('bunong-vn','GEN',3,7,null,$b$Măt lĕ bar hê khân păng lin ro gĭt năl khân păng gŭ rhôk; jêh ri khân păng jĭm n'ha play rvi njêng ndơ nsrom săk jăn.$b$,false),
('bunong-vn','GEN',3,8,null,$b$Khân păng tăng nteh Yêhôva hăn tâm đang trau dôl sial rngân ta mhaơ. Bu klâu jêh ri ur păng du krap ma Yêhôva tâm nklang tơm si tâm đang.$b$,true),
('bunong-vn','GEN',3,9,null,$b$Ƀiă lah Yêhôva Brah Ndu kuăl bu klâu nây jêh ri lah ma păng: “Mbah ntŭk may gŭ?”$b$,false),
('bunong-vn','GEN',3,10,null,$b$Bu klâu nây lah: “Gâp tăng nteh may tâm đang trau, jêh ri gâp klach yor lah gâp gŭ rhôk; pô ri yơh gâp krap,”$b$,false),
('bunong-vn','GEN',3,11,null,$b$Yêhôva Brah Ndu lah: “Mbu mbơh may gŭ rhôk? May mâp sa lĕ play tơm si gâp buay jêh, mâu ăn may sa ôh?”$b$,false),
('bunong-vn','GEN',3,12,null,$b$Bu klâu nây lah: “Bu ur may ăn gŭ ndrel ma gâp, păng yơh ăn ma gâp play nây jêh ri gâp sa.”$b$,true),
('bunong-vn','GEN',3,13,null,$b$Yêhôva Brah Ndu lah ma bu ur: “Moh nau ay ƀư pô nây?” Bu ur lah: “Bêh ndơm gâp, pô ri gâp sa”.$b$,false),
('bunong-vn','GEN',3,14,null,$b$Yêhôva Brah Ndu lah ma bêh: “Yor lah may ƀư jêh pô nây, may geh nau rtăp rak ktang lơn ma lĕ rngôch mpa rong, jêh ri mpô mpa bri; may mra vơr ma ndŭl may, jêh ri mra sa ndruyh neh lĕ nar may gŭ rêh.$b$,false),
('bunong-vn','GEN',3,15,null,$b$Gâp mra njêng nau tâm rlăng may đah bu ur nây, nđâp ma nau tâm rlăng kon sau may đah kon sau păng, păng mra jot sôt bôk may jêh ri may ƀư sôt ndơl jâng păng.”$b$,false),
('bunong-vn','GEN',3,16,null,$b$Păng lah ma bu ur: “Gâp mra n'hao nau ji ay dôl ay ntreo; jêh ri ay mra deh ma nau ji đŏng; ƀiă lah ay ăt mra ŭch ma sai ay, jêh ri păng mra jêng Kôranh ay.”$b$,false),
('bunong-vn','GEN',3,17,null,$b$Jêh ri păng lah ma Y-Ađam: “Yor lah may tông jêh bâr ur may jêh ri sa jêh play tơm si gâp buay, hŏ lah jêh: ‘Lơi may sa ôh play nây.’ ‘Neh geh nau rtăp rak yor may; may mra geh ndơ sông sa tă bơh neh ma nau hŏt rgănh lĕ nar may gŭ rêh.$b$,false),
('bunong-vn','GEN',3,18,null,$b$Neh mra hon tơm lok jêh ri rtau lok ma may, jêh ri may mra sa n'ha trau bri.$b$,true),
('bunong-vn','GEN',3,19,null,$b$May mra sông sa piăng trau may ma dak rhal ta muh măt may tât may plơ̆ sĭt tay ma neh. Yor lah tă bơh neh yơh bu njêng jêh may yor lah may jêng ndruyh neh, jêh ri may mra plơ̆ sĭt tay jêng ndruyh neh.$b$,false),
('bunong-vn','GEN',3,20,null,$b$Bu klâu tâm amoh ur păng H'Êvơ yor lah păng jêng me ma lĕ rngôch bunuyh.$b$,false),
('bunong-vn','GEN',3,21,null,$b$Jêh ri Yêhôva Brah Ndu ƀư an ma Y-Ađam jêh ri ma ur păng ao ntâu, jêh ri sâm nsoh khân păng.$b$,false),
('bunong-vn','GEN',3,22,null,$b$Yêhôva Brah Ndu lah: “Aơ, bunuyh jêng jêh nâm bu he, gĭt năl nau ueh jêh ri nau mhĭk, Aƀaơ aơ klach lah păng yơr ti pĕ play tơm si nau rêh, sa, jêh ri gŭ rêh n'ho ro.”$b$,true),
('bunong-vn','GEN',3,23,null,$b$Yor nây, Yêhôva Brah Ndu mprơh păng bơh đang trau Êđen, gay ma păng pŏk kuai neh, bơh nĕ yơh bu njêng jêh păng.$b$,false),
('bunong-vn','GEN',3,24,null,$b$Yêhôva Brah Ndu mprơh bunuyh nây, jêh ri pa lơ đang trau Êđen păng dơm phung Chêrubim jêh ri đao gưm hit ma mpiăt ŭnh ndăch vĭr ƀa ƀơ gay ma king trong hăn ta tơm play nau rêh.$b$,true),
('bunong-vn','GEN',4,1,null,$b$Y-Ađam gŭ đah ur păng H'Evơ ntreo jêh ri deh ma Y-Kain, jêh ri lah: “Gâp geh jêh du huê bu klâu ma nau Yêhôva kơl.”$b$,true),
('bunong-vn','GEN',4,2,null,$b$Păng deh đŏng ma Y-Abel, oh Y-Kain, Y-Abel jêng rmăk biăp, ƀiă lah Y-Kain jêng bunuyh ƀư mir.$b$,false),
('bunong-vn','GEN',4,3,null,$b$Jŏ djê̆ ma nây Y-Kain njŭn ndơ nhhơr ma Yêhôva play tă bơh neh.$b$,false),
('bunong-vn','GEN',4,4,null,$b$Bi Y-Abel nhhơr ƀa ƀă kon biăp deh bôk rah jêh ri ngi păng, Yêhôva dơn Y-Abel jêh ri ndơ păng nhhơr,$b$,false),
('bunong-vn','GEN',4,5,null,$b$Ƀiă lah Yêhôva mâu dơn ôh Y-Kain jêh ri ndơ păng nhhơr. Y-Kain ji nuih ngăn jêh ri muh măt păng jâk.$b$,false),
('bunong-vn','GEN',4,6,null,$b$Yêhôva lah ma Y-Kain, mâm ƀư may nuih jêh ri muh măt may jâk?$b$,false),
('bunong-vn','GEN',4,7,null,$b$Tơ lah may ƀư ueh, mâu hĕ gâp mra dơn may? Tơ lah may mâu ƀư ueh ôh nau tih mra rmơch nhŭp may. Nau tih ŭch nhŭp may, ƀiă lah ăn may dơi đah păng.”$b$,false),
('bunong-vn','GEN',4,8,null,$b$Y-Kain lah ma oh păng Y-Abel: “Kay he hăn tâm mir”. Jêh ri dôl khân păng gŭ tâm mir, Y-Kain ƀư ma Y-Abel, oh păng jêh ri nkhĭt lơi ô băl.$b$,true),
('bunong-vn','GEN',4,9,null,$b$Jêh ri Yêhôva lah ma Y-Kain: “Mbah oh may Y-Abel?” Y-Kain lah: “Gâp mâu gĭt ôh; di lĕ gâp jêng bunuyh mât mray oh gâp?”$b$,false),
('bunong-vn','GEN',4,10,null,$b$Jêh ri Yêhôva lah: “Moh nau may ƀư jêh?” Mham oh may nter ma gâp tă bơh neh.$b$,false),
('bunong-vn','GEN',4,11,null,$b$Aƀaơ aơ may geh nau rtăp rak jêh tă bơh neh hăk jêh trôm mbung sa mham oh may tă bơh ti may.$b$,false),
('bunong-vn','GEN',4,12,null,$b$Tơ lah may pŏk kuai mir, neh mâu mra geh play âk ôh ma may, may mra jêng du huê nơm du ƀa ƀơ jêh ri nsong mblêng ta neh ntu.”$b$,false),
('bunong-vn','GEN',4,13,null,$b$Y-Kain lah ma Yêhôva: “Nau tâm rmal gâp jêng toyh lơn ma gâp dơi dơn.$b$,true),
('bunong-vn','GEN',4,14,null,$b$Aơ, may mprơh jêh gâp nar aơ bơh n'gor aơ; jêh ri pôn gâp bơh muh măt may; gâp mra jêng du huê nơm du ƀa ƀơ jêh ri nsong mblêng ta neh ntu jêh ri mbu mra tâm mâp đah gâp mra nkhĭt lơi gâp.”$b$,false),
('bunong-vn','GEN',4,15,null,$b$Ƀiă lah Yêhôva lah ma Păng: ‘Mâu! Tơ lah mbu nâm nkhĭt Y-Kain, bu mra plơng bôk ma păng pơh tơ̆ .” Pô ri Yêhôva ƀư nau tâm mbên ma Y-Kain, gay ma mbu nâm mâp đah păng bu mâu dơi nkhĭt păng ôh.$b$,false),
('bunong-vn','GEN',4,16,null,$b$Jêh ri Y-Kain du tă bơh muh măt Yêhôva hăn gŭ tâm n'gor Nôt pa lơ Êđen.$b$,false),
('bunong-vn','GEN',4,17,null,$b$Y-Kain gŭ đah ur păng; ntreo jêh ri deh ma Y-Hênôk. Păng ƀư du rplay ƀon tâm amoh ƀon nây Y-Hênôk, tĭng nâm amoh kon păng,$b$,true),
('bunong-vn','GEN',4,18,null,$b$Y-Hênôk jêng mbơ̆ Y-Irat; Y-Irat jêng mbơ̆ Y-Mêhujaêl; Y-Mêhujaêl jêng mbơ̆ Y-Lamek.$b$,false),
('bunong-vn','GEN',4,19,null,$b$Y-Lamek gŭ ur bar; amoh ur tơm H'Ada, amoh ur yông H'Sila,$b$,false),
('bunong-vn','GEN',4,20,null,$b$H'Ada deh Y-Jabel; păng jêng che tơm ma phung gŭ tâm ngih bok jêh ri rong mpô mpa.$b$,false),
('bunong-vn','GEN',4,21,null,$b$Amoh oh păng Y-Jubal; păng jêng che tơm ma lĕ phung goh gong rêng jêh ri uh n'hôm.$b$,true),
('bunong-vn','GEN',4,22,null,$b$H'Sila deh Y-Tubal Kain; păng yơh jêng nơm chiăr kông jêh ri loih. Amoh oh bu ur Y-Tubal Kain jêng H'Nama.$b$,false),
('bunong-vn','GEN',4,23,null,$b$Y-Lamek lah ma ur păng, Ơ H'Ada jêh ri H'Sila, iăt hom bâr gâp; Ơ phung ur Y-Lamek, rkêng tôr ma nau gâp ngơi. Gâp nkhĭt jêh du huê bunuyh yor păng ƀư sôt gâp, du huê bu klâu ndăm yor păng dong gâp.$b$,false),
('bunong-vn','GEN',4,24,null,$b$Tơ lah bu plơng bôk pơh tơ̆ ma Y-Kain. Nanê̆, bu mra plơng rnoh ma Y-Lamek pơh jât ma pơh tơ̆ .”$b$,false),
('bunong-vn','GEN',4,25,null,$b$Y-Ađam hôm gŭ ndrel ma ur păng; păng hôm deh du huê kon bu klâu, jêh ri păng tâm amoh kon nây Y-Set, yor lah lah: “Brah Ndu hŏ ăn đŏng ma gâp du huê kon bu klâu ntrok Y-Abel, nơm Y-Kain hŏ nkhĭt lơi jêh.”$b$,true),
('bunong-vn','GEN',4,26,null,$b$Y-Set geh kon bu klâu, jêh ri tâm amoh kon păng Y-Ênôs, Rnôk nây phung bunuyh ntơm mbơh ma sơm Yêhôva.$b$,false),
('bunong-vn','GEN',5,1,null,$b$Aơ sămƀŭt nkoch phung mon sau Y-Ađam. Tơ lah Brah Ndu rhăk njêng bunuyh, păng njêng tĭng nâm rup Brah Ndu nơm.$b$,true),
('bunong-vn','GEN',5,2,null,$b$Brah Ndu rhăk njêng bu ur, bu klâu jêh ri mât ton ma khân păng. Brah Ndu tâm amoh khân păng “bunuyh” nar Brah Ndu rhăk njêng khân păng.$b$,false),
('bunong-vn','GEN',5,3,null,$b$Tơ lah Y-Ađam gŭ rêh jêh du rhiăng pe jât năm, păng geh du huê kon bu klâu tâm ban ma păng nơm, kơp nâm rup păng, jêh ri păng tâm amoh Y-Set.$b$,false),
('bunong-vn','GEN',5,4,null,$b$Jêh bu deh ma Y-Set, Y-Ađam gŭ rêh pham rhiăng năm jêh ri păng geh phung kon bu klâu jêh ri phung kon bu ur.$b$,false),
('bunong-vn','GEN',5,5,null,$b$Lĕ rngôch nar Y-Ađam gŭ rêh sĭn rhiăng pe jât năm, jêh ri păng khĭt.$b$,false),
('bunong-vn','GEN',5,6,null,$b$Tơ lah Y-Set geh jêh du rhiăng ma prăm năm, păng geh kon, amoh păng Y-Ênôs.$b$,true),
('bunong-vn','GEN',5,7,null,$b$Jêh du deh ma Y-Ênôs, Y-Set gŭ rêh geh pham rhiăng ma pơh năm jêh ri păng geh phung kon bu klâu jêh ri phung kon bu ur.$b$,true),
('bunong-vn','GEN',5,8,null,$b$Lĕ rngôch nar Y-Set gŭ rêh geh sĭn rhiăng jât ma bar năm, jêh ri păng khĭt.$b$,true),
('bunong-vn','GEN',5,9,null,$b$Tơ lah Y-Ênos gŭ rêh jêh sĭn jât năm, păng geh kon, amoh păng Y-Kênan.$b$,false),
('bunong-vn','GEN',5,10,null,$b$Jêh bu deh ma Y-Kênan, Y-Ênôs gŭ rêh pham rhiăng jât ma prăm năm, jêh ri păng geh phung kon bu ur jêh ri phung kon bu klâu.$b$,false),
('bunong-vn','GEN',5,11,null,$b$Lĕ rngôch nar Y-Ênôs gŭ rêh geh sĭn rhiăng prăm năm, jêh ri păng khĭt.$b$,false),
('bunong-vn','GEN',5,12,null,$b$Tơ lah Y-Kônan rêh jêh pơh jât năm, păng geh kon, amoh păng Y-Mahalalel.$b$,true),
('bunong-vn','GEN',5,13,null,$b$Jêh bu deh ma Y-Mahalalel. Y-Kênan gŭ rêh pham rhiăng puăn jât năm, jêh ri păng geh phung kon bu klâu jêh ri kon bu ur.$b$,true),
('bunong-vn','GEN',5,14,null,$b$Lĕ rngôch nar Y-Kênan gŭ rêh geh sĭn rhiăng jât năm, jêh ri păng khĭt.$b$,true),
('bunong-vn','GEN',5,15,null,$b$Tơ lah Y-Mahalalel gŭ rêh jêh prao jât ma prăm năm, păng geh kon amoh Y-Jaret.$b$,false),
('bunong-vn','GEN',5,16,null,$b$Jêh bu deh ma Y-Jaret, Y-Mahalalel gŭ rêh pham rhiăng pe jât năm, jêh ri păng lŏ geh phung kon bu klâu jêh ri kon bu ur.$b$,false),
('bunong-vn','GEN',5,17,null,$b$Lĕ rngôch nar Y-Mahalalel gŭ rêh pham rhiăng sĭn jât ma prăm năm, jêh ri păng khĭt.$b$,false),
('bunong-vn','GEN',5,18,null,$b$Tơ lah Jaret gŭ rêh jêh du rhiăng prao jât ma bar năm, păng geh kon tâm amoh Y-Ênŏk.$b$,false),
('bunong-vn','GEN',5,19,null,$b$Jêh bu deh ma Y-Ênŏk, Y-Jaret gŭ rêh, pham rhiăng năm, jêh ri păng lŏ geh phung kon bu klâu jêh ri phung kon bu ur.$b$,false),
('bunong-vn','GEN',5,20,null,$b$Lĕ rngôch nar Jaret gŭ rêh, geh sĭn rhiăng prao jât ma bar năm, jêh ri păng khĭt.$b$,false),
('bunong-vn','GEN',5,21,null,$b$Tơ lah Y-Ênŏk gŭ rêh jêh prao jât ma prăm năm, păng geh kon tâm amoh Y-Mêthusêla.$b$,false),
('bunong-vn','GEN',5,22,null,$b$Jêh bu deh ma Y-Mêthusêla, Y-Ênŏk hăn ndrel ma Brah Ndu pe rhiăng năm, jêh ri păng geh phung kon bu klâu jêh ri phung kon bu ur.$b$,false),
('bunong-vn','GEN',5,23,null,$b$Lĕ rngôch nar Y-Ênŏk gŭ rêh geh pe rhiăng prao jât ma prăm năm.$b$,false),
('bunong-vn','GEN',5,24,null,$b$Y-Ênŏk hăn ndrel ma Brah Ndu jêh ri bu mâu hôm saơ păng ôh, yor lah Brah Ndu sŏk ndjôt păng jêh.$b$,false),
('bunong-vn','GEN',5,25,null,$b$Tơ Y-Mêthusêla gŭ rêh jêh du rhiăng pham jât ma pơh năm, păng geh kon, amoh păng Y-Lamek.$b$,false),
('bunong-vn','GEN',5,26,null,$b$Y-Mêthusêla gŭ rêh pơh rhiăng pham jât ma bar năm, jêh ri păng geh phung kon bu klâu jêh ri phung kon bu ur.$b$,false),
('bunong-vn','GEN',5,27,null,$b$Lĕ rngôch nar Y-Mêthusêla gŭ rêh geh sĭn rhiăng prao jât ma sĭn năm jêh ri păng khĭt.$b$,false),
('bunong-vn','GEN',5,28,null,$b$Tơ lah Y-Lamek gŭ rêh jêh du rhiăng pham jât ma bar năm, păng geh kon bu klâu.$b$,false),
('bunong-vn','GEN',5,29,null,$b$Păng tâm amoh Y-Nôê, jêh ri lah: “Nơm aơ mra bonh leng he tâm kan he jêh ri tâm nau ŏk ti he ƀư yor lah neh Yêhôva rtăp rak jêh.”$b$,false),
('bunong-vn','GEN',5,30,null,$b$Jêh bu deh ma Y-Nôê, Y-Lamek gŭ rêh prăm rhiăng sĭn jât ma prăm năm, jêh ri păng geh phung kon bu klâu jêh ri kon bu ur.$b$,false),
('bunong-vn','GEN',5,31,null,$b$Lĕ rngôch nar Y-Lamek gŭ rêh geh pơh rhiăng pơh jât ma pơh năm, jêh ri păng khĭt.$b$,false),
('bunong-vn','GEN',5,32,null,$b$Tơ lah Y-Nôê gŭ rêh jêh prăm rhiăng năm geh pe nuyh kon bu klâu, amoh khân păng Y-Sem, Y-Cham jêh ri Y-Japhet.$b$,false),
('bunong-vn','GEN',6,1,null,$b$Tơ lah phung bunuyh ntơm bĭk rơ̆ ta klơ neh ntu, jêh ri khân păng geh kon bu ur,$b$,true),
('bunong-vn','GEN',6,2,null,$b$phung kon bu klâu Brah Ndu saơ phung kon bu ur phung bunuyh ueh; jêh ri khân păng gŭ ur sai đah mbu nâm khân păng săch.$b$,false),
('bunong-vn','GEN',6,3,null,$b$Yêhôva lah: “Huêng nau rêh gâp mâu mra gŭ ƀa ƀơ tâm bunuyh ôh, yor lah păng jêng nglay săk. Ƀiă lah ăt păng mra gŭ rêh du rhiăng bar jât năm.”$b$,false),
('bunong-vn','GEN',6,4,null,$b$Phung bunuyh toyh juat gŭ rêh ta neh ntu rnôk nây, jêh ri bah kơi pa nĕ dôl phung kon bu klâu Brah Ndu gŭ ndrel phung kon bu ur bunuyh jêh ri khân păng geh kon; phung nây jêng phung ktang tâm rnôk kăl e khân păng jêng phung lư.$b$,true),
('bunong-vn','GEN',6,5,null,$b$Yêhôva saơ nau ƀai bunuyh jêng toyh ta neh ntu, jêh ri lĕ nau mĭn, nuih n'hâm mĭn nuih n'hâm păng knŏng mhĭk mro.$b$,false),
('bunong-vn','GEN',6,6,null,$b$Yêhôva nduyh tôr yor lah păng njêng jêh bunuyh ta neh ntu, jêh ri păng geh nuih n'hâm rngot.$b$,false),
('bunong-vn','GEN',6,7,null,$b$Pô ri Yêhôva lah: “Gâp mra ƀư rai bơh neh ntu bunuyh gâp hŏ rhăk njêng jêh, bunuyh nđâp ma mpô mpa, mpa vơr, jêh ri sĭm tâm trôk; gâp nduyh tôr yor gâp hŏ njêng jêh khân păng.$b$,false),
('bunong-vn','GEN',6,8,null,$b$Ƀiă lah Y-Nôê geh nau yô̆ ta năp măt Yêhôva.$b$,false),
('bunong-vn','GEN',6,9,null,$b$Aơ phung kon sau Y-Nôê, Y-Nôê jêng bunuyh sŏng srăng, mâu geh nau khư nduyh ôh tâm rnôk păng. Y-Nôê hăn ndrel ma Brah Ndu.$b$,true),
('bunong-vn','GEN',6,10,null,$b$Y-Nôê geh pe nuyh kon bu klâu Y-Sem, Y-Cham, jêh ri Y-Japhet.$b$,false),
('bunong-vn','GEN',6,11,null,$b$Brah Ndu saơ lĕ phung neh ntu jêng tih mhĭk jêh, jêh ri khân păng ăn bêng neh ntu ma nau ƀai.$b$,true),
('bunong-vn','GEN',6,12,null,$b$Brah Ndu uănh ma neh ntu, jêh ri păng saơ neh ntu bêng ma tih mhĭk; yor lah lĕ rngôch bunuyh knŏng tĭng nau mhĭk.$b$,false),
('bunong-vn','GEN',6,13,null,$b$Brah Ndu lah ma Y-Nôê: “Nau lôch ma lĕ rngôch nglay săk tât jêh ta năp măt gâp; yor lah neh ntu bêng nau djơh mhĭk ma nau khân păng ƀư, jêh ri gâp mra ƀư rai khân păng ndrel ma neh ntu.$b$,false),
('bunong-vn','GEN',6,14,null,$b$Ăn may ƀư du mlâm kumpăn ma si gôphê. Ăn may ƀư âk jrô tâm Kumpăn nây, jêh ri mhĭng păng ma dak ƀlĭt bitument tâm trôm jêh ri pa dih.$b$,false),
('bunong-vn','GEN',6,15,null,$b$Pô aơ ăn may ƀư păng; jong Kumpăn nây geh pe rhiăng hăt huy păng prăm jât hăt, jêh ri tă bơh ntur tât ta chor păng pe jât hăt,$b$,false),
('bunong-vn','GEN',6,16,null,$b$ăn may ƀư chor Kumpăn jêh ri om ntŭk hŏng prêh du hăt gay ma ƀư mpông bloh jê̆ ta nklang chor đah mpir. Ăn may ƀư pe tăp tâm Kumpăn nây jêh ri ƀư du rplay mpông ta pŭng păng.$b$,false),
('bunong-vn','GEN',6,17,null,$b$Yor lah gâp mra ăn dak lip ta neh ntu gay ƀư rai tâm dâng trôk lĕ rngôch mpô mpa geh suh n'hâm nau rêh lĕ rngôch mpô mpa ta klơ neh ntu mra khĭt.$b$,false),
('bunong-vn','GEN',6,18,null,$b$Ƀiă lah gâp mra ƀư nau tâm rnglăp đah may. Ăn may lăp tâm trôm Kumpăn, may phung kon bu klâu may, ur may, jêh ri ur phung kon bu klâu may jêh ri may nơm.$b$,false),
('bunong-vn','GEN',6,19,null,$b$May nglăp ndrel ma may tâm Kumpăn bar mlâm ăp ntil mpô mpa rêh, du mlâm me, du mlâm nkuăng, gay ăn khân păng rêh.$b$,false),
('bunong-vn','GEN',6,20,null,$b$Sĭm tĭng nâm ntil mpôl păng, mpô mpa tĭng nâm ntil mpôl păng, mpa vơr tĭng nâm ntil mpôl păng bar mlâm ăp ntil mpôl mra văch ma may, gay ma may prăp khân păng rêh,$b$,false),
('bunong-vn','GEN',6,21,null,$b$ăn may sŏk ndơ sông sa tâm ban lĕ prăp tâm Kumpăn. Ndơ nây jêng ndơ may sông sa nđâp ma khân păng ƀă.”$b$,false),
('bunong-vn','GEN',6,22,null,$b$Y-Nôê ƀư pô nây; păng ƀư lĕ tĭng nâm nau Brah Ndu ntăm jêh.$b$,true),
('bunong-vn','GEN',7,1,null,$b$Yêhôva lah ma Y-Nôê: “Lăp hom tâm Kumpăn ndrel ma lĕ rnăk vâl may, yor lah gâp saơ may sŏng srăng ta năp gâp đơ phung bunuyh rnôk aơ.$b$,true),
('bunong-vn','GEN',7,2,null,$b$Ăn may nglăp ndrel mpa kloh ueh ma may pơh me, pơh nkuăng, jêh ri ndơ mâu kloh ueh du me, du nkuăng, gay ma prăp ntil khân păng ta neh ntu.$b$,false),
('bunong-vn','GEN',7,3,null,$b$Bơh lĕ rngôch ntil sĭm tâm trôk, tâm ban đŏng, nkuăng pơh, me pơh, gay prăp mpôl khân păng ta neh ntu$b$,false),
('bunong-vn','GEN',7,4,null,$b$Yor lah hôm knŏng pơh nar gâp mra ăn trôk mih ta neh ntu dôl tâm puăn jât năng puăn jât nar; jêh ri gâp ŭch ƀư rai lơi lĕ rngôch mpô mpa gâp njêng jêh ta klơ neh ntu aơ.$b$,false),
('bunong-vn','GEN',7,5,null,$b$Y-Nôe ƀư lĕ tĭng nâm nau Yêhôva ntăm jêh ma păng.$b$,false),
('bunong-vn','GEN',7,6,null,$b$Rnôk dak lip neh ntu Y-Nôê geh prao rhiăng năm jêh.$b$,true),
('bunong-vn','GEN',7,7,null,$b$Y-Nôê lăp tâm Kumpăn ndrel ma phung kon bu klâu păng, ur păng, jêh ri lĕ ƀăn păng, gay ma klaih bơh dak lip.$b$,false),
('bunong-vn','GEN',7,8,null,$b$Mpô mpa kloh, mpô mpa mâu kloh, sĭm jêh ri lĕ rngôch mpa vơr ma ndŭl vơr ta neh$b$,true),
('bunong-vn','GEN',7,9,null,$b$lăp bar bar tâm Kumpăn, me nkuăng ndrel ma Y-Nôê, tĭng nâm Brah Ndu ntăm jêh ma Y-Nôê.$b$,false),
('bunong-vn','GEN',7,10,null,$b$Tăch pe nar dak ntơm lip yơh ta neh ntu.$b$,false),
('bunong-vn','GEN',7,11,null,$b$Tơ lah Y-Nôê geh prao rhiăng năm, ta khay bar, nar jât ma pơh lĕ rngôch tu dak, ntu jru luh jêh ri mpông bloh jê̆ ta klơ trôk pơk jêh.$b$,true),
('bunong-vn','GEN',7,12,null,$b$Trôk mih ta neh ntu puăn jât năng puăn jât nar.$b$,false),
('bunong-vn','GEN',7,13,null,$b$Nar nây Y-Nôê lăp tâm trôm Kumpăn ndrel ma ndrel phung kon bu klâu păng Y-Sem, Y-Cham jêh ri Y-Japhat ur Y-Nôê jêh ri pe nuyh ƀăn păng,$b$,false),
('bunong-vn','GEN',7,14,null,$b$jêh ri lĕ rngôch mpa bri tĭng nâm ntil mpôl păng, lĕ rngôch mpô mpa rong tĭng nâm ntil mpôl khân păng, lĕ rngôch mpô mpa vơr ta neh tĭng nâm ntil mpôl păng, jêh ri lĕ rngôch sĭm tĭng nâm ntil mpôl khân păng.$b$,false),
('bunong-vn','GEN',7,15,null,$b$Khân păng lăp tâm trôm Kumpăn ndrel ma Y-Nôê bar bar, lĕ rngôch mpa geh n'hâm nau rêh.$b$,true),
('bunong-vn','GEN',7,16,null,$b$Khân păng lăp me nkuăng, tĭng nâm Brah Ndu ntăm jêh ma Y-Nôê. Jêh ri Yêhôva chăng mpông.$b$,false),
('bunong-vn','GEN',7,17,null,$b$Dak lip neh ntu tâm puăn jât năng, puăn jât nar; dak hao ƀa ƀơ jêh ri nthông Kumpăn, jêh ri Kumpăn gŭ ta klơ neh ntu.$b$,true),
('bunong-vn','GEN',7,18,null,$b$Dak hao lơ prêh ta klơ neh ntu; jêh ri Kumpăn thông ta klơ mpiăt dak.$b$,false),
('bunong-vn','GEN',7,19,null,$b$Dak lơ hô hao đŏng kŏ tât lĕ yôk prêh tâm dâng trôk ndâp da dê.$b$,false),
('bunong-vn','GEN',7,20,null,$b$Dak hao jât ma prăm hăt prêh lơn ta klơ kô yôk.$b$,true),
('bunong-vn','GEN',7,21,null,$b$Lĕ rngôch mpô mpa blau mpât vơr sak nsong ta klơ neh ntu khĭt, sĭm, ndrôk, mpa bri lĕ rngôch mpa vơr ta klơ neh ntu, nđâp ma lĕ rngôch bunuyh.$b$,false),
('bunong-vn','GEN',7,22,null,$b$Lĕ rngôch mpa ta klơ neh sơh geh n'hâm nau rêh suh tă bơh trôm muh khĭt da dê.$b$,false),
('bunong-vn','GEN',7,23,null,$b$Yêhôva ƀư rai lĕ rngôch mpô mpa rêh ta klơ neh ntu, bunuyh, mpô mpa, mpa vơr jêh ri lĕ sĭm och tâm trôk, khân păng rai lĕ jêh bơh neh ntu Hôm knŏng Y-Nôê jêh ri phung gŭ ndrel ma păng tâm Kumpăn.$b$,false),
('bunong-vn','GEN',7,24,null,$b$Dak hôm pô nây ta neh ntu tâm du rhiăng prăm jât nar.$b$,false),
('bunong-vn','GEN',8,1,null,$b$Ƀiă lah Brah Ndu kah gĭt ma Y-Nôê jêh ri lĕ rngôch mpa bri jêh ri mpô mpa rong gŭ ndrel ma păng tâm Kŭmpăn. Brah Ndu ăn geh sial khôm ta neh ntu jêh ri dak hŭch.$b$,true),
('bunong-vn','GEN',8,2,null,$b$Tu dak, klŏng jru jêh ri mpông bloh jê̆ ta klơ trôk chăng jêh; jêh ri trôk mâu hôm mih ôh.$b$,false),
('bunong-vn','GEN',8,3,null,$b$Dak hŭch ƀa ƀơ bah neh ntu; tâm du rhiăng prăm jât nar pa kơi dak hŭch.$b$,false),
('bunong-vn','GEN',8,4,null,$b$Ta khay pơh nar jât ma pơh Kumpăn gŭ ta klơ yôk Ararat,$b$,false),
('bunong-vn','GEN',8,5,null,$b$dak hŭch ƀa ƀơ n'ho ma tât ta khay jât. Ta khay jât, nar tal nguay, kô yôk ntơm mpơl.$b$,false),
('bunong-vn','GEN',8,6,null,$b$Tăch puăn jât nar Y-Nôê pơk mpông bloh jê̆ păng ƀư ta Kŭmpăn.$b$,false),
('bunong-vn','GEN',8,7,null,$b$Păng mƀơk du mlâm nđak. Păng mpăr nsong tât dak suăt lam neh ntu.$b$,false),
('bunong-vn','GEN',8,8,null,$b$Jêh ri păng mƀơk du mlâm plŭk, ŭch uănh gĭt lah dak hŏ suăt ngăn jêh hĕ ta klơ neh ntu$b$,false),
('bunong-vn','GEN',8,9,null,$b$ƀiă lah plŭk mâu saơ ntŭk drâm ôh, pô ri păng plơ̆ ta Y-Nôê ta Kŭmpăn. Yor lah ăt hôm dak lam neh ntu. Păng yơr ti nhŭp plŭk, jêh ri nglăp lơi tâm Kŭmpăn ndrel ma păng nơm.$b$,false),
('bunong-vn','GEN',8,10,null,$b$Păng gŭ kâp đŏng pơh nar jêh ri păng mƀơk plŭk tă bơh Kŭmpăn.$b$,false),
('bunong-vn','GEN',8,11,null,$b$Plŭk plơ̆ sĭt ta păng tâm mhaơ, jêh ri aơ păng gleng ma muăr păng du n'ha play Ôlivơ ăt hôm ndrêh; pô ri Y-Nôê gĭt dak suăt jêh ta neh ntu.$b$,false),
('bunong-vn','GEN',8,12,null,$b$Păng gŭ kâp pơh nar đŏng jêh ri mƀơk plŭk; jêh ri plŭk mâu hôm plơ̆ sĭt ma păng ôh.$b$,false),
('bunong-vn','GEN',8,13,null,$b$Năm prao rhiăng ma nguay, khay nguay, nar nguay, dak suăt lĕ jêh bơh neh ntu, Y-Nôê pơk chor bôk pho Kŭmpăn, uănh, aơ neh ntu sơh jêh.$b$,true),
('bunong-vn','GEN',8,14,null,$b$Ta khay bar, nar bar jât ma pơh neh sơh jêh.$b$,false),
('bunong-vn','GEN',8,15,null,$b$Jêh ri Brah Ndu lah ma Y-Nôe:$b$,false),
('bunong-vn','GEN',8,16,null,$b$“Luh hom tă bơh Kŭmpăn, may, ur may, phung kon bu klâu may jêh ri lĕ ƀăn may, ndrel ma may nơm.”$b$,false),
('bunong-vn','GEN',8,17,null,$b$Ngluh lơi lĕ rngôch mpa rêh gŭ ndrel ma may, sĭm, mpô mpa jêh ri lĕ mpa vơr ta neh ntu aơ, gay ma khân păng deh kon âk jêh ri bĭk rơ̆ ta neh ntu aơ.”$b$,false),
('bunong-vn','GEN',8,18,null,$b$Pô ri Y-Nôê du luh tă bơh Kŭmpăn, ur păng, phung kon bu klâu păng jêh ri ƀăn păng.$b$,false),
('bunong-vn','GEN',8,19,null,$b$Lĕ rngôch mpa bri, lĕ rngôch mpa vơr lĕ rngôch sĭm, lĕ rngôch mpa blau mpât n'gơ ta neh ntu tĭng nâm ntil mpôl khân păng luh tă bơh Kŭmpăn.$b$,false),
('bunong-vn','GEN',8,20,null,$b$Jêh ri Y-Nôê rdâk nơng ƀư brah ma Yêhôva, jêh ri păng sŏk lĕ đơ mpô mpa kloh jêh ri lĕ sĭm kloh jêh ri păng nhhơr mpa nhhơr gŭch ta klơ nơng nây.$b$,true),
('bunong-vn','GEN',8,21,null,$b$Yêhôva ƀâu n'hôl ndơ kah jêh ri lah êng tâm nuih n'hâm păng: “Gâp mâu mra rtăp rak neh ntu đŏng ôh yor bunuyh, yor lah nau mĭn nuih n'hâm bunuyh mhĭk ntơm bơh păng dôl mom; mâu lĕ hôm gâp ƀư rai lĕ mpa rêh tâm ban ma gâp hŏ ƀư jêh.$b$,false),
('bunong-vn','GEN',8,22,null,$b$Dôl neh ntu ăt hôm, nau tuch tăm, jêh ri nau kăch roih, nau nđik jêh ri nau duh, yăn kăl vai jêh yăn sĭt puh, nar jêh ri măng mâu mra roh ôh.”$b$,false),
('bunong-vn','GEN',9,1,null,$b$Brah Ndu mât ton nau ueh uĭn ma Y-Nôê jêh ri ma phung kon bu klâu păng, jêh ri lah ma khân păng: “Ăn khân may jêng bĭk rơ̆ jêh ri ăn bêng neh ntu.”$b$,true),
('bunong-vn','GEN',9,2,null,$b$Lĕ rngôch mpô mpa tâm neh ntu jêh ri lĕ sĭm tâm trôk, lĕ rngôch mpa vơr ta neh jêh ri ka tâm dak lêng mra klach ma may. Gâp jao jêh lĕ rngôch mpa nây tâm ti khân may da dê.$b$,true),
('bunong-vn','GEN',9,3,null,$b$Lĕ rngôch mpa blau mpât n'gơ, mra jêng ndơ khân may, gâp ăn ma khân may lĕ rngôch mpa nây, nâm bu gâp ăn jêh tơm trau nse.$b$,false),
('bunong-vn','GEN',9,4,null,$b$Knŏng lơi khân may sa ôh puăch hôm nau rêh păng, nâm bu ntĭt mham păng.$b$,false),
('bunong-vn','GEN',9,5,null,$b$Tơ lah bu nkhŭt mham nau rêh khân may, nanê̆ gâp mra plơng har ma ăp mpô mpa jêh ri bunuyh. Gâp mra plơng har ma bunuyh nkhĭt băl păng.$b$,false),
('bunong-vn','GEN',9,6,null,$b$“Mbu nâm nkhŭt mham bunuyh, bunuyh đŏng mra nkhŭt mham nơm nây; yor lah Brah Ndu njêng bunuyh tĭng nâm rup păng nơm.$b$,true),
('bunong-vn','GEN',9,7,null,$b$Bi khân may, ăn khân may bĭk rơ̆ , ăn khân may geh kon sau âk, kŏ khân păng ăn bêng neh ntu.”$b$,false),
('bunong-vn','GEN',9,8,null,$b$Brah Ndu lah ma Y-Nôê jêh ri ma phung kon bu klâu păng.$b$,true),
('bunong-vn','GEN',9,9,null,$b$“Aơ, gâp ƀư nau gâp tâm rnglăp đah khân may, jêh ri ma phung kon sau khân may tâm nar kăndơ̆ ,$b$,false),
('bunong-vn','GEN',9,10,null,$b$ma lĕ mpa rêh gŭ ndrel ma khân may, sĭm, mpô mpa rong, jêh ri lĕ rngôch mpô mpa bri tâm neh ntu ndrel ma khân may lĕ mpô mpa luh tă Kumpăn.$b$,false),
('bunong-vn','GEN',9,11,null,$b$Gâp ƀư nau gâp tâm rnglăp đah khân may; gâp mâu hôm ƀư rai ôh lĕ rngôch mpô mpa rêh ma dak; mâu lĕ hôm geh nau dak lip rai neh ntu.”$b$,false),
('bunong-vn','GEN',9,12,null,$b$Brah Ndu lah: “Aơ ndơ tâm mbên nau gâp tâm rnglăp đah may jêh ri đah lĕ rngôch mpô mpa rêh gŭ ndrel ma khân may ma lĕ rnôk kăndơ̆ .$b$,false),
('bunong-vn','GEN',9,13,null,$b$Gâp dơm bêh tŭng tĭng gâp tâm ndâr; păng mra jêng mpa tâm mbên nau gâp tâm rnglăp đah neh ntu.$b$,false),
('bunong-vn','GEN',9,14,null,$b$Tơ lah gâp geh ndâr tŭk ta klơ neh ntu, bêh tŭng tĭng mra mpơl tâm ndâr,$b$,false),
('bunong-vn','GEN',9,15,null,$b$jêh ri gâp mra kah gĭt nau tâm rnglăp gâp đah khân may jêh ri đah lĕ rngôch mpô mpa rêh tâm săk jăn, jêh ri dak mâu mra jêng dak lip gay ma rai lĕ rngôch mpa rêh đŏng ôh.$b$,false),
('bunong-vn','GEN',9,16,null,$b$Tơ lah bêh tŭng tĭng gŭ tâm ndâr, gâp mra uănh păng gay ma kah gĭt nau tâm rnglăp n'ho ro ƀư jêh đah Brah Ndu jêh ri đah lĕ rngôch mpô mpa rêh ta klơ neh ntu.”$b$,false),
('bunong-vn','GEN',9,17,null,$b$Brah Ndu lah ma Y-Nôê: “Aơ yơh ndơ tâm mbên ma nau tâm rnglăp gâp ƀư jêh vah vang gâp đah lĕ rngôch mpa rêh ta klơ neh ntu.”$b$,false),
('bunong-vn','GEN',9,18,null,$b$Phung kon bu klâu Y-Nôê luh tă bơh Kŭmpăn jêng Y-Sem, Y-Cham jêh ri Y-Japhet. Y-Cham jêng bơ̆ Y-Kanaan.$b$,true),
('bunong-vn','GEN',9,19,null,$b$Pe nuyh aơ jêng kon bu klâu Y-Nôê; jêh ri bơh khân păng yơh geh bunuyh bêng neh ntu.$b$,false),
('bunong-vn','GEN',9,20,null,$b$Y-Nôê jêng nơm ƀư mir, jêh ri păng tăm play kriăk ƀâu.$b$,true),
('bunong-vn','GEN',9,21,null,$b$Păng nhêt dak play kriăk ƀâu, jêh ri păng nhŭl ndrănh; jêh ri păng bêch rhôk tâm ngih bok păng.$b$,false),
('bunong-vn','GEN',9,22,null,$b$Y-Cham, bơ̆ Kanaan, saơ bơ̆ păng gŭ rhôk, jêh ri mbơh ma bar hê nâu păng pa dih.$b$,true),
('bunong-vn','GEN',9,23,null,$b$Y-Sem jêh ri Y-Japhet sŏk du blah bok, dơm ta săng nglik khân păng, jêh ri hăn rŭch nkơi nkơi. Khân păng ntâk mbơ̆ khân păng. Khân păng n'gĭl uănh ta ntŭk êng, mâu saơ ôh nau rhôk bơ̆ khân păng.$b$,false),
('bunong-vn','GEN',9,24,null,$b$Y-Nôê kah rngăl tă bơh nau nhŭl ndrănh ƀư ma păng. Păng gĭt mâm nau kon păng ƀư ma păng,$b$,true),
('bunong-vn','GEN',9,25,null,$b$Păng lah: “Ăn Kanaan geh nau rtăp rak! Păng mra jêng dĭk ma phung dĭk phung oh nâu păng.”$b$,false),
('bunong-vn','GEN',9,26,null,$b$Păng lah tâm ban lĕ: “Mât ton ma Yêhôva, Brah Ndu Y-Sem! Ăn Kanaan jêng dĭk ma Y-Sem,$b$,true),
('bunong-vn','GEN',9,27,null,$b$Ăn Brah Ndu ƀư huy n'har neh ma Y-Japhet, e jêh ri ăn păng gŭ tâm ngih bok Y-Sem. Jêh ri ăn Kanaan jêng dĭk ma Y-Japhet.$b$,false),
('bunong-vn','GEN',9,28,null,$b$Jêh dak lip Y-Nôê gŭ rêh pe rhiăng prăm jât năm.$b$,false),
('bunong-vn','GEN',9,29,null,$b$Lĕ rngôch nar Y-Nôê gŭ rêh sĭn rhiăng prăm jât năm, jêh ri păng khĭt.$b$,true),
('bunong-vn','GEN',10,1,null,$b$Aơ phung kon bu klâu jêh ri phung kon sau Y-Sem, Y-Cham jêh ri Y-Japhet. Phung kon bu klâu Y-Nôê jêh dak lip bu deh kon bu klâu ma khân păng.$b$,true),
('bunong-vn','GEN',10,2,null,$b$Phung kon bu klâu Y-Japhet; Y-Gômer, Y-Magôk; Y-Madai; Y-Javan, Y-Tubal, Y-Mêsek, jêh ri Y-Tiras.$b$,true),
('bunong-vn','GEN',10,3,null,$b$Phung kon bu klâu Y-Gômer, Y-Askênas, Y-Ripat, jêh ri Y-Tôgarma,$b$,false),
('bunong-vn','GEN',10,4,null,$b$phung kon bu klâu Y-Javan, Y-Êlisa, Y-Tarsis, Y-Kitim, jêh ri Y-Dôdanim.$b$,false),
('bunong-vn','GEN',10,5,null,$b$Tă bơh phung nây luh phung ƀon lan nchah du nsong gŭ tâm n'gor kơh dak mƀŭt jêh ri Kô dak mƀŭt. Nây jêng phung kon bu klâu Y-Japhet tâm n'gor khân păng, ăp nơm tĭng nâm nau khân păng nơm ngơi, tĭng nâm mpôl ntil khân păng.$b$,true),
('bunong-vn','GEN',10,6,null,$b$Phung kon bu klâu Y-Cham, Y-Kus, Y-Misram, Y-Put jêh ri Y-Kanaan.$b$,true),
('bunong-vn','GEN',10,7,null,$b$Phung kon bu klâu Y-Kus: Y-Sêba, Y-Havila, Y-Sabta, Y-Rama jêh ri Y-Saptêka. Phung kon bu klâu Y-Rama: Y-Sêba jêh ri Y-Dêdan.$b$,false),
('bunong-vn','GEN',10,8,null,$b$Y-Kus jêng mbơ̆ Y-Nimrôt. Păng yơh jêng du huê ktang ta neh ntu aơ.$b$,false),
('bunong-vn','GEN',10,9,null,$b$Păng jêng du huê bunuyh gru pănh geh lư n'găr ta năp Yêhôva. Yor nây yơh bu lah: “Nâm bu Y-Nimrôt, bunuyh gru pănh geh nau lư n'găr ta năp Yêhôva,”$b$,false),
('bunong-vn','GEN',10,10,null,$b$Tơm ƀon bri hađăch păng jêng ƀon Babel, ƀon Êrek, jêh ri ƀon Akat, lĕ rngôch ƀon nây gŭ tâm n'gor Sinar.$b$,true),
('bunong-vn','GEN',10,11,null,$b$Tă n'gor nây păng hăn ta n'gor Asiri jêh ri rdâk ƀon Ninivơ, ƀon Rêhôbôt-Ir, ƀon Kala$b$,true),
('bunong-vn','GEN',10,12,null,$b$jêh ri ƀon Resen vah vang ƀon Ninivơ jêh ri ƀon Kala.$b$,false),
('bunong-vn','GEN',10,13,null,$b$Misram jêng mbơ̆ Y-Ludim, Y-Anamin, Y-Lêhabim, Y-Naptuhim,$b$,false),
('bunong-vn','GEN',10,14,null,$b$Y-Patrusim, Y-Kasluhim (bơh phung nây yơh luh phung Philistin) jêh ri Y-Kaptôrim.$b$,false),
('bunong-vn','GEN',10,15,null,$b$Y-Kanaan geh kon bu klâu, amoh Y-Sidôn, jêng kon bôk rah, jêh ri Y-Het,$b$,true),
('bunong-vn','GEN',10,16,null,$b$jêh ri phung Jêbusit, phung Amôrit, phung Girgasit,$b$,false),
('bunong-vn','GEN',10,17,null,$b$phung Hivit, phung Arkit, phung Sinit.$b$,false),
('bunong-vn','GEN',10,18,null,$b$Phung Arvadit, phung Sêmarit, jêh ri phung Hamatit. Jêh ma nây phung mpôl băl Kanaan nkhah gŭ êng êng.$b$,true),
('bunong-vn','GEN',10,19,null,$b$Knŏng neh phung Kanaan sŏk tă bơh ƀon Sidôn mơ bơh ƀon Gêgar tât ta ƀon Gaxa jêh ri mơ bơh ƀon Sôdôm, ƀon Gômôrơ, ƀon Atma jêh ri ƀon Sêbôim tât ta ƀon Lasa.$b$,true),
('bunong-vn','GEN',10,20,null,$b$Nây yơh phung kon bu klâu Y-Cham, tĭng nâm mpôl khân păng, tĭng nâm nau khân păng ngơi, tâm n'gor khân păng, tâm ƀon bri hađăch khân păng.$b$,true),
('bunong-vn','GEN',10,21,null,$b$Y-Sem jêng che tơm ma lĕ phung kon Y-Êber, jêh ri jêng nâu Y-Japhet, geh phung kon tâm ban lĕ.$b$,true),
('bunong-vn','GEN',10,22,null,$b$Phung kon bu klâu Y-Sem, Y-Êlam, Y-Asur, Y-Aspaksat, Y-Lut, jêh ri Y-Aram.$b$,false),
('bunong-vn','GEN',10,23,null,$b$Phung kon bu klâu Y-Aram: Y-Us, Y-Hul, Y-Gêter, jêh ri Y-Mas,$b$,false),
('bunong-vn','GEN',10,24,null,$b$Y-Arpaksat jêng mbơ̆ Y-Sêla, jêh ri Y-Sêla jêng mbơ̆ Y-Êber.$b$,false),
('bunong-vn','GEN',10,25,null,$b$Y-Êber geh bar hê kon bu klâu, amoh du huê Y-Pêlek yor lah tâm rnôk păng phung gŭ ta neh ntu tâm nklah pă jêh ri amoh oh păng jêng Y-Jôktan.$b$,false),
('bunong-vn','GEN',10,26,null,$b$Y-Jôktan jêng mbơ̆ Y-Almôdat, Y-Sêlep, Y-Hasarmavet, Y-Jêra,$b$,false),
('bunong-vn','GEN',10,27,null,$b$Y-Hadôram, Y-Usal, Y-Dikla.$b$,false),
('bunong-vn','GEN',10,28,null,$b$Y-Ôbal, Y-Abimaêl, Y-Seba,$b$,true),
('bunong-vn','GEN',10,29,null,$b$Y-Ôphir, Y-Havila jêh ri Y-Jôbap, lĕ rngôch phung nây jêng kon bu klâu Y-Jôktan.$b$,false),
('bunong-vn','GEN',10,30,null,$b$N'gor khân păng gŭ sŏk dŭt ƀon Mêsa mơ bơh n'gor Sêphar tât ta n'gor prêh pa lơ.$b$,false),
('bunong-vn','GEN',10,31,null,$b$Nây jêng phung kon bu klâu Y-Sem, tĭng nâm mpôl khân păng, tĭng nâm nau khân păng ngơi, tâm n'gor khân păng, tâm ƀon bri hađăch khân păng.$b$,false),
('bunong-vn','GEN',10,32,null,$b$Nây yơh jêng phung mpôl băl phung kon bu klâu Y-Nôê tĭng nâm rnôk khân păng, tâm n'gor khân păng. Bơh khân păng yơh phung mpôl băl nchah nsong du êng êng tâm neh ntu jêh dak lip.$b$,true),
('bunong-vn','GEN',11,1,null,$b$Lĕ rngôch neh ntu geh knŏng du ntil nau ngơi jêh ri rplay ngơi tâm ban.$b$,true),
('bunong-vn','GEN',11,2,null,$b$Dôl phung bunuyh hăn leo pa lơ, khân păng saơ neh lâng tâm n'gor Sinar. Khân păng gŭ ta nây.$b$,false),
('bunong-vn','GEN',11,3,null,$b$Khân păng tâm lah ndrăng khân păng: “Kay lŏng he, ăn he ƀư neh uk jêh ri gŭch ma ŭnh ăn dăng.” Neh uk jêng lŭ ma khân păng jêh ri dak blĭt bitumen jêng ndơ tâm krêp.$b$,false),
('bunong-vn','GEN',11,4,null,$b$Khân păng lah: “Kay lŏng he ăn he ƀư du rplay ƀon toyh jêh ri du rplay ngih gung, bôk păng ăn kŏ ma trôk. Ăn he joi nau lư n'găr, klach lah he mra tâm nkhah du nsong lam bri neh,”$b$,false),
('bunong-vn','GEN',11,5,null,$b$Yêhôva jŭr ŭch uănh ƀon jêh ri ngih gung phung kon bunuyh ndâk jêh:$b$,false),
('bunong-vn','GEN',11,6,null,$b$Yêhôva lah: “Aơ, khân păng jêng du phung ƀon lan jêh ri khân păng geh du ntil nau ngơi. Aơ jêng knŏng tơm ma kan khân păng mra ƀư. Jêh ri aƀaơ khân păng dơi ƀư lĕ rngôch kan khân păng mĭn ŭch ƀư.$b$,false),
('bunong-vn','GEN',11,7,null,$b$Kay lŏng he, ăn he jŭr gay ma tâm rlŭk nau khân păng ngơi, gay ma khân păng mâu dơi gĭt rbăng ôh nau khân păng tâm ngơi ndrăng khân păng.$b$,false),
('bunong-vn','GEN',11,8,null,$b$Pô ri Yêhôva nchah du khân păng êng êng ta klơ neh ntu, jêh ri khân păng cha lơi nau rdâk ƀon nây.$b$,false),
('bunong-vn','GEN',11,9,null,$b$Yor ri bu tâm amoh ƀon nây Babel, yor lah ta nây yơh, Yêhôva tâm rlŭk nau ngơi phung neh ntu. Jêh ri ntơm bơh nây yơh Yêhôva tâm nchah du lơi khân păng êng êng lam bri ta klơ neh ntu.$b$,true),
('bunong-vn','GEN',11,10,null,$b$Aơ phung kon sau Y-Sem, Y-Sem gŭ rêh du rhiăng năm jêh ri geh kon, amoh păng Y-Arpaksat, bar năm rlau jêh dak lip.$b$,true),
('bunong-vn','GEN',11,11,null,$b$Jêh păng geh Arpaksat, Y-Sem gŭ rêh prăm rhiăng năm jêh ri lŏ geh phung kon bu klâu jêh ri kon bu ur.$b$,true),
('bunong-vn','GEN',11,12,null,$b$Y-Arpaksat gŭ rêh, pe jât ma prăm năm jêh ri păng geh kon, moh păng Y-Sêla,$b$,true),
('bunong-vn','GEN',11,13,null,$b$jêh păng geh Y-Sêla, Y-Arpaksat gŭ rêh puăn rhiăng pe năm jêh ri lŏ geh phung kon bu klâu, jêh ri kon bu ur.$b$,false),
('bunong-vn','GEN',11,14,null,$b$Y-Sêla gŭ rêh pe jât năm jêh ri geh kon, amoh păng Y-Êber.$b$,false),
('bunong-vn','GEN',11,15,null,$b$Jêh păng geh Y-Êber, Y-Sêla gŭ rêh, puăn rhiăng pe năm jêh ri geh phung kon bu klâu jêh ri phung kon bu ur.$b$,true),
('bunong-vn','GEN',11,16,null,$b$Y-Êber gŭ rêh pe jât ma puăn năm jêh ri păng geh kon, amoh păng Y-Pêlek.$b$,true),
('bunong-vn','GEN',11,17,null,$b$Jêh păng geh Y-Pêlek, Y-Êber gŭ rêh puăn rhiăng pe jât năm, jêh ri lŏ geh phung kon bu klâu jêh ri phung kon bu ur.$b$,true),
('bunong-vn','GEN',11,18,null,$b$Y-Pêlek gŭ rêh pe jât năm ri păng geh kon, amoh păng Y-Rêu,$b$,false),
('bunong-vn','GEN',11,19,null,$b$jêh păng geh Y-Rêu, Y-Pêlek gŭ rêh bar rhiăng ma sĭm năm jêh ri lŏ geh phung kon bu ur jêh ri phung kon bu klâu.$b$,false),
('bunong-vn','GEN',11,20,null,$b$Y-Rêu gŭ rêh pe jât ma bar năm, jêh ri păng geh kon, amoh păng Y-Sêruk.$b$,true),
('bunong-vn','GEN',11,21,null,$b$Jêh păng geh Y-Sêruk, Y-Rêu gŭ rêh bar rhiăng ma pơh năm, jêh ri lŏ geh phung kon bu klâu jêh ri kon bu ur.$b$,false),
('bunong-vn','GEN',11,22,null,$b$Y-Sêruk gŭ rêh pe jât năm, jêh ri păng geh kon, amoh păng Y-Nahôr.$b$,true),
('bunong-vn','GEN',11,23,null,$b$Jêh păng geh Y-Nahôr, Y-Sêruk gŭ rêh bar rhiăng năm, jêh ri lŏ geh phung kon bu klâu jêh ri kon bu ur.$b$,false),
('bunong-vn','GEN',11,24,null,$b$Y-Nahôr gŭ rêh bar jât ma sĭn năm jêh ri păng geh kon, moh păng Y-Têra.$b$,false),
('bunong-vn','GEN',11,25,null,$b$Jêh păng geh Y-Têra, Y-Nahôr gŭ rêh du rhiăng jât ma sĭn năm jêh ri geh phung kon bu klâu jêh ri phung kon bu ur.$b$,true),
('bunong-vn','GEN',11,26,null,$b$Y-Têra gŭ rêh pơh jât năm, jêh ri păng geh phung kon, amoh khân păng Y-Aram, Y-Nahôr, jêh ri Y-Haran.$b$,true),
('bunong-vn','GEN',11,27,null,$b$Aơ jêng phung kon sau Y-Têra; Y-Têra jêng mbơ̆ Y-Abram, Y-Nahôr jêh ri Y-Haran jêh ri Y-Haran jêng mbơ̆ Y-Lot,$b$,true),
('bunong-vn','GEN',11,28,null,$b$Y-Haran khĭt lor ma mbơ̆ păng Têra tâm n'gor bu deh ma păng ta ƀon Ur n'gor Kaldê.$b$,false),
('bunong-vn','GEN',11,29,null,$b$Y-Abram jêh ri Y-Nahôr gŭ ur, amoh ur Y-Abram jêng H'Sarai, amoh ur Y-Nahôr H'Milka, kon bu ur Y-Hran, mbơ̆ H'Milka, kon bu ur Y-Haran, mbơ̆ H'Milka jêh ri mbơ̆ H'Iska.$b$,true),
('bunong-vn','GEN',11,30,null,$b$Ƀiă lah H'Sarai jêng bu ur mâu bă mâu geh kon ôh.$b$,false),
('bunong-vn','GEN',11,31,null,$b$Y-Têra sŏk kon bu klâu păng Y-Abram jêh ri sau păng Y-Lot, kon bu klâu Y-Haran jêh ri H'Sarai ƀăn păng, ur Y-Abram kon bu klâu păng, jêh ri khân păng luh du ndrel tă bơh ƀon Ur tâm n'gor Kaldê ŭch hăn ta n'gor Kanaan. Ƀiă lah khân păng hăn tât ta ƀon Charan jêh ri gŭ ta nây.$b$,true),
('bunong-vn','GEN',11,32,null,$b$Nar Y-Têra gŭ rêh geh bar rhiăng ma prăm năm, jêh ri Y-Têra khĭt ta ƀon Charan.$b$,false),
('bunong-vn','GEN',12,1,null,$b$Yêhôva lah ma Y-Abram, luh tă bơh n'gor may, cha lơi ndŭl mpôl may jêh ri ngih mbơ̆ may, hăn ta n'gor gâp mra ntĭm ăn ma may.$b$,true),
('bunong-vn','GEN',12,2,null,$b$Gâp mra ăn may jêng du mpôl băl toyh; gâp mra ăn nau ueh uĭn ma may; gâp mra ăn amoh may geh nau lư n'gar jêh ri may mra jêng nau ueh uĭn ma phung êng.$b$,false),
('bunong-vn','GEN',12,3,null,$b$Gâp mra ăn nau ueh uĭn ma mbu nâm ăn nau ueh lăng ma may; gâp mra rtăp rak ma mbu nơm rtăp rak may; jêh ri tâm may lĕ rngôch mpôl băl bunuyh tâm neh ntu mra geh nau ueh uĭn.$b$,false),
('bunong-vn','GEN',12,4,null,$b$Y-Abram hăn tĭng nâm Yêhôva lah jêh ma păng jêh ri Y-Lot hăn ndrel ma păng. Y-Abram geh pơh jât ma prăm năm tơ lah păng du luh tă bơh ƀon Charan.$b$,false),
('bunong-vn','GEN',12,5,null,$b$Y-Abram sŏk ur păng H'Sarai jêh ri kon oh păng Y-Lot jêh ri lĕ rngôch drăp ndơ khân păng geh, jêh ri nđâp ma bunuyh khân păng sŏk ta ƀon Charan. Khân păng hăn ta n'gor Kanaan. Pô ri khân păng tât jêh ta n'gor Kanaan.$b$,false),
('bunong-vn','GEN',12,6,null,$b$Y-Abram rgăn n'gor nây tât ta ntŭk Sichem, tât ta tơm si bu yơk mbah ta Môrê. Rnôk nây phung Kanaan gŭ tâm n'gor nây.$b$,false),
('bunong-vn','GEN',12,7,null,$b$Yêhôva tâm mpơl păng nơm ma Y-Abram jêh ri lah: “Gâp mra ăn n'gor aơ ma phung kon sau may.” Pô ri ta nây păng rdâk du nơng ƀư brah ma Yêhôva, nơm tâm mpơl jêh ma păng.$b$,false),
('bunong-vn','GEN',12,8,null,$b$Bơh ntŭk nây păng hăn ta yôk pa lơ ƀon Bêthel jêh ri rdâk ngih bok, geh ƀon Bêthel pa dâng jêh ri ƀon Ai pa lơ. Păng rdâk ta nây du nơng ƀư brah ma Yêhôva jêh ri kuăl mbơh sơm ma amoh Yêhôva.$b$,false),
('bunong-vn','GEN',12,9,null,$b$Jêh ri Abram n'ho hăn ta n'gor mpeh tâm Rđŭng.$b$,false),
('bunong-vn','GEN',12,10,null,$b$Rnôk nây geh nau sa sât ji ngot tâm n'gor nây. Pô ri Y-Abram jŭr hăn ta n'gor Êjipt, ŭch gŭ ta nây, yor lah nau sa sât ji ngot tâm n'gor.$b$,true),
('bunong-vn','GEN',12,11,null,$b$Tơ lah păng ntơm lăp tâm n'gor Êjipt, păng lah ma H'Sarai ur păng. “Aơ gâp gĭt ay jêng bu ur ueh;$b$,false),
('bunong-vn','GEN',12,12,null,$b$jêh ri phung Êjipt mra lah, tơ lah khân păng saơ ay, ‘Ur păng yơh aơ: Pô ri khân păng mra nkhĭt gâp. Ƀiă lah khân păng ăn ay gŭ rêh.$b$,false),
('bunong-vn','GEN',12,13,null,$b$Ay lah, ay jêng oh bu ur gâp, pô nây mơ bu mra ƀư ueh ma gâp yor ay, jêh ri ăn gâp gŭ rêh yor ay.”$b$,false),
('bunong-vn','GEN',12,14,null,$b$Tơ lah Y-Abram tât ta n'gor Êjipt, phung Êjipt saơ bu ur nây ueh ngăn.$b$,true),
('bunong-vn','GEN',12,15,null,$b$Tơ lah phung Kôranh Y-Pharaôn saơ păng khân păng rnê nau ueh păng ta năp Y-Pharaôn, jêh ri bu njŭn leo bu ur nây ta ngih Y-Pharaôn.$b$,false),
('bunong-vn','GEN',12,16,null,$b$Păng ƀư ueh ma Y-Abram yor bu ur nây. Y-Abram geh biăp, ndrôk, seh bri nkuăng, phung oh mon mƀuăl bu klâu, phung oh mon bu ur, seh bri me jêh ri seh samô.$b$,false),
('bunong-vn','GEN',12,17,null,$b$Ƀiă lah Yêhôva ăn nau ji tưp toyh ma Y-Pharaôn jêh ri ngih păng yor H'Sarai ur Y-Abram.$b$,true),
('bunong-vn','GEN',12,18,null,$b$Pô ri Y-Pharaôn kuăl Y-Abram jêh ri lah: “Moh nau may ƀư ma gâp? Mâm ƀư may mâu mbơh ma gâp, păng jêng ur may?$b$,false),
('bunong-vn','GEN',12,19,null,$b$Phâm ƀư may lah, păng jêng oh bu ur gâp? Pô ri yơh gâp hŏ sŏk păng jêng ur gâp jêh. Aƀaơ, aơ ur may, sŏk păng jêh ri du hom may.”$b$,false),
('bunong-vn','GEN',12,20,null,$b$Y-Pharaôn đă bu njŭn păng hăn nđâp ma ur păng, jêh ri lĕ rngôch mpô mpa păng geh.$b$,false),
('bunong-vn','GEN',13,1,null,$b$Y-Abram du tă bơh n'gor Êjipt hăn ta n'gor tâm Rđŭng, păng, ur păng, jêh ri lĕ rngôch ndơ păng geh, jêh ri Y-Lot ndrel ma păng.$b$,true),
('bunong-vn','GEN',13,2,null,$b$Y-Abram ndrŏng ngăn geh mpô mpa rong, prăk jêh ri mah.$b$,false),
('bunong-vn','GEN',13,3,null,$b$Jêh ri păng nsong tă bah n'gor Rđŭng tât ta ƀon Bêthel jêh ri ƀon Ai.$b$,false),
('bunong-vn','GEN',13,4,null,$b$Ta ntŭk păng rdâk du nơng ƀư brah sa ơm dơh. Ta nây Y-Abram kuăl mbơh sơm ma amoh Yêhôva.$b$,false),
('bunong-vn','GEN',13,5,null,$b$Y-Lot, nơm hăn nsong ndrel Y-Abram, geh biăp, ndrôk tâm ban lĕ jêh ri geh âk rplay ngih bok.$b$,false),
('bunong-vn','GEN',13,6,null,$b$Tâm n'gor nây kŏ tât mâu tŏng ntŭk ma khân păng gŭ ndrel, yor lah mpô mpa drăp ndơ khân păng âk.$b$,false),
('bunong-vn','GEN',13,7,null,$b$Geh nau tâm djrel ndrăng phung chiă biăp, ndrôk Y-Abram jêh ri rmăk chiă biăp ndrôk Y-Lot. Rnôk nây phung Kanaan jêh ri phung Pêrisit gŭ tâm n'gor.$b$,false),
('bunong-vn','GEN',13,8,null,$b$Y-Abram lah ma Y-Lot: “Gâp dăn ma may, lơi ăn ôh geh nau tâm djrel may đah gâp, jêh ri ndrăng phung chiă biăp, ndrôk may đah phung chiă biăp, ndrôk gâp; yor lah he jêng oh nâu.$b$,true),
('bunong-vn','GEN',13,9,null,$b$“Mâu di hĕ geh âk n'gor ta năp măt may? Tâm nkhah hom may nơm gâp, tơ lah may sŏk mpeh pa chiau, gâp mra hăn mơ pa ma; tơ lah may sŏk mpeh pa ma, gâp mra hăn mpeh pa chiau.”$b$,false),
('bunong-vn','GEN',13,10,null,$b$Y-Lot n'gơr măt uănh ta lĕ Neh Lâng dak krong Y-Yurdan geh dak âk lam, jêng nâm bu đang trau Yêhôva nâm bu n'gor Êjipt mpeh ƀon Sôar, Ê hŏ Yêhôva ƀư rai ôh ƀon Sôđôm, jêh ri ƀon Gômôrơ.$b$,false),
('bunong-vn','GEN',13,11,null,$b$Pô ri Y-Lot săch Neh Lâng Dak Krong Yurdan sŏk lĕ ma păng jêh ri păng hăn mơ pa lơ pô ri khân păng tâm nkhah.$b$,false),
('bunong-vn','GEN',13,12,null,$b$Y-Abram gŭ tâm n'gor Kanaan. Y-Lot gŭ tâm ƀon toyh tâm Neh Lâng jêh ri păng rgâl ntŭk ngih bok păng hăn tât ta ƀon Sôdôm.$b$,false),
('bunong-vn','GEN',13,13,null,$b$Phung bunuyh ƀon ƀai jêh ri ƀư tih toyh ngăn đah Yêhôva.$b$,false),
('bunong-vn','GEN',13,14,null,$b$Yêhôva lah ma Y-Abram jêh Y-Lot tâm nkhah bơh păng. “N'gơr măt may, jêh ri bơh ntŭk may gŭ, uănh mpeh pa dor mpeh, rđŭng, pa lơ, jêh ri pa dâng;$b$,false),
('bunong-vn','GEN',13,15,null,$b$yor lah lĕ rngôch neh may saơ gâp mra ăn ma may jêh ri ma phung kon sau may n'ho ro.$b$,false),
('bunong-vn','GEN',13,16,null,$b$Gâp mra ăn phung kon sau may jêng âk nâm bu ndruyh neh. Pô ri tơ lah mbu dơi kơp ndruyh neh, dơi lĕ păng kơp phung kon sau may.$b$,true),
('bunong-vn','GEN',13,17,null,$b$Dâk hom may, sak nsong rgăn n'gor aơ, yor lah gâp mra ăn n'gor aơ ma may.”$b$,false),
('bunong-vn','GEN',13,18,null,$b$Y-Abram rgâl ntŭk ngih bok păng jêh ri hăn gŭ ta tơm si Mamrê, dăch ƀon Hêbron; jêh ri păng rdâk ta nây du nơng ƀư brah ma Yêhôva.$b$,false),
('bunong-vn','GEN',14,1,null,$b$Tâm rnôk Y-Amraphel hađăch n'gor Sinar, Y-Ariôk hađăch ƀon Êlasar, Y-Kêdôr, Lômer hađăch ƀon Êlam jêh ri Y-Tidal hađăch ƀon Gôim,$b$,true),
('bunong-vn','GEN',14,2,null,$b$phung hađăch nây tâm lơh đah Y-Bêra hađăch ƀon Sôdôm, hađăch ƀon Atma, Y-Sêmêber hađăch ƀon Sêbôim jêh ri hađăch ƀon Bêla (jêng ƀon Sôar).$b$,false),
('bunong-vn','GEN',14,3,null,$b$Lĕ rngôch phung aơ tâm rƀŭn tâm rlŭng Sidim (jêng Dak Mƀŭt Boh).$b$,false),
('bunong-vn','GEN',14,4,null,$b$Dôl tâm jât ma bar năm khân păng lăp hađăch Y-Kêdôr Lômer ƀiă lah năm jât ma pe khân păng plơ̆ sĭt tâm rdâng.$b$,false),
('bunong-vn','GEN',14,5,null,$b$Năm jât ma puăn Y-Kê-dôr-lô-mer hăn ndrel ma phung hađăch mpeh ma păng, jêh ri khân păng tâm lơh, dơi khân păng đah phung Rêpham ta ƀon Astarôt Karnan, đah phung susim ta ƀon Ham, đah phung Êmim tâm rlŭng Kiriathaim.$b$,false),
('bunong-vn','GEN',14,6,null,$b$Jêh ri ndrel ma phung Hôrit tâm yôk Sir, tât ta Êlparan ta n'har neh tâm bri rdah.$b$,false),
('bunong-vn','GEN',14,7,null,$b$Jêh ri khân păng sĭt tă bơh nây, tât ta ƀon Ênmispat (jêng ƀon Kadês). Jêh ri khân păng tâm lơh dơi đah lĕ n'gor phung Amalek jêh ri đah phung Amôrit, gŭ ta ƀon Hasasôn Tamar.$b$,false),
('bunong-vn','GEN',14,8,null,$b$Dôl nây hađăch ƀon Sôdôm, hađăch ƀon Gômôrơ, hađăch ƀon Atma, hađăch ƀon Sêbôim, jêh ri hađăch ƀon Bêla (jêng ƀon Sôar) hăn jêh ri dăp ta han khân păng ma nau tâm lơh tâm Rlŭng Siđim,$b$,false),
('bunong-vn','GEN',14,9,null,$b$đah Y-Kêdôr Lômer hađăch ƀon Êlam, Y-Tidal hađăch ƀon Gôim, Amraphet, hađăch n'gor Sinar, jêh ri Y-Ariôk hađăch ƀon Êlasar, puăn nuyh hađăch tâm lơh đah prăm nuyh hađăch.$b$,false),
('bunong-vn','GEN',14,10,null,$b$Geh Tâm Rlŭng Sitim geh âk ntu dak blĭt ƀitimer. Hađăch ƀon Sôdôm jêh ri hađăch ƀon Gômôrơ du jêh ri tŭp tâm ntu nây jêh ri phung hôm nchuăt du leo pa yôk.$b$,false),
('bunong-vn','GEN',14,11,null,$b$Phung rlăng sŏk lĕ drăp ndơ ƀon Sôdôm jêh ri ƀon Gômôrơ, nđâp ma lĕ ndơ khân păng sông sa jêh ri ntơm sĭt.$b$,false),
('bunong-vn','GEN',14,12,null,$b$Khân păng nhŭp Y-Lot tâm ban lĕ jêng kon oh Y-Abram nđâp ma lĕ drăp ndơ păng, nơm nây gŭ ta ƀon Sôdôm jêh ri khân păng sĭt.$b$,false),
('bunong-vn','GEN',14,13,null,$b$Du huê tâm phung du văch mbơh ma Y-Abram, du huê Hêbrơ. Y-Abram gŭ ta tơm si Mamrê, du huê Amôrit, oh Eskôl jêh ri Aner. Phung aơ tâm rnglăp đah Y-Abram.$b$,true),
('bunong-vn','GEN',14,14,null,$b$Tơ lah Y-Abram tăng lư kon oh păng jêng bună jêh, păng rgum leo pe rhiăng jât ma pham nuyh păng hŏ nti jêh, phung bu deh tâm ngih păng, jêh ri tĭng phung rlăng tât ta ƀon Dan.$b$,true),
('bunong-vn','GEN',14,15,null,$b$Dôl măng Y-Abram tâm pă phung oh mon păng, dơi đah phung rlăng nây, jêh ri tĭng phung nây ta ƀon Hôba mpeh mơ dor ƀon Damas.$b$,false),
('bunong-vn','GEN',14,16,null,$b$Păng sŏk rgum lĕ rngôch drăp ndơ, păng sŏk sĭt Y-Lot kon oh păng tâm ban lĕ, nđâp ma drăp ndơ păng, nđâp ma phung bu ur jêh ri phung bunuyh êng.$b$,false),
('bunong-vn','GEN',14,17,null,$b$Jêh Y-Abram sĭt tă bơh nau dơi đah Y-Kêdôr Lomer jêh ri phung hađăch ndrel ma păng, hađăch ƀon Sôđôm luh hăn tâm mâp đah Y-Abram ta rlŭng Savê (nâm bu ntĭt rlŭng hađăch)$b$,true),
('bunong-vn','GEN',14,18,null,$b$Y-Mêlkisadek hađăch ƀon Salem ndjôt leo piăng let jêh ri dak play kriăk ƀâu. Y-Mêlkisadek jêng Kôranh ƀư brah ma Brah Ndu, Nơm Ta Klơ Lơn.$b$,false),
('bunong-vn','GEN',14,19,null,$b$Păng mât ton ma Y-Abram jêh ri lah: “Ăn Brah Ndu Nơm Klơ Lơn, Nơm Rhăk trôk jêh ri neh ntu mât ton ma Y-Abram.$b$,true),
('bunong-vn','GEN',14,20,null,$b$Jêh ri mât ton ma Brah Ndu, Nơm Klơ Lơn. Nơm jao jêh phung rlăng đah may tâm ti may.” Jêh ri Y-Abram ăn ma Y-Mêlkasadek du kô̆ tâm jât lĕ ndơ păng sŏk jêh.$b$,true),
('bunong-vn','GEN',14,21,null,$b$Hađăch ƀon Sôdôm lah ma Y-Abram: “Ăn bunuyh ma gâp jêh ri drăp ndơ dŏng ma may nơm.”$b$,false),
('bunong-vn','GEN',14,22,null,$b$Ƀiă lah Y-Abram lah ma hađăch ƀon Sôdôm: “Gâp ton sơm săk jêh ma Yêhôva Brah Ndu Nơm Klơ Lơn, nơm rlăk trôk jêh ri neh ntu.$b$,false),
('bunong-vn','GEN',14,23,null,$b$Gâp mâu mra sŏk ôh du mlâm nglai mâu lah du njăr rse kât ntâu jot, mâu lah du ntil ndơ may, klach lah may lah: ‘Gâp yơh n'hao ndrŏng Y-Abram’,$b$,false),
('bunong-vn','GEN',14,24,null,$b$gâp mra sŏk knŏng ndơ phung dôl mom sa jêh, jêh ri ndơ pă ma phung bunuyh hăn ndrel ma gâp; ăn Y-Aner, Y-Eskôl, jêh ri Y-Mamrê sŏk ndơ tâm pă ma khân păng.$b$,false),
('bunong-vn','GEN',15,1,null,$b$Jêh nau nây Yêhôva ngơi ma Y-Abram tâm nau tâm saơ, lơi klach ôh, Ơ Y-Abram. Gâp jêng khêl may, jêh ri nau nkhôm may toyh ngăn.”$b$,true),
('bunong-vn','GEN',15,2,null,$b$Ƀiă lah Y-Abram lah: “Ơ Kôranh Brah Yêhôva, moh ndơ may mra ăn ma gâp? Yor lah gâp ê geh kon ôh, jêh ri Y-Êliêser bơh ƀon Damas jêng nơm dơn drăp tâm ngih gâp.”$b$,false),
('bunong-vn','GEN',15,3,null,$b$Y-Abram lah: “Aơ, may mâu mâp ăn kon ma gâp ôh, jêh ri du huê dĭk bu deh tâm ngih gâp mra jêng nơm ndơn drăp gâp.”$b$,false),
('bunong-vn','GEN',15,4,null,$b$Jêh ri Yêhôva lah ma Y-Abram pô aơ: “Bunuyh nây mâu mra jêng nơm ndơn drăp may ôh, ƀiă lah kon bu klâu may nơm mra jêng nơm ndơn drăp may”.$b$,false),
('bunong-vn','GEN',15,5,null,$b$Păng njŭn leo Y-Abram pa dih jêh ri lah: “N'gơr măt ta klơ trôk jêh ri kơp mănh tơ lah may dơi.” Jêh ri lah ma Păng: “Tâm ban pô nây yơh kon sau may mra jêng,”$b$,false),
('bunong-vn','GEN',15,6,null,$b$Y-Abram chroh ma Yêhôva, jêh ri păng nkoch nau nây jêng nau sŏng srăng ma Y-Abram.$b$,false),
('bunong-vn','GEN',15,7,null,$b$Kôranh Brah lah ma păng: “Gâp jêng Yêhôva, nơm njŭn leo may tă bơh ƀon Ur tâm n'gor Kaldê, gay ăn may ndơn n'gor aơ,”$b$,true),
('bunong-vn','GEN',15,8,null,$b$Y-Abram lah: Ơ Kôranh Brah Yêhôva, mâm gâp mra gĭt ma gâp mra ndơn n'gor aơ?”$b$,false),
('bunong-vn','GEN',15,9,null,$b$Kôranh Brah lah ma Y-Abram: “Sŏk ăn ma gâp du mlâm ndrôk me geh pe năm, du mlâm be me pe năm, du mlâm biăp nkuăng pe năm, du mlâm plŭk jêh ri du mlâm ntơp.”$b$,false),
('bunong-vn','GEN',15,10,null,$b$Jêh ri Y-Abram sŏk lĕ rngôch ndơ nây, blah du đah đah jêh ri dơm ndơ păng du đah đah tâm ntrŭp pŭng ndrel; ƀiă lah mâu blah ôh sĭm.$b$,false),
('bunong-vn','GEN',15,11,null,$b$Tơ lah grât nđak jŭr văch ta mpa khĭt nây, Y-Abram ntrŭt lơi khân păng.$b$,false),
('bunong-vn','GEN',15,12,null,$b$Kêng nhâp nar Y-Abram lêt bêch; jêh ri aơ, geh nau klach toyh jêh ri nau ngo klĕng tât ma păng.$b$,true),
('bunong-vn','GEN',15,13,null,$b$Jêh ri Yêhôva lah ma Y-Abram: “Ăn may gĭt nanê̆ ma phung kon sau may mra gŭ tâm n'gor, mâu jêng n'gor khân păng nơm ôh; khân păng mra jêng dĭk ma phung nây, jêh ri phung nây mra tŭn jot khân păng dôl tâm puăn rhiăng năm.$b$,false),
('bunong-vn','GEN',15,14,null,$b$Ƀiă lah gâp mra phat dôih mpôl băl khân păng pah kan nây; jêh ri bah kơi ta nây khân păng luh du geh âk drăp ndơ.$b$,false),
('bunong-vn','GEN',15,15,null,$b$Ƀiă lah, lah may mra khĭt hăn gŭ ndrel ma phung che may ma nau đăp mpăn. Bu mra tâp may jêh may ranh ngăn.$b$,true),
('bunong-vn','GEN',15,16,null,$b$Ta rnôk tal puăn phung kon sau may mra plơ̆ sĭt ta aơ; yor lah nau kue phung Amôrit ê rĭng ôh.”$b$,true),
('bunong-vn','GEN',15,17,null,$b$Tơ lah nar nhâp geh nau ngo, nôk aơ, geh ŭnh năk luh nhhŭk jêh ri geh ŭnh rdo rgăn ta vah vang puăch mpa blah nây.$b$,false),
('bunong-vn','GEN',15,18,null,$b$Tâm nar nây Yêhôva ƀư nau tâm rnglăp đah Y-Abram, lah: “Gâp mra ăn n'gor aơ ma phung kon sau may, ntơm bơh dak krong n'gor Êjipt tât ta dak krong toyh, dak krong Ơphrat,$b$,false),
('bunong-vn','GEN',15,19,null,$b$n'gor phung Kênit, phung Kênisit, phung Katmônit.$b$,false),
('bunong-vn','GEN',15,20,null,$b$Phung Hitit, phung Pêrisit, phung Rêpham,$b$,false),
('bunong-vn','GEN',15,21,null,$b$phung Armôrit, phung Kanaan, phung Girgasit, jêh ri phung Jêbusit.$b$,false),
('bunong-vn','GEN',16,1,null,$b$H'Sarai ur Y-Abram mâu mâp deh kon ôh. Păng geh du huê oh mon bu ur Êjipt amoh păng H'Agar,$b$,true),
('bunong-vn','GEN',16,2,null,$b$H'Sarai lah ma Y-Abram: “Aơ, Yêhôva njêng gâp jêng du huê bu ur ndrô gâng (mâu bă kon;) hăn hom may gŭ ndrel đah bu ur oh mon bu ur gâp; năng ai gâp mra geh phung kon tă bơh păng.” Y-Abram tông bâr H'Sara.$b$,false),
('bunong-vn','GEN',16,3,null,$b$Jêh Y-Abram gŭ jât năm tâm n'gor Kanaan H'Sarai ur păng sŏk H'Agar oh mon păng, bu ur Êjipt, jêh ri ăn bu ur nây jêng ur ma sai păng Y-Abram,$b$,false),
('bunong-vn','GEN',16,4,null,$b$Y-Abram hăn gŭ ndrel ma H'Agar, jêh ri păng ntreo. Tơ lah H'Agar saơ păng nơm ntreo jêh, păng tâm rmot ma Kôranh bu ur păng.$b$,false),
('bunong-vn','GEN',16,5,null,$b$Jêh ri H'Sarai lah ma Y-Abram: “Ăn nau tih gâp tŭp ta may. Gâp jao an oh mon gâp tâm ntang ntơh may, jêh ri tơ lah păng ntreo jêh, păng tâm rmot ma gâp. Ăn Yêhôva phat dôih gâp đah may.”$b$,false),
('bunong-vn','GEN',16,6,null,$b$Ƀiă lah Y-Abram lah ma H'Sarai: “Aơ, ay jêng Kôranh ma oh mon bu ur ay, ƀư hom ma păng tĭng nâm nau mĭn ueh.” H'Sarai ƀư dăng đah păng, jêh ri du ƀah ngai đah muh măt H'Sarai.$b$,false),
('bunong-vn','GEN',16,7,null,$b$Tông mpăr ueh Yêhôva saơ păng ta tu dak tâm bri rdah, tu dak nây ta meng trong hăn ta n'gor Sur.$b$,true),
('bunong-vn','GEN',16,8,null,$b$Păng lah: Ơ H'Agar oh mon bu H'Sarai, mbah tă ay văch, jêh ri mbah ay leo hăn?” Păng lah: “Gâp du ƀah ngai đah muh măt H'Sarai, Kôranh bu ur gâp”$b$,false),
('bunong-vn','GEN',16,9,null,$b$Tông mpăr ueh Yêhôva lah ma păng: “Sĭt hom ta Kôranh bu ur ay, jêh ri tông bâr păng.”$b$,false),
('bunong-vn','GEN',16,10,null,$b$Tông mpăr ueh Yêhôva lah ma păng: “Gâp mra ăn bĭk phung kon sau ay kŏ bu mâu dơi kơp ôh.”$b$,false),
('bunong-vn','GEN',16,11,null,$b$Tông mpăr ueh Yêhôva lah ma păng: “Aơ, ay hŏ ntreo jêh; ay mra deh ma du huê kon bu klâu. Jêh ri ay mra tâm amoh păng Y-Ismaêl, yor lah Yêhôva tăng jêh nau rêh ni ay.$b$,false),
('bunong-vn','GEN',16,12,null,$b$Păng mra jêng nâm bu du mlâm seh bri; păng mra joi ƀư ma lĕ rngôch bunuyh jêh ri lĕ rngôch bunuyh mra joi ƀư ma păng, jêh ri păng mra gŭ êng đah lĕ rngôch phung oh nâu păng.’$b$,true),
('bunong-vn','GEN',16,13,null,$b$H'Agar ntơ amoh ma Yêhôva nơm ngơi đah păng nây: “May Jêng Brah Ndu Nơm Saơ.” Yor lah păng lah: “Ngăn hĕ gâp saơ ta aơ nơm saơ gâp?”$b$,false),
('bunong-vn','GEN',16,14,null,$b$Yor nây, bu rnha ntu dak nây Bêrla Hairôi; aơ, păng gŭ ta vah vang mbon Kadês jêh ri ƀon Bêret.$b$,false),
('bunong-vn','GEN',16,15,null,$b$H'Agar deh du huê kon bu klâu đah Y-Abram. Y-Abram tâm amoh kon bu klâu H'Agar deh nây Y-Ismaêl.$b$,true),
('bunong-vn','GEN',16,16,null,$b$Rnôk H'Agar deh ma Y-Ismaêl, Y-Abram geh pham jât ma prao năm jêh.$b$,false),
('bunong-vn','GEN',17,1,null,$b$Tơ lah Y-Abram geh sĭn jât ma sĭn năm, Yêhôva tâm mpơl ma Y-Abram, lah ma păng: “Gâp Jêng Brah Ndu Nơm Geh Lĕ Nau Brah, hăn hom ta năp gâp jêh ri ăn may jêng nơm mâu geh nau bu dơi nduyh ôh.$b$,true),
('bunong-vn','GEN',17,2,null,$b$Gâp mra ƀư nau tâm rnglăp đah may, jêh ri gâp mra ăn bĭk phung kon sau may âk ngăn.”$b$,false),
('bunong-vn','GEN',17,3,null,$b$Y-Abram chŭn măt ta neh, jêh ri Brah Ndu ngơi đah păng, lah:$b$,false),
('bunong-vn','GEN',17,4,null,$b$“Aơ, nau tâm rnglăp gâp ƀư đah may, may mra jêng mbơ̆ ma âk phung ntil mpôl băl.$b$,false),
('bunong-vn','GEN',17,5,null,$b$Bu mâu mra rnha amoh may Y-Abram ôh, ƀiă lah amoh may mra jêng Y-Abraham; h yor lah gâp njêng jêh may mbơ̆ ma âk phung ndŭl mpôl.$b$,false),
('bunong-vn','GEN',17,6,null,$b$Gâp mra ăn ma may geh âk kon sau, jêh ri gâp mra ngluh phung mpôl băl tă bơh may, jêh ri phung hađăch mra luh tă bah may.$b$,false),
('bunong-vn','GEN',17,7,null,$b$Gâp mra ƀư nâp nau tâm rnglăp gâp đah may jêh ri đah phung kon sau may ma kăndơ̆ tâm lĕ rnôk khân păng, jêng nau tâm rnglăp n'ho ro, ŭch jêng Brah Ndu ma may jêh ri ma phung kon sau may kăndơ̆ , n'gor may gŭ aơ tâm bri bu.$b$,false),
('bunong-vn','GEN',17,8,null,$b$Gâp mra ăn ma may ma kon sau may kăndơ̆ , lĕ n'gor Kanaan mra jêng ndơ may n'ho ro; jêh ri gâp mra jêng Brah Ndu khân păng.”$b$,false),
('bunong-vn','GEN',17,9,null,$b$Brah Ndu lah ma Y-Abraham: “Bi may, ăn may ndjôt prăp nau gâp tâm rnglăp, may jêh ri phung kon sau may kăndơ̆ .$b$,true),
('bunong-vn','GEN',17,10,null,$b$Pô aơ nau Gâp tâm rnglăp ăn may djôt prăp, nau tâm rnglăp Gâp ma may jêh ri ma phung kon sau may kăndơ̆ ăn lĕ rngôch phung bu klâu khân may dơn nau koh ntâu.$b$,false),
('bunong-vn','GEN',17,11,null,$b$Ăn khân may siăt ntâu ta chiông ndơ chrach (cho) bu klâu khân may, jêh ri nau nây mra jêng nau tâm mbên ma nau gâp tâm rnglăp đah khân may.$b$,false),
('bunong-vn','GEN',17,12,null,$b$Ăn khân may koh ntâu ăp nơm bu klâu ta nar tal pham jêh bu deh ma păng. Ăn khân may ƀư nau aơ tâm lĕ rngôch rnôk, đơ phung deh tâm ngih, mâu lah đơ phung bu rvăt ma prăk tă bơh phung bu năch mâu jêng kon may nơm ôh.$b$,false),
('bunong-vn','GEN',17,13,null,$b$Bu mra koh ntâu mbu nâm bu deh tâm ngih may, jêh ri mbu nâm bu rvăt ma prăk. Pô ri nau gâp tâm rnglăp mra tâm mpơl tâm săk jăn may jêng nau tâm rnglăp n'ho ro.$b$,false),
('bunong-vn','GEN',17,14,null,$b$Ăp nơm bu klâu mâu geh koh ntâu ôh tâm săk jăn păng bu mra nkhĭt lơi păng bơh phung ƀon lan păng; păng rlau jêh nau gâp tâm rnglăp.$b$,false),
('bunong-vn','GEN',17,15,null,$b$Brah Ndu lah ma Y-Abraham: “Bi H'Sarai ur may, may mâu mra hôm rnha amoh păng H'Sarai ôh, ƀiă lah amoh păng amoh jêng H'Sara.$b$,false),
('bunong-vn','GEN',17,16,null,$b$Gâp mra ăn nau ueh uĭn ma păng; păng mra jêng mê̆ ma âk phung ntil mpôl bunuyh; phung hađăch ma phung mpôl băl mra luh tă bơh păng.”$b$,false),
('bunong-vn','GEN',17,17,null,$b$Jêh ri Y-Abraham chŭn măt ta neh. Păng gơm, lah tâm nuih n'hâm păng: “Dơi lĕ deh du huê kon tă tâm nơm geh jêh du rhiăng năm? Dơi lĕ H'Sara ntreo, nơm geh jêh sĭn jât năm?’$b$,true),
('bunong-vn','GEN',17,18,null,$b$Y-Abraham lah ma Brah Ndu: “Ơ, ăn Y-Ismaêl gŭ rêh ta năp may.”$b$,false),
('bunong-vn','GEN',17,19,null,$b$Brah Ndu lah: “Mâu, ƀiă lah H'Sara ur may, mra deh du huê kon bu klâu ma may, jêh ri ăn may tâm amoh păng Y-Isăk; gâp mra ƀư nâp nau gâp tâm rnglăp đah may jêng nau tâm rnglăp n'ho ro ma phung kon sau păng kăndơ̆ .$b$,false),
('bunong-vn','GEN',17,20,null,$b$Bi ma Y-Ismaêl, gâp tăng nau may lah jêh. Aơ, gâp mra ăn nau ueh uĭn ma păng, jêh ri gâp mra ăn bĭk phung kon sau păng âk ngăn. Păng mra jêng mbơ̆ ma jât ma bar nuyh kon hađăch, jêh ri gâp mra ăn păng du mpôl băl toyh.$b$,false),
('bunong-vn','GEN',17,21,null,$b$Ƀiă lah nau gâp tâm rnglăp gâp mra ƀư nâp đah Y-Isăk nơm H'Sara mra deh ma may tâm yăn aơ năm ntaơ.”$b$,true),
('bunong-vn','GEN',17,22,null,$b$Tơ lah lôch nau ngơi đah Y-Abraham, Brah Ndu hao du bơh Y-Abraham.$b$,false),
('bunong-vn','GEN',17,23,null,$b$Jêh ri Y-Abraham sŏk Y-Ismaêl kon bu klâu păng, nđâp ma lĕ rngôch phung dĭk bu deh jêh tâm ngih păng, jêh ri lĕ rngôch phung rvăt jêh ma prăk păng, ăp nơm bu klâu tâm phung ngih Y-Abraham, jêh ri păng koh ntâu tâm nar nây đŏng, tĭng nâm Brah Ndu ntăm jêh ma păng.$b$,false),
('bunong-vn','GEN',17,24,null,$b$Y-Abraham geh sĭn jât ma sĭn năm tơ lah bu koh ntâu păng.$b$,false),
('bunong-vn','GEN',17,25,null,$b$Y-Ismaêl bu koh ntâu tâm rnôk păng jât ma pe năm.$b$,false),
('bunong-vn','GEN',17,26,null,$b$Nar nây lĕ Y-Abraham jêh ri Y-Ismaêl kon bu klâu păng, păng dơn nau koh ntâu.$b$,false),
('bunong-vn','GEN',17,27,null,$b$Jêh ri lĕ rngôch phung bu klâu bu deh tâm ngih păng, nđâp phung bu rvăt ma prăk bơh phung bu năch dơn da dê nau koh ntâu ndrel ma păng.$b$,false),
('bunong-vn','GEN',18,1,null,$b$Yêhôva tâm mpơl ma Y-Abraham ta tơm si Mamrê, dôl păng gŭ ta mpông lăp ngih bok dôl trôk duh nar,$b$,true),
('bunong-vn','GEN',18,2,null,$b$Păng n'gơr măt uănh jêh ri aơ, geh pe nuyh dâk gŭ râng ta năp păng, tơ lah păng saơ phung nây, păng nchuăt hăn tâm mâp đah phung nây tă mpông ngih bok jêh ri chon mon ta neh.$b$,false),
('bunong-vn','GEN',18,3,null,$b$Păng lah: “Ơ Kôranh Brah gâp, tơ lah may maak đah gâp, lơi du đah gâp oh mon may.$b$,false),
('bunong-vn','GEN',18,4,null,$b$Ăn bu sŏk leo djê̆ dak rao jâng khân may, jêh ri rlu hom khân may tâm dâng tơm si,$b$,false),
('bunong-vn','GEN',18,5,null,$b$dôl gâp sŏk njŭn leo ndơ sông sa gay ƀư dăng n'hâm ăn khân may, rĭ mơ khân may dơi hăn, yor nây khân may văch jêh ta gâp oh mon khân may.” Phung nây lah: “Ƀư hom nâm bu may hŏ lah jêh.”$b$,false),
('bunong-vn','GEN',18,6,null,$b$Y-Abraham ndal lăp tâm ngih bok, lah ma H'Sara: Nkra gơnh pe bĭ rnih môi, mon jêh ri ƀư hom ƀănh.$b$,true),
('bunong-vn','GEN',18,7,null,$b$Y-Abraham nchuăt sŏk njŭn du mlâm kon ndrôk nse jêh ri ueh jêh ri ăn ma oh mon; nơm nây ƀư puăch ro.$b$,false),
('bunong-vn','GEN',18,8,null,$b$Păng sŏk leo dak toh ndrôk ndrel ma kon ndrôk bu nkra jêh, jêh ri thai ma phung nây, păng gŭ râng ta meng phung nây tâm dâng tơm si dôl phung nây sa.$b$,false),
('bunong-vn','GEN',18,9,null,$b$Phung nây lah ma păng: “Mbah H'Sara ur may?” Păng lah: “Aơ, păng gŭ tâm ngih bok.”$b$,true),
('bunong-vn','GEN',18,10,null,$b$Du huê tâm phung nây lah: “Nanê̆ gâp mra plơ̆ văch ma may yăn aơ năm ntaơ, jêh ri H'Sara ur may mra deh ma du huê kon bu klâu.” H'Sara gŭ iăt tâm trôm mpông ngih bok pa kơi păng.$b$,false),
('bunong-vn','GEN',18,11,null,$b$Y-Abraham jêh ri H'Sara ranh jêh, jêh ri H'Sara mâu rnơm geh kon tĭng nâm nau vay phung bu ur.$b$,false),
('bunong-vn','GEN',18,12,null,$b$H'Sara gơm tâm nuih n'hâm păng, lah: “Gâp ranh jêh, jêh ri sai gâp ranh lĕ; mâm gâp dơi geh nau maak?”$b$,false),
('bunong-vn','GEN',18,13,null,$b$Yêhôva lah ma Y-Abraham: “Mâm ƀư H'Sara gơm jêh ri lah; ‘Ngăn lĕ gâp mra dơi geh du huê kon tơ lah gâp ranh jêh?’$b$,false),
('bunong-vn','GEN',18,14,null,$b$Geh lĕ nau jêr kŏ tât Yêhôva mâu dơi ƀư ôh? Tĭng nâm yăn tâm nal jêh gâp mra plơ̆ văch ta may tâm năm ntaơ, jêh ri H'Sara mra deh ma du huê kon bu klâu.”$b$,false),
('bunong-vn','GEN',18,15,null,$b$Ƀiă lah H'Sara dun, lah: “Gâp mâu mâp gơm ôh.” Yor lah păng klach, ƀiă lah Yêhôva lah: “Mâu, ay gơm jêh.”$b$,false),
('bunong-vn','GEN',18,16,null,$b$Phung bu klâu nây ntơm hăn, jêh ri uănh bơh ƀon Sôdôm, Y-Abraham hăn ndrel ma khân păng njŭn khân păng,$b$,true),
('bunong-vn','GEN',18,17,null,$b$Yêhôva lah: “Gâp mra pôn lĕ ma Y-Abraham mâm nau gâp mra ƀư?$b$,false),
('bunong-vn','GEN',18,18,null,$b$Yor lah Y-Abraham mra jêng du phung mpôl băl toyh jêh ri chăt jêng, lĕ rngôch phung mpôl bunuyh tâm neh ntu mra geh nau ueh uĭn tă tâm păng.$b$,false),
('bunong-vn','GEN',18,19,null,$b$Mâu, yor lah gâp săch păng jêh, gay ma păng ntăm jêh ri ma ngih păng kăndơ̆ , gay ma khân păng ndjôt prăp nau nti Yêhôva ƀư nau sŏng srăng jêh ri nau di, gay ma Yêhôva dơi ăn nanê̆ nau păng ton jêh ma Y-Abraham.”$b$,true),
('bunong-vn','GEN',18,20,null,$b$Jêh ri Yêhôva lah: “Yor lah nau vơl phong ƀon Sôdôm jêh ri ƀon Gômôrơ jêng toyh jêh ri nau tih khân păng mhĭk ngăn.$b$,false),
('bunong-vn','GEN',18,21,null,$b$Gâp mra jŭr jêh ri uănh, gĭt lah khân păng ƀư lĕ tĭng nâm nau vơl tât jêh ma gâp. Tơ lah mâu di pô nây ôh, gâp mra gĭt.”$b$,false),
('bunong-vn','GEN',18,22,null,$b$Phung bu klâu nây du jêh ri hăn rlet ma ƀon Sôđôm. Ƀiă lah Y-Abraham ăt gŭ râng ta năp Yêhôva.$b$,false),
('bunong-vn','GEN',18,23,null,$b$Y-Abraham hăn dăch jêh ri lah: “May mra ƀư rai lĕ phung sŏng ndrel ma phung ƀai?$b$,false),
('bunong-vn','GEN',18,24,null,$b$Bi tơ lah geh prăm jât nuyh sŏng tâm ƀon nây may mra ƀư rai lĕ, mâu yô̆ ôh ma ntŭk nây yor prăm jât nuyh sŏng tâm ntŭk nây?$b$,false),
('bunong-vn','GEN',18,25,null,$b$May mâu blau ƀư pô nây ôh, nkhĭt phung sŏng ndrel ma phung ƀai. Tơ lah pô nây nau tât ma phung sŏng jêng tâm ban ma nau tât ma phung ƀai. Mâu ôh Kôranh Brah mâu păng ƀư ôh nau pô nây, Mâu hĕ Kôranh phat dôih lĕ neh ntu mra ƀư nau di?”$b$,false),
('bunong-vn','GEN',18,26,null,$b$Yêhôva lah: “Tơ lah gâp saơ tâm ƀon Sôdôm prăm jât nuyh sŏng gâp mra yô̆ an lĕ ƀon nây yor khân păng.”$b$,false),
('bunong-vn','GEN',18,27,null,$b$Y-Abraham plơ̆ lah: “Aơ, gâp nơm nđâp lah jêng knŏng ndruyh neh ƀiă lah, janh ngơi ma Kôranh Brah.$b$,false),
('bunong-vn','GEN',18,28,null,$b$Bi tơ lah kƀah prăm nuyh tâm prăm jât nuyh sŏng nây? Yor kƀah prăm nuyh nây may mra tâm rmal lĕ, lĕ ƀon?” Jêh ri păng plơ̆ lah: “Gâp mâu mra ƀư rai ƀon ôh tơ lah gâp saơ ta nây puăn jât ma prăm nuyh sŏng.”$b$,false),
('bunong-vn','GEN',18,29,null,$b$Păng lah đŏng du tơ̆ , bi tơ lah mra geh puăn jât nuyh ta nây?” Jêh ri păng plơ̆ lah: “Gâp mâu mra ƀư ôh yor ma phung puăn jât nuyh nây.”$b$,false),
('bunong-vn','GEN',18,30,null,$b$Păng lah: “Ơ, Lơi ăn Kôranh Brah ji nuih, jêh ri gâp mra ngơi. Bi tơ lah geh pe jât nuyh ta nây?” Păng lah: “Gâp mâu mra ƀư ôh tơ lah gâp saơ pe jât nuyh ta nây.”$b$,false),
('bunong-vn','GEN',18,31,null,$b$Păng lah: “Aơ, gâp mra nănh janh ngơi đah Kôranh Brah. Bi tơ lah mra geh bar jât nuyh ta nây?” Păng lah: “Gâp mâu mra ƀư rai ƀon ôh yor phung bar jât nuyh,”$b$,false),
('bunong-vn','GEN',18,32,null,$b$Păng lah: “Ơ, Lơi ăn Kôranh Brah ji nuih ôh, jêh ri gâp mra ngơi đŏng knŏng du tơ̆ , Bi tơ lah mra geh jât nuyh ta nây?” Păng lah: “Gâp mâu mra ƀư rai ƀon ôh yor phung jât nuyh.”$b$,true),
('bunong-vn','GEN',18,33,null,$b$Yêhôva hăn du tơ lah jêh lôch tâm ngơi đah Y-Abraham, jêh ri Y-Abraham sĭt ta ntŭk păng.$b$,false),
('bunong-vn','GEN',19,1,null,$b$Ta mhaơ bar hê tông mpăr ueh nây tât ta ƀon Sôdôm; jêh ri Y-Lot gŭ ta mpông pêr ƀon Sôdôm. Tơ lah Y-Lot saơ bar hê tông mpăr păng dâk hăn ŭch tâm mâp ma khân păng, jêh ri păng chŭn măt ta neh.$b$,true),
('bunong-vn','GEN',19,2,null,$b$Păng lah: “Aơ, Ơ phung Kôranh gâp ơi, gâp vơh vơl ma khân may teng hom, lăp gŭ bêch tâm ngih gâp oh mon khân may. Rao hom jâng khân may jêh ri ơm ôi, ôi taơ khân may dơi dâk jêh ri dâk hăn.” Khân păng lah: “Ơ ơh hên mra gŭ ta trong măng aơ.”$b$,false),
('bunong-vn','GEN',19,3,null,$b$Y-Lot nchâp ngăn khân păng, pô ri khân păng teng lăp tâm ngih păng. Păng nkra an ma phung nây ndơ sông sa. Jêh ri păng gŭch nđông piăng let mâu geh ndrui ôh, jêh ri khân păng sông sa.$b$,false),
('bunong-vn','GEN',19,4,null,$b$Ê khân păng lâng săk ôh, phung bu klâu ƀon lan ƀon Sôdôm nchueng jŭm ngih, phung mom ndăm nđâp phung bu ranh lĕ rngôch bunuyh ƀon lan.$b$,false),
('bunong-vn','GEN',19,5,null,$b$Khân păng kuăl Y-Lot jêh ri lah: “Mbah phung bu klâu văch jêh ngih may măng aơ? Njŭn khân păng ma hên gay ma hên dơi gĭt khân păng.”$b$,false),
('bunong-vn','GEN',19,6,null,$b$Y-Lot du luh hăn ta khân păng jêh ri chăng lơi mpông pa kơi păng.$b$,false),
('bunong-vn','GEN',19,7,null,$b$Păng lah: “Gâp dăn ma khân may, ơ phung oh nâu, lơi ƀư nau ƀai pô aơ ôh.$b$,false),
('bunong-vn','GEN',19,8,null,$b$Aơ gâp geh bar hê kon bu ur ê mâp gŭ đah bu klâu ôh; gâp njŭn khân păng ma khân may, jêh ri ăn khân may ƀư ma khân păng tĭng nâm khân may ŭch. Ƀiă lah lơi ta khân may ƀư ôh ma phung bu klâu nây, yor lah khân păng jưh mbe ngih gâp.”$b$,false),
('bunong-vn','GEN',19,9,null,$b$Phung nây lah: “Du hom may. Nơm aơ văch gŭ jăng jai, ƀiă lah păng ŭch jêng phung phat dôih. Pô ri hên mra ƀư mhĭk ma may âk lơn ma khân păng.” Jêh ri khân păng tŭn Y-Lot ktang ngăn. Khân păng hăn dăch ŭch ƀư chah mpông.$b$,false),
('bunong-vn','GEN',19,10,null,$b$Ƀiă lah phung bu klâu gŭ tâm ngih Y-Lot nây yơr ti mphâk Y-Lot lăp tâm ngih ndrel ma khân păng, jêh ri chăng mpông.$b$,false),
('bunong-vn','GEN',19,11,null,$b$Khân păng ƀư chieh măt phung bunuyh ta mpông ngih, phung jê̆ nđâp ma toyh, kŏ khân păng rgănh joi mpông.$b$,false),
('bunong-vn','GEN',19,12,null,$b$Jêh ri phung tông mpăr nây lah ma Y-Lot: “May lŏ hôm geh nơm êng lĕ tâm aơ?” Klay may, phung kon bu klâu, phung kon bu ur, mâu lah mbu nâm may geh tâm ƀon aơ, ngluh lơi khân păng bơh ƀon aơ,$b$,false),
('bunong-vn','GEN',19,13,null,$b$Yor lah hên mra ntơm ƀư rai ntŭk aơ, yor lah nau nter phong ƀon aơ ta năp Yêhôva; jêh ri Yêhôva njuăl hên văch gay ƀư rai ƀon.”$b$,false),
('bunong-vn','GEN',19,14,null,$b$Y-Lot hăn lah ma klay păng, phung bu klâu hŏ tâm văng jêng ndrôi đah lĕ kon bu ur păng. “Dâk hom khân may, du luh tă bơh ntŭk aơ; yor lah Yêhôva mra ƀư rai ƀon aơ.” Ƀiă lah phung klay păng mĭn ma Y-Lot mưch ma khân păng.$b$,false),
('bunong-vn','GEN',19,15,null,$b$Ơm ôi phung tông mpăr ntrŭt Y-Lot, lah: “Dâk hom may, sŏk ur may jêh ri bar hê kon bu ur may geh ta aơ, klach lah khân may rai ndrel ma nau tâm rmal ƀon aơ.”$b$,true),
('bunong-vn','GEN',19,16,null,$b$Ƀiă lah păng ƀư jâk; jêh ri phung nây têk ta ti păng, ur păng, jêh ri bar hê kon bu ur păng, yor lah Yêhôva yô̆ ma păng. Phung nây njŭn khân păng ta mpâr ƀon.$b$,true),
('bunong-vn','GEN',19,17,null,$b$Jêh khân ngluh lơi phung nây, jêh ri lah; “Du hom gay ma tâm rklaih nau rêh khân ay may. Lơi n'gĭl uănh pa kơi mâu lĕ dơi gŭ tâm lĕ ntŭk Neh Lâng, du ta yôk klach lah geh rai nđâp ma khân ay may.$b$,true),
('bunong-vn','GEN',19,18,null,$b$Y-Lot lah ma phung tông mpăr: “Ơ ơh, Ơ phung Kôranh gâp.$b$,false),
('bunong-vn','GEN',19,19,null,$b$Aơ, gâp oh mon khân may geh jêh nau yô̆ ta năp khân may, jêh ri khân may ƀư jêh nau ueh ngăn ma gâp tâm nau khân may tâm rklaih nau rêh gâp. Ƀiă lah gâp mâu dơi du ta yôk ôh, klach lah nau mhĭk ban gâp jêh ri gâp mra khĭt;$b$,false),
('bunong-vn','GEN',19,20,null,$b$Aơ, ƀon bri hađăch jêh ri jêng du ƀon jê̆; jêh ri gâp dơi du krap ta nây. Păng mâu jêng ƀon jê̆ ôh hĕ? Pô ri nau rêh gâp mra klaih,”$b$,false),
('bunong-vn','GEN',19,21,null,$b$Tông mpăr lah ma Y-Lot, Ơ gâp dơn lĕ nau may dăn aơ, jêh ri gâp mâu mra ƀư rai ôh ƀon may lah nây.$b$,true),
('bunong-vn','GEN',19,22,null,$b$Hăn gơnh hom may, du ta nây; yor lah gâp mâu mra ƀư du ntil nau ôh kŏ may tât ta nây.” Yor ri bu rnha ƀon nây Sôar.$b$,false),
('bunong-vn','GEN',19,23,null,$b$Nar luh jêh tơ lah Y-Lot tât ta ƀon Sôar.$b$,false),
('bunong-vn','GEN',19,24,null,$b$Rnôk nây Yêhôva ăn mih lŭ mô ŭnh jêh ri ŭnh tŭp ta ƀon Sôdôm jêh ri ƀon Gômôrơ bơh Yêhôva tă klơ trôk.$b$,false),
('bunong-vn','GEN',19,25,null,$b$Păng ƀư rai ƀon nây jêh ri lĕ Neh Lâng, lĕ rngôch bunuyh gŭ tâm ƀon nây, nđâp ma ndơ hon ta neh.$b$,true),
('bunong-vn','GEN',19,26,null,$b$Ƀiă lah ur Y-Lot n'gĭl uănh pa kơi, jêh ri păng jêng meh gâng boh.$b$,false),
('bunong-vn','GEN',19,27,null,$b$Y-Abraham hăn ơm ôi ta ntŭk păng gŭ sa ơm ri ta năp Yêhôva.$b$,true),
('bunong-vn','GEN',19,28,null,$b$Păng uănh mpeh ƀon Sôdôm, ƀon Gômôrơ jêh ri lĕ Neh Lâng. Aơ, păng saơ nhhŭk ŭnh năk toyh.$b$,false),
('bunong-vn','GEN',19,29,null,$b$Tơ lah Brah Ndu ƀư rai ƀon tâm Neh Lâng, Brah Ndu kah gĭt ma Y-Abraham, jêh ri ngluh Y-Lot tă bơh tâm nklang nau tâm rmal ƀư rai nây tơ lah păng ƀư rai ƀon Y-Lot gŭ kăl e ri.$b$,true),
('bunong-vn','GEN',19,30,null,$b$Y-Lot du tă bơh ƀon Sôar jêh ri gŭ tâm yôk ndrel ma bar hê kon bu ur păng, yor lah păng klach gŭ tâm ƀon Sôar. Pô ri păng gŭ tâm trôm yôk ndrel ma bar hê kon bu ur păng.$b$,true),
('bunong-vn','GEN',19,31,null,$b$Nur păng lah ma oh păng: “Mbơ̆ he ranh jêh, jêh ri mâu hôm geh ôh bu klâu ta neh ntu dơi gŭ ndrel ma he tĭng nâm nau vay lĕ neh ntu.$b$,false),
('bunong-vn','GEN',19,32,null,$b$Lŏng he n'hơk mbơ̆ he ma dak play kriăk ƀâu, jêh ri he mra bêch đah păng, gay ma prăp mpôl đah păng”$b$,false),
('bunong-vn','GEN',19,33,null,$b$khân păng n'hơk ăn bơ̆ khân păng nhêt dak play kriăk ƀâu măng nây. Nur păng hăn bêch ndrel ma mbơ̆ păng; ƀiă lah Y-Lot mâu gĭt ôh ndah jŏ păng hăn bêch, mâu lĕ dơi gĭt ndah jŏ păng dâk du.$b$,false),
('bunong-vn','GEN',19,34,null,$b$Ôi taơ Nur păng lah ma oh păng: “Gâp bêch jêh măng aơ ndrel mbơ̆ gâp. Ăn he n'hơk ăn păng nhêt dak play kriăk ƀâu đŏng măng ta oi, jêh ri ay mra bêch ndrel ma păng, gay ma he dơi prăp mpôl đah mbơ̆ he.”$b$,false),
('bunong-vn','GEN',19,35,null,$b$Khân păng n'hơk mbơ̆ khân păng ma dak play kriăk ƀâu măng nây. Oh păng hăn bêch ndrel ma mbơ̆ păng ƀiă lah Y-Lot mâu gĭt ôh ndah jŏ păng hăn ƀiă lah Y-Lot mâu gĭt ôh ndah jŏ păng hăn bêch, mâu gĭt lĕ ndah jŏ păng dâk.$b$,false),
('bunong-vn','GEN',19,36,null,$b$Pô ri yơh lĕ bar hê kon bu ur Y-Lot ntreo đah mbơ̆ khân păng nơm.$b$,false),
('bunong-vn','GEN',19,37,null,$b$Nur păng deh ma du huê kon bu klâu, jêh ri tâm amoh păng Môap tât aƀaơ.$b$,false),
('bunong-vn','GEN',19,38,null,$b$Oh păng deh ma du huê kon bu klâu lĕ, jêh ri tâm amoh Ben Ami; nơm nây jêng mbơ̆ ma phung Amôn tât aƀaơ.$b$,false),
('bunong-vn','GEN',20,1,null,$b$Y-Abraham dâk tă bơh nây hăn ta n'gor Nêgep. Mpeh Rđŭng păng gŭ vah vang ƀon Kadês jêh ri n'gor Sur, jêh ri păng gŭ ƀât lât ta n'gor Gêrar.$b$,true),
('bunong-vn','GEN',20,2,null,$b$Bi ur păng H'Sara, Braham lah: “Păng jêng oh bu ur gâp.” Y-Abimêlek hađăch ƀon Gêrar njuăl bu nhŭp H'Sara.$b$,false),
('bunong-vn','GEN',20,3,null,$b$Ƀiă lah dôl măng Brah Ndu tâm mpơl ma Y-Abimêlek tâm nau mbơi, jêh ri lah ma păng: “Aơ may mra khĭt yor bu ur may nhŭp jêh, yor lah păng jêng ur bu.”$b$,false),
('bunong-vn','GEN',20,4,null,$b$Y-Abimêlek ê mâp hăn dăch păng ôh, Păng lah: “Ơ Kôranh Brah may mra ƀư rai lĕ mpôl băl sŏng srăng?”$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','GEN',20,5,null,$b$Mâu di hĕ păng nơm lah ma gâp: “Păng jêng oh bu ur gâp?” Jêh ri păng nơm lah: “Păng jêng nâu gâp. Gâp ƀư jêh nau aơ đah nuih n'hâm sŏng jêh ri ti mâu geh tih ôh.”$b$,false),
('bunong-vn','GEN',20,6,null,$b$Brah Ndu lah ma păng tâm nau mbơi: “Nanê̆ gâp gĭt ma nuih n'hâm may sŏng may ƀư jêh nau aơ. Gâp lĕ n'gang, mâu ăn may ƀư tih đah gâp ôh; pô ri gâp mâu ăn may pah păng ôh.$b$,false),
('bunong-vn','GEN',20,7,null,$b$Pô ri, aƀaơ mplơ̆ hom ma bu klâu nây ur păng, yor lah păng jêng du huê Kôranh nơm mbơh lor. Păng mra mbơh sơm ma may, jêh ri may mra gŭ rêh. Ƀiă lah tơ lah may mâu mplơ̆ lơi păng, ăn may gĭt, may mra khĭt ngăn, nđâp ma lĕ rngôch bunuyh tâm ngih may.$b$,false),
('bunong-vn','GEN',20,8,null,$b$Y-Abimêlek, dâk ơm ôi. Păng kuăl lĕ rngôch phung oh mon păng jêh ri nkoch lĕ nau nây. Phung oh mon păng klach hâu ngăn.$b$,true),
('bunong-vn','GEN',20,9,null,$b$Y-Abimêlek kuăl Y-Abraham jêh ri lah: “Moh nau may ƀư jêh ma hên? Moh nau tih gâp ƀư jêh đah may kŏ may ƀư tât jêh nau tih toyh ma gâp jêh ri ma ƀon bri hađăch gâp? May ƀư jêh ma gâp nâm bu nau bu mâu vay ƀư ôh.”$b$,false),
('bunong-vn','GEN',20,10,null,$b$Y-Abimêlek lah ma Y-Abraham: “Moh nau may mĭn kŏ may ƀư pô nây lĕ?”$b$,false),
('bunong-vn','GEN',20,11,null,$b$Y-Abraham lah: “Yor gâp mĭn tâm n'gor aơ mâu mâp geh nau klach ma Brah Ndu ôh, jêh ri bu mra nkhĭt gâp yor ma ur gâp.$b$,false),
('bunong-vn','GEN',20,12,null,$b$Ƀiă lah nanê̆ păng jêng oh bu ur gâp, kon bu ur mbơ̆ gâp; ƀiă lah păng mâu jêng kon bu ur me gâp jêh ri păng jêng ur gâp jêh.$b$,false),
('bunong-vn','GEN',20,13,null,$b$Tơ lah Brah Ndu ăn gâp nsong ngai bơh ngih mbơ̆ gâp, gâp lah ma păng: “Aơ nau ueh may mra ăn ma gâp tâm ăp ntŭk he hăn, ăn may lah, păng jêng nâu gâp,”$b$,false),
('bunong-vn','GEN',20,14,null,$b$Y-Abimêlek sŏk âk biăp, ndrôk, phung oh mon bu klâu jêh ri phung oh mon bu ur, jêh ri ăn ma Y-Abraham, jêh ri mplơ̆ lơi ur păng H'Sara.$b$,false),
('bunong-vn','GEN',20,15,null,$b$Y-Abimêlek lah: “Aơ, n'gor gâp gŭ ta năp may; gŭ hom ta ntŭk may ŭch.”$b$,false),
('bunong-vn','GEN',20,16,null,$b$Păng lah ma H'Sara: “Aơ, gâp ăn jêh ma nâu ay du glo prăk, prăk nây mra jêng ndơ nanê̆ ma ay jêng sŏng ta năp lĕ rngôch bunuyh bu mra kơp ay jêng sŏng.”$b$,false),
('bunong-vn','GEN',20,17,null,$b$Y-Abraham mbơh sơm ma Brah Ndu, jêh ri Brah Ndu ƀư bah Y-Abimêlek, ur păng jêh ri phung oh mon bu ur păng jêh ri khân păng deh kon.$b$,false),
('bunong-vn','GEN',20,18,null,$b$Yor lah Yêhôva ăn jêh lĕ ngih Y-Abimêlek jêng dŭt bă yor H'Sara ur Y-Abraham.$b$,false),
('bunong-vn','GEN',21,1,null,$b$Yêhôva kơl H'Sara nâm bu nau păng hŏ lah jêh, jêh ri Yêhôva ăn ma H'Sara nau păng ton jêh.$b$,true),
('bunong-vn','GEN',21,2,null,$b$H'Sara ntreo jêh ri deh ma du huê kon bu klâu ma Y-Abraham tơ lah păng ranh, di tĭng nâm năm Brah Ndu ngơi jêh ma păng.$b$,false),
('bunong-vn','GEN',21,3,null,$b$Y-Abraham amoh Y-Isăk kon bu klâu H'Sara deh ma păng.$b$,true),
('bunong-vn','GEN',21,4,null,$b$Y-Abraham keh ntâu Y-Isăk kon bu klâu păng tâm nar pham tĭng nâm Brah Ndu ntăm jêh ma păng.$b$,false),
('bunong-vn','GEN',21,5,null,$b$Y-Abraham geh du rhiăng năm jêh tơ lah tơ lah bu deh ma Y-Isăk kon bu klâu păng.$b$,false),
('bunong-vn','GEN',21,6,null,$b$H'Sara lah: “Brah Ndu ăn gâp gơm; lĕ rngôch mbu nâm tăng mra gơm ndrel ma gâp.”$b$,false),
('bunong-vn','GEN',21,7,null,$b$Păng lah: “Mbu nâm dơi lah ma Y-Abraham, ma H'Sara ăn pu phung kon? Ƀiă lah gâp deh jêh du huê kon bu klâu ma păng tơ lah păng ranh.”$b$,false),
('bunong-vn','GEN',21,8,null,$b$Kon se nây văch ma toyh jêh ri păng cha lơi pu toh. Y-Abraham ƀư nau sông sa toyh nar Y-Isăk cha lơi toh.$b$,true),
('bunong-vn','GEN',21,9,null,$b$H'Sara saơ kon bu klâu H'Agar, bu ur Êjipt deh ma Y-Abraham, gơm mưch.$b$,false),
('bunong-vn','GEN',21,10,null,$b$Pô ri păng lah ma Y-Abraham, mprơh lơi bu ur aơ jêh ri kon bu klâu păng, yor lah kon bu klâu bu ur aơ mâu mra dơi ndơn drăp ôh ndrel ma Y-Isăk kon bu klâu gâp;$b$,false),
('bunong-vn','GEN',21,11,null,$b$Nau nây rngot hâu ngăn ma Y-Abraham yor kon bu klâu păng.$b$,false),
('bunong-vn','GEN',21,12,null,$b$Ƀiă lah Brah Ndu lah ma Y-Abraham: “Lơi rngot ôh yor kon bu klâu jêh ri me păng. Lĕ moh nau H'Sara lah ma may.$b$,false),
('bunong-vn','GEN',21,13,null,$b$Gâp mra njêng lĕ ma kon bu klâu bu ur yông may du phung mpôl băl, yor lah păng jêng kon may.”$b$,false),
('bunong-vn','GEN',21,14,null,$b$Pô ri Y-Abraham dâk ơm ôi, sŏk piăng let jêh ri, du nông dak, ăn ma H'Agar dơm ta săng nglik. Păng ăn kon jêh ri ăn păng hăn. H'Agar hăn jêh ri nsong mblêng tâm ndrêch rdah Bêr Sêba.$b$,false),
('bunong-vn','GEN',21,15,null,$b$Tơ lah lĕ jêh dak tâm nông păng cha lơi kon păng tâm ƀŭr.$b$,false),
('bunong-vn','GEN',21,16,null,$b$Jêh ri păng hăn gŭ ngai djê̆ đah kon păng du bông pănh hăr; yor lah păng lah: “Lơi ăn gâp saơ ôh kon gâp khĭt” Dôl păng gŭ ngai đah kon păng, păng nhĭm nter.$b$,true),
('bunong-vn','GEN',21,17,null,$b$Brah Ndu tăng bâr kon se ndăm nhĭm jêh ri tông mpăr ueh Brah Ndu tă bơh trôk kuăl H'Agar lah ma păng: “Mâm ƀư ay rŭng răng ơ H'Agar? Lơi klach ôh yor lah Brah Ndu tăng jêh bâr kon se ndăm jê̆ nter ta ntŭk păng gŭ.$b$,false),
('bunong-vn','GEN',21,18,null,$b$Dâk hom ay pư kon ay chông tâm ti ay; yor lah gâp mra ăn păng du mpôl băl toyh.”$b$,false),
('bunong-vn','GEN',21,19,null,$b$Brah Ndu pơk măt păng jêh ri păng saơ du ntu dak. Păng hăn bâk bêng nông păng, jêh ri păng ăn kon păng nhêt.$b$,false),
('bunong-vn','GEN',21,20,null,$b$Brah Ndu gŭ ndrel ma kon se ndăm nây, jêh ri păng văch ma toyh. Păng gŭ tâm bri rdah păng jêng bunuyh rtăp ti pănh na.$b$,false),
('bunong-vn','GEN',21,21,null,$b$Păng gŭ tâm bri rdah Paran, jêh ri me păng săch du huê bu ur bơh n'gor Êjipt jêng ur păng.$b$,true),
('bunong-vn','GEN',21,22,null,$b$Rnôk nây Y-Abimêlek ndrel ma Kôranh ta han păng Pikôl lah ma Y-Abraham: “Brah Ndu gŭ ndrel ma may tâm lĕ kan may ƀư.$b$,true),
('bunong-vn','GEN',21,23,null,$b$Yor nây aƀaơ aơ ăn may sơm ton ma gâp ta aơ ma amoh Brah Ndu may mâu mra ndơm gâp ôh, phung kon gâp mâu lĕ, jêh ri phung kon sau gâp mâu lĕ. Ƀiă lah nâm bu gâp ƀư răp jăp jêh đah may ăn may mra ƀư răp jăp đah gâp tâm ban lĕ jêh ri ma n'gor may gŭ jưh ƀât lât aơ.”$b$,true),
('bunong-vn','GEN',21,24,null,$b$Y-Abraham lah: “Gâp sơm ton”.$b$,true),
('bunong-vn','GEN',21,25,null,$b$Y-Abraham nduyh Y-Abimêlek yor nau phung oh mon Y-Abimêlek pit lơi du mlâm ntu dak.$b$,true),
('bunong-vn','GEN',21,26,null,$b$Y-Abimêlek lah: “Gâp mâu gĭt ôh mbu ƀư nau nây mâu lĕ may mbơh ma gâp, mâu lĕ gâp tăng nau aơ lor ma nar aơ.”$b$,false),
('bunong-vn','GEN',21,27,null,$b$Pô ri Y-Abraham sŏk âk biăp jêh ri ndrôk jêh ri ăn ma Y-Abimêlek jêh ri bar hê khân păng ƀư nau tâm rnglăp.$b$,false),
('bunong-vn','GEN',21,28,null,$b$Y-Abraham sŏk ăn êng pơh mlâm kon biăp me.$b$,false),
('bunong-vn','GEN',21,29,null,$b$Y-Abimêlek lah ma Y-Abraham: “Mâm ƀư may ăn êng pơh mlâm biăp me aơ?”$b$,false),
('bunong-vn','GEN',21,30,null,$b$Păng lah, ăn may dơn tă bơh ti gâp pơh mlâm kon biăp me aơ.”$b$,false),
('bunong-vn','GEN',21,31,null,$b$Yor ri bu rnha ntŭk nây Bêr Sêba. Yor ta nây yơh lĕ khân păng bar he sơm ton.$b$,false),
('bunong-vn','GEN',21,32,null,$b$Pô ri khân păng ƀư nau tâm rnglăp ta Bêr Sêba. Y-Abimêlek jêh ri Kôranh ta han păng Pikôl hăn sĭt ta n'gor phung Philistin.$b$,true),
('bunong-vn','GEN',21,33,null,$b$Y-Abraham tăm du tơm si tamarik ta Bêr Sêba, jêh ri ta nây păng kuăl mbơh sơm ma amoh Yêhôva, Brah Ndu Nơm Gŭ Rêh N'ho Ro.$b$,true),
('bunong-vn','GEN',21,34,null,$b$Y-Abraham gŭ jŏ nar tâm n'gor phung Philistin.$b$,false),
('bunong-vn','GEN',22,1,null,$b$Jêh nau nây Brah Ndu rlong uănh Y-Abraham, jêh ri lah ma păng: “Ơ Y-Abraham”, Păng lah: “Aơ, ta aơ gâp”.$b$,true),
('bunong-vn','GEN',22,2,null,$b$Brah Ndu lah, sŏk hom kon may, kon may geh knŏng du huê, Y-Isăk nơm may rŏng hăn hom ta n'gor Môria ta nây ăn may nhhơr păng jêng ndơ nhhơr gŭch ta klơ du rplay yôk gâp mra ntĭm ma may.$b$,true),
('bunong-vn','GEN',22,3,null,$b$Y-Abraham dâk ơm ôi, păng dăp ưn seh bri păng jêh ri păng jă hăn ndrel ma păng bar hê oh mon bu klâu păng jêh ri nđâp ma kon păng Y-Isăk. Păng chôk long prăp ma ndơ nhhơr gŭch, jêh ri dâk leo hăn ta ntŭk Brah Ndu ntĭm jêh ma păng.$b$,true),
('bunong-vn','GEN',22,4,null,$b$Nar tal pe Y-Abraham n'gơr măt jêh ri saơ ntŭk nây bơh ngai.$b$,false),
('bunong-vn','GEN',22,5,null,$b$Jêh ri Y-Abraham lah ma phung oh mon bu klâu păng. “Gŭ hom khân may ta aơ ndrel ma seh bri. Gâp jêh ri bu klâu ndăm mra hăn tât ta ri. Hên mra mbah yơk jêh ri plơ̆ sĭt ma khân may.$b$,false),
('bunong-vn','GEN',22,6,null,$b$Y-Abraham sŏk long prăp ma nhhơr gŭch, bun ta klơ Y-Isăk kon păng. Ti păng ndjôt pêih jêh ri ŭnh. Lĕ bar hê khân păng hăn ndrel.$b$,false),
('bunong-vn','GEN',22,7,null,$b$Y-Isăk lah ma Y-Abraham mbơ̆ păng: “Ơ mbơ̆ ” Y-Abraham lah: “Aơ, ta aơ ŭnh jêh ri long, ƀiă lah mbah kon biăp prăp ma ndơ nhhơr gŭch?”$b$,false),
('bunong-vn','GEN',22,8,null,$b$Y-Abraham lah: “Ơ nâu, Brah Ndu nơm mra ăn kon biăp prăp ma ndơ nhhơr gŭch.” Pô ri lĕ khân păng bar hê hăn ndrel.$b$,false),
('bunong-vn','GEN',22,9,null,$b$Tơ lah khân păng tât jêh ta ntŭk Brah Ndu ntĭm jêh ma păng, Y-Abraham rdâk ta nây nơng ƀư brah, jêh ri păng dăp long. Păng chăp Y-Isăk kon bu klâu păng, jêh ri dơm păng ta klơ nơng ƀư brah ta klơ long.$b$,true),
('bunong-vn','GEN',22,10,null,$b$Y-Abraham yơr ti păng sŏk pêih gay ma nkhĭt kon păng.$b$,false),
('bunong-vn','GEN',22,11,null,$b$Ƀiă lah tông mpăr ueh Yêhôva kuăl păng tă bơh trôk, lah: “Y-Abraham, Ơ Y-Abraham” Păng lah: “Aơ ta aơ gâp”$b$,false),
('bunong-vn','GEN',22,12,null,$b$Tông mpăr ueh lah: “Lơi ƀư tât ti may ma kon se bu klâu nây ôh, mâu lĕ dơi ƀư du ntil nau ma păng; yor lah aƀaơ aơ gâp gĭt may klach yơk mbah ma Brah Ndu; yor lah may mâu nhhuach ôh kon may ma gâp, knŏng du huê nây.”$b$,false),
('bunong-vn','GEN',22,13,null,$b$Y-Abraham n'gơr uănh, jêh ri aơ pa kơi păng geh du mlâm biăp nkuăng iang nke tâm ƀŭr. Y-Abraham hăn sŏk biăp nkuăng nây jêh ri nhhơr păng jêng ndơ nhhơr gŭch ntrok kon păng.$b$,true),
('bunong-vn','GEN',22,14,null,$b$“Y-Abraham rnha ntŭk nĕ, “Yêhôva mra ăn;” yor nây yơh bu lah tât ta nar aơ. “Ta yôk Yêhôva bu mra ăn.”$b$,false),
('bunong-vn','GEN',22,15,null,$b$Tông mpăr ueh Yêhôva kuăl Y-Abraham tă bơh trôk du tơ̆ đŏng,$b$,true),
('bunong-vn','GEN',22,16,null,$b$jêh ri lah: “Gâp sơm ton đah gâp nơm, Yêhôva lah, yor lah may ƀư jêh nau aơ jêh ri mâu nhhuach ôh kon may, knŏng du huê nây,$b$,false),
('bunong-vn','GEN',22,17,null,$b$gâp mra ăn nau ueh uĭn ma may, jêh ri gâp mra ƀư bĭk kon sau may nâm bu mănh tâm trôk jêh ri nâm bu choih ta kơh dak mƀŭt. Jêh ri phung kon sau may mra dơi đah phung rlăng khân păng.$b$,false),
('bunong-vn','GEN',22,18,null,$b$Lĕ rngôch phung mpôl băl tâm neh ntu mra geh nau ueh uĭn yor phung kon sau may, yor lah may tông jêh bâr gâp.”$b$,false),
('bunong-vn','GEN',22,19,null,$b$Pô ri Y-Abraham plơ̆ sĭt ta phung oh mon bu klâu păng. Khân păng dâk hăn ndrel ta ƀon Bêr Sêba; jêh ri Y-Abraham gŭ ta ƀon Bêr Sêba.$b$,false),
('bunong-vn','GEN',22,20,null,$b$Jêh nau nây bu mbơh ma Y-Abraham, lah: “Aơ H'Milka tâm ban lĕ deh jêh phung kon ma Y-Nahôr, oh may;$b$,true),
('bunong-vn','GEN',22,21,null,$b$Y-Us kon deh bôk rah ma păng, Y-Bus oh păng. Y-Kêmuêl mbơ̆ Y-Aram.$b$,false),
('bunong-vn','GEN',22,22,null,$b$Y-Keset, Y-Hasô, Y-Pildas, Y-Jitlap jêh ri Y-Bêthel.$b$,false),
('bunong-vn','GEN',22,23,null,$b$Y-Bêthel jêng mbơ̆ ma H'Rêbêka phung pham nuyh aơ H'Milka deh ma Y-Nahôr oh Y-Abraham.$b$,false),
('bunong-vn','GEN',22,24,null,$b$H'Ruma ur yông Y-Nahôr deh phung kon đah Y-Nahôr, amoh khân păng Y-Têba, Y-Gaham, Y-Tahas jêh ri Y-Maka.$b$,true),
('bunong-vn','GEN',23,1,null,$b$H'Sara gŭ rêh du rhiăng bar jât ma pơh năm, dah nây yơh năm H'Sara gŭ rêh.$b$,true),
('bunong-vn','GEN',23,2,null,$b$H'Sara khĭt ta ƀon Kiriat (Arba nâm bu ntĭt ƀon Hêbron) tâm n'gor Kanaan. Y-Abraham hăn gay ma klâng rvê ma H'Sara.$b$,false),
('bunong-vn','GEN',23,3,null,$b$Y-Abraham dâk pa năp bunuyh păng khĭt jêh ri lah ma phung kon bu klâu Y-Het.$b$,true),
('bunong-vn','GEN',23,4,null,$b$“Gâp jêng bu năch jêh bunuyh gŭ ƀât lât ndrel ma phung khân may. Ăn ma gâp ntŭk ƀư môch tâm n'gor bri khân may, gay ma gâp dơi tâp bunuyh gâp khĭt.$b$,true),
('bunong-vn','GEN',23,5,null,$b$Phung kon bu klâu Y-Het plơ̆ lah ma Y-Abraham.$b$,false),
('bunong-vn','GEN',23,6,null,$b$“Iăt hom hên, Ơ Kôranh, may jêng du huê Kôranh toyh tâm nklang hên, tâp hom bunuyh may khĭt tâm môch ueh lơn phung hên. Mâu geh ôh du huê tâm phung hên mra dun mâu ăn ôh môch păng ma may mâu lah ƀư nau jêr mâu ăn may tâp bunuyh may khĭt.”$b$,true),
('bunong-vn','GEN',23,7,null,$b$Y-Abraham dâk jêh ri chon mon ta năp phung bunuyh ƀon lan n'gor nây, phung kon bu klâu Y-Het.$b$,false),
('bunong-vn','GEN',23,8,null,$b$Păng lah ma bu. Tơ lah khân may mĭn ueh gâp dơi tâp bunuyh ta năp măt gâp, iăt hom gâp jêh ri dăn an ma gâp boh Y-Ephôn kon bu klâu Y-Sôhar.$b$,false),
('bunong-vn','GEN',23,9,null,$b$Gay ma păng ăn ma gâp trôm yôk Makpêle, ndơ păng ta pĭt mir păng. Ăn păng tăch ma gâp ma prăk nŭm, pô ri mơ gâp mra geh ntŭk môch jêng ndơ gâp nơm tâm nklang khân may.”$b$,true),
('bunong-vn','GEN',23,10,null,$b$Y-Ephrôn gŭ ta nklang phung kon bu klâu Y-Het, Y-Ephrôn plơ̆ lah ma Y-Abraham ta năp phung kon bu klâu Y-Het, lĕ rngôch phung lăp ta mpông pêr ƀon păng.$b$,false),
('bunong-vn','GEN',23,11,null,$b$“Mâu ôh, Kôranh gâp ah, iăt hom nau gâp. Gâp ăn ma may mir nây, jêh ri gâp ăn trôm yôk geh dăch ta nây. Gâp ăn ndơ nây ma may ta năp phung kon bunuyh ƀon lan gâp. Ăn may tâp bunuyh may khĭt.”$b$,true),
('bunong-vn','GEN',23,12,null,$b$Jêh ri Y-Abraham chon mon ta năp phung ƀon lan n'gor nây.$b$,false),
('bunong-vn','GEN',23,13,null,$b$Păng ngơi ma Y-Êprôn ta năp phung ƀon lan n'gor nây lah: “Iăt hom nau gâp, tơ lah may di, gâp mra ăn rnoh mir nây ma may. Sŏk hom rnoh nây bơh gâp, gay ma gâp dơi tâp bunuyh gâp khĭt ta nây.”$b$,false),
('bunong-vn','GEN',23,14,null,$b$Y-Êprôn lah ma Y-Abraham:$b$,false),
('bunong-vn','GEN',23,15,null,$b$“Iăt hom ơ Kôranh gâp, du rva neh klăp prao kilô n'gul prăk moh khlay nau nây ndrăng may đah gâp? Pô ri tâp hom bunuyh may khĭt.”$b$,false),
('bunong-vn','GEN',23,16,null,$b$Y-Abraham dơn nau Y-Êprôn lah, jêh ri veh prăk khân păng Y-Êprôn klăp ma păng ta năp phung kon bu klâu Y-Het, prao kilô n'gul prăk tĭng nâm prăk bu dŏng tâm rvăt rgâl rnôk nây.$b$,false),
('bunong-vn','GEN',23,17,null,$b$Pô ri yơh mir Y-Êprôn ta Makpêla mpeh pa lơ Mamrê, mir nđâp trôm yôk ta nây, jêh ri lĕ rngôch tơm si geh tâm mir,$b$,false),
('bunong-vn','GEN',23,18,null,$b$bu jao ngăn ma Y-Abraham jêng ndơ păng ta năp phung kon bu klâu Y-Het, ta năp lĕ rngôch phung lăp ta mpông pêr ƀon păng.$b$,false),
('bunong-vn','GEN',23,19,null,$b$Jêh ri trôm yôk ta mir Makpêla mơ pa lơ Mamrê (nâm bu ntĭt Hêbron) tâm n'gor Kanaan.$b$,false),
('bunong-vn','GEN',23,20,null,$b$Mir jêh ri trôm yôk geh ta nây phung kon bu klâu Y-Het jao ngăn ma Y-Abraham jêng ntŭk môch.$b$,false),
('bunong-vn','GEN',24,1,null,$b$Y-Abraham ranh jêh, jêh ri Yêhôva ăn jêh nau ueh uĭn ma Y-Abraham tâm ăp ntil ndơ.$b$,true),
('bunong-vn','GEN',24,2,null,$b$Y-Abraham lah ma oh mon păng, nơm pah kan jŏ lơn tâm ngih păng, nơm chiă uănh lĕ rngôch drăp ndơ păng. “Dơm hom ti may tâm dâng tơm blu gâp.$b$,false),
('bunong-vn','GEN',24,3,null,$b$Gâp mra ăn may ton đah Yêhôva, Brah Ndu trôk jêh ri Brah Ndu neh ntu, may mâu mra sŏk ôh ur ma kon bu klâu gâp bơh phung kon bu ur phung Kanaan ndrel ma khân păng gâp gŭ.$b$,false),
('bunong-vn','GEN',24,4,null,$b$Ƀiă lah ăn may hăn ta n'gor gâp jêh ri ta phung mpôl băl gâp, jêh ri sŏk ta nây du huê ur ma kon bu klâu gâp Y-Isăk”.$b$,false),
('bunong-vn','GEN',24,5,null,$b$Oh mon lah ma păng: “Klăp lah bu ur nây mâu ŭch tĭng gâp văch ta n'gor aơ ôh, dơi lĕ gâp njŭn leo kon may sĭt ta n'gor may tă văch jêh?”$b$,false),
('bunong-vn','GEN',24,6,null,$b$Y-Abraham lah ma păng: “Njrăng hơ̆ lơi ta may njŭn leo kon gâp ta nây ôh.”$b$,false),
('bunong-vn','GEN',24,7,null,$b$Yêhôva Brah Ndu trôk nơm ăn gâp luh jêh tă bơh ngih mbơ̆ gâp jêh ri bơh n'gor bu deh jêh ma gâp, nơm ngơi jêh ma gâp jêh sơm ton jêh ma gâp pô aơ: “Gâp mra ăn n'gor aơ ma phung kon sau may, păng mra njuăl phung oh mon păng ta năp may jêh ri may mra joi ur ma kon bu klâu gâp bơh ntŭk nây.$b$,false),
('bunong-vn','GEN',24,8,null,$b$Ƀiă lah tơ lah bu ur nây mâu ŭch tĭng may, may mra klaih bơh nau sơm ton gâp ăn may ƀư. Ƀiă lah lơi ta njŭn leo kon bu klâu gâp ta nây ôh.”$b$,false),
('bunong-vn','GEN',24,9,null,$b$Pô ri oh mon dơm ti păng tâm dâng tơm blu Y-Abraham, Kôranh păng jêh ri sơm ton ma păng tâm nau nây.$b$,false),
('bunong-vn','GEN',24,10,null,$b$Oh mon sŏk jât mlâm seh samô Kôranh păng jêh ri hăn. Păng djôt leo ndrel âk ndơ khlay bơh Kôranh păng ăn. Păng hăn ta n'gor Mêsôpôtami ta ƀon Nahôr.$b$,true),
('bunong-vn','GEN',24,11,null,$b$Păng ăn seh samô drôm pa dih ƀon dăch ta ntu dak dôl ngo suâr vâr păr vik, ta mông phung bu ur luh hăn bâk dak.$b$,false),
('bunong-vn','GEN',24,12,null,$b$Păng lah, Ơ Yêhôva, Brah Ndu Y-Abraham Kôranh gâp, gâp vơh vơl ma may ăn gâp tâm mâp nar aơ di nâm nau gâp ŭch jêh ri tâm mpơl hom nau rŏng răp jăp đah Kôranh gâp Y-Abraham.$b$,false),
('bunong-vn','GEN',24,13,null,$b$Aơ, gâp gŭ ta ndrâm dak, jêh ri phung kon bu ur bunuyh ƀon lan văch bâk dak.$b$,false),
('bunong-vn','GEN',24,14,null,$b$Ăn bu ur druh nơm gâp mra lah: “Nhêt hom jêh ri gâp mra ăn seh samô may nhêt tâm ban lĕ ăn nơm nây jêng bu ur may mƀŏng jêh ma oh mon may Y-Isăk. Ma nau nây gâp mra gĭt may tâm mpơl jêh nau rŏng răp jăp ma Kôranh gâp.”$b$,false),
('bunong-vn','GEN',24,15,null,$b$Êlôch ôh nau păng ngơi, aơ, H'Rêbêka văch yar yăng dak păng ta săng nglik. H'Rêbêka jêng kon bu ur Y-Bêthel, kon bu klâu H'Milka ur Y-Nahôr, oh Y-Abraham.$b$,true),
('bunong-vn','GEN',24,16,null,$b$Bu ur druh nây ueh ngăn, păng ê geh sai ôh, mâu lĕ geh du huê bu klâu mâp gŭ ndrel ma păng. Păng jŭr leo hăn ta ndrâm dak, bâk dak bêng yăng păng jêh ri hao.$b$,true),
('bunong-vn','GEN',24,17,null,$b$Oh mon nây nchuăt ran tâm mâp đah păng jêh ri lah: “Gâp dăn ma ay, ăn gâp nhêt djê̆ dak bơh yăng ay,$b$,false),
('bunong-vn','GEN',24,18,null,$b$Păng lah, nhêt hom. Ơ Kôranh gâp” Păng rklêng ro yăng nây ăn păng nhêt.$b$,false),
('bunong-vn','GEN',24,19,null,$b$Tơ lah jêh ăn păng nhêt păng lah ma oh mon nây: “Gâp mra bâk dak ăn seh samô nhêt tâm ban lĕ ăn hơm da dê.”$b$,false),
('bunong-vn','GEN',24,20,null,$b$Păng nkhŭt ro dak tă bơh yăng păng ta mbong dak jêh ri nchuăt hăn ta ntu dak, gay bâk dak jêh ri păng bâk dak ma lĕ rngôch seh samô.$b$,true),
('bunong-vn','GEN',24,21,null,$b$Oh mon nây uănh ma păng mâu mƀrêh măt, gŭ klăk gay gĭt tơ lah Yêhôva ăn tât ngăn nau lap păng nsong mâu lah mâu.$b$,false),
('bunong-vn','GEN',24,22,null,$b$Tơ lah seh samô nhêt dak hơm jêh, bunuyh nây sŏk mblo tôr mah rnoh jâk păng n'gul sêkel jêh ri bar mlâm kông ăn ta ti păng rnoh jâk păng jât sêkel mah.$b$,false),
('bunong-vn','GEN',24,23,null,$b$Păng lah: “Mbu mbơ̆ me ay? Geh lĕ ntŭk tâm ngih mbơ̆ ay hên dơi bêch?”$b$,false),
('bunong-vn','GEN',24,24,null,$b$Păng lah: “Gâp jêng kon bu ur Y-Bêthel sau H'Milka đah Y-Nahôr.”$b$,true),
('bunong-vn','GEN',24,25,null,$b$Păng plơ̆ lah: “Hên geh âk rhe jêh ri gơ̆ , nđâp ma ntŭk bêch.”$b$,false),
('bunong-vn','GEN',24,26,null,$b$Bunuyh nây kŭnh bôk păng mbah yơk ma Yêhôva.$b$,false),
('bunong-vn','GEN',24,27,null,$b$Păng lah: “Mât ton ma Yêhôva, Brah Ndu Kôranh gâp Y-Abraham, păng mâu cha lơi ôh nau rŏng răp jăp jêh ri nau nanê̆ păng ma Kôranh gâp! Bi ma gâp, Yêhôva njŭn gâp ta trong ngih phung oh Kôranh gâp.”$b$,false),
('bunong-vn','GEN',24,28,null,$b$Bu ur druh nchuăt ran nkoch bri ma phung ngih mê̆ păng lĕ nau tât.$b$,true),
('bunong-vn','GEN',24,29,null,$b$H'Rêbêka geh du huê nâu tâm amoh Y-Laban. Y-Laban nchuăt hăn ta bunuyh nây ta ndrâm dak.$b$,false),
('bunong-vn','GEN',24,30,null,$b$Tơ lah păng saơ năl ti jêh ri kông ta ti oh bu ur păng jêh ri tơ lah păng tăng nau H'Rêbêka oh păng ngơi, “Bunuyh nây ngơi ma gâp nâm bu pô aơ.” Păng hăn ta bunuyh nây. Jêh ri, aơ, păng gŭ râng dăch seh samô dăch ndrâm dak.$b$,true),
('bunong-vn','GEN',24,31,null,$b$Păng lah: “Lăp hom nơm Yêhôva mât ton jêh. Mâm ƀư may gŭ pa dih? Yor lah gâp nkra jêh ngih nđâp ma ntŭk seh samô.”$b$,false),
('bunong-vn','GEN',24,32,null,$b$Pô ri bunuyh nây lăp tâm ngih. Y-Laban njŭr ndơ tă klơ seh samô, jêh ri ăn rhe ma seh samô jêh ri gơ̆ . Bu ăn dak ma nơm nây rao jâng jêh ri phung bunuyh ndrel ma păng.$b$,false),
('bunong-vn','GEN',24,33,null,$b$Jêh ri bu ăn păng ndơ sông sa; ƀiă lah păng lah: “Gâp mâu hŏ sa ôh ê lor ma gâp mbơh kan gâp hăn.” Y-Laban lah: “Ngơi hom”.$b$,false),
('bunong-vn','GEN',24,34,null,$b$Păng lah, gâp jêng oh mon Y-Abraham.$b$,true),
('bunong-vn','GEN',24,35,null,$b$Yêhôva ăn nau ueh uĭn âk ma Kôranh gâp, jêh ri păng ndrŏng jêh. Yêhôva ăn jêh ma păng âk biăp jêh ri âk ndrôk, prăk jêh ri mah, phung oh mon bu klâu jêh ri phung oh mon bu ur, âk seh samô jêh ri seh bri.$b$,true),
('bunong-vn','GEN',24,36,null,$b$H'Sara ur Kôranh gâp, tơ lah păng ranh jêh păng deh du huê kon bu klâu ma Kôranh gâp; jêh ri păng ăn ma kon păng lĕ rngôch ndơ păng geh.$b$,false),
('bunong-vn','GEN',24,37,null,$b$Kôranh gâp ăn gâp sơm ton, lah: “Lơi sŏk ôh ur ma kon gâp tâm phung kon bu ur Kanaan, tâm n'gor khân păng gâp gŭ.$b$,false),
('bunong-vn','GEN',24,38,null,$b$Ƀiă lah ăn may hăn ta ngih mbơ̆ gâp tâm phung mpôl băl gâp, jêh ri sŏk du huê ur ma kon bu klâu gâp.”$b$,false),
('bunong-vn','GEN',24,39,null,$b$Gâp lah ma Kôranh gâp: ‘Klăp lah bu ur nây mâu mra tĭng gâp ôh.’$b$,false),
('bunong-vn','GEN',24,40,null,$b$Ƀiă lah păng lah ma gâp. ‘Yêhôva nơm gâp tông bâr, mra njuăl hăn oh mon ueh păng ndrel ma may, jêh ri ăn tât nau lap ma nau may hăn nsong; jêh ri may mra sŏk ma kon bu klâu gâp du huê ur bơh ndŭl mpôl gâp tâm ngih mbơ̆ gâp.$b$,false),
('bunong-vn','GEN',24,41,null,$b$Pô ri may mra klaih ma nau gâp ăn sơm ton, tơ lah may tât ta mpôl băl gâp, jêh ri tơ lah khân păng mâu ăn păng ma may, may mra klaih bơh nau gâp ăn may sơm ton.’$b$,false),
('bunong-vn','GEN',24,42,null,$b$Nar aơ gâp tât ta ndrâm dak jêh ri gâp lah: ‘Ơ Yêhôva, Brah Ndu Kôranh gâp Y-Abraham, tơ lah may ăn tât nau lap ma nau gâp hăn nsong aơ,$b$,false),
('bunong-vn','GEN',24,43,null,$b$“Aơ gâp gŭ râng ta tu dak. Ăn bu ur druh nơm văch bâk dak jêh ri ma păng gâp mra lah: “Gâp dăn ma ay, ăn gâp nhêt djê̆ dak yăng ay.”$b$,false),
('bunong-vn','GEN',24,44,null,$b$Jêh ri păng mra lah ma gâp: “Nhêt hom may, jêh ri gâp mra bâk an dak ma seh samô may ăn nơm nây jêng bu ur Yêhôva mƀŏng jêh ma kon bu klâu Kôranh gâp.”$b$,false),
('bunong-vn','GEN',24,45,null,$b$“Ê lôch nau gâp ngơi pô ri tâm nuih n'hâm gâp, aơ, H'Rêbêka văch jêng yăng păng ta săng nglik. Păng hăn jŭr ta ndrâm dak jêh ri bâk. Gâp lah ma păng.” Gâp dăn ma ay, ăn gâp nhêt ƀă dak ay.$b$,true),
('bunong-vn','GEN',24,46,null,$b$Păng rklĭng ro yăng bơh săng nglik jêh ri lah: “Nhêt hom, jêh ri gâp mra ăn seh samô may nhêt đŏng? Pô ri gâp nhêt, jêh ri păng ăn nđâp ma seh samô nhêt ƀă.$b$,false),
('bunong-vn','GEN',24,47,null,$b$Jêh ri gâp ôp păng: ‘Mbu me mbơ̆ ay? Păng lah, gâp jêng kon bu ur Y-Bêthel sau Y-Nahôr, nơm H'Milka deh ma păng.’ Jêh ri gâp sâm dok rgên ta trôm muh păng jêh ri sâm dok kông ta ti păng.$b$,false),
('bunong-vn','GEN',24,48,null,$b$Jêh ri gâp kŭnh bôk mbah yơk ma Yêhôva jêh ri mât ton ma Yêhôva, Brah Ndu Kôranh gâp Y-Abraham, nơm njŭn leo jêh gâp trong di gay sŏk kon bu ur oh Kôranh gâp jêng ur ma kon bu klâu păng.$b$,false),
('bunong-vn','GEN',24,49,null,$b$Aƀaơ aơ, tơ lah khân may mra ƀư nau ueh jêh ri nau nanê̆ đah Kôranh gâp, ăn may mbơh ma gâp. Tơ lah mâu dơi, mbơh ma gâp, gay ma gâp dơi teng pa ma mâu lah pa chiau.”$b$,false),
('bunong-vn','GEN',24,50,null,$b$Y-Laban jêh ri Y-Bêthel plơ̆ lah: “Nau aơ luh bơh Yêhôva, hên mâu dơi lah ôh ma may nau mhĭk mâu lah nau ueh,$b$,true),
('bunong-vn','GEN',24,51,null,$b$Aơ, H'Rêbêka gŭ ta năp may; sŏk păng jêh ri hăn hom, ăn păng jêng ur ma kon bu klâu Kôranh may, tĭng nâm Yêhôva lah jêh.’$b$,false),
('bunong-vn','GEN',24,52,null,$b$Tơ lah oh mon Y-Abraham tăng jêh nau khân păng ngơi, păng chon mon ta neh ta năp Yêhôva.$b$,false),
('bunong-vn','GEN',24,53,null,$b$Oh mon nây rhi ndơ nkrơ̆ ƀư ma prăk, mah jêh bok ao ăn ma H'Rêbêka. Păng ăn ndơ khlay ma nâu jêh ri ma me păng.$b$,false),
('bunong-vn','GEN',24,54,null,$b$Păng jêh ri phung bunuyh ndrel ma păng sông sa nhêt jêh ri khân păng bêch ta nây du măng. Tơ lah khân păng dâk ơm ôi păng lah: “Ăn gâp sĭt ma Kôranh gâp.”$b$,false),
('bunong-vn','GEN',24,55,null,$b$Nâu jêh ri me H'Rêbêka lah: “Ăn bu ur gŭ ndrel hên jŏ djê̆, djê̆ ngăn jât nar jêh ri mơ păng mra hăn.”$b$,true),
('bunong-vn','GEN',24,56,null,$b$Păng lah ma phung nây. “Lơi ta khân ay may ƀư nkân (piai) gâp ôh, yor lah Yêhôva ăn tât jêh nau lap ma nau gâp nsong. Ăn gâp dơi sĭt ta Kôranh gâp.”$b$,false),
('bunong-vn','GEN',24,57,null,$b$Khân păng lah: “Hên mra kuăl bu ur druh jêh ri ôp păng.”$b$,false),
('bunong-vn','GEN',24,58,null,$b$Khân păng kuăl H'Rêbêka jêh ri lah ma păng: “Ay ŭch hăn lĕ ndrel ma bunuyh aơ?” Păng lah: ‘Gâp mra hăn”.$b$,false),
('bunong-vn','GEN',24,59,null,$b$Khân păng ăn H'Rêbêka oh bu ur khân păng hăn, nđâp oh mon bu ur sâm mpu H'Rêbêka, oh mon Y-Abraham jêh ri phung bunuyh ndrel ma păng.$b$,false),
('bunong-vn','GEN',24,60,null,$b$Khân păng mât ton ma H'Rêbêka jêh ri lah ma păng. Ơ oh bu ur hên, ăn ay jêng me ma rmưn rsen bunuyh; jêh ri ăn phung kon sau ay dơi đah phung tâm rmot khân păng.”$b$,false),
('bunong-vn','GEN',24,61,null,$b$H'Rêbêka nđâp ma oh mon bu ur păng dâk; khân păng ncho seh samô jêh ri tĭng bunuyh nây. Oh mon Y-Abraham sŏk H'Rêbêka jêh ri hăn.$b$,true),
('bunong-vn','GEN',24,62,null,$b$Y-Isăk sĭt tă bơh trong Bêrlahairôi Yor păng gŭ tâm Rđŭng.$b$,true),
('bunong-vn','GEN',24,63,null,$b$Ta ngo suâr vâr păr vik Y-Isăk hăn luh ta mir gay gŭ mĭn. Păng n'gor măt jêh ri, aơ, geh seh samô văch.$b$,false),
('bunong-vn','GEN',24,64,null,$b$H'Rêbêka n'gơr măt đŏng. Tơ lah păng saơ Y-Isăk păng jŭr tă klơ seh samô.$b$,false),
('bunong-vn','GEN',24,65,null,$b$Păng lah ma oh mon: “Mbu moh bu klâu hăn tâm mir ŭch tâm mâp đah he?” Oh mon lah: “Păng yơh Kôranh gâp.” Pô ri H'Rêbêka sŏk bok nkŭm muh măt păng.$b$,true),
('bunong-vn','GEN',24,66,null,$b$Oh mon nkoch bri ma Y-Isăk lĕ nau păng ƀư jêh.$b$,false),
('bunong-vn','GEN',24,67,null,$b$Y-Isăk leo H'Rêbêka tâm ngih bok H'Sara me păng. Păng sŏk H'Rêbêka jêng ur păng jêh ri rŏng ma păng. Pô ri Y-Isăk geh nau tâm bonh leng jêh khĭt me păng.$b$,true),
('bunong-vn','GEN',25,1,null,$b$Y-Abraham sŏk du huê ur êng, amoh păng H'Kêtura.$b$,true),
('bunong-vn','GEN',25,2,null,$b$Păng deh Y-Simran, Y-Jôksan, Y-Mêdan, Y-Midian, Y-Ishak jêh ri Y-Sua.$b$,false),
('bunong-vn','GEN',25,3,null,$b$Y-Jôksan geh kon Y-Seba jêh ri Y-Dêdan, phung kon bu klâu Y-Dêdan geh Y-Asurim, Y-Lêtusim jêh ri Y-Lêumin.$b$,false),
('bunong-vn','GEN',25,4,null,$b$Phung kon bu klâu Y-Midian geh Y-Êpha, Y-Êpher, Y-Hanôk, Y-Abida jêh ri Y-Elda. Lĕ rngôch phung aơ jêng phung kon sau H'Kêtura.$b$,false),
('bunong-vn','GEN',25,5,null,$b$Y-Abraham ăn lĕ drăp ndơ păng geh ma Y-Isăk.$b$,false),
('bunong-vn','GEN',25,6,null,$b$Ƀiă lah Y-Abraham ăn lĕ drăp ndơ ma kon ur yông păng. Tơ lah păng ăt hôm rêh păng njuăl phung nây hăn du ngai đah kon păng Y-Isăk mpeh pa lơ tâm n'gor pa lơ.$b$,false),
('bunong-vn','GEN',25,7,null,$b$Dŭm aơ năm Y-Abraham gŭ rêh, du rhiăng pơh jât ma prăm năm.$b$,true),
('bunong-vn','GEN',25,8,null,$b$Y-Abraham tăch n'hâm jêh ri păng khĭt ranh jŏk jong, du huê bunuyh ranh ngăn jêh ri păng hăn gŭ ndrel ma phung che păng.$b$,false),
('bunong-vn','GEN',25,9,null,$b$Y-Isăk jêh ri Y-Ismaêl, phung kon bu klâu păng tâp păng tâm trôm yôk Makpêla tâm mir Y-Êprôn kon bu klâu Y-Sôar, du huê kon bu klâu Y-Het ta năp Mamrê,$b$,false),
('bunong-vn','GEN',25,10,null,$b$mir Y-Abraham rvăt jêh bơh phung kon Y-Het. Ta nây bu tâp Y-Abraham jêh ri H'Sara ur păng.$b$,false),
('bunong-vn','GEN',25,11,null,$b$Jêh khĭt Y-Abraham Brah Ndu ăn nau ueh uĭn ma Y-Isăk kon păng. Y-Isăk gŭ ta Bêrlahairôi.$b$,false),
('bunong-vn','GEN',25,12,null,$b$Aơ phung kon sau Y-Ismaêl, kon bu klâu Y-Abraham, nơm bu ur n'gor Êjipt H'Agar oh mon bu ur H'Sara deh ma Y-Abraham.$b$,true),
('bunong-vn','GEN',25,13,null,$b$Aơ amoh phung kon bu klâu Y-Ismaêl tĭng nâm di ntrong bu deh ma khân păng: Kon deh bôk rah ma Y-Ismaêl jêng Y-Nêhaôt, jêh ri Y-Kêdar, Y-Athêel, Y-Mipsam.$b$,false),
('bunong-vn','GEN',25,14,null,$b$Y-Misma, Y-Duma, Y-Masa.$b$,false),
('bunong-vn','GEN',25,15,null,$b$Y-Hadat, Y-Têma, Y-Jêtur, Y-Napis jêh ri Y-Kêdêma.$b$,true),
('bunong-vn','GEN',25,16,null,$b$Phung aơ yơh jêng phung kon bu klâu Y-Ismaêl, tĭng nâm ƀon jêh ri ntŭk jưh ma ăp nơm khân păng, jât ma bar nuyh kon hađăch tĭng nâm ndŭl mpôl khân păng.$b$,false),
('bunong-vn','GEN',25,17,null,$b$Năm Y-Ismaêl gŭ rêh geh du rhiăng pe jât ma pơh năm. Păng tăch n'hâm khĭt jêh ri hăn gŭ ndrel ma ndŭl mpôl păng.$b$,false),
('bunong-vn','GEN',25,18,null,$b$Khân păng gŭ ntơm bơh n'gor Havila tât ta n'gor Sur, mpeh hŏng n'gor Êjipt, mơ pa n'gor Asiri. Khân păng tâm ƀư rlăng đah lĕ rngôch oh nâu khân păng.$b$,true),
('bunong-vn','GEN',25,19,null,$b$Aơ phung kon sau Y-Isăk kon bu klâu Y-Abraham, Y-Abraham jêng mbơ̆ Y-Isăk.$b$,true),
('bunong-vn','GEN',25,20,null,$b$Y-Isăk geh puăn jât năm tơ lah păng gŭ ur păng H'Rêbêka kon bu ur Y-Bêthel. Du huê Siri bơh n'gor Padan Aram, oh bu ur Y-Laban du huê Siri.$b$,true),
('bunong-vn','GEN',25,21,null,$b$Y-Isăk mbơh sơm ma Yêhôva yor ur păng, yor păng jêng bu ur mâu bă. Yêhôva dơn nau păng mbơh sơm, jêh ri H'Rêbêka ur păng ntreo.$b$,false),
('bunong-vn','GEN',25,22,null,$b$Phung kon mpât tâm ndŭl păng jêh ri păng lah: “Tơ lah ngăn pô nây, mâm ƀư gâp ăt hôm rêh?” Pô ri păng hăn ôp Yêhôva.$b$,false),
('bunong-vn','GEN',25,23,null,$b$Yêhôva lah ma păng: “Bar phung mpôl băl gŭ tâm ndŭl ay bar phung bunuyh ƀon lan mra luh bơh ndŭl proch ay; du phung mra jêng ktang lơn ma phung êng, jêh ri nâu ranh mra pah kan ma kon nse.”$b$,false),
('bunong-vn','GEN',25,24,null,$b$Tơ lah nar păng deh tât jêh Aơ geh kon bar tâm ndŭl păng,$b$,false),
('bunong-vn','GEN',25,25,null,$b$Nơm luh lor lơn jêng chăng lam săk jăn nâm bu ao mbâl geh rsau. Pô ri khân păng tâm amoh Y-Êsau.$b$,false),
('bunong-vn','GEN',25,26,null,$b$Jêh ri oh păng luh, ti păng kuăn ta jâng jon Y-Êsau. Pô ri bu amoh păng Y-Yakôb. l Ti Y-Isăk geh prao jât năm tơ lah H'Rêbêka deh ma khân păng.$b$,false),
('bunong-vn','GEN',25,27,null,$b$Phung kon se nây văch ma toyh Y-Êsau jêng du huê bunuyh rtăp pănh ngăn, bunuyh gŭ tâm bri. Ƀiă lah Y-Yakôb jêng bunuyh rdơ̆ bunuyh gŭ tâm ngih bok.$b$,true),
('bunong-vn','GEN',25,28,null,$b$Y-Isăk rŏng ma Y-Êsau yor lah păng geh puăch jun sa ƀiă lah H'Rêbêka rŏng ma Y-Yakôb.$b$,true),
('bunong-vn','GEN',25,29,null,$b$Du nar Y-Yakôb gŭ ƀư por Y-Êsau sĭt tă bơh bri ji ngot ngăn$b$,false),
('bunong-vn','GEN',25,30,null,$b$Y-Êsau lah ma Y-Yakôb: “Ăn gâp sa por chăng nĕ, yor lah gâp ji ngot ngăn.” (Yor nây bu rnha păng Y-Êđôm)$b$,false),
('bunong-vn','GEN',25,31,null,$b$Y-Yakôb lah: “Tăch pa gâp lor nau may jêng nâu ranh.”$b$,false),
('bunong-vn','GEN',25,32,null,$b$Y-Êsau lah ma păng: “Aơ, gâp bơi ma khĭt; moh khlay ma gâp nau jêng nâu ranh?”$b$,false),
('bunong-vn','GEN',25,33,null,$b$Y-Yakôb lah; “Sơm ton ma gâp lor.” Păng sơm ton tăch ma Y-Yakôb nau păng jêng nâu ranh.$b$,false),
('bunong-vn','GEN',25,34,null,$b$Jêh ri Y-Yakôb ăn Y-Êsau piăng let jêh ri por tuh. Păng sa nhêt jêh ri hăn. Pô ri yơh Y-Êsau tâm rmot ma nau păng jêng nâu ranh.$b$,false),
('bunong-vn','GEN',26,1,null,$b$Geh nau sa sât ji ngot tâm n'gor êng đah nau sa sât ji ngot tâm rnôk Y-Abraham. Y-Isăk hăn ta ƀon Gêrar ta Y-Abimêlek hađăch phung Philistin.$b$,true),
('bunong-vn','GEN',26,2,null,$b$Yêhôva tâm mpơl ma păng jêh ri lah: “Lơi hăn ôh ta n'gor Êjipt ăn may gŭ tâm n'gor gâp mra lah an ma may.$b$,true),
('bunong-vn','GEN',26,3,null,$b$Gŭ tâm n'gor aơ jêh ri gâp mra gŭ ndrel ma may jêh ri ăn nau ueh uĭn ma may; yor lah gâp mra ăn lĕ n'gor aơ ma may jêh ri ma phung kon sau may jêh ri gâp mra ƀư nanê̆ nau gâp ton jêh ma Y-Abraham mbơ̆ may.$b$,false),
('bunong-vn','GEN',26,4,null,$b$Gâp mra ƀư bĭk phung kon sau nâm bu mănh tâm trôk; jêh ri gâp mra ăn lĕ n'gor aơ ma phung kon sau may. Lĕ rngôch ntil mpôl băl tâm neh ntu mra geh nau ueh uĭn yor phung kon sau may;$b$,false),
('bunong-vn','GEN',26,5,null,$b$Yor lah Y-Abraham tông jêh bâr gâp jêh ri păng tĭng kơt nau gâp đă, nau gâp ngơi, jêh ri nau vay gâp.”$b$,false),
('bunong-vn','GEN',26,6,null,$b$Pô ri Y-Isăk gŭ tâm ƀon Gêrar.$b$,true),
('bunong-vn','GEN',26,7,null,$b$Tơ lah phung bunuyh ƀon nây ôp păng ma ur păng, păng lah: “Păng jêng oh bu ur gâp.” Klach lah: “Phung bunuyh rnôk aơ mra nkhĭt gâp yor H'Rêbêka.” Yor lah păng ueh ngăn măt uănh.$b$,false),
('bunong-vn','GEN',26,8,null,$b$Tơ lah păng gŭ ta nây jŏ jêh, Y-Abimêlek hađăch phung Philistin, gŭ uănh ta mpông bloh jê̆ jêh ri saơ Y-Isăk ut H'Rêbêka ur păng.$b$,false),
('bunong-vn','GEN',26,9,null,$b$Y-Abimêlek kuăl Y-Isăk jêh ri lah, nanê̆ păng jêng ur may. Mâm may lah, păng jêng oh bu ur gâp?” Y-Isăk lah ma păng. “Yor lah gâp klach lah gâp mra khĭt yor păng.”$b$,false),
('bunong-vn','GEN',26,10,null,$b$Y-Abimêlek lah, moh nau may ƀư ma hên? Klăp lah du huê bunuyh ƀon lan hên bêch ndrel ur may, jêh ri may mra ƀư nsŭk hên.”$b$,false),
('bunong-vn','GEN',26,11,null,$b$Pô ri Y-Abimêlek ntăm ma lĕ rngôch bunuyh ƀon lan lah: “Mbu nâm pah bu klâu aơ mâu lah ur păng, bu mra nkhĭt păng.”$b$,false),
('bunong-vn','GEN',26,12,null,$b$Y-Isăk tuch, tăm tâm n'gor nây, jêh ri păng rek năm nây du rhiăng tơ̆ hao lơn. Yêhôva ăn nau ueh uĭn ma păng,$b$,true),
('bunong-vn','GEN',26,13,null,$b$jêh ri păng jêng ndrŏng, jêh ri drăp păng hao mro kŏ tât păng jêng ndrŏng toyh ngăn ngên.$b$,false),
('bunong-vn','GEN',26,14,null,$b$Păng geh biăp âk, ndrôk âk jêh ri oh mon âk. Pô ri phung Philistin mâu nach ma păng.$b$,true),
('bunong-vn','GEN',26,15,null,$b$Lĕ rngôch ntu dak phung oh mon mbơ̆ păng Y-Abraham kuyh jêh tâm rnôk mbơ̆ păng, phung Philistin brôi lơi lĕ rngôch.$b$,false),
('bunong-vn','GEN',26,16,null,$b$Y-Abimêlek lah ma Y-Isăk: “Du hom may bơh hên, yor lah may ktang lơn ma hên.”$b$,false),
('bunong-vn','GEN',26,17,null,$b$Pô ri Y-Isăk du tă bơh nây; păng ndâk ngih bok păng tâm rlŭng Gêrar jêh ri gŭ ta nây.$b$,true),
('bunong-vn','GEN',26,18,null,$b$Y-Isăk kuyh tay ntu dak bu kuyh tâm rnôk Y-Abraham mbơ̆ păng; yor lah phung Philistin brôi lơi jêh khĭt Y-Abraham. Jêh ri păng rnha ntu dak nây tĭng nâm amoh mbơ̆ păng rnha jêh.$b$,true),
('bunong-vn','GEN',26,19,null,$b$Ƀiă lah tơ lah phung oh mon Y-Isăk kuyh tâm rlŭng jêh ri ndrâm geh tu dak dơl.$b$,false),
('bunong-vn','GEN',26,20,null,$b$Phung rmăk biăp ndrôk ƀon Gêrar tâm djrel đah phung rmăk biăp ndrôk Y-Isăk lah: “Dak hên” Păng rnha ntu dak nây Êsek, yor lah phung rmăk biăp ndrôk tâm djrel.$b$,true),
('bunong-vn','GEN',26,21,null,$b$Khân păng kuyh du ntu dak êng jêh ri phung rmăk biăp ndrôk tâm djrel đŏng. Pô ri păng rnha ntu dak nây Sima.$b$,true),
('bunong-vn','GEN',26,22,null,$b$Păng du tă bơh nây jêh ri păng kuyh đŏng du ntu dak êng. Phung rmăk biăp ndrôk mâu hôm tâm djrel ôh ma ntu dak nây. Păng rnha ntu dak nây Rêhôbôt jêh ri lah: “Aƀaơ Yêhôva ăn ntŭk ma hên, jêh ri hên mra geh nau chăt jêng âk tâm n'gor.”$b$,false),
('bunong-vn','GEN',26,23,null,$b$Bơh nây păng hăn hao ta ƀon Bêr Sêba.$b$,true),
('bunong-vn','GEN',26,24,null,$b$Yêhôva tâm mpơl ma păng măng nây jêh ri lah: “Gâp jêng Brah Ndu Y-Abraham mbơ̆ may, lơi klach ôh, yor lah gâp gŭ ndrel ma may. Gâp mra ăn nau ueh uĭn ma may, jêh ri gâp mra ƀư bĭk phung kon sau may yor Y-Abraham oh mon gâp.”$b$,true),
('bunong-vn','GEN',26,25,null,$b$Pô ri păng rdâk ta nây du nơng Brah jêh ri kuăl mbơh sơm ma amoh Yêhôva. Păng rdâk ngih bok păng ta nây jêh ri phung oh mon Y-Isăk kuyh du mlâm ntu dak ta nây.$b$,true),
('bunong-vn','GEN',26,26,null,$b$Y-Abimêlek văch bơh ƀon Gêrar hăn ta Y-Isăk ndrel ma Y-Ahusat Kôranh phung Tahan păng.$b$,true),
('bunong-vn','GEN',26,27,null,$b$Y-Isăk lah ma khân păng: “Mâm ƀư khân may ŭch hăn văch ta gâp, yor lah khân may tâm rmot ma gâp, jêh ri khân may mprơh jêh gâp tă bơh khân may?”$b$,false),
('bunong-vn','GEN',26,28,null,$b$Khân păng lah, Hên saơ rah vah jêh Yêhôva gŭ ndrel ma may, pô ri hên mĭn: Ăn geh nau sơm ton ndrăng he, may đah hên, ăn hên ƀư nau tâm rnglăp đah may;$b$,false),
('bunong-vn','GEN',26,29,null,$b$gay ma may lơi ƀư nau mhĭk ma hên ôh, nâm bu hên mâu mâp pah bi may ôh, jêh ri knŏng hên ƀư jêh nau ueh ma may, jêh ri hên ăn may hăn ma nau đăp mpăn. Aƀaơ may jêng nơm Yêhôva mât ton.”$b$,false),
('bunong-vn','GEN',26,30,null,$b$Y-Isăk thai ndơ sông, nhêt ma khân păng; khân păng sông sa jêh ri nhêt.$b$,false),
('bunong-vn','GEN',26,31,null,$b$Kah nar ôi taơ khân păng dâk ơm jêh ri khân păng tâm ton ndrăng khân păng. Y-Isăk ăn khân păng sĭt, jêh ri khân păng hăn ma nau đăp mpăn.$b$,false),
('bunong-vn','GEN',26,32,null,$b$Nar nây yơh phung oh mon Y-Isăk mbơh ntu dak khân păng kuyh jêh, jêh ri lah ma păng: ‘Hên geh dak jêh.”$b$,true),
('bunong-vn','GEN',26,33,null,$b$Păng rnha ntu dak nây Sêba, yor nây bu rnha ƀon nây Bêr Sêba n'ho ma tât aƀaơ.$b$,false),
('bunong-vn','GEN',26,34,null,$b$Tơ lah Y-Êsau geh puăn jât năm păng gŭ H'Yudit jêng ur păng kon bu ur Y-Bêri du huê Hitit, jêh ri H'Basmat kon bu ur Y-Êlon, du huê Hitit lĕ.$b$,true),
('bunong-vn','GEN',26,35,null,$b$Khân păng ƀư nau rngot ma nuih n'hâm Y-Isăk jêh ri H'Rêbêka.$b$,false),
('bunong-vn','GEN',27,1,null,$b$Tơ lah Y-Isăk ranh jêh, măt păng ngo mâu hôm dơi saơ ôh, păng kuăl Y-Êsau kon bôk rah păng jêh ri păng lah: “Ơ nâu” kon păng plơ̆ lah ma păng: “Aơ, ta aơ gâp.”$b$,true),
('bunong-vn','GEN',27,2,null,$b$Păng lah: “Aơ, gâp ranh jêh; gâp mâu gĭt ôh.$b$,false),
('bunong-vn','GEN',27,3,null,$b$Aƀaơ may sŏk ndơ may vay nsong yôk bri, dĭng hăr jêh ri na ndron may. Hăn tâm bri jêh ri pănh jun ma gâp.$b$,false),
('bunong-vn','GEN',27,4,null,$b$Nkra puăch jun nây ma gâp tĭng nâm gâp ŭch sa. Njŭn ma gâp gay ma gâp sa jêh ri gâp dơi mât ton ma may lor ma gâp khĭt.”$b$,false),
('bunong-vn','GEN',27,5,null,$b$H'Rêbêka tăng nau Y-Iăk lah ma Y-Êsau kon bu klâu păng. Pô ri tơ lah Y-Êsau hăn tâm bri ŭch joi jun jêh ri nsĭt ta ngih.$b$,true),
('bunong-vn','GEN',27,6,null,$b$H'Rêbêka lah ma Y-Yakôb kon bu klâu păng: “Gâp tăng mbơ̆ may ngơi ma Y-Êsau, nâu may pô aơ,$b$,true),
('bunong-vn','GEN',27,7,null,$b$‘njŭn ma gâp puăch jun jêh ri nkra puăch ăn kah sa, gay ma gâp dơi sa jêh ri mât ton ma may ta năp Yêhôva lor ma gâp khĭt.’$b$,false),
('bunong-vn','GEN',27,8,null,$b$Aƀaơ aơ, Ơ nâu iăt nau gâp, tĭng nâm nau gâp ntăm ma may.$b$,false),
('bunong-vn','GEN',27,9,null,$b$“Hăn ta phung biăp, be sŏk ma gâp bar mlâm be ueh, jêh ri gâp mra nkra puăch kah sa ma mbơ̆ may tĭng nâm păng rŏng.$b$,false),
('bunong-vn','GEN',27,10,null,$b$May mra njŭn puăch nây ma mbơ̆ may, gay ma păng sa jêh ri mât ton ma may lor păng khĭt.”$b$,false),
('bunong-vn','GEN',27,11,null,$b$Ƀiă lah Y-Yakôb lah ma H'Rêbêka me păng: “Aơ, Y-Êsau, nâu gâp geh rsao âk jêh ri gâp mâu geh rsau ôh.$b$,false),
('bunong-vn','GEN',27,12,null,$b$Klăp lah mbơ̆ gâp mra rbot gâp, jêng gâp mra jêng bunuyh ndơm păng, jêh ri gâp mra tât rtăp rak ma gâp nơm, mâu di nau mât ton ôh.”$b$,false),
('bunong-vn','GEN',27,13,null,$b$Me păng lah ma păng: “Ơ nâu, ăn nau rtăp rak may tŭp ta gâp. Knŏng iăt nau gâp jêh ri hăn sŏk hom be ma gâp.”$b$,true),
('bunong-vn','GEN',27,14,null,$b$Jêh ri păng hăn sŏk njŭn păng ma me păng; jêh ri me păng nkra puăch kah sa tĭng nâm bơ̆ păng ŭch.$b$,false),
('bunong-vn','GEN',27,15,null,$b$H'Rêbêka sŏk kho ao ueh Y-Êsau kon bôk rah păng, ndơ geh tâm ngih, jêh ri păng sâm nsoh kho ao nây ma Y-Yakôb oh păng.$b$,false),
('bunong-vn','GEN',27,16,null,$b$Jêh ri păng put ti jêh ri trô ko păng ma ntâu kon be.$b$,false),
('bunong-vn','GEN',27,17,null,$b$Jêh ri păng ăn puăch tâm ti Y-Yakôb kon bu klâu păng puăch kah sa jêh ri piăng let păng nkra jêh.$b$,false),
('bunong-vn','GEN',27,18,null,$b$Păng hăn ta mbơ̆ păng jêh ri lah: “Ơ mbơ̆ gâp.” Y-Isăk lah: “Ta aơ gâp, mbu may, Ơ nâu?”$b$,true),
('bunong-vn','GEN',27,19,null,$b$Y-Yakôb lah ma mbơ̆ păng: “Gâp jêng Y-Êsau kon bôk rah may. Gâp ƀư jêh tĭng nâm nau may ntăm jêh ma gâp. Dâk hom, gŭ jêh ri sa puăch jun gâp, gay ma may dơi mât ton ma gâp.”$b$,false),
('bunong-vn','GEN',27,20,null,$b$Ƀiă lah Y-Isăk lah ma kon bu klâu păng: “Mâm may gơnh mâp jun, Ơ nâu?” Păng lah: “Yor lah Yêhôva Brah Ndu may ăn nau ƀun lap ma gâp.”$b$,false),
('bunong-vn','GEN',27,21,null,$b$Y-Isăk lah ma Y-Yakôb: “Văch êp, gay ma gâp dơi rbot may, Ơ nâu, gĭt lah may jêng kon gâp Y-Êsau ngăn lĕ mâu lah mâu?”$b$,false),
('bunong-vn','GEN',27,22,null,$b$Y-Yakôb hăn êp mbơ̆ păng Y-Isăk, jêh ri păng rbot jêh ri lah: “Bâr ngơi nâm bu bâr ngơi Y-Yakôb, ƀiă lah ti, nâm bu ti Y-Êsau.”$b$,false),
('bunong-vn','GEN',27,23,null,$b$Jêh ri Y-Isăk mâu gĭt năl păng ôh, ƀiă lah ti păng geh rsau nâm bu ti nâu păng Y-Êsau. Pô ri Y-Isăk mât ton ma Y-Yakôb.$b$,false),
('bunong-vn','GEN',27,24,null,$b$Păng lah: “May jêng kon gâp Y-Êsau ngăn lĕ?” Păng lah: “Gâp yơh.”$b$,false),
('bunong-vn','GEN',27,25,null,$b$Păng lah: “Ăn puăch ma gâp; gâp mra sa puăch jun kon gâp, gâp ŭch gâp mât ton ma may.” Păng ăn puăch ma mbơ̆ păng jêh ri păng sa. Păng njŭn dak play kriăk ƀâu jêh ri păng nhêt.$b$,true),
('bunong-vn','GEN',27,26,null,$b$Jêh ri Y-Isăk mbơ̆ păng lah ma păng: “Hăn êp ta gâp jêh ri chŭm gâp, Ơ nâu.”$b$,false),
('bunong-vn','GEN',27,27,null,$b$Păng hăn êp jêh ri chŭm Y-Iăk ƀâu nglâm kho ao păng jêh ri mât ton ma păng lah: “Ơ, ƀâu nglâm kon bu klâu gâp, jêng nâm bu ƀâu nglâm mir Yêhôva ăn jêh nau ueh uĭn.$b$,false),
('bunong-vn','GEN',27,28,null,$b$Dăn ma Brah Ndu ăn ma may dak ngom tă bơh trôk, jêh ri ăn neh may jêng ngăn, geh ba jêh ri dak play kriăk ƀâu âk.$b$,true),
('bunong-vn','GEN',27,29,null,$b$Ăn âk bunuyh ƀon lan jêng tông mpăr ueh may, jêh ri âk phung mpôl băl chon ta năp may. Ăn may jêng Kôranh ma phung oh may, jêh ri ăn phung kon bu klâu me may chon ta năp may. Ăn mbu nâm rtăp rak may jêng bunuyh bu rtăp rak; jêh ri ăn mbu nâm ƀư nau ueh uĭn ma may, geh nau ueh uĭn.”$b$,false),
('bunong-vn','GEN',27,30,null,$b$Tơ lah mhe jêh Y-Isăk mât ton ma Y-Yakôb, jêh ri Y-Yakôb mhe du tă bơh Y-Isăk mbơ̆ păng. Y-Êsau, nâu păng mhe tă sĭt nsong pănh.$b$,true),
('bunong-vn','GEN',27,31,null,$b$Păng nkra tâm ban lĕ puăch kah sa jêh ri njŭn ma mbơ̆ păng jêh ri lah ma mbơ̆ păng: “Ăn mbơ̆ gâp dâk jêh ri sa puăch jun kon bu klâu may, gay ma may dơi mât ton ma gâp.$b$,false),
('bunong-vn','GEN',27,32,null,$b$Y-Isăk, mbơ̆ păng lah ma păng: “Mbu may?’ Gâp jêng Y-Êsau kon bu klâu bôk rah, deh lor lơn.”$b$,false),
('bunong-vn','GEN',27,33,null,$b$Y-Isăk sâr hâu ngăn lah: “Mbu nâm sŏk jêh puăch jun jêh ri njŭn ăn jêh gâp sa, gâp sa lĕ jêh lor ma tât may, jêh ri gâp mât ton jêh ma păng. Nanê̆ păng mra geh nau mât ton.”$b$,true),
('bunong-vn','GEN',27,34,null,$b$Tăng nau mbơ̆ păng lah: Y-Êsau nter ktang ngăn, bêng ma nau rngot, jêh ri păng lah ma mbơ̆ păng: “Mât ton ma gâp tâm ban lĕ, Ơ mbơ̆ gâp.”$b$,false),
('bunong-vn','GEN',27,35,null,$b$Ƀiă lah Y-Isăk lah: “Oh may văch jêh ma nau ndơm, jêh ri păng sŏk jêh nau mât ton may.$b$,false),
('bunong-vn','GEN',27,36,null,$b$Y-Êsau lah: “Mâu di yor nây bu moh păng Y-Yakôb? Yor lah păng pit lơi jêh ndơ gâp bar tơ̆ . Păng sŏk lơi jêh nau gâp jêng nâu ranh, jêh ri, aƀaơ aơ păng sŏk lơi đŏng nau mât ton gâp.” Jêh ri păng lah: “May mâu prăp hĕ nau mât ton ma gâp.”$b$,false),
('bunong-vn','GEN',27,37,null,$b$Y-Isăk lah ma Y-Êsau: “Aơ, gâp ăn jêh păng jêng Kôranh may jêh ri gâp ăn jêh lĕ rngôch phung oh nâu păng jêng oh mon păng; gâp siăm jêh păng ma ba jêh ri dak play kriăk ƀâu. Moh ndơ gâp ăn ma may aơ?”$b$,false),
('bunong-vn','GEN',27,38,null,$b$Y-Êsau lah ma mbơ̆ păng: “May geh knŏng du nau mât ton hĕ, Ơ mbơ̆ gâp?” Mât ton an ma gâp tâm ban lĕ, ơ mbơ̆ gâp, Ơ mbơ̆ gâp.”$b$,false),
('bunong-vn','GEN',27,39,null,$b$Jêh ri Y-Êsau nter nhĭm, Y-Isăk, mbơ̆ păng plơ̆ lah ma păng, aơ, may mra gŭ ta neh mâu jêng ndơ âk ôh, jêh ri may mra kƀah dak ngom bơh trôk ta klơ.$b$,false),
('bunong-vn','GEN',27,40,null,$b$May mra gŭ rêh ma đao may ri mơ dơi rêh, jêh ri jêng oh mon ma oh may. Ƀiă lah dôl may rêh mblêng ta aơ ta ri, may mra nkêch lơi mâng mbăk păng ta trô ko may.$b$,false),
('bunong-vn','GEN',27,41,null,$b$Y-Êsau tâm rmot ma Y-Yakôb yor nau mât ton mbơ̆ khân păng ăn ma păng, jêh ri Y-Êsau lah êng tâm nuih n'hâm: “Nar nhĭm nhhiăng ma mbơ̆ gâp hŏ dăch tât jêh. Rnôk nây gâp mra nkhĭt Y-Yakôb, oh gâp:$b$,true),
('bunong-vn','GEN',27,42,null,$b$“Bu mbơh ma H'Rêbêka nau Y-Êsau kon bu klâu bôk rah păng ngơi. Păng đă bu kuăl Y-Yakôb kon păng jêh ri lah: “Aơ, nâu may Y-Êsau ma nau păng mĭn har plơng mra nkhĭt may.$b$,false),
('bunong-vn','GEN',27,43,null,$b$Aƀaơ, Ơ nâu, iăt nau gâp. Dâk hom may jêh ri hăn du ta ƀon Charan ma Y-Laban nâu gâp.$b$,false),
('bunong-vn','GEN',27,44,null,$b$Ăn may gŭ ndrel ma păng ăn jŏ djê̆ kŏ tât nau nuih nâu may roh jêh,$b$,false),
('bunong-vn','GEN',27,45,null,$b$tơ lah nâu may roh nau păng nuih ma may, jêh ri chuêl jêh nau may ƀư ma păng. Dôl nây gâp mra an may sĭt bơh nây. Moh khlay gâp roh lĕ bar hê khân may tâm du nar?”$b$,false),
('bunong-vn','GEN',27,46,null,$b$H'Rêbêka lah ma Y-Isăk: “Nau rêh gâp rngot ngăn, mâu hôm ŭch rêh đŏng ôh, yor lah phung kon bu ur Mpôl Y-Het. Tơ lah Y-Yakôb sŏk du huê tâm phung kon bu ur Mpôl Y-Het jêng ur, du huê bu ur tâm n'gor aơ nâm bu phung nây; moh khlay nau rêh gâp?”$b$,false),
('bunong-vn','GEN',28,1,null,$b$Y-Isăk kuăl Y-Yakôb, păng mât ton jêh ri ntăm ma Y-Yakôb: “Lơi sŏk ôh ur bơh phung kon bu ur n'gor Kanaan.$b$,true),
('bunong-vn','GEN',28,2,null,$b$Dâk hom may, hăn ta n'gor Padan Aram ta ngih Y-Bêthel mbơ̆ me may.$b$,true),
('bunong-vn','GEN',28,3,null,$b$Ăn Brah Ndu, Nơm geh lĕ Nau Brah, ăn nau ueh uĭn ma may jêh ri ăn bĭk rơ̆ may, gay ma may mra jêng du phung ƀon lan âk.$b$,false),
('bunong-vn','GEN',28,4,null,$b$Dăn ma păng ăn ma may nau mât ton Y-Abraham jêh ri ma phung kon sau may, gay ma may dơi dơn n'gor may gŭ ƀât lât, n'gor Brah Ndu ăn jêh ma Y-Abraham.”$b$,false),
('bunong-vn','GEN',28,5,null,$b$Pô ri Y-Isăk ăn Y-Yakôb hăn. Păng hăn ta n'gor Padan Aram ta Y-Bêthel kon bu klâu, bunuyh Aramêa, nâu H'Rêbêka, me Y-Yakôb jêh ri Y-Êsau.$b$,false),
('bunong-vn','GEN',28,6,null,$b$Y-Êsau saơ Y-Isăk mât ton jêh ma Y-Yakôb ăn jêh păng hăn ta ƀon Padan Aram, gay ma sŏk ur ta nây; jêh ri dôl păng mât ton ma păng, păng ntăm pô aơ, lah: “Lơi ta may sŏk ur bơh phung kon bu ur Kanaan.”$b$,true),
('bunong-vn','GEN',28,7,null,$b$Jêh ri Y-Êsau saơ jêh Y-Yakôb tông bâr mbơ̆ me păng, hăn jêh ta n'gor Padan Aram.$b$,false),
('bunong-vn','GEN',28,8,null,$b$Tơ lah Y-Êsau saơ phung kon bu ur n'gor Kanaan mâu geh nau maak ôh ma Y-Isăk mbơ̆ păng.$b$,false),
('bunong-vn','GEN',28,9,null,$b$Y-Êsau hăn ta Y-Ismaêl jêh ri sŏk ur êng. H'Mahalat kon bu ur Y-Ismaêl, kon bu klâu Y-Abraham, ruh Y-Nêbalôt.$b$,false),
('bunong-vn','GEN',28,10,null,$b$Y-Yakôb du tă bơh ƀon Bêr Sêba jêh ri hăn ta ƀon Charan.$b$,true),
('bunong-vn','GEN',28,11,null,$b$Păng tât ta du ntŭk jêh ri bêch ta nây du măng, yor lah nar nhâp jêh. Păng sŏk glo lŭ ta ntŭk nây dŏng jêng ka n'hơi dâm bôk jêh ri lâng săk bêch ta nây.$b$,false),
('bunong-vn','GEN',28,12,null,$b$Păng geh nau mbơi. Aơ, geh du mlâm gung ndâk ta neh jêh ri bôk jâng gung prêh kŏ pa trôk; jêh ri aơ, phung tông mpăr ueh Brah Ndu hao jêh ri jŭr ta gung nây.$b$,false),
('bunong-vn','GEN',28,13,null,$b$Aơ, Yêhôva gŭ râng ta klơ jâng gung jêh ri lah: “Gâp jêng Yêhôva, Brah Ndu Y-Abraham che may jêh ri Brah Ndu Y-Isăk. Neh may lâng săk gâp mra ăn may jêh ri ma phung kon sau may.$b$,false),
('bunong-vn','GEN',28,14,null,$b$Phung kon sau may mra jêng âk nâm bu ndruyh neh, may mra ăn bĭk pa dâng, pa lơ, pa lơ dor jêh ri tâm rđŭng, jêh ri lĕ rngôch phung mpôl băl tâm neh ntu mra geh nau ueh uĭn, yor may jêh ri yor phung kon sau may.$b$,false),
('bunong-vn','GEN',28,15,null,$b$Aơ, gâp gŭ ndrel ma may, jêh ri gâp mra chiă uănh may tâm ăp ntŭk may mra hăn, jêh ri mra njŭn may sĭt ta n'gor aơ; yor lah gâp mâu mra cha lơi may ôh kŏ tât gâp ƀư jêh nau gâp ngơi ma may.”$b$,false),
('bunong-vn','GEN',28,16,null,$b$Y-Yakôb kah rngăl bêch jêh ri lah: “Nanê̆, Yêhôva gŭ tâm ntŭk aơ, jêh ri gâp mâu gĭt nau nây ôh.”$b$,false),
('bunong-vn','GEN',28,17,null,$b$Păng klach jêh ri lah: “Ntŭk aơ khư klach ngăn. Nanê̆, ntŭk aơ jêng ngih Brah Ndu, jêh ri jêng mpông pêr trôk!”$b$,false),
('bunong-vn','GEN',28,18,null,$b$Y-Yakôb dâk ơm ôi, păng sŏk lŭ dâm bôk, ndâk păng jêng ndơ tâm mbên, jêh ri nkhŭt dak ƀâu kah ta klơ nây.$b$,true),
('bunong-vn','GEN',28,19,null,$b$Păng rnha ntŭk nây Bêthel, ƀiă lah sa ơm ri ntŭk nây bu rnha Lus,$b$,false),
('bunong-vn','GEN',28,20,null,$b$Y-Yakôb ƀư nau ton jêh ri lah: “Tơ lah Brah Ndu mra gŭ ndrel ma gâp, tơ lah păng mra chiă uănh gâp tâm trong gâp nsong, tơ lah păng mra ăn piăng let ma gâp sa jêh ri kho ao ma gâp soh,$b$,false),
('bunong-vn','GEN',28,21,null,$b$gay ma gâp sĭt ma nau đăp mpăn ta ngih mbơ̆ gâp, pô ri Yêhôva mra jêng Brah Ndu gâp.$b$,false),
('bunong-vn','GEN',28,22,null,$b$Jêh ri lŭ aơ gâp ndâk jêh jêng ndơ tâm mbên mra jêng ngih Brah Ndu; jêh ri gâp mra ăn du kô̆ tâm jât bơh lĕ rngôch ndơ may mra ăn ma gâp.”$b$,true),
('bunong-vn','GEN',29,1,null,$b$Y-Yakôb dâk hăn jêh ri tât ta n'gor phung ƀon pa lơ.$b$,true),
('bunong-vn','GEN',29,2,null,$b$Păng uănh jêh ri, geh du ntŭk ntu dak tâm mir jêh ri pe mpôl phung biăp gŭ kuen ta nây; yor lah bơh ntu dak nây bu ăn nhêt biăp. Lŭ ta bâr ntu dak nây toyh,$b$,false),
('bunong-vn','GEN',29,3,null,$b$Tơ lah bu tâm rƀŭn ta nây lĕ rngôch mpôl biăp, phung rmăk biăp rlă lŭ bơh bâr ntu dak nây gay ma ăn biăp nhêt jêh ri rdâl tay lŭ ta bâr ntu dak.$b$,false),
('bunong-vn','GEN',29,4,null,$b$Y-Yakôb lah ma khân păng: “Ơ phung oh nâu mbah tă khân may?” Khân păng lah: “Hên văch tă bơh ƀon Charan.”$b$,false),
('bunong-vn','GEN',29,5,null,$b$Păng lah ma phung nây: “Khân may gĭt năl lĕ Y-Laban, kon bu klâu Y-Nahôr phung nây lah: “Hên gĭt năl lĕ păng.”$b$,false),
('bunong-vn','GEN',29,6,null,$b$Păng lah: “Păng ngăch săk jăn lĕ?” Phung nây lah: “Păng ngăch lĕ”, jêh ri aơ H'Rachel kon bu ur păng văch ndrel ma biăp!”$b$,false),
('bunong-vn','GEN',29,7,null,$b$Y-Yakôb lah: “Aơ, nar hôm e ơm ê tât mông ôh tâm rƀŭn biăp. Ăn biăp nhêt dak jêh ri njŭn leo khân păng hăn sa hĭp.”$b$,false),
('bunong-vn','GEN',29,8,null,$b$Khân păng lah, hên mâu dơi kŏ lĕ rngôch biăp tâm rƀŭn ndrel, jêh ri bu rlă lŭ tă bâr ntu dak. Dôl nây hên ăn biăp nhêt.”$b$,false),
('bunong-vn','GEN',29,9,null,$b$Dôl Y-Yakôb gŭ ngơi đah khân păng, H'Rachel hăn văch ndrel ma biăp mbơ̆ păng, yor lah păng jêng rmăk biăp.$b$,false),
('bunong-vn','GEN',29,10,null,$b$Tơ lah Y-Yakôb saơ H'Rachel, kon bu ur Y-Laban, nâu me păng jêh ri biăp Y-Laban nâu me păng, Y-Yakôb hăn rlă lŭ bơh bâr ntu dak jêh ri ăn biăp Y-Laban nâu me păng nhêt.$b$,true),
('bunong-vn','GEN',29,11,null,$b$Jêh ri Y-Yakôb chŭm H'Rachel jêh ri nhĭm.$b$,false),
('bunong-vn','GEN',29,12,null,$b$Y-Yakôb nkoch ma H'Rachel, păng jêng mpôl băl mbơ̆ H'Rachel, jêh ri păng jêng kon H'Rachel. Păng nchuăt mbơh nau nây ma mbơ̆ păng,$b$,false),
('bunong-vn','GEN',29,13,null,$b$tơ lah Y-Laban tăng nau nkoch bri ma Y-Yakôb kon oh bu ur păng, păng nchuăt ran tâm mâp, ut chŭm păng, jêh ri njŭn leo sĭt ta ngih păng. Y-Yakôb nkoch bri ma Y-Laban lĕ nau tât.$b$,false),
('bunong-vn','GEN',29,14,null,$b$Y-Laban lah ma păng: “Nanê̆, may jêng nting gâp jêh ri nglay săk gâp.” Y-Yakôb gŭ ndrel ma păng du khay.$b$,false),
('bunong-vn','GEN',29,15,null,$b$Jêh ri Y-Laban lah ma Y-Yakôb. Yor lah may jêng ndŭl mpôl gâp, may mra pah kan ma gâp dơm dam hĕ? Lah ma gâp, dŭm gâp mra nkhôm may?”$b$,false),
('bunong-vn','GEN',29,16,null,$b$Y-Laban geh bar hê kon bu ur, amoh nur sâng păng H'Lêa, amoh oh păng H'Rachel.$b$,false),
('bunong-vn','GEN',29,17,null,$b$H'Lêa geh măt ra-ai, ƀiă lah muh măt nđâp săk jăn H'Rachel ueh ngăn.$b$,false),
('bunong-vn','GEN',29,18,null,$b$Y-Yakôb rŏng ma H'Rachel jêh ri lah: “Gâp mra pah kan ma may pơh năm gay ma geh H'Rachel kon bu ur may jêng ur.”$b$,false),
('bunong-vn','GEN',29,19,null,$b$Y-Laban lah: “Ueh lơn gâp ăn păng ma may, ma đah gâp ăn păng ma bu klâu êng. Gŭ hom ndrel ma gâp.”$b$,false),
('bunong-vn','GEN',29,20,null,$b$Pô ri Y-Yakôb pah kan pơh năm gay geh H'Rachel jêng ur. Năm đah nây jêng nâm bu djê̆ ir nar ma păng yor nau păng rŏng ma bu ur nây.$b$,false),
('bunong-vn','GEN',29,21,null,$b$Y-Yakôb lah ma Y-Laban: “Ăn ma gâp ur gâp, gay ma gâp dơi gŭ ndrel ma păng, yor lah năm gâp pah kan lôch jêh.”$b$,false),
('bunong-vn','GEN',29,22,null,$b$Y-Laban tâm rƀŭn lĕ rngôch bunuyh ntŭk nây ƀư nau nhêt sông.$b$,true),
('bunong-vn','GEN',29,23,null,$b$Tơ lah măng jêh păng sŏk kon bu ur păng H'Lêa njŭn leo ma Y-Yakôb jêh ri Y-Yakôb gŭ ndrel păng.$b$,false),
('bunong-vn','GEN',29,24,null,$b$Y-Laban ăn oh mon bu ur păng jêng oh mon ma H'Lêa kon bu ur păng.$b$,true),
('bunong-vn','GEN',29,25,null,$b$Kah ang ôi, aơ bu ur nây nkhơng ma H'Lêa. Jêh ri Y-Yakôb lah ma Y-Laban: “Moh nau may ƀư ma gâp?” Mâu di hĕ gâp pah kan ma may gay geh H'Rachel? Pô ri, mâm ƀư may ndơm jêh gâp?”$b$,false),
('bunong-vn','GEN',29,26,null,$b$Y-Laban lah: “Mâu vay ôh ta n'gor aơ ăn oh lor lơn ma nur.$b$,false),
('bunong-vn','GEN',29,27,null,$b$Ăn may gŭ ndrel ma păng tâm du nar pơh, jêh ri hên mra ăn lĕ oh păng ma may, tơ lah may pah kan đŏng pơh năm.$b$,false),
('bunong-vn','GEN',29,28,null,$b$Y-Yakôb ƀư pô nây. Păng gŭ ndrel ma H'Lêa lĕ du nar pơh jêh ri Y-Laban ăn đŏng H'Rachel kon bu ur păng jêng ur Y-Yakôb.$b$,false),
('bunong-vn','GEN',29,29,null,$b$(Y-Laban ăn đŏng oh mon bu ur păng H'Bilha jêng oh mon bu ur ma H'Rachel kon bu ur păng)$b$,false),
('bunong-vn','GEN',29,30,null,$b$Y-Yakôb gŭ ndrel ma H'Rachel jêh ri rŏng ma H'Rachel âk lơn ma H'Lêa. Păng pah kan đŏng ma Y-Laban pơh năm.$b$,false),
('bunong-vn','GEN',29,31,null,$b$Yêhôva saơ Y-Yakôb mâu rŏng ôh ma H'Lêa, jêh ri păng dơi ăn H'Lêa ntreo. Bi H'Rachel jêng bu ur mâu bă.$b$,true),
('bunong-vn','GEN',29,32,null,$b$H'Lêa ntreo jêh ri deh ma du huê kon bu klâu. Păng amoh kon nây Y-Ruben, yor lah păng lah: “Yêhôva uănh jêh ma nau rngot gâp. Yor nây, nanê̆, sai gâp mra rŏng ma gâp.”$b$,false),
('bunong-vn','GEN',29,33,null,$b$Păng ntreo đŏng jêh ri deh ma du huê kon bu klâu, jêh ri lah yor lah Yêhôva tăng jêh bu mâu rŏng ôh ma gâp, pô ri păng ăn đŏng kon bu klâu aơ ma gâp.” Jêh ri păng tâm amoh Y-Simêôn.$b$,false),
('bunong-vn','GEN',29,34,null,$b$Păng ntreo jêh ri deh đŏng ma du huê kon bu klâu jêh ri lah: “Aƀaơ aơ, sai gâp mra tâm krêp đah gâp, yor lah gâp deh jêh ma păng pe nuyh kon bu klâu.” Yor ri bu tâm amoh păng Y-Lêvi.$b$,false),
('bunong-vn','GEN',29,35,null,$b$Păng ntreo jêh ri deh đŏng ma du huê kon bu klâu, jêh ri păng lah: “Tơ̆ aơ gâp mra tâm rnê ma Yêhôva.” Yor ri păng tâm amoh kon nây Y-Yuđa, q jêh ri păng rlu ntreo.$b$,false),
('bunong-vn','GEN',30,1,null,$b$Tơ lah H'Rachel saơ păng mâu deh kon ma Y-Yakôb ôh, păng mô nach ma nur păng; jêh ri păng lah ma Y-Yakôb: “Ăn phung kon ma gâp mâu lah gâp khĭt.”$b$,true),
('bunong-vn','GEN',30,2,null,$b$Y-Yakôb hao nuih, ji nuih ma H'Rachel jêh ri lah: “Gâp hĕ jêng Brah Ndu, nơm dun ăn kon ma ay?”$b$,true),
('bunong-vn','GEN',30,3,null,$b$H'Rachel lah: “Aơ oh mon bu ur gâp H'Bilha. Gŭ hom ndrel păng, gay ma păng dơi deh kon ta kômâk gâp, jêh ri ma gâp mra geh phung kon đŏng bơh păng.”$b$,false),
('bunong-vn','GEN',30,4,null,$b$H'Rachel ăn H'Bilha oh mon bu ur păng jêng ur Y-Yakôb, jêh ri Y-Yakôb hăn gŭ ndrel păng.$b$,false),
('bunong-vn','GEN',30,5,null,$b$H'Bilha ntreo jêh ri deh ma du huê kon bu klâu ma Y-Yakôb.$b$,false),
('bunong-vn','GEN',30,6,null,$b$H'Rachel lah, Brah Ndu sek uănh nau gâp sŏng jêh. Păng tăng jêh bâr gâp jêh ri ăn ma gâp du huê kon bu klâu.” Yor nây păng tâm amoh kon nây Y-Dan.$b$,false),
('bunong-vn','GEN',30,7,null,$b$H'Bilha oh mon bu ur H'Rachel ntreo đŏng jêh ri deh ma du huê kon bu klâu tal bar ma Y-Yakôb.$b$,false),
('bunong-vn','GEN',30,8,null,$b$H'Rachel lah: “Gâp tâm nhăt ktang đah nur gâp, jêh ri gâp dơi jêh.” Pô ri păng tâm amoh kon nây Y-Naptali.$b$,false),
('bunong-vn','GEN',30,9,null,$b$Tơ lah H'Lêa saơ jêh păng rlu ntreo,$b$,false),
('bunong-vn','GEN',30,10,null,$b$păng sŏk H'Silpa oh mon bu ur H'Lêa deh du huê kon bu klâu ma Y-Yakôb.$b$,false),
('bunong-vn','GEN',30,11,null,$b$H'Lêa lah: “Nau ueh uĭn ngăn”. Pô ri păng tâm amoh Y-Gat.$b$,false),
('bunong-vn','GEN',30,12,null,$b$H'Silpa oh mon bu ur H'Lêa deh du huê kon bu klâu tal bar ma Y-Yakôb.$b$,false),
('bunong-vn','GEN',30,13,null,$b$H'Lêa lah: “Maak ngăn gâp! Yor lah phung bu ur mra rnha gâp nơm maak.” Pô ri păng tâm amoh Y-Aser.$b$,false),
('bunong-vn','GEN',30,14,null,$b$Y-Ruben hăn tâm mir dôl yăn kăch ba ƀlê. Păng saơ play bum mandragôr jêh ri păng djôt play nây ma H'Lêa me păng. H'Rachel lah ma H'Lêa: “Ăn ma gâp ƀă play bum mandragôr kon ay.”$b$,false),
('bunong-vn','GEN',30,15,null,$b$H'Lêa lah ma păng: “Ê tŏng hĕ ay sŏk jêh sai gâp? Ƀiă lah ay ŭch sŏk play bum mandragôr kon gâp đŏng?” H'Rachel lah: “Pô ri Y-Yakôb mra bêch ndrel ay măng aơ gay ma gâp dơi geh play bum mandragôr kon ay.”$b$,false),
('bunong-vn','GEN',30,16,null,$b$Tơ lah Y-Yakôb sĭt ta bơh mir kêng măng, H'Lêa luh hăn tâm mâp đah păng jêh ri lah: “May mra văch bêch ndrel ma gâp, yor lah gâp lĕ rvăt jêh may ma bum mandragôr kon gâp.” Pô ri Y-Yakôb ndrel ma H'Lêa măng nây.$b$,false),
('bunong-vn','GEN',30,17,null,$b$Brah Ndu tăng H'Lêa ntreo jêh ri deh kon bu klâu tal prăm ma Y-Yakôb.$b$,true),
('bunong-vn','GEN',30,18,null,$b$H'Lêa lah, Brah Ndu nkhôm jêh gâp, yor lah gâp ăn oh mon bu ur gâp ma sai gâp.” Pô ri păng tâm amoh Y-Isakar.$b$,false),
('bunong-vn','GEN',30,19,null,$b$H'Lêa ntreo đŏng jêh ri deh kon bu klâu tal prao ma Y-Yakôb.$b$,false),
('bunong-vn','GEN',30,20,null,$b$H'Lêa lah, Brah Ndu ăn drăp ndơ khlay ngăn ma gâp, aƀaơ sai gâp mra yơk ma gâp, yor lah gâp deh jêh ma păng prao nuyh kon bu klâu.” Pô ri păng tâm amoh Y-Sabulôn.$b$,true),
('bunong-vn','GEN',30,21,null,$b$Jêh ma nây păng deh du huê kon bu ur jêh ri tâm amoh H'Dina.$b$,false),
('bunong-vn','GEN',30,22,null,$b$Jêh ri Brah Ndu kah gĭt ma H'Rachel. Păng iăt nau jêh ri ăn păng ntreo.$b$,false),
('bunong-vn','GEN',30,23,null,$b$Păng ntreo jêh ri deh du huê kon bu klâu jêh ri lah: “Brah Ndu sŏk lơi jêh nau bêk gâp.”$b$,false),
('bunong-vn','GEN',30,24,null,$b$Păng amoh kon se nây Y-Yôsep, lah: “Gay ma Brah Ndu ntop đŏng an ma gâp du huê kon bu klâu êng.”$b$,false),
('bunong-vn','GEN',30,25,null,$b$Jêh H'Rachel deh ma Y-Yôsep, Y-Yakôb lah ma Y-Laban: “Ăn gâp hăn gay gâp dơi sĭt ta ntŭk gâp nơm tâm n'gor gâp.$b$,true),
('bunong-vn','GEN',30,26,null,$b$Ăn ma gâp phung ur gâp jêh ri phung kon gâp; yor ŭch geh phung nây yơh gâp pah kan jêh ma may, jêh ri ăn gâp hăn; yor lah may gĭt jêh kan gâp kơl may.”$b$,false),
('bunong-vn','GEN',30,27,null,$b$Y-Laban lah ma păng: “Ăn gâp lah nau aơ; gâp gĭt ma nau geh Yêhôva ăn jêh nau ueh uĭn ma gâp yor may.$b$,false),
('bunong-vn','GEN',30,28,null,$b$Lah hom mdah âk gâp mra nkhôm may jêh ri gâp mra ăn.”$b$,true),
('bunong-vn','GEN',30,29,null,$b$Y-Yakôb lah ma păng: “May gĭt jêh mâm nau gâp pah kan ma may, moh mpô mpa may rong jêng jêh yor gâp,$b$,false),
('bunong-vn','GEN',30,30,null,$b$yor lah may geh djê̆ dơm ndơ lor ma gâp tât, Ƀiă lah păng hao jêng âk. Yêhôva ăn jêh nau ueh uĭn ta ntŭk gâp hăn. Bi aƀaơ aơ ndah jŏ gâp mra geh ndơ ma ngih gâp nơm?”$b$,false),
('bunong-vn','GEN',30,31,null,$b$Y-Laban lah: “Moh ndơ gâp mra ăn ma may? Y-Yakôb lah, may mâu mra ăn ndơ ma gâp ôh. Tơ lah may mra ƀư pô aơ ma gâp, gâp mra chiăp đŏng ôh biăp may.$b$,false),
('bunong-vn','GEN',30,32,null,$b$Nar aơ gâp mra hăn ta nklang lĕ rngôch biăp may ŭch dơm rnglah êng lĕ rngôch biăp rvanh jêh ri ƀlak, lĕ rngôch biăp krăk, jêh ri lĕ rngôch be rvanh jêh ri ƀlak. Ndơ nây mra jêng ndơ nkhôm gâp.$b$,true),
('bunong-vn','GEN',30,33,null,$b$Pô ri nau sŏng srăng gâp mra tâm mpơl ma gâp bah kơi; tơ lah may mra văch uănh ndơ nkhôm gâp. Lĕ rngôch be mâu geh rvanh jêh ri ƀlak, lĕ rngôch biăp mâu geh krăk mra kơp tâm ban ma gâp ntŭng.”$b$,false),
('bunong-vn','GEN',30,34,null,$b$Y-Laban lah: “Ueh jêh ăn nau nây jêng tĭng nâm nau may ngơi.”$b$,false),
('bunong-vn','GEN',30,35,null,$b$Nar nây lĕ Y-Laban tâm nkhah be nkuăng rvanh jêh ri ƀlak jêh ri lĕ rngôch be me rvanh jêh ri ƀlak, lĕ rngôch be nkuăng geh ntŭk nglang jêh ri lĕ rngôch biăp krăk. Păng jao ndơ nây ma ti phung kon bu klâu păng.$b$,false),
('bunong-vn','GEN',30,36,null,$b$Păng ăn ƀah ngai pe nar hăn păng đah Y-Yakôb. Y-Yakôb chiăp biăp Y-Laban hôm e.$b$,false),
('bunong-vn','GEN',30,37,null,$b$Y-Yakôb sŏk n'gĭng ndrêh tơm ai pôplar, amandê, jêh ri platan, păng koch ntâu n'gĭng si nây mpơl ntŭk nglang.$b$,true),
('bunong-vn','GEN',30,38,null,$b$Păng dơm n'gĭng si nây tâm pa năp biăp pa, kêng, jêng ntŭk bong dak, jêng ntŭk khân păng hăn văch nhêt dak.$b$,false),
('bunong-vn','GEN',30,39,null,$b$Biăp tâm gar ta năp n'gĭng si nây jêh ri khân păng deh kon rvanh ƀrưnh jêh ri ƀlak.$b$,false),
('bunong-vn','GEN',30,40,null,$b$Y-Yakôb tâm nkhah lĕ rngôch kon biăp nây jêh ri păng dơm ndrel ma biăp rvanh jêh ri krăk tâm biăp Y-Yakôb; ƀiă lah păng dơm êng biăp păng nơm. Păng mâu tâm srŭk biăp păng nơm đah biăp Y-Laban ôh.$b$,false),
('bunong-vn','GEN',30,41,null,$b$Tơ lah biăp ktang lơn tâm gar Y-Yakôb dơm n'gĭng si tâm nor ta năp măt khân păng gay ma khân păng tâm gar ta năp n'gĭng si.$b$,false),
('bunong-vn','GEN',30,42,null,$b$Ƀiă lah tơ lah biăp ra ai, păng mâu dơm ndrel ôh. Pô ri biăp ra ai lơn jêng ndơ Y-Laban, jêh ri biăp ktang lơn jêng ndơ Y-Yakôb.$b$,false),
('bunong-vn','GEN',30,43,null,$b$Pô ri Y-Yakôb hao ndrŏng ngăn. Păng geh biăp âk, phung oh mon bu ur, phung oh mon bu klâu, seh samô jêh ri seh bri.$b$,false),
('bunong-vn','GEN',31,1,null,$b$Y-Yakôb tăng nau phung kon bu klâu Y-Laban ngơi lah: “Y-Yakôb sŏk jêh lĕ rngôch ndơ mbơ̆ he; jêh ri ma ndơ mbơ̆ he yơh păng jêng ndrŏng.”$b$,true),
('bunong-vn','GEN',31,2,null,$b$Y-Yakôb saơ Y-Laban mâu hôm rŏng ma păng ôh.$b$,true),
('bunong-vn','GEN',31,3,null,$b$Jêh ri Yêhôva lah ma Y-Yakôb: “Sĭt hom ta n'gor phung che may jêh ri ma phung mpôl băl jêh ri gâp mra gŭ ndrel ma may.”$b$,false),
('bunong-vn','GEN',31,4,null,$b$Y-Yakôb đă bu hăn kuăl H'Rachel jêh ri H'Lêa hăn ta mir djôt biăp păng.$b$,false),
('bunong-vn','GEN',31,5,null,$b$Păng lah ma phung ur păng: “Gâp saơ mbơ̆ khân ay mâu hôm rŏng ma gâp ôh nâm bu lor ƀiă lah Brah Ndu mbơ̆ gâp gŭ ndrel ma gâp jêh.$b$,false),
('bunong-vn','GEN',31,6,null,$b$Khân ay gĭt jêh gâp pah kan jêh ma lĕ nau ktang gâp ma mbơ̆ khân ay.$b$,false),
('bunong-vn','GEN',31,7,null,$b$Ƀiă lah mbơ̆ khân ay ndơm jêh gâp, tâm rgâl jât tơ̆ ndơ nkhôm gâp; ƀiă lah Brah Ndu mâu ăn păng ƀư ma gâp ôh.”$b$,false),
('bunong-vn','GEN',31,8,null,$b$Tơ lah păng lah: “Biăp, be rvanh mra jêng ndơ nkhôm may; pô ri lĕ rngôch biăp be deh rvanh.$b$,false),
('bunong-vn','GEN',31,9,null,$b$Pô ri Brah Ndu sŏk jêh biăp be mbơ̆ khân ay jêh ri ăn ma gâp.$b$,false),
('bunong-vn','GEN',31,10,null,$b$Dôl biăp tâm gar gâp n'gơr măt uănh tâm nau mbơi; aơ be nkuăng tâm groi đah be me jêng rvanh ƀrưnh, jêh ri ƀlak.$b$,false),
('bunong-vn','GEN',31,11,null,$b$Tông mpăr ueh Brah Ndu lah ma gâp tâm nau mbơi: “Ơ Y-Yakôb!, Gâp lah: “Aơ ta aơ gâp.$b$,false),
('bunong-vn','GEN',31,12,null,$b$Păng lah: “N'gơr măt may jêh ri uănh: Lĕ rngôch be nkuăng tâm groi đah be me jêng rvanh ƀrưnh, jêh ri ƀlak; yor lah gâp saơ lĕ nau Y-Laban ƀư ma may.$b$,false),
('bunong-vn','GEN',31,13,null,$b$Gâp jêng Brah Ndu Bêthel ntŭk may nkhŭt dak ƀâu kah ta klơ ndơ tâm mbên, ntŭk may ƀư jêh nau ton ma gâp. Aƀaơ aơ, dâk hom may, luh bơh n'gor aơ jêh ri sĭt ta n'gor bu deh ma may.$b$,false),
('bunong-vn','GEN',31,14,null,$b$H'Rachel jêh ri H'Lêa plơ̆ lah ma păng: “Hôm geh lĕ ma hên du kô̆ mâu lah drăp ndơn tâm ngih mbơ̆ hên?$b$,false),
('bunong-vn','GEN',31,15,null,$b$Mâu di hĕ păng kơp hên tâm ban ma bu năch? Yor lah păng tăch jêh hên, jêh ri sa jêh prăk bu rvăt hên!$b$,false),
('bunong-vn','GEN',31,16,null,$b$Lĕ drăp ndơ Brah Ndu sŏk bơh mbơ̆ hên jêng ndơ hên jêh ri ma phung kon hên. Aƀaơ aơ, ƀư lĕ mâm nau Brah Ndu đă may ƀư.”$b$,false),
('bunong-vn','GEN',31,17,null,$b$Pô ri Y-Yakôb dâk, jêh ri păng ăn phung kon bu klâu jêh ri phung ur păng ncho seh samô.$b$,true),
('bunong-vn','GEN',31,18,null,$b$Păng ndjôt leo lĕ mpô mpa păng, ndơ bun jêh, phung păng geh jêh tĭng nâm păng sŏk tâm n'gor Padan Aram, ŭch hăn ta Y-Isăk mbơ̆ păng tâm n'gor Kanaan.$b$,false),
('bunong-vn','GEN',31,19,null,$b$Y-Laban hăn nkăp rsau biăp păng, jêh ri H'Rachel ntŭng rup brah ngih mbơ̆ păng.$b$,true),
('bunong-vn','GEN',31,20,null,$b$Y-Yakôb du ntŭng bơh Y-Laban bunuyh Aram. Păng mâu lah ôh ma păng mĭn du.$b$,true),
('bunong-vn','GEN',31,21,null,$b$Păng du ma lĕ rngôch mpa păng geh. Păng dâk jêh ri rgăn dak krong Ơphrat, jêh ri păng hăn mơ pa yôk Gilêat.$b$,true),
('bunong-vn','GEN',31,22,null,$b$Ta nar tal pe bu mbơh ma Y-Laban nau Y-Yakôb du jêh.$b$,true),
('bunong-vn','GEN',31,23,null,$b$Pô ri păng sŏk ndŭl mpôl păng ndrel ma păng jêh ri tĭng Y-Yakôb pơh nar hăn trong. Păng dăch ban Y-Yakôb ta yôk Gilêat.$b$,false),
('bunong-vn','GEN',31,24,null,$b$Brah Ndu hăn ta Y-Laban bunuyh Aram tâm nau mbơi dôl măng jêh ri lah ma păng: “Njrăng hom ma may nơm. Lơi ngơi ma Y-Yakôb nau ueh mâu lah nau mhĭk ôh.”$b$,false),
('bunong-vn','GEN',31,25,null,$b$Y-Laban ban Y-Yakôb. Y-Yakôb pâng rdâk jêh ngih bok păng ta n'gor mpư̆ yôk, jêh ri Y-Laban ndrel ma phung păng rdâk đŏng ngih bok ta n'gor mpư̆ yôk Gilêat.$b$,true),
('bunong-vn','GEN',31,26,null,$b$Y-Laban lah ma Y-Yakôb: “Moh may ƀư jêh? May du ntŭng bơh gâp jêh ri may rdu phung kon bu ur nâm bu phung bu nă bu nhŭp ma đao.$b$,true),
('bunong-vn','GEN',31,27,null,$b$Mâm ƀư may du ntŭng jêh ri sŏk ndô ndơ gâp, mâu mbơh ma gâp ôh, gay ma gâp dơi ăn may hăn ma nau maak, nau mprơ ma bâr gâr jê̆ jêh ri bâr gong rêng?$b$,false),
('bunong-vn','GEN',31,28,null,$b$Mâu lĕ may ăn gâp chŭm phung kon bu klâu jêh ri phung kon bu ur gâp. Ma nau rluk may ƀư pô nây.$b$,false),
('bunong-vn','GEN',31,29,null,$b$Ti gâp dơi ƀư mhĭk ma may, ƀiă lah Brah Ndu mbơ̆ may ngơi jêh đah gâp măng ndơh lah: “Njrăng hom ma may nơm, lơi ngơi ma Y-Yakôb nau ueh mâu lah nau mhĭk ôh.$b$,false),
('bunong-vn','GEN',31,30,null,$b$Aƀaơ aơ may du yor may klâng ngăn ma ngih mbơ̆ may ƀiă lah mâm ƀư may ntŭng rup brah gâp?”$b$,false),
('bunong-vn','GEN',31,31,null,$b$Y-Yakôb plơ̆ lah ma Y-Laban: “Yor lah gâp klach lah may mra sŏk sĭt phung kon bu ur may bơh gâp.$b$,true),
('bunong-vn','GEN',31,32,null,$b$Ƀiă lah ma nau nơm may saơ rup brah may, nơm nây mâu mra gŭ rêh ôh. Ta năp phung oh nâu he ăn may sek uănh moh ndơ jêng ndơ may gŭ ndrel gâp, jêh ri sŏk ndơ nây. Yor lah Y-Yakôb mâu gĭt ôh H'Rachel ntŭng jêh rup brah nây.$b$,false),
('bunong-vn','GEN',31,33,null,$b$Y-Laban lăp tâm ngih bok Y-Yakôb, ngih bok H'Lêa jêh ri tâm ngih bok bar hê oh mon bu ur, ƀiă lah păng mâu saơ ndơ nây ôh. Păng lah tă bơh ngih bok H'Lêa jêh ri lăp tâm ngih H'Rachel.$b$,true),
('bunong-vn','GEN',31,34,null,$b$H'Rachel sŏk jêh rup brah jêh ri dơm ndơ nây tâm dâng ưn seh samô, jêh ri păng săp gŭ ta klơ rup brah nây. Y-Laban rhi tâm lĕ ngih bok nây, ƀiă lah mâu saơ ndơ nây ôh.$b$,false),
('bunong-vn','GEN',31,35,null,$b$H'Rachel lah ma mbơ̆ păng: “Lơi ăn kôranh gâp nuih ôh, yor lah gâp mâu dơi dâk ta năp may, yor lah tât jêh ma gâp tĭng nâm nau vay phung bu ur.” Păng joi ƀiă lah păng mâu dơi saơ ôh rup brah.$b$,false),
('bunong-vn','GEN',31,36,null,$b$Y-Yakôb ji nuih jêh ri nduyh Y-Laban, Y-Yakôb lah ma Y-Laban: “Moh nau vay gâp rlau? Moh nau tih gâp kŏ may tĭng gâp ma nau nuih?$b$,false),
('bunong-vn','GEN',31,37,null,$b$May rhi lĕ ndơ gâp? May saơ lĕ ndơ may nơm? Dơm ndơ nây ta aơ ta năp phung oh nâu gâp, jêh ri ta năp phung oh nâu may, gay ma khân păng dơi phat dôih ndrăng he bar hê.$b$,false),
('bunong-vn','GEN',31,38,null,$b$Nĕ, bar jât năm jêh gâp gŭ ndrel ma may. Biăp me may jêh ri be me may mâu mâp rlêh ôh, jêh ri gâp mâu mâp sa ôh biăp nkuăng may.$b$,false),
('bunong-vn','GEN',31,39,null,$b$Gâp mâu mâp njŭn ôh ma may biăp mpa bri hêk sa. Gâp nơm dơn nau roh nây. May ăn gâp trok jêh gĭt lah bu ntŭng măng mâu lah dôl nar.$b$,false),
('bunong-vn','GEN',31,40,null,$b$Pô aơ gâp jêng: Duh nđat gâp dôl nar jêh ri kăt ƀư krăp gâp dôl măng jêh ri gâp mâu dơi bêch ôh.$b$,false),
('bunong-vn','GEN',31,41,null,$b$Aơ, bar jât năm aơ gâp gŭ tâm ngih may, gâp pah jêh kan ma may jât ma puăn năm gay ma geh bar hê kon bu ur may, jêh ri prao năm ma biăp may, jêh ri may tâm rgâl jêh jât tơ̆ ndơ nkhôm gâp.$b$,false),
('bunong-vn','GEN',31,42,null,$b$Tơ lah Brah Ndu mbơ̆ gâp, Brah Ndu Y-Abraham, Nơm Y-Isăk klach yơk, mâu gŭ mpeh pa gâp, nanê̆ may ăn gâp sĭt ti dơm. Brah Ndu saơ jêh nau knap gâp jêh ri kan ti gâp, jêh ri păng nduyh may măng ndơh.$b$,true),
('bunong-vn','GEN',31,43,null,$b$Y-Laban plơ̆ lah ma Y-Yakôb: “Phung kon bu ur nây jêng phung kon bu ur gâp, phung kon nây jêng kon gâp, biăp nây jêng biăp gâp jêh ri lĕ rngôch ndơ may saơ nây jêng ndơ gâp. Moh gâp dơi ƀư nar aơ ma phung aơ, phung kon bu ur gâp mâu lah ma phung kon khân păng deh jêh?”$b$,true),
('bunong-vn','GEN',31,44,null,$b$Aƀaơ aơ, lŏng he, ăn he ƀư nau tâm rnglăp gâp đah may, jêh ri ăn nau nây jêng nau mbơh ăn ngăn may đah gâp.”$b$,false),
('bunong-vn','GEN',31,45,null,$b$Pô ri Y-Yakôb sŏk leo glo lŭ tâm păng jêng ndơ tâm mbên.$b$,false),
('bunong-vn','GEN',31,46,null,$b$Y-Yakôb lah ma phung oh nâu păng: “Bun lŭ” khân păng sŏk bun lŭ, jêh ri sông sa ta meng lŭ bun nây.$b$,true),
('bunong-vn','GEN',31,47,null,$b$Y-Laban rnha ntŭk nây Jêgar Saha dutha, ƀiă lah Y-Yakôb rnha ntŭk nây Galet.$b$,false),
('bunong-vn','GEN',31,48,null,$b$Y-Laban lah: “Nku bun lŭ aơ jêng nau mbơh nanê̆ ngăn ndrăng may đah gâp nar aơ.” Yor nây bu rnha ntŭk nây Galet.$b$,false),
('bunong-vn','GEN',31,49,null,$b$Jêh ri Mispa yor lah Y-Laban lah: “Ăn Yêhôva mât mray ndrăng may đah gâp dôl he gŭ êng êng.$b$,false),
('bunong-vn','GEN',31,50,null,$b$Tơ lah may ƀư mhĭk ma phung kon bu ur gâp, mâu lah tơ lah may sŏk phung ur êng, nđâp tơ lah mâu geh bunuyh ôh gŭ ndrel he, ăn may kah gĭt Brah Ndu yơh jêng nơm saơ ndrăng may đah gâp.”$b$,false),
('bunong-vn','GEN',31,51,null,$b$Y-Laban lah ma Y-Yakôb: “Ăn may saơ nku bun lŭ nây jêh ri ndơ tâm mbên gâp ndâk jêh ta nklang gâp đah may.$b$,true),
('bunong-vn','GEN',31,52,null,$b$Nku bun lŭ aơ jêh ri ndơ tâm mbên aơ jêng nau mbơh ma gâp mâu mra rgăn nku bun lŭ aơ hăn ta may ôh, jêh ri may mâu mra rgăn ôh ndơ tâm mbên aơ văch ŭch ƀư mhĭk ma gâp.$b$,false),
('bunong-vn','GEN',31,53,null,$b$Ăn Brah Ndu Y-Abraham, Brah Ndu Y-Nahôr jêh ri Brah Ndu mbơ̆ khân păng phat dôih ndrăng he.” Jêh ri mbơ̆ păng klach yơk.$b$,false),
('bunong-vn','GEN',31,54,null,$b$Y-Yakôb nhhơr ndơ ƀư brah ta yôk jêh ri păng kuăl phung oh nâu păng sông sa; jêh ri khân păng bêch du măng ta yôk nây.$b$,false),
('bunong-vn','GEN',31,55,null,$b$Ơm ôi Y-Laban dâk, chŭm phung kon sau jêh ri phung kon bu ur păng. Păng mât ton ma kon sau păng jêh ri hăn sĭt ta ntŭk păng nơm.$b$,true),
('bunong-vn','GEN',32,1,null,$b$Y-Yakôb dâk hăn jêh ri phung tông mpăr ueh Brah Ndu tâm mâp đah păng.$b$,true),
('bunong-vn','GEN',32,2,null,$b$Y-Yakôb lah tơ lah păng saơ phung nây: “Aơ phung ta han Brah Ndu!” Pô ri păng rnha ntŭk nây Mahanam.$b$,false),
('bunong-vn','GEN',32,3,null,$b$Y-Yakôb njuăl hăn lor ma păng phung mbơh ma Y-Êsau nâu păng ta n'gor Sir tâm ƀon bri hađăch Y-Êđôm.$b$,true),
('bunong-vn','GEN',32,4,null,$b$Păng ntăm nau aơ ma phung nây: “Pô aơ ăn khân may lah ma Kôranh gâp Y-Êsau; ‘Pô aơ oh mon may Y-Yakôb lah gâp gŭ jêh ndrel Y-Laban n'ho ma tât aƀaơ.$b$,false),
('bunong-vn','GEN',32,5,null,$b$Gâp geh âk ndrôk, seh bri, biăp, phung oh mon bu klâu jêh ri phung oh mon bu ur. Gâp njuăl nau mbơh aơ ma kôranh gâp gay may mra yô̆ ma gâp.’ ”$b$,false),
('bunong-vn','GEN',32,6,null,$b$Phung mbơh plơ̆ lah ma Y-Yakôb, lah: “Hên hăn tâm mâp jêh đah nâu may Y-Êsau, jêh ri păng văch tâm mâp đah may ndrel ma puăn rhiăng nuyh”.$b$,true),
('bunong-vn','GEN',32,7,null,$b$Y-Yakôb klach ngăn jêh ri rŭng răng. Păng tâm pă bunuyh ndrel ma păng, nđâp ma biăp, ndrôk, jêh ri seh samô tâm bar phung.$b$,false),
('bunong-vn','GEN',32,8,null,$b$Păng mĭn: “Tơ lah Y-Êsau tâm mâp đah du phung jêh ri nkhĭt lơi, du phung hôm jêng klaih.”$b$,false),
('bunong-vn','GEN',32,9,null,$b$Y-Yakôb lah: “Ơ Brah Ndu mbơ̆ gâp Y-Abraham, lah jêh ma gâp. ‘Sĭt hom ma n'gor may jêh ri ma mpôl băl may, jêh ri gâp mra ƀư ueh ma may.’$b$,false),
('bunong-vn','GEN',32,10,null,$b$Gâp mâu khư ôh ma nau jê̆ lơn tâm lĕ nau rŏng răp jăp jêh ri lĕ nau răp jăp may tâm mpơl jêh ma oh mon may; yor lah gâp rgăn jêh dak krong Y-Yurdan aơ knŏng ma mâng gâp, jêh ri aƀaơ gâp jêng bar phung.$b$,false),
('bunong-vn','GEN',32,11,null,$b$Gâp vơh vơl ma may, tâm rklaih hom gâp bơh ti nâu gâp Y-Êsau, yor lah gâp klach ma păng, klach păng văch nkhĭt hên nđâp ma me ndrel ma phung kon.$b$,false),
('bunong-vn','GEN',32,12,null,$b$Ƀiă lah may lah jêh: “Gâp mra ƀư nau ueh ma may, jêh ri gâp mra ăn phung kon sau may âk nâm bu choih dak mƀŭt, bu mâu dơi kơp ôh yor âk ir ar.”$b$,false),
('bunong-vn','GEN',32,13,null,$b$Păng bêch ta nây măng nây. Păng sŏk ƀă ndơ păng geh ndrel ma ndơ păng ŭch nhhơr ma Y-Êsau nâu păng:$b$,true),
('bunong-vn','GEN',32,14,null,$b$Bar rhiăng mlâm be me, bar jât mlâm be nkuăng, bar rhiăng mlâm biăp me, bar jât mlâm biăp nkuăng.$b$,false),
('bunong-vn','GEN',32,15,null,$b$Pe jât mlâm seh samô me, hôm pu kon khân păng, puăn jât mlâm ndrôk me, jât mlâm ndrôk nkuăng, bar jât mlâm seh bri me, jêh ri jât mlâm seh bri nkuăng.$b$,false),
('bunong-vn','GEN',32,16,null,$b$Păng jao mpô mpa nây êng êng, ăp tĭng ma phung oh mon păng, jêh ri lah ma phung nây. “Hăn hom khân may lor ma gâp, jêh ri ăn ngai tĭng phung mpô mpa êng êng nây.”$b$,true),
('bunong-vn','GEN',32,17,null,$b$Păng ntăm pô aơ ma nơm hăn lor. “Tơ lah Y-Êsau nâu gâp mra mâp đah may jêh ri ôp ma may, Mbu Kôranh may? Mbah may hăn? Ma mbu nâm mpô mpa ta năp may?”$b$,false),
('bunong-vn','GEN',32,18,null,$b$Ăn may lah: “Khân păng jêng ndơ oh mon may Y-Yakôb. Khân păng jêng ndơ nhhơr ma Y-Êsau Kôranh gâp; jêh ri aơ, nđâp ma păng lĕ pa kơi hên.”$b$,false),
('bunong-vn','GEN',32,19,null,$b$Păng ntăm ma phung tal bar tal pe tâm ban lĕ, jêh ri lĕ rngôch ma phung tĭng phung mpô mpa nây, lah: “Ăn khân may ngơi pô nây ma Y-Êsau tơ lah khân may tâm mâp ma păng.$b$,false),
('bunong-vn','GEN',32,20,null,$b$Ăn khân may lah: ‘Nđâp ma oh mon may Y-Yakôb lĕ pa kơi hên.’ ” Yor lah păng mĭn, klăp lah gâp mra rli nuih păng ma mpa nhhơr hăn lor ma gâp, jêh ri dăch pa kơi gâp mra saơ muh măt păng. Klăp lah păng mra dơn gâp.”$b$,false),
('bunong-vn','GEN',32,21,null,$b$Mpa păng nhhơr nây hăn lor ta năp păng; ƀiă lah păng nơm bêch măng nĕ tâm ntŭk khân păng jưh.$b$,false),
('bunong-vn','GEN',32,22,null,$b$Tâm măng nây păng dâk, sŏk bar hê ur păng, bar hê oh mon bu ur păng, jêh ri phung jât ma nguay kon bu klâu păng, jêh ri rgăn ta ntŭk rgăn dak krong Yabôk.$b$,true),
('bunong-vn','GEN',32,23,null,$b$Păng sŏk phung nây ăn phung nây rgăn dak krong jêh ri njuăl kơh tê̆ lĕ rngôch mpô mpa păng geh.$b$,true),
('bunong-vn','GEN',32,24,null,$b$Y-Yakôb gŭ êng păng Geh du huê bunuyh tâm chĭk (nhăt) đah păng kŏ tât dăch luh nar.$b$,false),
('bunong-vn','GEN',32,25,null,$b$Tơ lah nơm nây saơ mâu dơi đah Y-Yakôb ôh păng dong Y-Yakôb ta gang rlêh nting tơm blu dôl khân păng tâm nhăt.$b$,false),
('bunong-vn','GEN',32,26,null,$b$Păng lah, Lơi gâp hăn, yor lah nar dăch luh “Ƀiă lah Y-Yakôb lah: “Gâp mâu mra ăn may hăn ôh, knŏng tơ lah mât ton ma gâp lor,”$b$,false),
('bunong-vn','GEN',32,27,null,$b$Păng lah ma Y-Yakôb: “Mbu moh may?” Păng lah: “Y-Yakôb”$b$,false),
('bunong-vn','GEN',32,28,null,$b$Păng lah: “Bu mâu mra rnha amoh may Y-Yakôb ôh, ƀiă lah Y-Israel, yor lah may tâm nhăt jêh đah Brah Ndu jêh ri đah phung bunuyh, jêh ri dơi may jêh.”$b$,false),
('bunong-vn','GEN',32,29,null,$b$Y-Yakôb ôp păng: “Gâp dăn ma may, mbơh hom ma gâp amoh may.” Păng lah: “Mâm ƀư may ôp amoh gâp?” Jêh ri păng mât ton ma Y-Yakôb ta nây.$b$,false),
('bunong-vn','GEN',32,30,null,$b$Pô ri Y-Yakôb rnha ntŭk nây Pêniêl, yor lah păng lah: “Gâp saơ jêh Brah Ndu ta năp, jêh ri nau rêh gâp klaih jêh.”$b$,false),
('bunong-vn','GEN',32,31,null,$b$Nar luh ta păng tơ lah păng rgăn Pêniêl; jêh ri păng hăn tĭl dĭt.$b$,false),
('bunong-vn','GEN',32,32,null,$b$Yor nây tât ta nar aơ phung kon Israel, mâu sa ôh suan tâm gang, yor lah păng dong jêh Y-Yakôb ta suan gang.$b$,true),
('bunong-vn','GEN',33,1,null,$b$Y-Yakôb n'gơr măt uănh jêh ri aơ, Y-Êsau văch ndrel ma puăn rhiăng bunuyh. Y-Yakôb tâm pă phung kon ma H'Lêa, H'Rachel, jêh ri ma bar hê oh mon bu ur.$b$,true),
('bunong-vn','GEN',33,2,null,$b$Păng dơm lor phung oh mon bu ur ndrel ma phung kon khân păng, pa kơi H'Lêa ndrel ma phung kon păng, jêh ri pa kơi lơn H'Rachel jêh ri Y-Yôsep.$b$,false),
('bunong-vn','GEN',33,3,null,$b$Păng nơm hăn lor lơn ma phung nây jêh chon mon ta neh pơh tơ̆ , kŏ tât dăch ta nâu păng.$b$,false),
('bunong-vn','GEN',33,4,null,$b$Ƀiă lah Y-Êsau nchuăt hăn tâm mâp đah păng, ut ta trôk ko păng, jêh ri chŭm păng; jêh ri khân păng nhĭm.$b$,true),
('bunong-vn','GEN',33,5,null,$b$Y-Êsau n'gơr măt saơ phung bu ur jêh ri phung kon, lah: “Mbu phung ndrel ma may aơ?” Y-Yakôb lah: “Phung kon Brah Ndu ăn jêh ma oh mon may ma nau yô̆.”$b$,false),
('bunong-vn','GEN',33,6,null,$b$Phung oh mon bu ur văch dăch ndrel ma phung kon khân păng jêh ri.$b$,false),
('bunong-vn','GEN',33,7,null,$b$H'Lêa jêh ri phung kon păng văch dăch lĕ jêh ri păn mbah. Dăch dŭt Y-Yôsep jêh H'Rachel văch dăch jêh ri chon mon mbah.$b$,false),
('bunong-vn','GEN',33,8,null,$b$Y-Êsau lah: “Moh may ŭch ƀư đah phung âk gâp mâp jêh lor nây?” Y-Yakôb lah: “Gay geh nau yô̆ ta năp Kôranh gâp.”$b$,false),
('bunong-vn','GEN',33,9,null,$b$Y-Êsau lah: “Gâp geh ăp jêh, Ơ oh gâp, prăp hom ma may nơm ndơ may geh.”$b$,true),
('bunong-vn','GEN',33,10,null,$b$Y-Yakôb lah: “Mâu, gâp dăn ma may, tơ lah gâp geh nau yô̆ ta năp may, ăn may sŏk dơn ndơ nhhơr bơh ti gâp, yor lah nau gâp saơ muh măt may tâm ban ma gâp saơ muh măt Brah Ndu, yor lah may dơn jêh gâp ma nau yô̆.$b$,true),
('bunong-vn','GEN',33,11,null,$b$Sŏk hom, gâp dăn ma may, ndơ gâp nhhơr ndjôt leo ma may jêh, yor lah Brah Ndu ƀư nau yô̆ ma gâp, jêh ri gâp geh ăp jêh.” Păng nchâp ngăn jêh ri Y-Êsau sŏk dơn.$b$,false),
('bunong-vn','GEN',33,12,null,$b$Y-Êsau lah: “Kay hăn he, jêh ri gâp mra hăn lor ma may”.$b$,true),
('bunong-vn','GEN',33,13,null,$b$Ƀiă lah Y-Yakôb lah ma păng: “Kôranh gâp gĭt phung kon se jêng ra ai, jêh ri biăp ndrôk ndrel ma gâp geh kon nse. Tơ lah bu ndal ma khân păng knŏng du nar, lĕ rngôch mpô mpa nây mra khĭt.$b$,false),
('bunong-vn','GEN',33,14,null,$b$Ăn Kôranh gâp hăn lor ma oh mon păng, jêh ri gâp mra hăn mbrơi; tĭng nâm mpô mpa dơi, jêh ri tĭng nâm phung kon dơi, kŏ gâp tât ta Kôranh gâp ta n'gor Sêir.”$b$,true),
('bunong-vn','GEN',33,15,null,$b$Y-Êsau lah: “Ăn gâp cha lat ma may phung gâp ƀa ƀă.” Păng lah: “Moh khlay nau nây? Ăn gâp geh nau yô̆ ta năp măt Kôranh gâp.”$b$,true),
('bunong-vn','GEN',33,16,null,$b$Pô ri nar nây Y-Êsau sĭt ta n'gor Sir.$b$,false),
('bunong-vn','GEN',33,17,null,$b$Ƀiă lah Y-Yakôb hăn ta ƀon Sukôt, ƀư ngih ma păng nơm jêh ri ƀư ndrung ma mpô mpa păng. Yor ri bu rnha ntŭk nây Sukôt.$b$,false),
('bunong-vn','GEN',33,18,null,$b$Tơ lah Y-Yakôb du luh tă bơh n'gor Padana Aram, păng tât ma nau đăp mpăn ta ƀon Sichem tâm n'gor Kanaan. Păng ƀư ntŭk jưh ta năp ƀon,$b$,true),
('bunong-vn','GEN',33,19,null,$b$Ntŭk păng rvăt tă bơh ti phung kon Y-Hamôr, mbơ̆ Y-Sichem, ma du rhiăng rlay prăk ntŭk păng ndâk ngih bok păng.$b$,false),
('bunong-vn','GEN',33,20,null,$b$Păng ndâk ta nây du nơng ƀư brah jêh ri rnha păng. Êl Êlôhê Israel.$b$,false),
('bunong-vn','GEN',34,1,null,$b$H'Dina kon bu ur H'Lêa deh ma Y-Yakôb, luh ŭch khâl đah phung bu ur n'gor nây.$b$,true),
('bunong-vn','GEN',34,2,null,$b$Y-Sichem kon bu klâu Y-Hamôr bunuyh Hivit, Kôranh n'gor nây, saơ păng, nhŭp nchâp bêch ndrel jêh ri ƀư bêk H'Dina.$b$,false),
('bunong-vn','GEN',34,3,null,$b$Nuih n'hâm bu klâu nây rŏng ma H'Dina kon bu ur Y-Yakôb. Păng rŏng ma bu ur nây jêh ri ngơi rah rơch ma H'Dina.$b$,false),
('bunong-vn','GEN',34,4,null,$b$Y-Sichem lah ma Y-Hamôr mbơ̆ păng: “Ăn may sŏk ma gâp bu ur nây jêng ur gâp.”$b$,false),
('bunong-vn','GEN',34,5,null,$b$Y-Yakôb tăng jêh nơm nây ƀư ƀơ̆ jêh H'Dina kon bu ur păng. Phung kon bu klâu păng gŭ tâm mir chiăp ndrôk, biăp păng, pô ri Y-Yakôb gŭ rklăk kŏ khân păng tât.$b$,false),
('bunong-vn','GEN',34,6,null,$b$Y-Hamôr mbơ̆ Y-Sichem hăn ta Y-Yakôb ŭch ngơi đah păng.$b$,false),
('bunong-vn','GEN',34,7,null,$b$Phung kon bu klâu Y-Yakôb sĭt tă bơh mir tơ lah khân păng tăng nau nây. Khân păng rngot jêh ri ji nuih hâu ngăn yor nau tih Y-Sichem ƀư tâm phung Israel, yor păng bêch đah kon bu ur Y-Yakôb, nau bu mâu vay ƀư.$b$,false),
('bunong-vn','GEN',34,8,null,$b$Y-Hamôr ngơi đah khân păng, lah: “Nuih n'hâm kon bu klâu gâp Y-Sichem klâng ma kon bu ur may. Gâp dăn ma khân may, ăn bu ur nây jêng ur păng.$b$,true),
('bunong-vn','GEN',34,9,null,$b$Ăn khân may ƀư nau tâm nkol ur sai đah hên; ăn ma hên phung kon bu ur khân may, jêh ri sŏk hom phung kon bu ur hên ma khân may.$b$,false),
('bunong-vn','GEN',34,10,null,$b$Khân may mra gŭ ndrel ma hên, jêh ri n'gor aơ mra gŭ ta năp khân may. Ăn khân may gŭ ta nây tâm tăch rgâl, jêh ri geh neh ma khân may nơm.”$b$,false),
('bunong-vn','GEN',34,11,null,$b$Y-Sichem lah ma mbơ̆ jêh ri ma phung oh nâu bu ur nây. “Ăn gâp dơi geh nau yô̆ ta năp măt khân may, jêh ri gâp mra ăn moh ndơ khân may lah.$b$,false),
('bunong-vn','GEN',34,12,null,$b$Ăn khân may dăn bơh gâp drăp ndơ khlay, jêh ri drăp nhơr ăn âk, jêh ri gâp mra ăn tĭng nâm khân may lah ma gâp, ƀiă lah ăn bu ur nây ma gâp, bu ur nây jêng ur gâp.”$b$,false),
('bunong-vn','GEN',34,13,null,$b$Phung kon bu klâu Y-Yakôb plơ̆ lah ma Y-Sichem jêh ri ma Y-Hamôr mbơ̆ păng ma nau ndơm, yor lah Y-Sichem ƀư ƀơ̆ jêh H'Dina oh bu ur khân păng.$b$,true),
('bunong-vn','GEN',34,14,null,$b$Khân păng lah ma Y-Sichem jêh ri ma Y-Hamôr: “Nau nây hên mâu dơi ƀư ôh, ăn nkhơng oh bu ur hên ma bunuyh mâu geh koh ntâu ôh. Nau nây jêng nau ƀư bêk hên.$b$,false),
('bunong-vn','GEN',34,15,null,$b$Hên mra dơn nau may dăn knŏng tơ lah khân may mra jêng tâm ban ma hên, ăn lĕ rngôch phung bu klâu tâm phung khân may dơn nau koh ntâu.$b$,false),
('bunong-vn','GEN',34,16,null,$b$Pô ri hên mra ăn ma khân may phung kon bu ur hên, jêh ri hên mra sŏk phung kon bu ur khân may ma hên; hên mra gŭ ndrel ma khân may, jêh ri he mra jêng du phung ƀon lan.$b$,false),
('bunong-vn','GEN',34,17,null,$b$Ƀiă lah, tơ lah khân may mâu mra tông ôh ma hên dơn nau koh ntâu, hên mra sŏk lơi phung kon bu ur hên jêh ri du.”$b$,false),
('bunong-vn','GEN',34,18,null,$b$Y-Hamôr jêh ri Y-Sichem kon bu klâu Y-Hamôr maak ma nau khân ngơi nây.$b$,true),
('bunong-vn','GEN',34,19,null,$b$Y-Sichem mâu hôm gŭ kâp jŏ ôh ƀư nau nây, yor lah păng rŏng ma kon bu ur Y-Yakôb. Bu yơk ma păng âk lơn ma lĕ ngih mbơ̆ păng.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','GEN',34,20,null,$b$Y-Hamôr jêh ri Y-Sichem kon bu klâu păng tât ta mpông pêr ƀon khân păng jêh ri ngơi đah phung bu klâu ƀon lan khân păng, lah:$b$,false),
('bunong-vn','GEN',34,21,null,$b$“Phung bunuyh aơ gŭ đăp mpăn ndrel he. Pô ri ăn khân păng gŭ jêh ri tăch rgâl drăp ndơ tâm n'gor aơ, yor lah aơ, n'gor găp tăng jêh ma khân păng. Ăn he sŏk phung kon bu ur khân păng jêh ur he, jêh ri he ăn ma khân păng phung kon bu ur he.$b$,false),
('bunong-vn','GEN',34,22,null,$b$Ƀiă lah phung bu klâu aơ mra dơn gŭ ndrel ma he. Jêng du phung ƀon lan knŏng tơ lah ăp nơm bu klâu tâm phung he dơn nau koh ntâu nâm bu khân păng koh ntâu jêh.$b$,false),
('bunong-vn','GEN',34,23,null,$b$Mâu di hĕ ndrôk, biăp, drăp ndơ, jêh ri lĕ rngôch mpô mpa khân păng mra jêng ndơ he? Knŏng ăn he dơn nau khân păng dăn, jêh ri khân păng mra gŭ ndrel ma he.”$b$,false),
('bunong-vn','GEN',34,24,null,$b$Lĕ rngôch mbu nâm du luh ta mpông pêr ƀon nây tông ma Y-Hamôr jêh ri Y-Sichem kon bu klâu păng jêh ri lĕ rngôch phung bu klâu du luh ta mpông pêr ƀon nây dơn nau koh ntâu.$b$,false),
('bunong-vn','GEN',34,25,null,$b$Nar tal pe tơ lah phung bu klâu ƀon nây gŭ ji, bar hê kon bu klâu Y-Yakôb, Y-Simêôn jêh ri Y-Lêvi, nâu H'Dina, sŏk đao khân păng, ntŭng lăp tâm ƀon nây, nkhĭt lơi lĕ rngôch phung bu klâu,$b$,false),
('bunong-vn','GEN',34,26,null,$b$Khân păng nkhĭt Y-Hamôr jêh ri Y-Sichem kon bu klâu păng ma đao, sŏk H'Dina bơh ngih Y-Sichem jêh ri du.$b$,false),
('bunong-vn','GEN',34,27,null,$b$Phung kon bu klâu Y-Yakôb tât ta phung khĭt jêh ri gro sŏk drăp ndơ tâm ƀon nây, yor lah khân păng ƀư ƀơ̆ jêh oh bu ur bu.$b$,false),
('bunong-vn','GEN',34,28,null,$b$Khân păng sŏk biăp, be jêh ri seh bri khân păng, mpa geh tâm ƀon jêh ri tâm mir.$b$,false),
('bunong-vn','GEN',34,29,null,$b$Khân păng sŏk lĕ drăp ndơ, phung kon se jê̆ jêh ri phung ur bu ndrel ma lĕ rngôch drăp ndơ tâm ngih.$b$,false),
('bunong-vn','GEN',34,30,null,$b$Y-Yakôb lah ma Y-Simêôn jêh ri Y-Lêvi: “Khân may ăn tât nau uh ah ma gâp jêh ri ăn phung bunuyh ƀon lan phung Kanaan jêh ri phung Pêrisit tâm rmot ma gâp, gâp jêng knŏng phung djê̆; tơ lah khân păng mra tâm rƀŭn ndrel n'grŭp đah ngih gâp.”$b$,true),
('bunong-vn','GEN',34,31,null,$b$Ƀiă lah khân păng lah: “Di lĕ bu klâu nây ƀư ma oh bu ur hên tâm ban ma du huê bu ur văng tĭr.”$b$,true),
('bunong-vn','GEN',35,1,null,$b$Brah Ndu lah ma Y-Yakôb: “Dâk hom may, hăn hao ta ƀon Bêthel jêh ri gŭ ta nây. Rdâk ta nây du rplay nơng ƀư brah ma Brah Ndu nơm tâm mpơl jêh ma may, rnôk may du bơh muh măt Y-Êsau nâu may.”$b$,true),
('bunong-vn','GEN',35,2,null,$b$Pô ri Y-Yakôb lah ma ngih păng jêh ri lĕ rngôch phung gŭ ndrel ma păng. “Cha lơi hom rup brah bu năch ta nklang khân may. Ƀư kloh hom khân may nơm, jêh ri rgâl lơi kho ao khân may.$b$,false),
('bunong-vn','GEN',35,3,null,$b$Dâk hom he, hăn hao ta ƀon Bêthel, gay ma ta nây gâp dơi rdâk du rplay nơng ƀư brah ma Brah Ndu, Nơm plơ̆ lah jêh ma gâp tâm nar gâp uh ah, jêh ri gŭ rêh ndrel ma gâp tâm ăp trong gâp sak nsong.”$b$,false),
('bunong-vn','GEN',35,4,null,$b$Khân păng ăn ma Y-Yakôb lĕ rngôch rup brah bu năch khân păng geh jêh ri thek khân păng mblo ta tôr. Y-Yakôb brôi ndơ nây tâm dâng tơm si êp ƀon Sichem.$b$,false),
('bunong-vn','GEN',35,5,null,$b$Dôl khân păng hăn, Brah Ndu nhhu phung gŭ tâm lĕ rngôch ƀon jŭm khân păng, pô ri phung nây mâu tĭng ôh phung kon Y-Yakôb.$b$,true),
('bunong-vn','GEN',35,6,null,$b$Y-Yakôb ndrel ma lĕ rngôch phung păng tât ta ƀon Lus tâm n'gor Kanaan (ƀon nây jêng ƀon Bêthel).$b$,false),
('bunong-vn','GEN',35,7,null,$b$Păng rdâk ta du rplay nơng ƀư brah jêh ri rnha ntŭk nây Êl Bêthel, yor lah ta nây Brah Ndu tâm mpơl jêh ma păng tơ lah păng du bơh nâu păng.$b$,false),
('bunong-vn','GEN',35,8,null,$b$Jêh ri H'Dêbôra khĭt, oh mon bu ur nơm mpu jêh H'Rêbêka, jêh ri bu tâp păng tâm dâng Bêthel ta tơm si, jêh ri bu rnha tơm si nây Alôn Bakut.$b$,false),
('bunong-vn','GEN',35,9,null,$b$Brah Ndu hŏ tâm mpơl jêh lĕ ma Y-Yakôb tơ lah păng văch tă bơh n'gor Padan Aram, jêh ri Brah Ndu mât ton ma păng.$b$,true),
('bunong-vn','GEN',35,10,null,$b$Brah Ndu lah ma păng: “Amoh may Y-Yakôb, amoh may bu mâu mra rnha Y-Yakôb ôh, ƀiă lah amoh may mra jêng Y-Israel,” Pô ri Brah Ndu tâm amoh păng Y-Israel.$b$,false),
('bunong-vn','GEN',35,11,null,$b$Brah Ndu lah ma păng: “Gâp jêng Brah Ndu, Nơm Geh Lĕ Nau Brah. Ăn may ƀư ăn bĭk. Du phung mpôl băl jêh ri âk phung mpôl băl mra luh tă bơh may, jêh ri tă bơh ndŭl proch may mra luh phung hađăch.$b$,false),
('bunong-vn','GEN',35,12,null,$b$Gâp mra ăn ma may jêh ri ma phung kon sau may pa kơi may n'gor gâp ăn jêh ma Y-Abraham jêh ri ma Y-Isăk.”$b$,false),
('bunong-vn','GEN',35,13,null,$b$Jêh ri Brah Ndu hao bơh păng bơh ntŭk Brah Ndu ngơi jêh ma păng.$b$,false),
('bunong-vn','GEN',35,14,null,$b$Y-Yakôb rdâk ndơ tâm mbên ma lŭ ta ntŭk Brah Ndu ngơi jêh đah păng Bêthel.$b$,false),
('bunong-vn','GEN',35,15,null,$b$Y-Yakôb ntơ ntŭk Brah Ndu lĕ ngơi đah păng Bêthel.$b$,false),
('bunong-vn','GEN',35,16,null,$b$Khân păng du hăn bơh ƀon Bêthel; jêh ri tơ lah khân păng ăt hôm ngai ê tât ta ƀon Êphrata. H'Rachel nkeng jêr ngăn.$b$,true),
('bunong-vn','GEN',35,17,null,$b$Dôl păng nkeng jêr ngăn n'hŭm lah ma păng. “Lơi klach ôh yor lah ay mra geh du huê kon bu klâu.”$b$,true),
('bunong-vn','GEN',35,18,null,$b$Dôl huêng păng ntơm du (Yor lah păng khĭt) păng tâm amoh Y-Bennôni, ƀiă lah mbơ̆ păng tâm amoh păng Y-Benjamin.$b$,false),
('bunong-vn','GEN',35,19,null,$b$Pô ri H'Rachel khĭt jêh ri bu tâp păng ta trong Êphrata (ƀon nây jêng ƀon Ƀêtlêhem)$b$,false),
('bunong-vn','GEN',35,20,null,$b$Y-Yakôb rdâk ndơ tâm mbên môch H'Rachel nây hôm tât ta nar aơ.$b$,false),
('bunong-vn','GEN',35,21,null,$b$Y-Israel hăn jêh ri pâng ngih bok ta kah tĕ ngih tŭm Êder,$b$,false),
('bunong-vn','GEN',35,22,null,$b$Dôl Y-Israel gŭ tâm n'gor nây Y-Ruben hăn bêch đah H'Bilha ur yông mbơ̆ păng; jêh ri Y-Israel tăng nau nây. Y-Yakôb geh jât ma bar nuyh kon bu klâu.$b$,false),
('bunong-vn','GEN',35,23,null,$b$Phung kon bu klâu H'Lêa: Y-Ruben kon deh bôk rah ma Y-Yakôb, Y-Simêôn, Y-Lêvi, Y-Yuđa, Y-Isakar, jêh ri Y-Sabulôn.$b$,false),
('bunong-vn','GEN',35,24,null,$b$Phung kon bu klâu H'Rachel: Y-Yôsep jêh Y-Benjamin,$b$,true),
('bunong-vn','GEN',35,25,null,$b$Phung kon bu klâu H'Bilha oh mon bu ur H'Rachel: Y-Dan jêh ri Naptali,$b$,false),
('bunong-vn','GEN',35,26,null,$b$Phung kon bu klâu H'Silpa oh mon bu ur H'Lêa: Y-Gat jêh ri Aser. Aơ yơh phung kon bu klâu bu deh ma Y-Yakôb ta n'gor Padan Aram.$b$,false),
('bunong-vn','GEN',35,27,null,$b$Y-Yakôb tât ta Y-Isăk mbơ̆ păng ta Mamrê, ƀon Kiriat Arba (nâm bu ntĭt ƀon Hêbron), ta nây Y-Abraham jêh ri Y-Isăk gŭ jêh.$b$,true),
('bunong-vn','GEN',35,28,null,$b$Lĕ rngôch nar Y-Isăk gŭ rêh geh du rhiăng pham jât năm.$b$,false),
('bunong-vn','GEN',35,29,null,$b$Y-Isăk tăch n'hâm khĭt, jêh ri bu tâm rƀŭn păng ndrel ma mpôl băl păng. Păng ranh jêh ri ranh jŏk jêh. Y-Êsau jêh ri Y-Yakôb phung kon bu klâu păng tâp păng.$b$,false),
('bunong-vn','GEN',36,1,null,$b$Phung aơ kon sau Y-Êsau (nơm nây jêng Êđôm).$b$,true),
('bunong-vn','GEN',36,2,null,$b$Y-Êsau sŏk phung ur păng bơh phung n'gor Kanaan: H'Ada kon bu ur Y-Êlon bunuyh Hitit, H'Ôhôlibama kon bu ur Y-Ana kon sau Y-Sibêôn bunuyh Hivit,$b$,false),
('bunong-vn','GEN',36,3,null,$b$jêh ri H'Basmat kon bu ur Ismaêl ruh Y-Nêbalôt.$b$,false),
('bunong-vn','GEN',36,4,null,$b$H'Ada deh ma Y-Êsau, H'Basmat deh ma Y-Rêuel,$b$,false),
('bunong-vn','GEN',36,5,null,$b$H'Ôhôlibama deh ma Y-Jêsus, Y-Jalam, jêh ri Y-Kôra. Aơ phung kon bu klâu Y-Êsau bu deh ma păng tâm n'gor Kanaan.$b$,false),
('bunong-vn','GEN',36,6,null,$b$Y-Êsau sŏk phung ur păng, phung kon bu klâu păng, phung kon bu ur păng, lĕ rngôch phung bunuyh tâm ngih păng, ndrôk păng, lĕ rngôch mpô mpa păng jêh ri lĕ rngôch drăp ndơ păng bun tâm n'gor Kanaan, jêh ri păng hăn du tâm n'gor ngai bơh Y-Yakôb oh păng;$b$,true),
('bunong-vn','GEN',36,7,null,$b$yor lah drăp ndơ khân păng âk ir kŏ khân păng mâu dơi gŭ ndrel ôh, jêh ri n'gor khân păng gŭ nây mâu dơi tŏng ôh ma khân păng, yor lah mpô mpa rong khân păng âk ngăn.$b$,false),
('bunong-vn','GEN',36,8,null,$b$Pô ri Y-Êsau gŭ tâm n'gor mpeh yôk Sêir. Y-Êsau jêng Êđôm.$b$,false),
('bunong-vn','GEN',36,9,null,$b$Aơ phung kon sau Y-Êsau che tơm ma phung Y-Êsau gŭ tâm n'gor yôk Sêir,$b$,true),
('bunong-vn','GEN',36,10,null,$b$Aơ amoh phung kon bu klâu Y-Êsau: Y-Êlipas kon bu klâu H'Ada ur Y-Êsau: Y-Rêuel kon bu klâu H'Basmat ur Êsau.$b$,false),
('bunong-vn','GEN',36,11,null,$b$Phung kon bu klâu Y-Êlipas geh: Y-Têman, Y-Ômar, Y-Sêphô, Y-Gatam, jêh ri Y-Kênas$b$,false),
('bunong-vn','GEN',36,12,null,$b$(H'Timna jêng ur yông Y-Êlipas kon bu klâu Y-Êsau; păng deh Y-Amalek ma Y-Êlipas) Amoh phung sau bu klâu H'Ada ur Y-Êsau.$b$,false),
('bunong-vn','GEN',36,13,null,$b$Aơ phung kon bu klâu Y-Rêuel: Y-Nahat, Y-Sêra, Y-Sama, jêh ri Y-Misa. Amoh phung sau bu klâu H'Basmat ur Y-Êsau.$b$,false),
('bunong-vn','GEN',36,14,null,$b$Aơ phung kon bu klâu H'Ôhôlibama kon bu ur H'Ana kon sau Y-Sibêôn ur Y-Êsau, deh ma Y-Jêsus, Y-Jalam jêh ri Y-Kôra.$b$,false),
('bunong-vn','GEN',36,15,null,$b$Aơ phung Kôranh ŭng tŭng phung kon bu klâu Y-Êsau. Phung kon bu klâu Y-Êsau kon deh bôk rah ma Y-Êsau Y-Têman, Y-Ômar, Y-Sêphô, Y-Kênas,$b$,true),
('bunong-vn','GEN',36,16,null,$b$Y-Kôra, Y-Gatam, jêh ri Y-Amalek. Phung Kôranh nây luh bơh Y-Êlipas tâm n'gor Êđôm, jêng phung sau bu klâu H'Ada.$b$,false),
('bunong-vn','GEN',36,17,null,$b$Aơ phung kon bu klâu Y-Rêuel kon bu klâu Y-Êsau, Y-Nahat, Y-Sêra, Y-Sama, Y-Misa. Phung nây jêng Kôranh mpôl băl Y-Rêuel tâm n'gor Êđôm, phung sau bu klâu H'Basmat ur Y-Êsau.$b$,false),
('bunong-vn','GEN',36,18,null,$b$Aơ phung kon bu klâu H'Ôhôlibama ur Y-Êsau, Y-Jêsus, Y-Jalam, Y-Kôra. Phung Kôranh nây H'Ôhôlibama kon bu ur H'Ana ur Y-Êsau deh.$b$,false),
('bunong-vn','GEN',36,19,null,$b$Phung nây jêng phung kon bu klâu Y-Êsau jêh ri amoh phung Kôranh khân păng. (Nơm nây jêng Y-Êđôm)$b$,false),
('bunong-vn','GEN',36,20,null,$b$Aơ phung kon bu klâu Y-Sêir bunuyh Hôrit, phung bunuyh gŭ tâm n'gor nây: Y-Lôtan, Y-Sôbal, Y-Sibêôn, Y-Ana,$b$,false),
('bunong-vn','GEN',36,21,null,$b$Y-Disôn, Y-Êser, jêh ri Y-Disan. Amoh phung Kôranh phung Hôrit, phung kon bu klâu Y-Sêir tâm n'gor Êđôm.$b$,false),
('bunong-vn','GEN',36,22,null,$b$Phung kon bu klâu Y-Lôtan: Y-Hôri jêh ri Y-Hêman. Jêh ri H'Timna jêng oh bu ur Y-Lôtan.$b$,false),
('bunong-vn','GEN',36,23,null,$b$Aơ phung kon bu klâu Y-Sôbal: Y-Alvan, Y-Manahat, Y-Êbal, Y-Sêphô jêh ri Y-Ônam.$b$,true),
('bunong-vn','GEN',36,24,null,$b$Aơ phung kon bu klâu Y-Sibêôn, Y-Aiyah, jêh ri Y-Ana. Y-Ana nây jêng nơm saơ tu dak duh tâm bri rdah dôl păng chiăp seh bri Y-Sibêôn mbơ̆ păng.$b$,true),
('bunong-vn','GEN',36,25,null,$b$Aơ phung kon bu klâu Y-Ana, Y-Disôn jêh ri H'Ôhôlibama kon bu ur Y-Ana.$b$,false),
('bunong-vn','GEN',36,26,null,$b$Aơ phung kon bu klâu Y-Disôn: Y-Hêmdan, Y-Êsban, Y-Itram jêh ri Y-Chêran.$b$,false),
('bunong-vn','GEN',36,27,null,$b$Aơ phung kon bu klâu Y-Êser: Y-Bilhan, Y-Savan, jêh ri Y-Akan.$b$,false),
('bunong-vn','GEN',36,28,null,$b$Aơ phung kon bu klâu Y-Disan: Y-Us jêh ri Y-Aran.$b$,true),
('bunong-vn','GEN',36,29,null,$b$Aơ phung Kôranh phung Hôrit: Y-Lôtan, Y-Sôbal, Y-Sibêôn, Y-Ana,$b$,false),
('bunong-vn','GEN',36,30,null,$b$Y-Disôn, Y-Êser, Y-Disan. Nây jêng phung Kôranh tâm phung Hôrit tĭng nâm ndŭl mpôl khân păng tâm n'gor Y-Sêir.$b$,false),
('bunong-vn','GEN',36,31,null,$b$Aơ phung hađăch chiă uănh tâm n'gor Êđôm lor geh du huê hađăch chiă uănh phung Israel:$b$,true),
('bunong-vn','GEN',36,32,null,$b$Y-Bêla kon bu klâu Y-Bêôr chiă uănh tâm n'gor Êđôm, amoh ƀon păng jêng Dinhaba.$b$,false),
('bunong-vn','GEN',36,33,null,$b$Y-Bêla khĭt jêh ri Y-Yôbap kon bu klâu Y-Sêra ƀon Bôsra chiă uănh ntrok păng.$b$,false),
('bunong-vn','GEN',36,34,null,$b$Y-Yôbap khĭt, jêh ri Husam n'gor Têman chiă uănh ntrok păng.$b$,false),
('bunong-vn','GEN',36,35,null,$b$Y-Husam khĭt, jêh ri Y-Hadat kon bu klâu Y-Bêdat, nơm tâm lơh dơi đah Y-Midian tâm n'gor Môap, chiă uănh ntrok păng. Amoh ƀon păng Avit.$b$,false),
('bunong-vn','GEN',36,36,null,$b$Y-Hadat khĭt, jêh ri Y-Samla ƀon Mêsrêka, chiă uănh ntrok păng.$b$,false),
('bunong-vn','GEN',36,37,null,$b$Y-Samla khĭt, jêh ri Y-Sal ƀon Rêhôbôt ta dak krong Ơphrat, chiă uănh ntrok păng.$b$,false),
('bunong-vn','GEN',36,38,null,$b$Y-Sal khĭt, jêh ri Y-Baalhanan kon bu klâu Akbôr chiă uănh ntrok păng.$b$,false),
('bunong-vn','GEN',36,39,null,$b$Y-Baalhanan kon bu klâu Y-Akbôr khĭt, jêh ri Y-Hadar chiă uănh ntrok păng. Amoh ƀon păng Pao; amoh ur păng H'Mêhetabel kon bu ur Y-Matret sau bu ur Y-Mêsahap.$b$,false),
('bunong-vn','GEN',36,40,null,$b$Aơ phung Kôranh luh bơh Y-Êsau tĭng nâm mpôl khân păng, tĭng nâm neh khân păng gŭ, tĭng nâm amoh khân păng: Y-Timna, Y-Alva, Y-Jêlet,$b$,false),
('bunong-vn','GEN',36,41,null,$b$Y-Ôhôlibama, Y-Êla, Y-Pinôn.$b$,false),
('bunong-vn','GEN',36,42,null,$b$Y-Kênas, Y-Têman, Y-Mipsar,$b$,false),
('bunong-vn','GEN',36,43,null,$b$Y-Makdiêl, Y-Iram. Amoh phung Kôranh n'gor Êđôm tĭng nâm ntŭk khân păng gŭ tâm n'gor khân păng. Aơ Y-Êsau che tơm ma phung Êđôm.$b$,false),
('bunong-vn','GEN',37,1,null,$b$Y-Yakôb gŭ tâm n'gor mbơ̆ păng mâp gŭ jêh ƀât lât, tâm n'gor Kanaan.$b$,true),
('bunong-vn','GEN',37,2,null,$b$Aơ nau nkoch bri ma mpôl băl Y-Yakôb: Y-Yôsep geh jât ma pơh năm, chiă biăp ndrel ma phung nâu păng. Păng jêng bu klâu dôl dal ndăm gŭ ndrel ma phung kon bu klâu H'Bilha jêh ri H'Silpa, phung ur mbơ̆ păng. Y-Yôsep nkoch ma mbơ̆ khân păng nau mhĭk khân păng ƀư.$b$,false),
('bunong-vn','GEN',37,3,null,$b$Y-Israel rŏng Y-Yôsep âk lơn ma lĕ rngôch kon păng, yor lah păng jêng kon păng geh jêh păng ranh. Păng ƀư ma kon păng du blah ao jâr jong ti.$b$,false),
('bunong-vn','GEN',37,4,null,$b$Tơ lah phung nâu păng saơ mbơ̆ khân păng rŏng ma Y-Yôsep âk lơn ma lĕ rngôch phung oh nâu, khân păng tâm rmot ma Y-Yôsep jêh ri mâu dơi ngơi ueh đah Y-Yôsep ôh.$b$,false),
('bunong-vn','GEN',37,5,null,$b$Y-Yôsep geh nau mbơi, jêh ri tơ lah păng nkoch bri nau nây ma phung oh nâu păng, khân păng tâm rmot ma Y-Yôsep âk lơn.$b$,true),
('bunong-vn','GEN',37,6,null,$b$Păng lah ma phung oh nâu păng: “Khân may iăt hom nau gâp hŏ mbơi jêh.$b$,true),
('bunong-vn','GEN',37,7,null,$b$Aơ, he gŭ chăp ba tâm mir, jêh ri nchăp ba khân may gŭ dăp tring jŭm păng jêh chon mon mbah ta năp nchăp ba gâp.”$b$,false),
('bunong-vn','GEN',37,8,null,$b$Phung nâu păng lah ma păng: “Ngăn lĕ may mra jêng Kôranh hên? Ngăn lĕ may mra chiă uănh hên?” Pô ri khân păng tâm rmot ma Y-Yôsep âk lơn yor nau mbơi jêh ri nau păng ngơi.$b$,false),
('bunong-vn','GEN',37,9,null,$b$Păng geh tay nau mbơi êng, jêh ri nkoch bri nau nây ma phung oh nâu păng, păng lah: “Aơ, gâp geh nau mbơi nar, khay, jêh ri jât ma nguay rplay mănh chon mon mbah ta năp gâp!”$b$,false),
('bunong-vn','GEN',37,10,null,$b$Păng nkoch bri nau nây ma mbơ̆ păng jêh ri ma phung oh nâu păng. Mbơ̆ păng nduyh păng, lah: “Moh nau mbơi may geh pô nây? Ngăn lĕ gâp, me may, jêh ri phung oh nâu may mra văch chon mon ta neh ta năp may?”$b$,false),
('bunong-vn','GEN',37,11,null,$b$Phung nâu păng mô nach ma păng, ƀiă lah mbơ̆ păng ndjôt prăp nau ngơi nây tâm nau mĭn păng.$b$,false),
('bunong-vn','GEN',37,12,null,$b$Phung nâu Y-Yôsep hăn chiă biăp mbơ̆ khân păng ta ƀon Sichem.$b$,true),
('bunong-vn','GEN',37,13,null,$b$Y-Israel lah, ma Y-Yôsep: “Mâu di hĕ phung nâu may chiă biăp ta ƀon Sichem? Văch hom gâp mra njuăl may ta khân păng.” Y-Yôsep lah ma păng: “Aơ ta aơ gâp.”$b$,false),
('bunong-vn','GEN',37,14,null,$b$Păng lah ma Y-Yôsep: “Hăn hom, uănh gĭt lah phung nâu may jêh ri phung biăp geh nau ueh, jêh ri sĭt mbơh ma gâp. Păng njuăl Y-Yôsep hăn tă bơh rlŭng Hêbron, jêh ri păng tât ta ƀon Sichem.$b$,false),
('bunong-vn','GEN',37,15,null,$b$Geh du huê bunuyh tâm mâp đah păng dôl păng nhhơt trong tâm mir. Bunuyh nây ôp păng: “Moh may joi?”$b$,false),
('bunong-vn','GEN',37,16,null,$b$Păng plơ̆ lah: “Gâp joi phung nâu gâp. Gâp dăn ma may, lah an ma gâp, mbah ntŭk khân păng chiăp biăp.”$b$,true),
('bunong-vn','GEN',37,17,null,$b$Bunuyh nây lah: “Khân păng du jêh bơh aơ, yor lah gâp tăng khân păng lah, hôm he ta ƀon Dôthan.” Pô ri Y-Yôsep hăn joi phung nâu păng jêh ri saơ khân păng ta ƀon Dôthan.$b$,false),
('bunong-vn','GEN',37,18,null,$b$Phung nâu păng, saơ păng bơh ngai, jêh ri ê hŏ dăch tât, phung khân păng mĭn ŭch nkhĭt lơi Y-Yôsep.$b$,false),
('bunong-vn','GEN',37,19,null,$b$Khân păng tâm lah ndrăng khân păng; “Aơ bunuyh bêch mbơi,$b$,false),
('bunong-vn','GEN',37,20,null,$b$pô ri, lŏng he, ăn he nkhĭt lơi păng, klŭp păng tâm ntu dak jêh ri he mra lah: “Du mlâm mpa bri sa jêh Păng? Jêh ri he mra saơ moh nau mra tât ma nau păng mbơi.”$b$,false),
('bunong-vn','GEN',37,21,null,$b$Ƀiă lah tơ lah Y-Ruben saơ nau nây, păng nklaih an Y-Yôsep bơh ti phung nâu păng. Păng lah: “Lơi ta he nkhĭt păng ôh!”$b$,false),
('bunong-vn','GEN',37,22,null,$b$Y-Ruben lah ma khân păng: “Lơi nkhŭt mham ôh; klŭp păng tâm ntu dak, tâm ndrêch rdah aơ, ƀiă lah lơi he ƀư ma păng ôh.”$b$,false),
('bunong-vn','GEN',37,23,null,$b$Păng ŭch rklaih Y-Yôsep bơh ti phung nâu păng, khân păng doh ao jâr jong ti khân păng soh.$b$,false),
('bunong-vn','GEN',37,24,null,$b$Khân păng nhŭp Y-Yôsep nklăch tâm ntu dak. Ntu nây sơh mâu geh dak ôh.$b$,true),
('bunong-vn','GEN',37,25,null,$b$Khân păng gŭ mƀŏng ma sông sa, khân păng n'gơr măt uănh, jêh ri aơ geh du phung Ismaêl văch tă bơh n'gor Galaat, ncho seh samô rdeng ndơ ƀâu kah, dak ƀâu kah, jêh ri dak si tăng ma n'gor Êjipt.$b$,true),
('bunong-vn','GEN',37,26,null,$b$Y-Yuđa lah ma phung oh nâu păng: “Moh khlay nkhĭt lơi oh he jêh ri pôn mham păng?$b$,true),
('bunong-vn','GEN',37,27,null,$b$Lŏng he, tăch păng ma phung Ismaêl. Lơi he ƀư ma păng ôh, yor lah păng jêng oh he, nglay săk he nơm.” Phung oh nâu păng tông nau nây.$b$,false),
('bunong-vn','GEN',37,28,null,$b$Jêh ri phung Midian tăch rgâl rgăn. Khân păng đŏt Y-Yôsep tă bơh ntu dak jêh ri tăch păng bar jât rlay prăk ma phung Ismaêl. Phung nây ndjôt Y-Yôsep leo ta n'gor Êjipt.$b$,false),
('bunong-vn','GEN',37,29,null,$b$Tơ lah Y-Ruben sĭt ta ntu nây jêh ri Y-Yôsep mâu gŭ ta nây ôh, păng nkhêk lơi kho ao păng.$b$,true),
('bunong-vn','GEN',37,30,null,$b$Păng sĭt ta phung oh păng jêh ri lah: “Bu klâu dôl dal ndăm mâu hôm saơ ôh, jêh ri mbah ntŭk gâp mra hăn?”$b$,false),
('bunong-vn','GEN',37,31,null,$b$Khân păng sŏk ao jâr Y-Yôsep, nkhĭt du mlâm be nkuăng jêh ri trăm ao jâr nây tâm mham.$b$,true),
('bunong-vn','GEN',37,32,null,$b$Khân păng ndjôt ao jâr jong ti nây njŭn sĭt ta mbơ̆ păng, lah: “Hên saơ ndơ aơ, sek uănh hom, gĭt lah jêng ao jâr kon may?”$b$,false),
('bunong-vn','GEN',37,33,null,$b$Y-Yakôb năl ao nây jêh ri lah: “Ao jâr kon gâp yơh.” Geh du mlâm mpa bri sa jêh păng. Nanê̆, Y-Yôsep hêk rai jêh.”$b$,false),
('bunong-vn','GEN',37,34,null,$b$Y-Yakôb nkhêk kho ao păng jêh ri soh ƀau jêh ri ndrê klâng khĭt ma kon bu klâu păng jŏ nar.$b$,true),
('bunong-vn','GEN',37,35,null,$b$Lĕ rngôch phung kon bu klâu păng jêh ri lĕ rngôch phung kon bu ur păng hăn văch bonh leng păng; ƀiă lah păng dun nau tâm bonh nây jêh ri lah; “Mâu!” Gâp mra jŭr hăn ta Ƀon Phung Khĭt ma kon gâp ma nau ndrê klâng.” Pô ri mbơ̆ păng nhĭm ma Y-Yôsep.$b$,false),
('bunong-vn','GEN',37,36,null,$b$Phung Midian tăch Y-Yôsep ta n'gor Êjipt ma Y-Pôtipar, Kôranh ta han phung gak.$b$,false),
('bunong-vn','GEN',38,1,null,$b$Rnôk nây Y-Yuđa du luh tă bơh phung oh nâu păng jêh ri gŭ ndrel ma du huê ƀon Adulam, amoh păng Y-Hira.$b$,true),
('bunong-vn','GEN',38,2,null,$b$Ta nây Y-Yuđa saơ du huê bu ur Kanaan, kon bu ur Y-Sua. Păng sŏk ƀư ur jêh ri hăn gŭ ndrel păng.$b$,true),
('bunong-vn','GEN',38,3,null,$b$Păng ntreo jêh ri deh ma du huê kon bu klâu, jêh ri Y-Yuđa tâm amoh păng Y-Er.$b$,false),
('bunong-vn','GEN',38,4,null,$b$Păng ntreo đŏng jêh ri deh ma du huê kon bu klâu, păng amoh kon nây Y-Ônan.$b$,false),
('bunong-vn','GEN',38,5,null,$b$Păng deh nay ma du huê kon bu klâu amoh păng Y-Sêla. Y-Yuđa gŭ ta ƀon Chêsip tơ lah păng deh ma kon nây.$b$,false),
('bunong-vn','GEN',38,6,null,$b$Y-Yuđa nsông ăn Y-Er, kon bu deh bôk rah ma du huê ur amoh păng H'Tamar.$b$,true),
('bunong-vn','GEN',38,7,null,$b$Ƀiă lah Y-Er kon bu deh bôk rah ma Y-Yuđa, ƀư nau ƀai ta năp Yêhôva; jêh ri Yêhôva nkhĭt păng.$b$,false),
('bunong-vn','GEN',38,8,null,$b$Y-Yuđa lah ma Y-Ônan: “Hăn gŭ ndrel ur nâu may, jêh ri ăn may ƀư ma păng tĭng nâm nau vay oh sai păng gay geh kon ma may.”$b$,false),
('bunong-vn','GEN',38,9,null,$b$Ƀiă lah Y-Ônan gĭt ma kon nây mâu mra jêng ma păng ôh, jêh ri tơ lah păng hăn gŭ đah ur nâu păng, păng ăn dak ntil păng tŭp tâm neh, gay lơi ăn geh kon ma nâu păng ôh.$b$,false),
('bunong-vn','GEN',38,10,null,$b$Nau păng ƀư nây jêng ƀai ta năp Yêhôva jêh ri Yêhôva nkhĭt păng đŏng.$b$,false),
('bunong-vn','GEN',38,11,null,$b$Y-Yuđa lah ma H'Tamar, ƀăn păng: “Ăn ay gŭ rêh ndrô khĭt sai tâm ngih mbơ̆ ay tât Y-Sêla kon bu klâu gâp văch ma toyh.” Yor lah H'Tamar klach păng mra khĭt nâm bu bar hê nâu păng. Pô ri H'Tamar hăn gŭ tâm ngih mbơ̆ păng.$b$,true),
('bunong-vn','GEN',38,12,null,$b$Jŏ năm pa kơi kon bu ur Y-Sua, ur Y-Yuđa khĭt. Tơ lah Y-Yuđa geh nau bonh leng jêh, păng hăn ta phung gŭ nkăp rsau biăp păng ta ƀon Timna ndrel Y-Hira bunuyh ƀon Adulam, băl păng.$b$,false),
('bunong-vn','GEN',38,13,null,$b$Bu mbơh ma H'Tamar, po ay hăn ta ƀon Timna, gay ma nkăp rsau biăp păng.”$b$,false),
('bunong-vn','GEN',38,14,null,$b$H'Tamar doh kho ao păng ndrô, nkŭm muh măt păng ma bok, n'gut bok nây, jêh ri gŭ ta mpông pêr ƀon Ênam ta trong ƀon Timna, yor lah păng saơ Y-Sêla toyh jêh, ƀiă lah bu mâu ăn păng jêng ur Y-Sêla ôh.$b$,false),
('bunong-vn','GEN',38,15,null,$b$Tơ Y-Yuđa saơ păng, mƀŏng lah jêng bu ur văng tĭr yor lah păng nkŭm lơi muh măt păng.$b$,false),
('bunong-vn','GEN',38,16,null,$b$Y-Yuđa hăn ta păng ta pĭt trong, lah: “Ăn gâp gŭ ndrel ay.” Yor lah păng mâu gĭt ôh nơm nây jêng ƀăn păng. Păng lah: “Moh ndơ may mra ăn may gâp, gay ma may dơi gŭ ndrel ma gâp?”$b$,false),
('bunong-vn','GEN',38,17,null,$b$Păng lah: “Gâp mra njuăl ma ay dum kon be bơh mpôl be gâp.” Păng lah: “May mra ăn lĕ ndơ ton du mlâm ndah jŏ tât may njuăl kon be nây?”$b$,false),
('bunong-vn','GEN',38,18,null,$b$Păng lah: “Moh ndơ ton gâp mra ăn ma ay?” Păng lah: “Rgên may, rse may jêh ri mâng jra may djôt ta ti.” Y-Yuđa ăn ndơ nây ma păng jêh ri hăn gŭ ndrel; jêh ri păng ntreo.$b$,false),
('bunong-vn','GEN',38,19,null,$b$Păng dâk sĭt. Păng doh lơi bok put măt jêh ri soh kho ao ndrô khĭt sai.$b$,false),
('bunong-vn','GEN',38,20,null,$b$Y-Yuđa njuăl kon be ma ti băl păng bunuyh Adulam, gay sŏk sĭt ndơ ton bơh ti bu ur nây. Ƀiă lah băl păng mâu saơ bu ur nây ôh.$b$,false),
('bunong-vn','GEN',38,21,null,$b$Păng ôp phung bunuyh gŭ ta ntŭk nây, lah: “Mbah bu ur văng tĭr ta ƀon Ênam ta pĭt trong?” Khân păng lah: “Mâu geh bu ur văng tĭr ta aơ.”$b$,false),
('bunong-vn','GEN',38,22,null,$b$Pô ri păng plơ̆ sĭt ma Y-Yuđa, jêh ri lah: “Gâp mâu saơ păng ôh,” jêh ri phung bunuyh gŭ ta ƀon nây lah: “Mâu geh bu ur văng tĭr ta aơ ôh.”$b$,false),
('bunong-vn','GEN',38,23,null,$b$Y-Yuđa lah: “Ăn prăp ndjôt prăp ndơ ton nây, klach lah he geh nau bêk. Aơ, gâp njuăl jêh kon be aơ, ƀiă lah may mâu saơ păng ôh.”$b$,false),
('bunong-vn','GEN',38,24,null,$b$Pe khay pa kơi, bu mbơh ma Y-Yuđa: “H'Tamar ƀăn may ƀư văng tĭr; jêh ri păng ntreo jêh yor nau văng tĭr nây.” Y-Yuđa lah: “Njŭn păng pa dih, jêh ri ăn bu su păng.$b$,false),
('bunong-vn','GEN',38,25,null,$b$Tơ lah bu njŭn păng pa dih, păng ăn bu mbơh ma po păng pô aơ: “Gâp ntreo đah nơm ndơ ton aơ.” Păng lah: “Sek uănh hom, gâp dăn ma may, mbu nâm rgên ti, rse jêh ri mâng aơ.”$b$,false),
('bunong-vn','GEN',38,26,null,$b$Y-Yuđa năl ndơ nây jêh ri lah: “Păng sŏng lơn ma gâp, yor lah gâp mâu ăn ôh păng jêng ur Y-Sêla kon gâp.” Jêh ri Y-Yuđa mâu hôm gŭ păng ôh.$b$,false),
('bunong-vn','GEN',38,27,null,$b$Ta nar păng nkeng, aơ, geh bă kon bar tâm ndŭl păng.$b$,true),
('bunong-vn','GEN',38,28,null,$b$Dôl păng bêch nkeng du huê kon mpơl ti. Bu ur djôt ndŭl kât rse brai chăng ta ti păng, lah: “Nơm aơ deh lor.”$b$,false),
('bunong-vn','GEN',38,29,null,$b$Ƀiă lah kon nây rhuăt ti păng, jêh ri, aơ oh păng du luh. Jêh ri n'hŭm lah: “Phâm ƀư may gao nau vay jêh ri du luh lor?” Yor nây bu amoh păng Y-Pêres.$b$,true),
('bunong-vn','GEN',38,30,null,$b$Pa kơi, oh păng du luh, nơm geh ti kât ma brai chăng; jêh ri bu amoh păng Y-Sêra.$b$,false),
('bunong-vn','GEN',39,1,null,$b$Bu ndjôt leo Y-Yôsep ta n'gor Êjipt, Y-Pôtipar, kôranh phung ta han Y-Pharaôn, kôranh ta han phung gak, du huê Êjipt, rvăt păng bơh phung Ismaêl, phung ndjôt leo păng ta nây jêh.$b$,true),
('bunong-vn','GEN',39,2,null,$b$Yêhôva gŭ ndrel ma Y-Yôsep, jêh ri drăp ndơ păng hao ƀa ƀơ. Păng gŭ tâm ngih kôranh păng, bunuyh Êjipt.$b$,false),
('bunong-vn','GEN',39,3,null,$b$Kôranh păng saơ Yêhôva gŭ ndrel ma păng, jêh ri Yêhôva ăn lĕ kan păng ƀư jêng da dê.$b$,false),
('bunong-vn','GEN',39,4,null,$b$Y-Yôsep geh nau yô̆ ta năp măt păng, jêh ri pah kan ma păng. Păng ăn Y-Yôsep jêng kôranh tâm ngih păng. Jêh ri jao lĕ ndơ păng geh ăn Y-Yôsep chiă.$b$,false),
('bunong-vn','GEN',39,5,null,$b$Ntơm bơh nar păng ăn Y-Yôsep jêng kôranh tâm ngih păng jêh ri ma lĕ ndơ păng geh, Yêhôva ăn nau ueh uĭn ma ngih bunuyh Êjipt yor Y-Yôsep. Nau ueh uĭn Yêhôva gŭ ta lĕ rngôch ndô ndơ păng geh tâm ngih nđâp tâm mir.$b$,false),
('bunong-vn','GEN',39,6,null,$b$Păng cha lơi lĕ rngôch ndơ păng geh ăn Y-Yôsep chiă uănh; jêh ri mâu hôm rvê njrăng ôh ma drăp ndơ păng, knŏng ma ndơ sông sa. Y-Yôsep jêng ueh jêh rom ray.$b$,false),
('bunong-vn','GEN',39,7,null,$b$Jŏ djê̆ ur kôranh păng uănh ma Y-Yôsep jêh ri lah: “Bêch hom ndrel gâp.”$b$,false),
('bunong-vn','GEN',39,8,null,$b$Ƀiă lah Y-Yôsep dun jêh ri lah ma ur Kôranh păng: “Aơ, kôranh gâp mâu rvê ôh moh ndơ gŭ ndrel gâp tâm ngih, jêh ri păng jao jêh lĕ rngôch ndơ păng geh tâm ti gâp.$b$,false),
('bunong-vn','GEN',39,9,null,$b$Păng mâu jêng toyh lơn ma gâp ôh, tâm ngih aơ; jêh ri păng mâu nhhuach du ntil ndơ ma gâp ôh, knŏng ay, yor lah ay jêng ur păng. Phâm gâp dơi ƀư nau ƀai toyh aơ, jêh ri ƀư tih đah Brah Ndu?”$b$,false),
('bunong-vn','GEN',39,10,null,$b$Dôl păng ngơi đah Y-Yôsep ăp nar, păng mâu gĭt ôh nau păng ŭch ăn Y-Yôsep bêch ndrel ma păng mâu lah gŭ êng ndrel păng.$b$,false),
('bunong-vn','GEN',39,11,null,$b$Du nar Y-Yôsep lăp tâm ngih ŭch pah kan, jêh ri mâu geh du huê bunuyh gŭ tâm ngih ôh.$b$,false),
('bunong-vn','GEN',39,12,null,$b$Ur kôranh păng kuăn Y-Yôsep ta ao jêh ri lah: “Bêch hom đah gâp” Y-Yôsep cha lơi ao tâm ti păng jêh ri du pa dih.$b$,true),
('bunong-vn','GEN',39,13,null,$b$Tơ lah păng saơ Y-Yôsep cha lơi ao tâm ti păng jêh ri du pa dih,$b$,false),
('bunong-vn','GEN',39,14,null,$b$păng kuăl phung bunuyh tâm ngih păng jêh ri păng lah ma phung nây pô aơ: “Uănh hom”. Sai gâp njŭn leo du huê bunuyh Hêbrơ ŭch mưch ma he.$b$,false),
('bunong-vn','GEN',39,15,null,$b$Bu klâu nây ŭch văch ta gâp bêch ndrel gâp, ƀiă lah gâp nter ma bâr huy, păng cha lơi ao păng ta gâp jêh ri du pa dih.”$b$,true),
('bunong-vn','GEN',39,16,null,$b$Jêh ri păng prăp ao Y-Yôsep dăch păng kŏ tât kôranh păng sĭt ta ngih.$b$,false),
('bunong-vn','GEN',39,17,null,$b$Păng ngơi pô aơ: “Oh mon may Hêbrơ ndơp ma he văch dăch gâp gay ƀư bêk gâp.$b$,false),
('bunong-vn','GEN',39,18,null,$b$Tơ lah gâp nter, păng cha lơi ao păng dăch gâp jêh ri du pa dih.”$b$,false),
('bunong-vn','GEN',39,19,null,$b$Tơ lah kôranh Y-Yôsep tăng nau ur păng ngơi ma păng, lah: “Pô aơ oh mon may ƀư jêh ma gâp.” Păng ji nuih.$b$,false),
('bunong-vn','GEN',39,20,null,$b$Jêh ri kôranh păng sŏk Y-Yôsep jêh ri krŭng păng tâm ntŭk bu krŭng bu nă hađăch. Y-Yôsep gŭ tâm ndrung bu nă.$b$,false),
('bunong-vn','GEN',39,21,null,$b$Ƀiă lah Yêhôva gŭ ndrel ma Y-Yôsep jêh ri tâm mpơl nau rŏng răp jăp ma păng, ăn păng geh nau yô̆ ta năp măt kôranh bu nă.$b$,false),
('bunong-vn','GEN',39,22,null,$b$Kôranh bu nă ăn Y-Yôsep chiă lĕ rngôch phung bu nă tâm ndrung nây; jêh ri moh kan bu ƀư ta nây, păng jêng nơm chiă.$b$,false),
('bunong-vn','GEN',39,23,null,$b$Kôranh bu nă mâu uănh ôh moh kan Y-Yôsep ƀư, yor lah Yêhôva gŭ ndrel ma păng; jêh ri Yêhôva ăn kan păng jêng.$b$,false),
('bunong-vn','GEN',40,1,null,$b$Jŏ djê̆ ma nây oh mon djôt kachok jêh ri oh mon ƀư kapŭng ma hađăch Êjipt ƀư tih ma kôranh khân păng hađăch Êjipt.$b$,true),
('bunong-vn','GEN',40,2,null,$b$Pharaôn ji nuih ma bar hê kôranh oh mon păng nây, kôranh ma phung djôt kachok jêh ri kôranh ma phung ƀư piăng let.$b$,false),
('bunong-vn','GEN',40,3,null,$b$Jêh ri păng ăn bu krŭng phung nây tâm ngih kôranh ta han phung gak tâm ndrung ntŭk bu krŭng Y-Yôsep.$b$,false),
('bunong-vn','GEN',40,4,null,$b$Kôranh ta han phung gak jao khân păng ma Y-Yôsep pah kan ma khân păng. Jêh ri khân păng gŭ jŏ djê̆ tâm ndrung bu nă.$b$,true),
('bunong-vn','GEN',40,5,null,$b$Tâm du măng oh mon djôt kachok jêh ri oh mon ƀư piăng let ma hađăch Êjipt bu krŭng jêh tâm ndrung geh nau mbơi. Lĕ khân păng bar hê geh nau mbơi geh nau rblang êng êng.$b$,true),
('bunong-vn','GEN',40,6,null,$b$Tơ lah Y-Yôsep hăn uănh khân păng ta ôi, khân păng geh nau rngot.$b$,false),
('bunong-vn','GEN',40,7,null,$b$Păng ôp phung kôranh Pharaôn gŭ ndrel ma păng tâm ndrung tâm ngih kôranh păng. “Mâm ƀư khân may rngot nar aơ?”$b$,true),
('bunong-vn','GEN',40,8,null,$b$Phung nây lah ma păng: “Hên geh jêh nau mbơi, jêh ri mâu geh nơm dơi rblang nau nây ôh.” Y-Yôsep lah ma khân păng: “Mâu di hĕ Brah Ndu nơm dơi rblang? Gâp dăn ma khân may, nkoch nau mbơi ma gâp.”$b$,false),
('bunong-vn','GEN',40,9,null,$b$Kôranh djôt kachok nkoch bri nau păng mbơi ma Y-Yôsep, lah ma păng. “Tâm nau gâp mbơi, aơ geh du tơm play kriăk ƀâu ta năp gâp.$b$,true),
('bunong-vn','GEN',40,10,null,$b$Tâm tơm play kriăk ƀâu nây geh pe mlâm n'gĭng, tơ lah n'ha păng ntơm chăt nse, kao dang, jêh ri rkŭm păng geh play kriăk ƀâu dŭm.$b$,false),
('bunong-vn','GEN',40,11,null,$b$Gâp djôt kachok hađăch. Gâp sŏk play kriăk ƀâu, iet tâm kachok Pharaôn, jêh ri ăn kachok nây ta ti Pharaôn.”$b$,false),
('bunong-vn','GEN',40,12,null,$b$Y-Yôsep lah ma păng: “Aơ jêng nau rblang ma nau nây: Pe mlâm n'gĭng jêng pe nar.$b$,false),
('bunong-vn','GEN',40,13,null,$b$Hôm pe nar Pharaôn mra ăn may luh plơ̆ sĭt ma kan may. May mra ăn kachok Pharaôn ma ti păng nâm bu may ƀư lor, dôl may jêng oh mon djôt kachok păng.$b$,false),
('bunong-vn','GEN',40,14,null,$b$Ƀiă lah ăn may kah gĭt ma gâp tơ lah may mra geh nau ueh, jêh ri nhhơ nau ueh ma gâp. Gâp dăn ma may, ngơi an ma gâp ma Pharaôn jêh ri ngluh gâp bơh ngih aơ.$b$,false),
('bunong-vn','GEN',40,15,null,$b$Yor lah nanê̆ bu ntŭng nhŭp gâp bơh n'gor phung Hêbrơ jêh ri ta aơ lĕ gâp mâu mâp ƀư tih ôh nkhơng ma bu krŭng gâp tâm ndrung bu nă aơ.”$b$,false),
('bunong-vn','GEN',40,16,null,$b$Tơ lah kôranh ƀư piăng let saơ nau rblang jêng ueh, păng lah ma Y-Yôsep: “Gâp tâm ban lĕ geh nau mbơi. Geh pe mlâm bai piăng let ta klơ bôk gâp.”$b$,true),
('bunong-vn','GEN',40,17,null,$b$Tâm bai piăng let prêh lơn, geh ăp ntil ndơ sông sa tă bơh kôranh nơm ƀư ăn ma Pha-ôn sa; sĭm jot ta klơ bôk gâp sa lĕ ndơ nây.$b$,false),
('bunong-vn','GEN',40,18,null,$b$Y-Yôsep lŏ plơ̆ lah: “Aơ jêng nau rblang ma nau nây: Pe mlâm bĭ jêng pe nar.$b$,false),
('bunong-vn','GEN',40,19,null,$b$Hôm pe nar Pharaôn mra koh trô ko may jêh ri yông may ta tơm si, jêh ri sĭm och mra sa săk may.”$b$,false),
('bunong-vn','GEN',40,20,null,$b$Ta nar tal pe, jêng nar kah gĭt nar deh Pharaôn, păng ƀư nau sông sa ma lĕ rngôch phung oh mon păng, jêh ri păng ngluh kôranh djôt kachok jêh ri kôranh ƀư piăng let ăn gŭ ta năp phung oh mon păng.$b$,true),
('bunong-vn','GEN',40,21,null,$b$Păng ăn kôranh djôt kachok sĭt ta kan păng, jêh ri ăn kachok ta ti Pharaôn.$b$,false),
('bunong-vn','GEN',40,22,null,$b$Ƀiă lah păng yông kôranh ƀư piăng let nâm bu nau Y-Yôsep rblang an jêh ma khân păng.$b$,true),
('bunong-vn','GEN',40,23,null,$b$Kôranh djôt kachok mâu hôm kah gĭt ôh ma Y-Yôsep, ƀiă lah lĕ chuêl hêng.$b$,false),
('bunong-vn','GEN',41,1,null,$b$Tăch bar năm Pharaôn mbơi păng gŭ râng ta kơh dak krong Nil.$b$,true),
('bunong-vn','GEN',41,2,null,$b$Aơ, geh jât mlâm ndrôk ueh jêh ri yau luh tă bơh dak krong jêh ri sa gơ̆ tâm ndrêch.$b$,false),
('bunong-vn','GEN',41,3,null,$b$Jêh ri, Aơ, jêh ma nây geh pơh mlâm ndrôk êng mâu ueh ôh jêh ri rgay luh tă bơh dak krong gŭ dăch ndrôk tal lor ta kơh dak krong Nil.$b$,true),
('bunong-vn','GEN',41,4,null,$b$Pơh mlâm ndrôk mâu ueh ôh jêh ri rgay jêh ri sa lơi pơh mlâm ndrôk ueh jêh ri lay. Jêh ri Pharaôn kah rngăl.$b$,false),
('bunong-vn','GEN',41,5,null,$b$Păng bêch tay jêh ri lŏ mbơi tal bar. Aơ, geh pơh ndrŏng ba săk rlay âk ngăn jêh ri ueh, khoh tă bơh du nkot.$b$,true),
('bunong-vn','GEN',41,6,null,$b$Jêh ri aơ pơh ndrŏng ba nsiăp jêh ri kro yor sial tă pa lơ khoh pa kơi ndrŏng ba tal lor.$b$,false),
('bunong-vn','GEN',41,7,null,$b$Pơh ndrŏng nsiăp rvăn lơi pơh ndrŏng săk rlay âk jêh ri ueh. Pharaôn kah rngăl, jêh ri, aơ nau nây jêng nau mbơi.$b$,false),
('bunong-vn','GEN',41,8,null,$b$Tât ôi jêh huêng păng rŭng răng. Păng đă bu kuăl lĕ rngôch phung rƀên jêh ri phung njêh tâm n'gor Êjipt jêh ri Pharaôn nkoch bri nau mbơi ma khân păng, ƀiă lah mâu geh du huê dơi rblang ôh nau mbơi nây ma Pharaôn.$b$,false),
('bunong-vn','GEN',41,9,null,$b$Jêh ri kôranh djôt kachok Pharaôn lah: “Gâp kah gĭt nar aơ nau gâp tih.$b$,true),
('bunong-vn','GEN',41,10,null,$b$Tơ lah Pharaôn nuih ma phung oh mon păng, păng đă bu krŭng gâp jêh ri kôranh ƀư piăng let tâm ngih kôranh ta han phung gak,$b$,false),
('bunong-vn','GEN',41,11,null,$b$hên geh nau mbơi tâm du măng, gâp nđâp ma păng, lĕ hên bar hê geh nau mbơi rblang êng êng.$b$,false),
('bunong-vn','GEN',41,12,null,$b$Geh ta nây ndrel ma hên du huê dôl ndăm Hêbrơ, oh mon kôranh ta han phung gak. Hên nkoch bri ma păng nau hên mbơi, jêh ri păng rblang an ma hên tĭng nâm nau hên mbơi.$b$,false),
('bunong-vn','GEN',41,13,null,$b$Geh nau tât ngăn nâm bu nau păng rblang jêh ma hên. Bu ăn gâp plơ̆ sĭt ma kan gâp, jêh ri bu yông nơm ƀư piăng let.$b$,false),
('bunong-vn','GEN',41,14,null,$b$Pô ri Pharaôn njuăl bu hăn kuăl Y-Yôsep, jêh ri bu ăn păng luh ro tă bơh ndrung bu nă. Tơ lah păng poih têp kang păng, rgâl kho ao, păng hăn ta năp Pharaôn.$b$,true),
('bunong-vn','GEN',41,15,null,$b$Pharaôn lah ma Y-Yôsep: “Gâp geh nau mbơi jêh. Mâu geh du huê nơm dơi rblang ôh. Gâp tăng bu lah, may dơi rblang nau mbơi tơ lah may tăng nau nây.”$b$,true),
('bunong-vn','GEN',41,16,null,$b$Y-Yôsep lŏ plơ̆ lah ma Pharaôn: “Mâu tăp gâp ôh, ƀiă lah Brah Ndu mra ăn ma Pharaôn nau plơ̆ lah ueh.”$b$,false),
('bunong-vn','GEN',41,17,null,$b$Pharaôn lah ma Y-Yôsep: “Tâm nau gâp mbơi, gâp gŭ râng ta kơh dak krong Nil,$b$,false),
('bunong-vn','GEN',41,18,null,$b$jêh ri geh pơh mlâm ndrôk lay jêh ri ueh luh tă bơh dak krong Nil, jêh ri gŭ sa gơ̆ tâm ndrêch.$b$,false),
('bunong-vn','GEN',41,19,null,$b$Jêh ma pơh mlâm ndrôk nây, lŏ geh pơh mlâm ndrôk êng mâu ueh ôh jêh ri rgay ngăn, mhĭk lơn ma gâp mâu mâp saơ tâm lĕ n'gor Êjipt.$b$,false),
('bunong-vn','GEN',41,20,null,$b$Ndrôk rgay jêh ri mâu ueh sa lơi lĕ rngôch ndrôk lay tal lor.$b$,false),
('bunong-vn','GEN',41,21,null,$b$Ƀiă lah jêh ndrôk rgay sa lĕ khân păng, bu mâu mĭn ôh ndrôk rgay lĕ sa jêh khân păng yor lah khân păng ăt jêng rgay mâm bu sa ơm. Pô ri gâp kah rngăl.$b$,false),
('bunong-vn','GEN',41,22,null,$b$Tâm ban lĕ gâp saơ tâm nau mbơi pơh ndrŏng ba rlay âk jêh ri ueh khoh tă bah du nkot.$b$,true),
('bunong-vn','GEN',41,23,null,$b$Jêh ri geh pơh ndrŏng ba nsiăp kro yor sial bơh lơ luh khoh pa kơi ma ndrŏng ba tal lor,$b$,false),
('bunong-vn','GEN',41,24,null,$b$ndrŏng ba rgay rvăn lơi pơh ndrŏng ba ueh. Gâp nkoch bri jêh nau nây ma phung rƀên, ƀiă lah mâu geh du huê khân păng dơi rblang ma gâp ôh.”$b$,false),
('bunong-vn','GEN',41,25,null,$b$Y-Yôsep lah ma Pharaôn: “Nau Pharaôn mbơi jêng nguay, Brah Ndu tâm mpơl jêh ma Pharaôn, phâm nau păng mra ƀư.$b$,true),
('bunong-vn','GEN',41,26,null,$b$Pơh mlâm ndrôk ueh jêng pơh năm jêh ri pơh ndrŏng ba ueh jêng pơh năm. Nau mbơi nây jêng nguay.$b$,false),
('bunong-vn','GEN',41,27,null,$b$Pơh mlâm ndrôk rgay jêh ri mâu ueh ôh luh bah kơi ma pơh mlâm ndrôk lor jêng pơh năm. Tâm ban lĕ pơh ndrŏng ba kro yor sial bah lơ su jêng pơh năm geh nau sa sât ji ngot.$b$,false),
('bunong-vn','GEN',41,28,null,$b$Di tĭng nâm gâp lah jêh ma Pharaôn. Brah Ndu tâm mpơl jêh ma Pharaôn phâm nau păng mra ƀư.$b$,false),
('bunong-vn','GEN',41,29,null,$b$Mra geh pơh năm ba âk ngăn tâm lĕ n'gor Êjipt.$b$,false),
('bunong-vn','GEN',41,30,null,$b$Jêh ma nây mra geh pơh năm nau sa sât ji ngot. Bu mra chuêl lĕ ba âk ngăn nây tâm n'gor Êjipt, jêh ri nau sa sât ji ngot mra ƀư rai n'gor.$b$,false),
('bunong-vn','GEN',41,31,null,$b$Bu mâu mra kah gĭt ôh ma ba âk nây tâm n'gor yor nau sa sât ji ngot pa kơi jêng rêh ni ngăn.$b$,false),
('bunong-vn','GEN',41,32,null,$b$Yor lah nau mbơi tâm mpơl bar tơ̆ ma Pharaôn, nau nây yor Brah Ndu ƀư nanê̆ jêh, jêh ri Brah Ndu mra ăn păng tât gơnh.$b$,false),
('bunong-vn','GEN',41,33,null,$b$Pô ri aƀaơ aơ ăn Pharaôn joi du huê bunuyh gĭt mĭn jêh ri njêh, jêh ri ăn chiă uănh n'gor Êjipt.$b$,false),
('bunong-vn','GEN',41,34,null,$b$Ăn Pharaôn sâm dơm phung kôranh tâm n'gor Êjipt, sŏk du kô̆ tâm prăm ba n'gor Êjipt dôl tâm pơh năm geh ba âk.$b$,false),
('bunong-vn','GEN',41,35,null,$b$Ăn khân păng bun prăp lĕ rngôch ndơ sông sa mra geh dôl pơh năm ueh, ăn khân păng bun ba tĭng nâm hađăch Pharaôn ntăm prăp tâm ƀon jêng ndơ sông sa, jêh ri ăn khân păng gak ndơ nây.$b$,false),
('bunong-vn','GEN',41,36,null,$b$Ndơ sông sa nây mra prăp ma n'gor gay ma dŏng dôl tâm pơh năm sa sât ji ngot mra tât tâm n'gor Êjipt, gay ma n'gor mâu mra rai ôh yor nau sa sât ji ngot.” Bu ăn Y-Yôsep Jêng Kôranh N'gor Êjipt.$b$,false),
('bunong-vn','GEN',41,37,null,$b$Pharaôn jêh ri lĕ rngôch phung oh mon păng maak dơn nau nây.$b$,true),
('bunong-vn','GEN',41,38,null,$b$Pharaôn lah ma phung oh mon păng: “Dơi lĕ he joi du huê bunuyh êng tâm ban ma nơm aơ, du huê geh Brah Huêng Brah Ndu gŭ tâm păng?”$b$,false),
('bunong-vn','GEN',41,39,null,$b$Pô ri Pharaôn lah ma Y-Yôsep: “Yor lah Brah Ndu tâm mpơl jêh ma may nau aơ, mâu geh ôh du huê blau mĭn jêh ri njêh nâm bu may.$b$,false),
('bunong-vn','GEN',41,40,null,$b$May mra chiă ngih gâp, jêh ri lĕ rngôch bunuyh ƀon lan gâp mra ƀư tĭng nâm nau may ntăm. Knŏng gâp jêng toyh lơn ma may yor gâp jêng hađăch.”$b$,false),
('bunong-vn','GEN',41,41,null,$b$Pharaôn lah ma Y-Yôsep: “Aơ gâp ăn may chiă lĕ n'gor Êjipt.”$b$,false),
('bunong-vn','GEN',41,42,null,$b$Pharaôn doh rgên tâp pŏng păng bơh ti jêh ri ntrŭp dok ta ti Y-Yôsep, păng sâm nsoh Y-Yôsep ma ao mhay rhên, jêh ri ăn văn ta trô ko du njăr rse mah.$b$,false),
('bunong-vn','GEN',41,43,null,$b$Păng ăn Y-Yôsep ncho ndeh seh tal bar păng jêh ri bu troh ta năp păng. “Chon Kômâk.” Pô ri Pharaôn ăn păng chiă uănh lĕ n'gor Êjipt.$b$,false),
('bunong-vn','GEN',41,44,null,$b$Pharaôn lah ma Y-Yôsep: “Gâp jêng Pharaôn. Tơ lah may mâu ăn ôh, mâu mra geh du huê bunuyh yor ti mâu lah jâng tâm n'gor Êjipt.”$b$,false),
('bunong-vn','GEN',41,45,null,$b$Pharaôn trơn amoh Y-Yôsep Y-Sapênat Phanêah; jêh ri păng ăn ma Y-Yôsep H'Asênat kon bu ur Y-Pôtipêra Kôranh ƀư brah ƀon Ôn jêng ur păng. Pô ri Y-Yôsep chop nhhol n'gor Êjipt.$b$,false),
('bunong-vn','GEN',41,46,null,$b$Y-Yôsep geh pe jât năm tơ lah păng ntơm pah kan ma Pharaôn hađăch Êjipt. Y-Yôsep luh bơh ta năp Pharaôn gay ma hăn lam n'gor Êjipt.$b$,true),
('bunong-vn','GEN',41,47,null,$b$Dôl pơh năm geh âk ba, neh jêng ndơ ngăn.$b$,false),
('bunong-vn','GEN',41,48,null,$b$Y-Yôsep bun prăp lĕ rngôch ndơ sông sa dôl tâm mpơl năm geh âk nây tâm n'gor Êjipt, jêh ri bun ndơ sông sa tâm âk rplay ƀon. Păng bun tâm ăp mƀon ndơ sông sa bơh mir jŭm ƀon nây.$b$,false),
('bunong-vn','GEN',41,49,null,$b$Y-Yôsep bun prăp ba âk ngăn tâm ban ma choih tâm dak rlai, kŏ păng mâu hôm dơi kơp ôh.$b$,false),
('bunong-vn','GEN',41,50,null,$b$Tât năm geh nau sa sât ji ngot, ur Y-Yôsep H'Asênat kon bu ur Y-Pôtipêra Kôranh ƀư brah ƀon Ôn, deh ma păng bar hê kon bu klâu.$b$,true),
('bunong-vn','GEN',41,51,null,$b$Y-Yôsep tâm amoh kon bu klâu bôk rah Y-Manasê, yor lah păng lah: “Brah Ndu ăn gâp chuêl lơi lĕ nau ŏk ra ah gâp jêh ri lĕ phung ngih mbơ̆ gâp.”$b$,false),
('bunong-vn','GEN',41,52,null,$b$Păng tâm amoh kon tal bar Y-Êphraim, yor lah păng lah: “Brah Ndu ăn gâp geh kon tâm n'gor nau rêh ni gâp.”$b$,true),
('bunong-vn','GEN',41,53,null,$b$Pơh năm geh ba tâm n'gor Êjipt lôch jêh.$b$,true),
('bunong-vn','GEN',41,54,null,$b$Pơh năm nau sa sât ji ngot ntơm tât tĭng nâm Y-Yôsep lah jêh. Geh nau sa sât ji ngot tâm lam n'gor, ƀiă lah tâm lam n'gor Êjipt geh ndơ sông sa.$b$,false),
('bunong-vn','GEN',41,55,null,$b$Tơ lah lĕ n'gor Êjipt geh nau sa sât ji ngot phung bunuyh ƀon lan nter ma Pharaôn gay ma geh ndơ sông sa. Pharaôn lah ma lĕ rngôch phung Êjipt: “Hăn hom ma Y-Yôsep. Ăn may ƀư tĭng nâm nau păng lah.”$b$,false),
('bunong-vn','GEN',41,56,null,$b$Pô ri tơ lah geh nau sa sât ji ngot lam n'gor, Y-Yôsep pơk lĕ rngôch jay, jêh ri tăch ba ma phung Êjipt. Yor lah nau sa sât ji ngot rêh ni ngăn tâm n'gor Êjipt.$b$,false),
('bunong-vn','GEN',41,57,null,$b$Lĕ rngôch n'gor hăn ta n'gor Êjipt gay rvăt ba tă bơh Y-Yôsep, yor lah nau sa sât ji ngot jêng rêh ni lam neh ntu.$b$,false),
('bunong-vn','GEN',42,1,null,$b$Tơ lah Y-Yakôb gĭt geh ba tâm n'gor Êjipt, păng lah ma phung kon bu klâu păng: “Mâm ƀư khân may gŭ dơm?”$b$,true),
('bunong-vn','GEN',42,2,null,$b$Păng lah: “Gâp tăng jêh geh ba tâm n'gor Êjipt. Jŭr hăn hom ta nây, rvăt ba ma he, gay ma he dơi gŭ rêh jêh ri mâu khĭt ôh.”$b$,true),
('bunong-vn','GEN',42,3,null,$b$Pô ri jât nuyh nâu Y-Yôsep hăn ŭch rvăt ba tâm n'gor Êjipt.$b$,true),
('bunong-vn','GEN',42,4,null,$b$Bunuyh Y-Yakôb mâu njuăl ôh Y-Benjamin oh Y-Yôsep ndrel ma phung nâu khân păng, yor lah nau mhĭk mra tât ma păng,$b$,false),
('bunong-vn','GEN',42,5,null,$b$pô ri phung kon bu klâu Israel hăn ŭch rvăt ba ndrel ma phung êng hăn ta n'gor Êjipt, yor lah geh nau sa sât ji ngot tâm n'gor Kanaan.$b$,false),
('bunong-vn','GEN',42,6,null,$b$Y-Yôsep jêng Kôranh chiă uănh n'gor. Phung nâu păng tât jêh ri chon mon ta năp păng chŭn măt ta neh.$b$,true),
('bunong-vn','GEN',42,7,null,$b$Y-Yôsep saơ phung nâu păng jêh ri gĭt năl khân păng, ƀiă lah păng ƀư tâm ban ma bu năch đah phung nâu păng, jêh ri ngơi dăng đah phung nâu păng. “Mbah tă khân may?” Khân păng lah: “Tă bơh n'gor Kanaan ŭch rvăt ndơ sông sa,”$b$,false),
('bunong-vn','GEN',42,8,null,$b$Y-Yôsep gĭt năl phung nâu păng, ƀiă lah phung nâu păng, mâu gĭt năl păng ôh.$b$,false),
('bunong-vn','GEN',42,9,null,$b$Y-Yôsep kah gĭt nau păng mbơi ma phung nâu păng, jêh ri păng lah: “Khân may jêng phung n'hut nhhol. Khân may văch gay gĭt ntŭk ra ai tâm n'gor aơ.”$b$,true),
('bunong-vn','GEN',42,10,null,$b$Phung nâu păng, lah ma păng: “Mâu!, Kôranh hên ah, ƀiă lah phung oh mon may văch, ŭch rvăt ndơ sông sa.$b$,false),
('bunong-vn','GEN',42,11,null,$b$Lĕ rngôch hên jêng phung kon bu klâu ma du huê bu klâu, hên jêng phung bunuyh sŏng srăng; phung oh mon may, mâu jêng phung nhhut ôh.”$b$,false),
('bunong-vn','GEN',42,12,null,$b$Păng lah: “Mâu, khân may văch gay gĭt ntŭk ra ai tâm n'gor.”$b$,false),
('bunong-vn','GEN',42,13,null,$b$Hên jêng phung oh mon may, jêng phung jât ma bar nuyh oh nâu, phung kon bu klâu ma du huê bu klâu tâm n'gor Kanaan, jêh ri aơ oh mpŭt aƀaơ gŭ ndrel ma mbơ̆ hên, jêh ri geh du huê roh jêh.”$b$,true),
('bunong-vn','GEN',42,14,null,$b$Ƀiă lah Y-Yôsep lah ma khân păng: “Di jêh gâp lah ma khân may. Khân may jêng phung n'hut.$b$,false),
('bunong-vn','GEN',42,15,null,$b$Pô aơ bu mra rlong uănh khân may, tĭng nâm Pharaôn hôm rêh, khân may mâu mra du luh tă bơh aơ ôh knŏng tơ lah oh khân may văch ta aơ.$b$,false),
('bunong-vn','GEN',42,16,null,$b$Njuăl du huê tâm phung khân may, gay ma păng njŭn leo oh khân may văch ta aơ, dôl khân may gŭ tâm ndrung bu nă, gay lŏng uănh nau khân may ngơi, gĭt lah khân may ngơi nau ngăn. Tơ lah mâu di pô nây ôh, tĭng nâm Pharaôn hôm rêh, khân may jêng phung n'hut.”$b$,false),
('bunong-vn','GEN',42,17,null,$b$Jêh ri păng ăn bu krŭng phung nâu păng tâm pe nar.$b$,false),
('bunong-vn','GEN',42,18,null,$b$Nar tal pe Y-Yôsep lah ma khân păng: “Ƀư pô aơ jêh ri khân may mra gŭ rêh, yor lah gâp klach yơk ma Brah Ndu.$b$,true),
('bunong-vn','GEN',42,19,null,$b$Tơ lah khân may jêng bunuyh sŏng srăng, ăn du huê tâm phung oh nâu khân may gŭ tâm ndrung bu nă. Ăn phung hôm mra njŭn ba ma phung ngih khân may dơi sông sa.$b$,false),
('bunong-vn','GEN',42,20,null,$b$Jêh ri njŭn leo ma gâp oh khân may. Pô ri nau khân may ngơi jêng nau ngăn, jêh ri khân may mâu mra khĭt ôh.” Khân păng ƀư pô nây.$b$,true),
('bunong-vn','GEN',42,21,null,$b$Jêh ri khân păng tâm ngơi ndrăng khân păng nơm: “Nanê̆ he tih yor oh he, yor lah he saơ jêh nau rngot huêng păng tơ lah păng vơh vơl ma he, jêh ri he mâu ŭch iăt ôh. Yor nây nau uh ah aơ tât ma he.”$b$,false),
('bunong-vn','GEN',42,22,null,$b$Y-Ruben plơ̆ lah ma khân păng: “Mâu di hĕ gâp lah ma khân may. Lơi khân may ƀư tih đah kon se aơ ôh? Ƀiă lah khân may mâu ŭch iăt ôh. Pô ri he dơn aƀaơ aơ nau phat dôih yor nau rung mham păng jêh.”$b$,true),
('bunong-vn','GEN',42,23,null,$b$Khân păng mâu gĭt ôh Y-Yôsep gĭt rbăng nau khân păng ngơi, yor lah geh nơm kâp rblang an ma khân păng.$b$,true),
('bunong-vn','GEN',42,24,null,$b$Y-Yôsep du bơh khân păng ŭch nhĭm. Păng plơ̆ ma phung nâu păng jêh ri ngơi ma khân păng. Y-Yôsep nhŭp Y-Simêôn bơh khân păng jêh ri chăp ta năp măt khân păng.$b$,false),
('bunong-vn','GEN',42,25,null,$b$Y-Yôsep đă bu mbêng ba tâm dŭng khân păng, jêh ri dơm prăk tâm dŭng ăp nơm khân păng, jêh ri ăn ma khân păng ndơ sông sa rŏ trong. Pô nây bu ƀư$b$,true),
('bunong-vn','GEN',42,26,null,$b$khân păng dăp ba khân păng ta klơ seh bri jêh ri khân păng hăn.$b$,false),
('bunong-vn','GEN',42,27,null,$b$Tơ lah du huê tâm phung khân păng pơk dŭng ŭch ăn gơ̆ kro ma seh bri păng tâm ntŭk khân păng jưh, păng saơ prăk tâm dŭng păng.$b$,false),
('bunong-vn','GEN',42,28,null,$b$Păng lah ma phung oh nâu păng: “Prăk gâp bu mplơ̆ jêh. Aơ, prăk gŭ tâm dŭng gâp.” Khân păng ioh nuih n'hâm jêh ri ngơi ndrăng khân păng nơm ma nau râm sâr. “Moh nau aơ Brah Ndu ƀư ma he?”$b$,false),
('bunong-vn','GEN',42,29,null,$b$Tơ lah khân păng tât ta Y-Yakôb mbơ̆ khân păng tâm n'gor Kanaan, khân păng nkoch bri lĕ nau hŏ tât jêh ma khân păng, lah:$b$,true),
('bunong-vn','GEN',42,30,null,$b$“Nơm jêng Kôranh n'gor ngơi dăng đah hên, jêh ri mĭn hên jêng phung n'hut.$b$,false),
('bunong-vn','GEN',42,31,null,$b$Ƀiă lah, hên lah ma păng: ‘Hên jêng phung bunuyh sŏng srăng, hên mâu jêng phung n'hut ôh.$b$,true),
('bunong-vn','GEN',42,32,null,$b$Hên jêng jât ma bar nuyh phung oh nâu, phung kon bu klâu mbơ̆ ; du huê roh hêt jêh, jêng oh mpŭt hên gŭ ndrel mbơ̆ hên tâm n'gor Kanaan.’$b$,false),
('bunong-vn','GEN',42,33,null,$b$Kôranh n'gor nây lah ma hên: “Pô aơ gâp mra gĭt ma khân may jêng bunuyh sŏng srăng; cha lơi ma gâp ta aơ du huê tâm phung oh nâu khân may; sŏk ba gay ma phung ngih khân may dơi sông sa, jêh ri hăn hom khân may.$b$,false),
('bunong-vn','GEN',42,34,null,$b$Njŭn leo oh mpŭt khân may ma gâp, pô ri gâp mra gĭt khân may mâu jêng ôh phung n'hut, ƀiă lah jêng phung sŏng srăng ngăn. Pô ri gâp mra mplơ̆ nâu khân may, jêh ri khân may mra tăch drăp ndơ tâm n'gor aơ.”$b$,true),
('bunong-vn','GEN',42,35,null,$b$Tơ lah khân păng nkhŭt dŭng khân păng, aơ nklâm prăk ăp nơm gŭ tâm dŭng păng tơ lah khân păng jêh ri mbơ̆ khân păng saơ mklâm prăk nây, khân păng klach.$b$,true),
('bunong-vn','GEN',42,36,null,$b$Y-Yakôb mbơ̆ khân păng lah: “Khân may ăn roh phung kon gâp, Y-Yôsep roh jêh, Y-Simêôn roh jêh, jêh ri aƀaơ khân may ŭch sŏk Y-Benjamin. Lĕ nau jêr aơ tât ma gâp.”$b$,true),
('bunong-vn','GEN',42,37,null,$b$Y-Ruben lah ma mbơ̆ păng: “Ăn may nkhĭt bar hê kon bu klâu gâp, tơ lah gâp mâu mplơ̆ ôh Y-Benjamin ma may. Jao păng tâm ti gâp, jêh ri gâp mra mplơ̆ păng ma may.”$b$,false),
('bunong-vn','GEN',42,38,null,$b$Ƀiă lah Y-Yakôb lah: “Kon bu klâu gâp mâu mra hăn ndrel ma khân may ôh. Yor lah nâu păng khĭt jêh, jêh ri knŏng êng păng aơ hôm. Tơ lah tât nau mhĭk ma păng rŏ trong khân may hăn, nau nây mra nkhĭt gâp yor ranh jêh, ăn gâp hăn gŭ ta Ƀon Phung Khĭt ma nau rngot.”$b$,false),
('bunong-vn','GEN',43,1,null,$b$Nau sa sât ji ngot knap ngăn tâm n'gor.$b$,true),
('bunong-vn','GEN',43,2,null,$b$Tơ lah lĕ jêh khân păng sa ba khân păng djôt tă bơh n'gor Êjipt, mbơ̆ khân păng lah ma khân păng. “Hăn rvăt hom ndơ sông sa djê̆ ma he.”$b$,false),
('bunong-vn','GEN',43,3,null,$b$Ƀiă lah Y-Yuđa lah ma păng: “Nơm nây mbơh rah vah jêh ma hên, ‘Khân may mâu mra saơ ôh muh măt gâp, knŏng tơ lah oh khân may văch ndrel ma khân may.’$b$,false),
('bunong-vn','GEN',43,4,null,$b$Tơ lah may mra njuăl hăn oh hên ndrel ma hên, hên mra hăn rvăt ndơ sông sa ma may.$b$,false),
('bunong-vn','GEN',43,5,null,$b$Ƀiă lah tơ lah may mâu ăn păng hăn ndrel ôh, hên mâu mra hăn ôh, yor lah nơm nây lah jêh ma hên. ‘Khân may mâu mra saơ muh măt gâp ôh, knŏng tơ lah oh khân may văch ndrel ma khân may?”$b$,false),
('bunong-vn','GEN',43,6,null,$b$Israel lah: “Mâm khân may ƀư nau jêr ma gâp ma nau khân may mbơh ma păng khân may geh du huê oh lĕ?”$b$,false),
('bunong-vn','GEN',43,7,null,$b$Khân păng lah: “Nơm nây ôp rah vah hên nơm jêh ri ma mpôl băl he, ‘Mbơ̆ khân may hôm rêh lĕ? Khân may lŏ geh lĕ oh êng? Hên plơ̆ lah ma păng tĭng nâm nau păng ôp aơ. Dơi lĕ hên gĭt lor păng mra lah.’ Ăn oh khân may văch?”$b$,false),
('bunong-vn','GEN',43,8,null,$b$Y-Yuđa lah ma Y-Israel mbơ̆ păng: “Ăn kon se nây hăn ndrel ma gâp. Hên mra dâk hăn, pô ri he mra gŭ rêh, mâu khĭt ôh, hên, may jêh ri phung kon hên.$b$,false),
('bunong-vn','GEN',43,9,null,$b$Gâp mra ton ma păng, may dơi ƀư ma gâp tơ lah gâp mâu njŭn sĭt păng ta năp may. Gâp mra tuy nau tih ƀa ƀơ ta năp may.$b$,false),
('bunong-vn','GEN',43,10,null,$b$Yor lah tơ lah hên mâu njong nar ôh, nanê̆ hên plơ̆ sĭt jêh tal bar.”$b$,false),
('bunong-vn','GEN',43,11,null,$b$Israel, mbơ̆ khân păng lah: ‘Tơ lah pô nây, ƀư hom pô aơ, dơm tâm dŭng khân may ueh lơn bơh n'gor aơ, jêh ri djôt leo ma nơm nây ndơ nhhơr dak ƀâu n'hôl djê̆ dak sŭt djê̆, ndơ sa kah, dak si tăng jêh ri play aman dê.$b$,true),
('bunong-vn','GEN',43,12,null,$b$Djôt tâm ti khân may prăk bar tơ̆ âk lơn, nđâp prăk bu nsĭt jêh tâm dŭng khân may. Klăp lah bu vĭ.$b$,false),
('bunong-vn','GEN',43,13,null,$b$Sŏk leo lĕ oh khân may, dâk hom, plơ̆ hăn ma nơm nây.$b$,false),
('bunong-vn','GEN',43,14,null,$b$Dăn ma Brah Ndu, Nơm Geh Lĕ Nau Brah, ăn nau yô̆ ma khân may ta năp nơm nây, gay ma păng mplơ̆ nâu khân may jêh ri Y-Benjamin. Tơ lah gâp roh phung kon gâp, gâp roh yơh.”$b$,false),
('bunong-vn','GEN',43,15,null,$b$Khân păng ndjôt ndơ nhhơr nây jêh ri prăk bar tơ̆ âk lơn, nđâp ma Y-Benjamin. Khân păng dâk hăn ta n'gor Êjipt jêh ri gŭ râng ta năp Y-Yôsep.$b$,false),
('bunong-vn','GEN',43,16,null,$b$Tơ lah Y-Yôsep saơ Y-Benjamin ndrel ma khân păng, păng lah ma phung oh mon chiă uănh ngih păng. “Ăn phung bunuyh lăp tâm ngih, gŭch puăch jêh ri nkra ndơ sông sa, yor lah khân păng mra sông sa ndrel ma gâp ta nklang bôk nar.”$b$,true),
('bunong-vn','GEN',43,17,null,$b$Bunuyh nây ƀư tĭng nâm nau Y-Yôsep ntăm, jêh ri păng njŭn leo phung bunuyh nây ta ngih Y-Yôsep.$b$,false),
('bunong-vn','GEN',43,18,null,$b$Phung nây klach yor lah bu njŭn leo khân păng ta ngih Y-Yôsep, jêh ri khân păng lah: “Yor prăk bu nsĭt tâm dŭng he tal lor bu njŭn he ta aơ. Păng ŭch joi nau đah he jêh ri ƀư mhĭk ma he, gay ăn he jêng dĭk jêh ri pit lơi seh bri he.”$b$,false),
('bunong-vn','GEN',43,19,null,$b$Pô ri khân păng ta oh mon chiă ngih Y-Yôsep, jêh ri ngơi ma păng ta mpông bloh ngih nây.$b$,false),
('bunong-vn','GEN',43,20,null,$b$Khân păng lah: “Ơ kôranh hên, hên jŭr văch jêh tal lor gay ma rvăt ndơ sông sa.$b$,false),
('bunong-vn','GEN',43,21,null,$b$Tơ lah hên tât ta ntŭk hên jưh, hên pơk dŭng jêh ri, aơ prăk ăp nơm hên gŭ tâm dŭng hên, prăk hôm nŭm.$b$,false),
('bunong-vn','GEN',43,22,null,$b$Pô ri hên mplơ̆ djôt nđâp ma prăk êng gay ma rvăt ndơ sông sa. Hên mâu gĭt ôh mbu mplơ̆ prăk tâm dŭng hên.”$b$,false),
('bunong-vn','GEN',43,23,null,$b$Păng lah: “Gŭ đăp mpăn hom, lơi klach ôh Brah Ndu khân may, Brah Ndu mbơ̆ khân may ăn jêh prăk tâm dŭng khân may. Gâp sŏk dơn jêh prăk khân may.” Jêh ri păng njŭn Y-Simêôn ma phung nây.$b$,false),
('bunong-vn','GEN',43,24,null,$b$Nơm nây ăn khân păng lăp tâm ngih Y-Yôsep. Ăn dak ma khân păng rao jâng. Nơm nây ăn hĭp kro ma seh bri khân păng.$b$,false),
('bunong-vn','GEN',43,25,null,$b$Khân păng nkra ndơ nhhơr dôl gŭ kâp Y-Yôsep tât ta nklang bôk nar, yor lah khân păng tăng jêh khân păng mra sông sa ta nây.$b$,false),
('bunong-vn','GEN',43,26,null,$b$Tơ lah Y-Yôsep sĭt ta ngih, khân păng njŭn ta ngih ndơ nhhơr khân păng geh, jêh ri khân păng chon mon chŭn măt ta neh.$b$,true),
('bunong-vn','GEN',43,27,null,$b$Y-Yôsep ôp khân păng ma nau ngăch prăl săk jăn, lah: “Mbơ̆ khân may hôm ngăch lĕ, nơm bu ranh khân may nkoch bri jêh ma gâp nây? Păng hôm rêh lĕ?”$b$,true),
('bunong-vn','GEN',43,28,null,$b$Khân păng lah: “Oh mon may, mbơ̆ hên hôm ngăch đŏng. Păng ăt hôm rêh lĕ.” Jêh ri khân păng kŭnh jêh ri khân păng chon mon mbah.$b$,false),
('bunong-vn','GEN',43,29,null,$b$Y-Yôsep n'gơr măt uănh saơ Y-Benjamin oh păng, kon ma mê̆ păng, jêh ri lah: “Di lĕ păng aơ jêng oh mpŭt. Khân may nkoch bri jêh ma gâp? Ăn Brah Ndu rŏng ma may, Ơ oh.”$b$,false),
('bunong-vn','GEN',43,30,null,$b$Nuih n'hâm Y-Yôsep rŏng ngăn ma oh păng jêh ri păng joi ntŭk ŭch nhĭm. Păng ndal lăp tâm jrô păng jêh ri nhĭm ta nây.$b$,false),
('bunong-vn','GEN',43,31,null,$b$Păng pach muh măt jêh ri du luh. Păng ât rdâng mâu mpơl nuih n'hâm păng ôh jêh ri lah: “Thai ndơ sông sa?”$b$,false),
('bunong-vn','GEN',43,32,null,$b$Bu Thai ndơ sông sa ma Y-Yôsep êng ntŭk, jêh ri ma phung Êjipt sông ndrel ma păng ntŭk êng lĕ, yor lah phung Êjipt mâu dơi sông ndrel ma phung Hêbrơ ôh, yor lah phung Êjipt kơp nau nây nau ƀư ƀơ̆ .$b$,false),
('bunong-vn','GEN',43,33,null,$b$Khân păng gŭ ta năp Y-Yôsep di mbor, nơm deh lor tĭng nâm nau vay păng jêng nâu ranh, jêh ri oh tĭng nâm nse lơn khân păng hih rhâl tâm uănh ndrăng khân păng nơm.$b$,true),
('bunong-vn','GEN',43,34,null,$b$Y-Yôsep đă bu ndơp ndơ sông sa ma khân păng ta năp păng; ƀiă lah ndơ ăn ma Y-Benjamin prăm tơ̆ âk lơn ma ndơ phung nâu păng. Khân păng nhêt jêh ri gŭ maak ndrel ma Y-Yôsep.$b$,false),
('bunong-vn','GEN',44,1,null,$b$Y-Yôsep ntăm ma phung oh mon chiă ngih păng pô aơ; “Mbêng dŭng phung bunuyh nây ma ndơ sông sa tĭng nâm dŭm âk khân păng dơi djôt, jêh ri dơm prăp ăp dŭng ma ăp nơm khân păng.$b$,true),
('bunong-vn','GEN',44,2,null,$b$Ăn may dơm lĕ kachok prăk gâp tâm dŭng nơm nse lơn ndrel ma ndrel ma prăk, ba păng.” Păng ƀư tĭng nâm nau Y-Yôsep ngơi.$b$,true),
('bunong-vn','GEN',44,3,null,$b$Tơ lah ang ôi, bu ăn phung nây hăn ndrel ma seh bri khân păng.$b$,true),
('bunong-vn','GEN',44,4,null,$b$Tơ lah khân păng du luh jêh tă bơh ƀon, ê ngai ôh. Y-Yôsep lah ma oh mon păng: “Dâk hom may tĭng phung nây; jêh ri tơ lah may ban khân păng, ăn may lah. Phâm ƀư khân may mplơ̆ nau mhĭk ma nau ueh?$b$,false),
('bunong-vn','GEN',44,5,null,$b$Mâm ƀư khân may sŏk ntŭng kachok prăk gâp? Mâu di hĕ kachok aơ kôranh gâp dŏng nhêt jêh ri dŏng sol nau ndâp? Tâm nau aơ khân may ƀư tih jêh.”$b$,false),
('bunong-vn','GEN',44,6,null,$b$Nơm nây ban phung nây jêh ri lah, nau nây,$b$,true),
('bunong-vn','GEN',44,7,null,$b$Khân păng lah ma nơm nây: “Mâm ƀư kôranh hên ngơi pô nây? Phung oh mon may mâu mâp ƀư nau pô nây ôh!$b$,false),
('bunong-vn','GEN',44,8,null,$b$Prăk hên saơ jêh ta dŭng hên hŏ djôt mplơ̆ jêh ma may bơh n'gor Kanaan. Pô ri phâm ƀư hên mra ntŭng prăk mâu lah mah bơh ngih kôranh may?$b$,false),
('bunong-vn','GEN',44,9,null,$b$Ta mbu nâm tâm phung oh mon may mra saơ kachok, mra jêng dĭk gâp.”$b$,false),
('bunong-vn','GEN',44,10,null,$b$Păng lah: “Ăn nau nây jêng tĭng nâm bu nau khân may ngơi. Ta mbu nâm bu mra saơ kachok mra jêng dĭk gâp, bi phung êng mra rsang.”$b$,false),
('bunong-vn','GEN',44,11,null,$b$Pô ri lĕ rngôch khân păng nhhiơ đuh dŭng khân păng ta neh jêh ri pơk.$b$,false),
('bunong-vn','GEN',44,12,null,$b$Păng rhi joi ntơm bơh nâu ranh tât ta oh nse; jêh ri păng saơ kachok tâm dŭng Y-Benjamin.$b$,false),
('bunong-vn','GEN',44,13,null,$b$Pô ri khân păng nkhêk lơi bok ao khân păng ăp nơm dơm dŭng ta klơ ndŭr kơi seh bri păng, jêh ri plơ̆ sĭt ta ƀon Y-Yôsep.$b$,false),
('bunong-vn','GEN',44,14,null,$b$Tơ lah Y-Yuđa jêh ri phung oh nâu păng tât ta ngih Y-Yôsep, Y-Yôsep ăt gŭ ta ngih. Khân păng chon mon ta neh ta năp păng.$b$,true),
('bunong-vn','GEN',44,15,null,$b$Y-Yôsep lah ma khân păng: “Moh khân may ƀư jêh? Khân may mâu gĭt hĕ bunuyh tâm ban ma gâp dơi sol nau ndâp?”$b$,false),
('bunong-vn','GEN',44,16,null,$b$Y-Yuđa lah: “Moh hên dơi lah ma kôranh gâp? Moh nau hên dơi ngơi? Phâm hên dơi n'gang hên nơm? Brah Ndu saơ jêh nau kue phung oh mon may, aơ hên jêng dĭk ma kôranh gâp, hên jêh ri nơm tâm ti păng nây mra saơ kachok.”$b$,true),
('bunong-vn','GEN',44,17,null,$b$Ƀiă lah Y-Yôsep lah: “Gâp mâu mĭn ôh ƀư pô nây! Knŏng nơm tâm ti păng nây mra saơ kachok mra jêng dĭk gâp; bi khân may ăn khân may sĭt đăp mpăn ta ngih mbơ̆ khân may.”$b$,false),
('bunong-vn','GEN',44,18,null,$b$Y-Yuđa hăn dăch ta Y-Yôsep jêh ri lah: “Ơ kôranh gâp, gâp dăn ma may, ăn oh mon may dơi ngơi du tong ma kôranh gâp; jêh ri lơi ăn nau may nuih ƀư ma oh mon may ôh; yor lah may jêng tâm ban ma Pharaôn.$b$,true),
('bunong-vn','GEN',44,19,null,$b$Kôranh gâp ôp jêh phung oh mon păng, lah: “Khân may geh lĕ mbơ̆ mâu lah oh?”$b$,true),
('bunong-vn','GEN',44,20,null,$b$Hên lah ma kôranh gâp: ‘Hên geh du huê mbơ̆ ranh jêh, jêh ri du huê oh bu deh ma păng dôl păng ranh. Nâu kon se nây khĭt jêh, jêh ri knŏng êng păng hôm bơh phung kon me păng. Mbơ̆ păng rŏng ma păng.’$b$,true),
('bunong-vn','GEN',44,21,null,$b$May lah jêh ma phung oh mon may, ‘Njŭn leo păng ma gâp, gay ma gâp dơi saơ păng.$b$,false),
('bunong-vn','GEN',44,22,null,$b$Hên lah jêh ma Kôranh gâp, ‘Kon se nây mâu dơi lơi mbơ̆ păng ôh, yor lah, tơ lah păng lơi mbơ̆ păng, mbơ̆ păng mra khĭt.’$b$,false),
('bunong-vn','GEN',44,23,null,$b$Ƀiă lah may lah jêh ma phung oh mon may. ‘Knŏng tơ lah oh khân may văch ndrel ma khân may, khân may mâu mra saơ muh măt gâp đŏng ôh.’$b$,false),
('bunong-vn','GEN',44,24,null,$b$Tơ lah hên sĭt jêh ma oh mon may, mbơ̆ gâp, hên nkoch bri ma păng nau kôranh gâp ngơi.$b$,false),
('bunong-vn','GEN',44,25,null,$b$Tơ lah mbơ̆ hên lah: ‘Hăn rvăt đŏng ndơ sông sa djê̆ ma he.’$b$,false),
('bunong-vn','GEN',44,26,null,$b$Hên lah: ‘Hên mâu dơi hăn ôh. Tơ lah oh nse hên hăn ndrel ma hên pô ri hên mra hăn; yor lah hên mâu hôm dơi saơ muh măt nơm nây ôh, knŏng tơ lah oh nse hên hăn ndrel ma hên.’$b$,false),
('bunong-vn','GEN',44,27,null,$b$Oh mon may, mbơ̆ gâp lah ma hên: ‘Khân may gĭt ur gâp deh jêh ma gâp bar hê kon bu klâu.$b$,false),
('bunong-vn','GEN',44,28,null,$b$Du huê luh tă bơh gâp jêh ri gâp lah jêh: “Nanê̆ mpa bri sa hêk jêh păng.” Jêh ri gâp mâu hôm saơ păng ôh.$b$,false),
('bunong-vn','GEN',44,29,null,$b$Tơ lah khân may sŏk đŏng nơm aơ tă bơh gâp, jêh ri tơ lah nau mhĭk tât ma păng, nau nây mra nkhĭt gâp yor ranh jêh, ăn gâp hăn jŭr tâm Ƀon Phung Khĭt ma nau rngot.’$b$,false),
('bunong-vn','GEN',44,30,null,$b$Aƀaơ aơ tơ lah gâp sĭt ma oh mon may, mbơ̆ gâp, jêh ri kon se ndăm nây mâu geh ndrel ma hên ôh, yor lah nau rêh păng jêng nguay đah nau rêh kon se ndăm nây.$b$,false),
('bunong-vn','GEN',44,31,null,$b$Tơ lah păng saơ kon se ndăm nây mâu geh sĭt ndrel ma hên ôh, păng mra khĭt pô ri phung oh mon păng mra ăn păng khĭt yor ranh jêh, ăn păng jŭr hăn ta Ƀon Phung Khĭt ma nau rngot.$b$,false),
('bunong-vn','GEN',44,32,null,$b$Yor lah oh mon may ton ma kon se ndăm nây ma mbơ̆ gâp, lah: “Gâp mra tuy ƀa ƀơ nau tih ta năp mbơ̆ gâp tơ lah gâp mâu mplơ̆ păng ma may.$b$,false),
('bunong-vn','GEN',44,33,null,$b$Bi aƀaơ, gâp dăn ma may ăn oh mon may dơi gŭ jêng dĭk kôranh gâp nsro kon se ndăm nây; jêh ri ăn kon se ndăm sĭt ndrel phung nâu păng.$b$,false),
('bunong-vn','GEN',44,34,null,$b$Yor lah mâm gâp dơi sĭt ma mbơ̆ gâp tơ lah kon se ndăm nây mâu sĭt ôh ndrel ma gâp? Gâp klach geh nau mhĭk tât ma mbơ̆ gâp.”$b$,false),
('bunong-vn','GEN',45,1,null,$b$Rnôk nay Y-Yôsep mâu hôm dơi nkân păng nơm ôh ta năp lĕ rngôch phung gŭ dăch păng, jêh ri păng nter: “Ăn lĕ rngôch bunuyh du luh?” Pô ri mâu hôm geh du huê bunuyh gŭ ndrel ma păng ôh, dôl Y-Yôsep ăn phung oh nâu păng gĭt năl păng.$b$,true),
('bunong-vn','GEN',45,2,null,$b$Păng nhĭm huy phung Êjipt jêh ri ngih Pharaôn tăng lĕ.$b$,true),
('bunong-vn','GEN',45,3,null,$b$Y-Yôsep lah ma phung oh nâu păng: “Gâp jêng Y-Yôsep. Mbơ̆ gâp hôm rêh lĕ?” Ƀiă lah phung oh nâu păng mâu dơi plơ̆ lah ma păng ôh, yor lah khân păng klach ta năp Y-Yôsep.$b$,false),
('bunong-vn','GEN',45,4,null,$b$Y-Yôsep lah ma phung oh nâu păng: “Văch dăch ta gâp, gâp dăn ma khân may.” Phung oh nâu păng hăn dăch jêh ri păng lah: “Gâp jêng Y-Yôsep, oh khân may, nơm khân may tăch jêh tâm n'gor Êjipt.$b$,true),
('bunong-vn','GEN',45,5,null,$b$Aƀaơ aơ, lơi khân may rngot, mâu lĕ dơi nuih ma khân may nơm, yor lah khân may tăch jêh gâp ta aơ; yor lah Brah Ndu njuăl jêh gâp văch lor ma khân may gay tâm rklaih nau rêh.$b$,false),
('bunong-vn','GEN',45,6,null,$b$Yor lah dôl bar năm jêh geh nau sa sât ji ngot tâm n'gor, jêh ri hôm prăm năm mâu mra geh ôh nau kah jik tuch mâu lah kăch roih.$b$,false),
('bunong-vn','GEN',45,7,null,$b$Brah Ndu njuăl gâp văch lor ma khân may gay prăp phung kon sau khân may tâm neh ntu, jêh ri gay prăp nau rêh khân may.$b$,true),
('bunong-vn','GEN',45,8,null,$b$Pô ri mâu geh khân may ôh njuăl gâp văch ta aơ, ƀiă lah Brah Ndu yơh păng ăn gâp jêng mbơ̆ ma Pharaôn jêh ri kôranh ma lĕ ngih păng jêh ri kôranh chiă uănh lĕ n'gor Êjipt.$b$,false),
('bunong-vn','GEN',45,9,null,$b$Ndal hom khân may, sĭt ta mbơ̆ gâp jêh ri lah ma păng pô aơ: “Kon may Y-Yôsep ngơi, Brah Ndu ăn gâp jêng Kôranh ma lĕ n'gor Êjipt. Văch hom ta gâp, lơi hôm gŭ kâp ôh.$b$,true),
('bunong-vn','GEN',45,10,null,$b$May mra gŭ tâm n'gor Gôsen, jêh ri may mra gŭ dăch gâp, may phung kon may, phung kon sau may, biăp may, ndrôk may, jêh ri lĕ rngôch ndơ may geh.$b$,false),
('bunong-vn','GEN',45,11,null,$b$Ta nây gâp mra siăm may, yor lah hôm prăm năm sa sât ji ngot, klach lah may jêh ri ngih may jêh ri lĕ rngôch ndơ may geh tât ma nau rêh ni.”$b$,false),
('bunong-vn','GEN',45,12,null,$b$Aơ, măt khân may saơ, jêh ri măt Y-Benjamin saơ lĕ ma bâr mbung gâp nơm ngơi ma khân may.$b$,false),
('bunong-vn','GEN',45,13,null,$b$Ăn khân may nkoch bri ma mbơ̆ gâp lĕ nau chrêk rmah gâp tâm n'gor Êjipt, jêh ri lĕ nau khân may saơ jêh. Gơnh oi khân may ăn mbơ̆ gâp jŭr ta aơ.”$b$,false),
('bunong-vn','GEN',45,14,null,$b$Jêh ri păng ut ta trô ko Y-Benjamin oh păng jêh ri nhĭm. Y-Benjamin tâm ban lĕ nhĭm ta trô ko păng.$b$,false),
('bunong-vn','GEN',45,15,null,$b$Păng chŭm lĕ rngôch phung oh nâu păng jêh ri nhĭm. Jêh nau nây phung oh nâu păng ngơi ndrel đah păng.$b$,false),
('bunong-vn','GEN',45,16,null,$b$Tơ lah bu tăng tâm ngih Pharaôn, phung oh nâu Y-Yôsep tât jêh.” Nau nây maak ngăn ma Pharaôn jêh ri ma phung oh mon păng.$b$,true),
('bunong-vn','GEN',45,17,null,$b$Pharaôn lah ma Y-Yôsep: “Lah ma phung oh nâu may: ‘Ƀư nau aơ rdeng seh bri khân may, plơ̆ sĭt hom ta n'gor Kanaan.$b$,true),
('bunong-vn','GEN',45,18,null,$b$Ăn khân may sŏk mbơ̆ khân may jêh ri phung ngih khân may, jêh ri plơ̆ văch ta gâp. Gâp mra ăn ma khân may ndơ ueh lơn tâm n'gor Êjipt, jêh ri khân may sa play ueh lơn tâm n'gor.’$b$,false),
('bunong-vn','GEN',45,19,null,$b$Tâm ban lĕ, ntăm ma khân păng: ‘Ăn khân may ƀư pô aơ, sŏk tă bơh n'gor Êjipt ndeh seh gay ma rdeng kon jê̆ khân may jêh ri ur khân may. Njŭn leo mbơ̆ khân may jêh ri plơ̆ văch.$b$,false),
('bunong-vn','GEN',45,20,null,$b$Lơi hôm rvê ma drăp ndơ khân may ôh, yor lah ndơ ueh lơn tâm lĕ n'gor Êjipt jêng ndơ khân may.’ ”$b$,false),
('bunong-vn','GEN',45,21,null,$b$Phung kon bu klâu Israel ƀư pô nây. Y-Yôsep ăn ma khân păng ndeh seh tĭng nâm nau Pharaôn ntăm jêh, păng lŏ ăn ndơ ma phung nây sông sa rŏ trong.$b$,false),
('bunong-vn','GEN',45,22,null,$b$Y-Yôsep ăn ma khân păng bok ao tơh; ƀiă lah ma Y-Benjamin păng ăn pe rhiăng rlay prăk jêh ri prăm blah bok ao tơh.$b$,false),
('bunong-vn','GEN',45,23,null,$b$Păng njuăl ma mbơ̆ păng ndơ aơ, Jât mlâm seh rdeng ndơ ueh bơh n'gor Êjipt, jêh ri jât mlâm seh bri me rdeng ba, piăng let jêh ri ndơ sông sa ma mbơ̆ păng rŏ trong.$b$,false),
('bunong-vn','GEN',45,24,null,$b$Pô ri păng njuăl hăn phung oh nâu păng, jêh ri tơ lah khân păng hăn, păng lah: “Lơi ta khân may tâm lah tâm djel rŏ trong ôh.”$b$,true),
('bunong-vn','GEN',45,25,null,$b$Pô ri khân păng luh bơh n'gor Êjipt jêh ri tât ta n'gor Kanaan ma Y-Yakôb mbơ̆ khân păng.$b$,true),
('bunong-vn','GEN',45,26,null,$b$Khân păng mbơh ma mbơ̆ khân păng: “Y-Yôsep ăt hôm rêh, jêh ri păng jêng Kôranh chiă uănh lĕ n'gor Êjipt.” Nuih n'hâm Y-Yakôb khĭt huăr, yor lah păng mâu đing ôh nau phung kon bu klâu păng mbơh.$b$,false),
('bunong-vn','GEN',45,27,null,$b$Ƀiă lah tơ lah phung kon păng nkoch lĕ nau Y-Yôsep ngơi jêh ma khân păng, jêh ri tơ lah păng saơ ndeh seh Y-Yôsep njuăl gay ma rdeng păng, huêng Y-Yakôb mbơ̆ khân păng plơ̆ kah gĭt.$b$,false),
('bunong-vn','GEN',45,28,null,$b$Jêh ri Y-Yakôb lah: “Găp jêh! Y-Yakôb kon bu klâu gâp hôm rêh. Gâp mra hăn tâm mâp ma păng lor ma gâp khĭt.”$b$,false),
('bunong-vn','GEN',46,1,null,$b$Israel du hăn ndrel ma lĕ rngôch drăp ndơ păng geh. Păng tât ta ƀon Ber Sêba jêh ri nhhơr ndơ ƀư brah ma Brah Ndu mbơ̆ păng Y-Isăk.$b$,true),
('bunong-vn','GEN',46,2,null,$b$Brah Ndu ngơi ma Israel tâm nau mpơl dôl măng jêh ri lah: “Y-Yakôb ơi, Y-Yakôb ơi.” Israel lah: “Aơ ta aơ gâp.”$b$,false),
('bunong-vn','GEN',46,3,null,$b$Brah Ndu lah: “Gâp jêng Brah Ndu, Brah Ndu mbơ̆ may, lơi klach ôh jŭr hăn ta n'gor Êjipt; yor lah ta nây gâp mra ăn may jêng du mpôl băl toyh.$b$,false),
('bunong-vn','GEN',46,4,null,$b$Gâp mra jŭr hăn ndrel ma nau ta n'gor Êjipt, jêh ri gâp mra ăn may plơ̆ sĭt tă bơh n'gor Êjipt jêh ri Y-Yôsep mra gŭ ndrel ma nau ta nar may khĭt.”$b$,false),
('bunong-vn','GEN',46,5,null,$b$Y-Yakôb hăn tă bơh ƀon Bersêba, jêh ri phung kon bu klâu Y-Israel rdeng Y-Yakôb mbơ̆ khân păng, nđâp ma phung kon khân păng jêh ri ur khân păng tâm ndeh seh Pharaôn njuăl jêh gay ma rdeng khân păng.$b$,false),
('bunong-vn','GEN',46,6,null,$b$Khân păng ndjôt leo ndrôk biăp jêh ri drăp ndơ khân păng geh tâm n'gor Kanaan, jêh ri hăn tât ta n'gor Êjipt. Y-Yakôb jêh ri lĕ rngôch phung kon sau ndrel ma păng.$b$,false),
('bunong-vn','GEN',46,7,null,$b$Păng djôt ndrel ma păng ta n'gor Êjipt phung kon bu klâu, phung sau bu klâu păng, phung kon bu ur jêh ri phung sau bu ur păng lĕ rngôch phung kon sau păng.$b$,true),
('bunong-vn','GEN',46,8,null,$b$Aơ amoh phung kon Y-Israel tât ta n'gor Êjipt. Y-Yakôb jêh ri phung păng: Y-Ruben kon bu klâu bôk rah deh ma Y-Yakôb,$b$,true),
('bunong-vn','GEN',46,9,null,$b$jêh ri phung kon bu klâu Y-Ruben: Y-Hanôk, Y-Palu, Y-Hêsron, jêh ri Y-Karmi.$b$,false),
('bunong-vn','GEN',46,10,null,$b$Phung kon bu klâu Y-Simêôn: Y-Jêmuêl, Y-Jamin, Y-Ôhat, Y-Jakin, Y-Sôhar jêh ri Y-Sôl kon bu klâu bu ur Kanaan.$b$,false),
('bunong-vn','GEN',46,11,null,$b$Phung aơ kon bu klâu Y-Lêvi: Y-Gersôn, Y-Kôhat jêh ri Y-Mêrari.$b$,false),
('bunong-vn','GEN',46,12,null,$b$Phung kon bu klâu Y-Yuđa: (ƀiă lah Y-Er jêh ri Y-Ônan khĭt jêh tâm n'gor Kanaan). Phung kon bu klâu Y-Pêres, Y-Hêsron jêh ri Y-Hamul.$b$,false),
('bunong-vn','GEN',46,13,null,$b$Phung kon bu klâu Y-Isakar: Y-Tôla, Y-Puva, Y-Yôp jêh ri Y-Simrôn,$b$,false),
('bunong-vn','GEN',46,14,null,$b$phung kon bu klâu Y-Sabulôn: Y-Sêret, Y-Êlon jêh ri Y-Jalêel.$b$,false),
('bunong-vn','GEN',46,15,null,$b$Phung nây phung kon bu klâu H'Lêa deh ma Y-Yakôb ta n'gor Padan Aram, nđâp ma H'Dina kon bu ur păng. Lĕ rngôch phung kon bu klâu jêh ri phung kon bu ur păng jêng pe jât ma pe nuyh.$b$,false),
('bunong-vn','GEN',46,16,null,$b$Phung kon bu klâu Y-Gat: Y-Sipiôn, Y-Hagi, Y-Suni, Y-Êsbôn, Y-Êri, Y-Arôdi jêh ri Y-Arêli.$b$,true),
('bunong-vn','GEN',46,17,null,$b$Phung kon bu klâu Y-Aser: H'Sêra oh bu ur khân păng. Phung kon bu klâu Y-Bêria: Y-Hêber jêh ri Y-Malkiêl.$b$,false),
('bunong-vn','GEN',46,18,null,$b$Phung nây phung kon bu klâu H'Silpa, nơm Y-Laban ăn ma H'Lêa kon bu ur păng. H'Silpa deh phung nây ma Y-Yakôb jât ma prao nuyh.$b$,true),
('bunong-vn','GEN',46,19,null,$b$Phung kon bu klâu H'Rachel ur Y-Yakôb: Y-Yôsep jêh ri Y-Benjamin.$b$,false),
('bunong-vn','GEN',46,20,null,$b$Phung H'Asêrat kon bu ur Y-Pôtipêra Kôranh ƀư brah ƀon Ôn deh ma Y-Yôsep tâm n'gor Êjipt: Y-Manasê jêh ri Y-Êphraim.$b$,true),
('bunong-vn','GEN',46,21,null,$b$Phung kon bu klâu Y-Benjamin: Y-Bêla, Y-Bêker, Y-Asbel, Y-Gêra, Y-Naman, Y-Êhi, Y-Ros, Y-Nupim, Y-Hupim jêh ri Y-Ardơ.$b$,true),
('bunong-vn','GEN',46,22,null,$b$Phung nây phung kon bu klâu H'Lêa deh ma Y-Yakôb, lĕ rngôch jât ma puăn nuyh.$b$,true),
('bunong-vn','GEN',46,23,null,$b$Kon bu klâu Y-Dan: Y-Husim,$b$,true),
('bunong-vn','GEN',46,24,null,$b$Phung kon bu klâu Y-Naptali: Y-Yasêel, Y-Guni, Y-Jêser jêh ri Y-Silem.$b$,false),
('bunong-vn','GEN',46,25,null,$b$Phung nây phung kon bu klâu H'Bilha, nơm Y-Laban ăn ma H'Rachel, kon bu ur păng, phung nây H'Bilha deh ma Y-Yakôb pơh nuyh.$b$,false),
('bunong-vn','GEN',46,26,null,$b$Lĕ rngôch phung bunuyh tât ta n'gor Êjipt ndrel ma Y-Yakôb, phung kon păng mâu geh kơp ur phung kon bu klâu păng ôh, lĕ rngôch prao jât ma prao nuyh.$b$,false),
('bunong-vn','GEN',46,27,null,$b$Phung kon bu klâu Y-Yôsep du deh ma păng tâm n'gor Êjipt, bar hê. Lĕ rngôch phung bunuyh ngih Y-Yakôb tât ta n'gor Êjipt, pơh jât nuyh.$b$,false),
('bunong-vn','GEN',46,28,null,$b$Y-Yakôb njuăl Y-Yuđa hăn lor tât ta Y-Yôsep gay ma leo trong hăn ta n'gor Gôsen. Pô ri khân păng tât ta n'gor Gôsen.$b$,true),
('bunong-vn','GEN',46,29,null,$b$Y-Yôsep ăn bu nkra ndeh seh păng jêh ri păng hăn ta n'gor Gôsen gay tâm mâp đah Israel mbơ̆ păng. Y-Yôsep tât ta păng, ut ta trô ko jêh ri nhĭm jong ngăn.$b$,true),
('bunong-vn','GEN',46,30,null,$b$Y-Israel lah ma Y-Yôsep: “Aƀaơ ăn gâp khĭt, yor lah gâp saơ jêh muh măt may jêh ri gĭt may ăt hôm rêh.”$b$,false),
('bunong-vn','GEN',46,31,null,$b$Y-Yakôb lah ma phung oh nâu păng jêh ri ma phung ngih mbơ̆ păng: “Gâp mra hăn mbơh ma Pharaôn lah: “Phung oh nâu gâp, jêh ri phung ngih mbơ̆ gâp bơh n'gor Kanaan tât jêh ma gâp.$b$,false),
('bunong-vn','GEN',46,32,null,$b$Phung nây jêng phung rmăk biăp, yor lah khân păng rong ndrôk, biăp. Khân păng djôt jêh ndrel biăp jêh ri ndrôk khân păng, jêh ri lĕ rngôch ndơ khân păng geh.”$b$,false),
('bunong-vn','GEN',46,33,null,$b$Tơ lah Pharaôn kuăl khân may jêh ri lah: “Moh kan khân may ƀư?”$b$,false),
('bunong-vn','GEN',46,34,null,$b$Ăn khân may lah: “Phung oh mon may, hên nđâp ma phung che hên, rong ndrôk, biăp ntơm bah hên hôm dôl dal ndăm tât aƀaơ aơ! Gay ma khân may dơi gŭ tâm n'gor Gôsen; yor lah ăp nơm rmăk biăp jêng ndơ ƀơ̆ ma phung Êjipt.$b$,false),
('bunong-vn','GEN',47,1,null,$b$Y-Yôsep hăn mbơh ma Pharaôn, lah: “Mbơ̆ gâp jêh ri phung oh nâu gâp, ndrel ma biăp, ndrôk jêh ri lĕ rngôch ndơ khân păng geh tât jêh tă bơh n'gor Kanaan; jêh ri khân păng gŭ tâm n'gor Gôsen.”$b$,true),
('bunong-vn','GEN',47,2,null,$b$Păng sŏk prăm nuyh tâm phung oh nâu păng jêh ri njŭn ma Pharaôn,$b$,false),
('bunong-vn','GEN',47,3,null,$b$Pharaôn lah ma phung oh nâu păng: “Moh kan khân may ƀư?” Khân păng lah ma Pharaôn: “Hên phung n'hăk mƀuăl may, jêng phung rmăk biăp hên, nđâp phung che hên tâm ban lĕ.”$b$,false),
('bunong-vn','GEN',47,4,null,$b$Khân păng lah ma Pharaôn: “Hên tât gay gŭ ƀât lât tâm n'gor aơ; yor lah mâu hôm geh ôh gơ̆ nse ma biăp phung n'hăk mƀuăl, yor lah nau sa sât ji ngot rêh ni ngăn tâm n'gor Kanaan. Pô ri hên dăn ma may, ăn phung n'hăk mƀuăl may gŭ tâm n'gor Gôsen.$b$,false),
('bunong-vn','GEN',47,5,null,$b$Pharaôn lah ma Y-Yôsep: “Mbơ̆ may jêh ri phung oh nâu may tât jêh ma may.$b$,false),
('bunong-vn','GEN',47,6,null,$b$N'gor Êjipt gŭ ta năp may. Ăn mbơ̆ may jêh ri phung oh nâu may gŭ tâm ntŭk ueh lơn tâm n'gor aơ; ăn khân păng gŭ tâm n'gor Gôsen. Tơ lah may saơ tâm phung khân păng bunuyh njêh, ăn păng jêng kôranh ma mpô mpa gâp rong.”$b$,false),
('bunong-vn','GEN',47,7,null,$b$Y-Yôsep njŭn Y-Yakôb mbơ̆ păng ma Pharaôn: Y-Yakôb mât ton ma$b$,true),
('bunong-vn','GEN',47,8,null,$b$Pharaôn lah ma Y-Yakôb: “Ndŭm năm may geh?”$b$,false),
('bunong-vn','GEN',47,9,null,$b$Y-Yakôb lah ma Pharaôn: “Năm gâp gŭ tâm neh ntu aơ geh jêh du rhiăng pe jât năm. Năm gâp gŭ rêh djê̆ jêh ri mhĭk, jêh ri mâu tâm ban ôh đah năm mbơ̆ jêh ri phung che gâp gŭ rêh ta neh ntu aơ.”$b$,true),
('bunong-vn','GEN',47,10,null,$b$Y-Yakôb mât ton ma Pharaôn jêh ri hăn luh du tă bơh păng$b$,true),
('bunong-vn','GEN',47,11,null,$b$Y-Yôsep ăn ntŭk gŭ ma mbơ̆ păng jêh ri ma phung oh nâu păng ntŭk ueh lơn tâm n'gor Êjipt, tâm n'gor Ramêsê. Tĭng nâm Pharaôn ntăm jêh.$b$,false),
('bunong-vn','GEN',47,12,null,$b$Y-Yôsep siăm mbơ̆ păng, phung oh nâu păng jêh ri lĕ ngih mbơ̆ păng ma ndơ sông sa tĭng nâm rnoh khân păng.$b$,true),
('bunong-vn','GEN',47,13,null,$b$Mâu geh ôh ndơ sông sa tâm lĕ n'gor yor lah nau sa sât ji ngot rêh ni ngăn. N'gor Êjipt jêh ri n'gor Kanaan ntơm khĭt rvet jêh yor nau sa sât ji ngot.$b$,true),
('bunong-vn','GEN',47,14,null,$b$Y-Yôsep bun jêh lĕ prăk geh tâm n'gor Êjipt jêh ri n'gor Kanaan bu rvăt ba. Jêh ri Y-Yôsep njŭn prăk nây tâm ngih Pharaôn.$b$,false),
('bunong-vn','GEN',47,15,null,$b$Tơ lah dâk lĕ jêh prăk tâm n'gor Êjipt jêh ri n'gor Kanaan, lĕ rngôch phung Êjipt hăn ma Y-Yôsep, lah: “Ăn ndơ sông sa ma hên. Moh khlay hên khĭt ta năp may, yor lah lĕ jêh prăk hên?”$b$,false),
('bunong-vn','GEN',47,16,null,$b$Y-Yôsep lah: “Ăn ndrôk biăp khân may, tơ lah khân may mâu geh prăk ôh, jêh ri gâp mra ăn ndơ sông sa ma khân may rgâl đah ndrôk, biăp khân may.”$b$,true),
('bunong-vn','GEN',47,17,null,$b$Pô ri khân păng njŭn ndrôk, biăp khân păng ma Y-Yôsep; jêh ri Y-Yôsep ăn ndơ sông sa ma khân păng tâm rgâl ma seh, ma biăp, ma ndrôk, jêh ri seh bri. Y-Yôsep siăm khân păng năm nây tâm rgâl ma lĕ rngôch ndrôk, biăp khân păng.$b$,false),
('bunong-vn','GEN',47,18,null,$b$Tơ lah năm nây lĕ jêh, khân păng lŏ hăn ma Y-Yôsep năm tal bar, lah ma Y-Yôsep: “Hên mâu mra pôn ôh ma kôranh hên, prăk hên lĕ jêh, jêh ri ndrôk, biăp jêng ndơ kôranh hên jêh; hôm knŏng săk jăn jêh ri neh hên.$b$,false),
('bunong-vn','GEN',47,19,null,$b$Moh khlay hên khĭt ta năp măt may, hên jêh ri neh hên? Rvăt hom hên jêh ri neh hên ma ndơ sông sa, jêh ri hên nđâp neh hên mra jêng dĭk Pharaôn. Ăn ma hên rnih ntil gay ma hên dơi gŭ rêh mâu khĭt ôh, jêh ri lơi ăn bri neh jêng rngot ôh.”$b$,false),
('bunong-vn','GEN',47,20,null,$b$Pô ri Y-Yôsep rvăt lĕ rngôch neh n'gor Êjipt ma Pharaôn; yor lah lĕ rngôch phung Êjipt tăch mir khân păng yor lah nau sa sât ji ngot rêh ni ngăn, jêh ri neh jêng ndơ Pharaôn.$b$,true),
('bunong-vn','GEN',47,21,null,$b$Bi bunuyh ƀon lan, păng ăn khân ô băl jêng dĭk ntơm bơh du n'har bri êng.$b$,false),
('bunong-vn','GEN',47,22,null,$b$Knŏng neh phung kôranh ƀư brah păng mâu rvăt ôh, yor lah phung kôranh ƀư brah geh ndơ sông sa Pharaôn pă an ma khân păng. Pô ri khân păng mâu tăch ôh neh khân păng.$b$,false),
('bunong-vn','GEN',47,23,null,$b$Y-Yôsep lah ma phung ƀon lan. Aơ, nar aơ gâp rvăt jêh khân may jêh ri neh khân may ma Pharaôn. Aơ, gâp ăn ma khân may rnih ntil boh ba ăn khân may tuch păng.$b$,false),
('bunong-vn','GEN',47,24,null,$b$Tơ lah tât yăn kăch, khân may mra ăn du kô̆ tâm prăm ma Pharaôn, jêh ri khân may prăp puăn kô̆ jêng rnih ntil jêh ri ndơ khân may sông sa, phung ngih khân may jêh ri ma phung kon jê̆ khân may.”$b$,false),
('bunong-vn','GEN',47,25,null,$b$Khân ô băl lah: “May sâm rklaih jêh nau rêh hên. Tơ lah nau aơ ƀư maak ma may, hên mra jêng dĭk ma Pharaôn.”$b$,false),
('bunong-vn','GEN',47,26,null,$b$Y-Yôsep ăn nau vay nây ma neh n'gor Êjipt n'ho may hôm tât aƀaơ, ăn du kô̆ tâm prăm ma Pharaôn. Knŏng neh phung Kôranh ƀư brah mâu jêng ndơ Pharaôn ôh.$b$,true),
('bunong-vn','GEN',47,27,null,$b$Phung Israel gŭ tâm n'gor Êjipt ta n'gor Gôsen. Khân păng bun ndô ndơ ta nây, n'hao drăp ndơ, jêh ri ăn bĭk rơ̆ .$b$,true),
('bunong-vn','GEN',47,28,null,$b$Y-Yakôb gŭ tâm n'gor Êjipt jât ma pơh năm; pô ri lĕ rngôch năm Y-Yakôb gŭ rêh geh du rhiăng puăn jât ma pơh năm.$b$,false),
('bunong-vn','GEN',47,29,null,$b$Tơ lah nar Israel khĭt dăch jêh; păng kuăl kon bu klâu păng Y-Yôsep jêh ri lah: “Tơ lah gâp geh nau yô̆ ta năp măt may, dơm ti may tâm dâng tơm blu gâp jêh ri ton ƀư ma gâp ma nau răp jăp jêh ri nanê̆; lơi tâp ôh gâp tâm n'gor Êjipt.$b$,false),
('bunong-vn','GEN',47,30,null,$b$Ăn may tâp gâp ta ntŭk phung mbơ̆ gâp; njŭn leo săk jăn gâp bơh n'gor Êjipt jêh ri tâp gâp tâm môch phung mbơ̆ gâp.” Y-Yôsep lah: “Gâp mra ƀư tĭng nâm nau may ngơi.”$b$,false),
('bunong-vn','GEN',47,31,null,$b$Y-Yakôb lah: “Sơm ton ma gâp.” Y-Yôsep sơm ton ma păng; jêh ri Israel dop ta bôk sưng bêch.$b$,false),
('bunong-vn','GEN',48,1,null,$b$Jêh nau nây bu lah ma Y-Yôsep: “Aơ, mbơ̆ may ji.” Pô ri Y-Yôsep sŏk ndrel ma păng bar hê kon bu klâu păng Y-Manasê jêh ri Y-Êphraim.$b$,true),
('bunong-vn','GEN',48,2,null,$b$Bu mbơh ma Y-Yakôb: “Kon bu klâu may Y-Yôsep văch ta may.” Y-Israel srôih jêh ri dâk gŭ ta sưng bêch.$b$,false),
('bunong-vn','GEN',48,3,null,$b$Y-Yakôb lah ma Y-Yôsep: “Brah Ndu Nơm Geh Lĕ Nau Brah, tâm mpơl jêh ma gâp ta ƀon Lus tâm n'gor Kanaan, jêh ri păng mât ton ma gâp,$b$,false),
('bunong-vn','GEN',48,4,null,$b$Păng lah ma gâp: “Aơ, gâp mra ăn may jêng âk jêh ri bĭk rơ̆ . Gâp mra ăn may jêng du phung mpôl băl, jêh ri gâp mra n'gor aơ ma phung kon sau may kăndơ̆ jêng ndơ khân păng n'ho ro.$b$,false),
('bunong-vn','GEN',48,5,null,$b$Aƀaơ bar hê kon bu klâu bu deh ma may tâm n'gor Êjipt lor gâp tât ma may tâm n'gor Êjipt jêng kon gâp, Y-Êphraim jêh ri Y-Manasê mra jêng kon gâp tâm ban ma Y-Ruben jêh ri Y-Simêôn.$b$,true),
('bunong-vn','GEN',48,6,null,$b$Bi phung kon may geh bah kơi khân păng mra jêng kon may. Khân păng mra chih amoh khân păng tĭng nâm amoh phung oh nâu khân păng tâm ntŭk khân păng krâm dơn drăp.$b$,false),
('bunong-vn','GEN',48,7,null,$b$Tơ lah gâp văch bơh n'gor Padan H'Rachel khĭt ƀư rngot gâp tâm n'gor Kanaan rŏ trong. Tơ lah ăt hôm ngai đah ƀon Êphrata; jêh ri gâp tâp păng ta nây ta trong hăn ta ƀon Êphrata (jêng ƀon Ƀetlêhem).”$b$,false),
('bunong-vn','GEN',48,8,null,$b$Tơ Y-Israel saơ phung kon bu klâu Y-Yôsep, păng lah: “Mbu moh phung aơ?”$b$,false),
('bunong-vn','GEN',48,9,null,$b$Y-Yôsep lah ma mbơ̆ păng: “Khân păng jêng kon bu klâu gâp, Brah Ndu ăn jêh ma gâp ta aơ.” Y-Israel lah: “Ăn khân păng dăch gâp, gâp dăn ma may, gay ma gâp dơi mât ton ma khân păng.”$b$,false),
('bunong-vn','GEN',48,10,null,$b$Dôl nây măt Y-Israel ngo yor ranh, păng mâu hôm dơi saơ ôh. Y-Yôsep ăn kon păng hăn dăch Y-Israel. Păng chŭm jêh ri ut sau păng$b$,true),
('bunong-vn','GEN',48,11,null,$b$Y-Israel lah ma Y-Yôsep: “Gâp mâu mĭn ôh gâp dơi saơ muh măt may jêh ri aơ, Brah Ndu ăn gâp dơi saơ nđâp ma phung kon may.”$b$,false),
('bunong-vn','GEN',48,12,null,$b$Y-Yôsep sŏk lơi phung kon bu klâu păng bơh kô mât mbơ̆ păng, jêh ri dop kŭp măt ta neh.$b$,false),
('bunong-vn','GEN',48,13,null,$b$Y-Yôsep leo khân păng lĕ bar hê, dơm Y-Êphraim pa ma păng, pa chiau Israel; jêh ri dơm Y-Manasê pa chiau păng, pa ma Israel; jêh ri Y-Yôsep ăn khân păng hăn dăch Israel,$b$,false),
('bunong-vn','GEN',48,14,null,$b$Y-Israel yơr ti ma păng jêh ri pah ta bôk Y-Êphraim oh nse. Jêh ri păng pah ti chiau păng ta bôk Y-Manasê, tâm deh bôk rah.$b$,false),
('bunong-vn','GEN',48,15,null,$b$Păng mât ton ma Y-Yôsep jêh ri lah: “Brah Ndu, ta năp nơm nây che gâp Y-Abraham, jêh ri mbơ̆ gâp Y-Isăk hăn jêh; Brah Ndu nơm rong siăm gâp lĕ nau rêh gâp n'ho ma nar aơ.$b$,false),
('bunong-vn','GEN',48,16,null,$b$Tông mpăr ueh tâm chuai jêh gâp bơh lĕ nau mhĭk, ăn păng mât ton ma phung kon se aơ! Ăn may prăp tâm khân păng amoh gâp, jêh ri amoh che gâp Y-Abraham jêh ri mbơ̆ gâp Y-Isăk; jêh ri ăn khân păng jêng bĭk rơ̆ tâm nklang neh ntu.”$b$,true),
('bunong-vn','GEN',48,17,null,$b$Tơ lah Y-Yôsep saơ mbơ̆ păng pah ti ma ta bôk Y-Êphraim, păng mâu maak ôh; jêh ri păng kuăn ti mbơ̆ păng, gay ma tâm rgâl bơh bôk Y-Êphraim ma bôk Y-Manasê.$b$,true),
('bunong-vn','GEN',48,18,null,$b$Y-Yôsep lah ma mbơ̆ păng: “Mâu di pô nây ôh, ơ mbơ̆ gâp, yor lah păng aơ jêng kon bôk rah. Dơm ti ma may ta bôk păng.”$b$,true),
('bunong-vn','GEN',48,19,null,$b$Ƀiă lah mbơ̆ păng dun jêh ri lah: “Gâp gĭt nau nây, Ơ nâu, gâp gĭt nau nây! Păng tâm ban lĕ mra jêng du phung mpôl băl, jêh ri păng mra jêng toyh lĕ. Ƀiă lah oh păng mra jêng toyh lơn ma păng, jêh ri phung kon sau păng mra jêng âk phung mpôl băl bunuyh.”$b$,true),
('bunong-vn','GEN',48,20,null,$b$Pô ri Y-Israel mât ton ma khân păng nar nây jêh ri lah: “Ma amoh may phung Israel mra mât ton, lah: “Ăn Brah Ndu njêng may tâm ban ma Y-Êphraim jêh ri Y-Manasê.” Pô ri Păng kơp Y-Êphraim jêng lor lơn ma Y-Manasê.$b$,true),
('bunong-vn','GEN',48,21,null,$b$Israel lah ma Y-Yôsep: “Aơ, gâp ntơm khĭt ƀiă lah Brah Ndu gŭ ndrel ma khân may, jêh ri păng mra njŭn leo đŏng khân may sĭt ta n'gor phung mbơ̆ khân may.$b$,false),
('bunong-vn','GEN',48,22,null,$b$Jêh ri gâp ăn ma may du kô̆ âk lơn ma phung oh nâu may, du rplay yôk gâp sŏk tă bơh ti phung Amôrit ma đao gưm jêh ri na gâp.”$b$,true),
('bunong-vn','GEN',49,1,null,$b$Y-Yakôb kuăl phung kon bu klâu păng jêh ri lah: “Tâm rƀŭn hom khân may, gay ma gâp dơi mbơh ma khân may nau mra tât tâm rnôk kăndơ̆ .$b$,true),
('bunong-vn','GEN',49,2,null,$b$Tâm rƀŭn hom khân may, iăt hom, Ơ phung kon bu klâu Y-Yakôb rkêng hom tôr khân may ma Israel mbơ̆ khân may.$b$,true),
('bunong-vn','GEN',49,3,null,$b$Ơ Y-Ruben, may jêng kon bôk rah, nuih n'hâm ktang gâp, jêh ri play lor nau nđôr gâp, toyh lơn tâm nau yơk jêh ri tâm nau ktang.$b$,true),
('bunong-vn','GEN',49,4,null,$b$May jêng tâm ban ma dak rbuh, may mâu mra jêng toyh lơn ôh, yor lah may hăn lâng săk jêh ta sưng bêch mbơ̆ may, may ƀư ƀơ̆ jêh păng, may hăn lâng săk jêh ta sưng bêch gâp!$b$,true),
('bunong-vn','GEN',49,5,null,$b$Y-Simêôn jêh ri Y-Lêvi jêng oh nâu khân păng dŏng đao gưm ŭch ƀư nau ƀai.$b$,true),
('bunong-vn','GEN',49,6,null,$b$Ơ huêng gâp, lơi tâm rnglăp ôh đah phung khân păng, yor lah tâm nau khân păng ji nuih khân păng nkhĭt jêh bunuyh, tâm nau khân păng rjil, khân păng koh jêh jâng jon ndrôk.$b$,true),
('bunong-vn','GEN',49,7,null,$b$Rtăp rak lơi nau khân păng ji nuih, yor lah nau nây ƀai; rtăp rak lơi nau khân păng ji nuih, yor lah nau nây djơh! Gâp mra rlak khân păng tâm phung Y-Yakôb, jêh ri mprơh khân păng tâm phung Israel,$b$,true),
('bunong-vn','GEN',49,8,null,$b$Ơ Y-Yuđa, phung oh nâu may mra tâm rnê ma may; ti may mra ƀư ma trô ko phung rlăng may; phung kon bu klâu mbơ̆ may mra păn mbah ta năp may.$b$,false),
('bunong-vn','GEN',49,9,null,$b$Y-Yuđa jêng du huê yau mŭr; Ơ nâu, may hăn ncho jêh bơh ndơ may sa hêk. Păng păn păng rmơch nâm bu du mlâm yau mŭr, nâm bu du huê me yau mŭr, mbu janh rlay păng?$b$,true),
('bunong-vn','GEN',49,10,null,$b$Mâng hađăch mâu mra du bơh Y-Yuđa ôh, mâu lĕ mâng kanuăk chiă uănh du bơh ta nklang jâng păng, kŏ nơm jêng khư ma ndơ nây tât; jêh ri ma păng yơh phung ƀon lan mra tông bâr.$b$,true),
('bunong-vn','GEN',49,11,null,$b$Păng mra kât kon seh bri păng ta tơm play kriăk ƀâu, jêh ri kât kon seh bri păng ta n'gĭng tơm play kriăk ƀâu ueh lơn. Păng pih bok ao păng tâm dak play kriăk ƀâu, jêh ri pih ao mbâl păng tâm mham play kriăk ƀâu.$b$,true),
('bunong-vn','GEN',49,12,null,$b$Măt păng mra jêng chăng ma dak play kriăk ƀâu, jêh ri sêk păng mra nglang ma dak toh ndrôk.$b$,true),
('bunong-vn','GEN',49,13,null,$b$Y-Sabulôn mra gŭ ta kơh dak mƀŭt; păng mra jêng ntŭk âk mlâm kumpăn jưh, n'har neh păng mra tât dăch ƀon Sidôn.$b$,true),
('bunong-vn','GEN',49,14,null,$b$Y-Isakar jêng du mlâm seh bri ktang gŭ rmơch vah vang ndrung biăp.$b$,true),
('bunong-vn','GEN',49,15,null,$b$Păng saơ jêh ntŭk rlu ueh, jêh ri n'gor jêng ueh. Păng ƀư kuăt săng nglik păng gay anh ndơ jâk, jêh ri jêng dĭk pah kan nchâp.$b$,true),
('bunong-vn','GEN',49,16,null,$b$Dan mra phat dôih ma phung ƀon lan păng, tâm ban ma nguay tâm phung mpôl băl Israel.$b$,true),
('bunong-vn','GEN',49,17,null,$b$Y-Dan mra jêng du mlâm bêh njŏ trong, du mlâm bêh rmâng njŏ trong jê̆, chôk ndơl jâng seh, kŏ nơm ncho seh tŭp ta trong.$b$,true),
('bunong-vn','GEN',49,18,null,$b$Gâp gŭ kâp nau may tâm rklaih, Ơ Yêhôva.$b$,true),
('bunong-vn','GEN',49,19,null,$b$Phung sŏk pit mra ƀư ma Y-Gat, ƀiă lah păng lĕ mra sŏk pit tĭng phung nây.$b$,true),
('bunong-vn','GEN',49,20,null,$b$Y-Aser mra sa ndơ sông sa ueh, păng mra ăn ndơ sông sa ueh khư ma hađăch.$b$,true),
('bunong-vn','GEN',49,21,null,$b$Y-Naptali jêng du mlâm jun me klaih jêh, păng deh kon ueh.$b$,true),
('bunong-vn','GEN',49,22,null,$b$Y-Yôsep jêng du n'gĭng play âk, du mlâm n'gĭng play âk ta tu dak; n'gĭng păng mra rlau n'gar.$b$,true),
('bunong-vn','GEN',49,23,null,$b$Phung pănh na tâm lơh đah păng, rjăng hăr ma păng jêh ri ƀư mhĭk ma păng;$b$,true),
('bunong-vn','GEN',49,24,null,$b$Ƀiă lah na khân păng hôm e dăng, nting tur khân păng hôm nâp ma ti Nơm Brah Y-Yakôb, ma Amoh Rmăk Biăp, Lŭ phung Israel.$b$,false),
('bunong-vn','GEN',49,25,null,$b$Ma Brah Ndu mbơ̆ may, nơm kơl may, Ma Nơm Geh Lĕ Nau Brah, nơm ăn nau ueh uĭn ma may, nau ueh uĭn bơh trôk klơ nau ueh uĭn bơh dak jru tâm dâng, nau ueh uĭn bơh toh jêh ri ndŭl.$b$,true),
('bunong-vn','GEN',49,26,null,$b$Nau mât ton bơh mbơ̆ may jêng toyh lơn ma nau mât ton bơh yôk gŭ n'ho ro, play bơh mbon gŭ n'ho ro, mra gŭ ta klơ bôk nơm tâm nkhah jêh bơh phung oh nâu păng.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','GEN',49,27,null,$b$Y-Benjamin jêng du mlâm mpa so bri vay hêk sa, ta ôi păng sa mpa păng nhŭp, jêh ri ta mhaơ păng tâm pă ndơ păng pit.”$b$,true),
('bunong-vn','GEN',49,28,null,$b$Lĕ phung aơ jêng phung jât ma bar mpôl băl Israel; jêh ri pô nây nau mbơ̆ khân păng ngơi tơ lah păng mât ton ma phung nây. Păng ăn ma ăp nơm phung nây nau mât ton khư ma êng êng nơm.$b$,true),
('bunong-vn','GEN',49,29,null,$b$Y-Yakôb ntăm ma khân păng jêh ri lah: “Gâp mra khĭt, hăn gŭ ndrel ma phung che gâp. Tâp hom gâp ndrel ma phung che gâp tâm trôm yôk tâm mir Y-Êprôn bunuyh Hitit,$b$,true),
('bunong-vn','GEN',49,30,null,$b$tâm trôm yôk ta mir Makpêla, pa lơ Mamrê tâm n'gor Kanaan, ntŭk Y-Abraham rvăt jêh ndrel ma mir bơh Y-Êprôn bunuyh Hitit gay geh ntŭk môch.$b$,false),
('bunong-vn','GEN',49,31,null,$b$Ta nây bu tâp jêh Y-Abraham jêh ri H'Sara ur păng. Ta nây lĕ bu tâp jêh Y-Isăk jêh ri H'Rêbêka ur păng; jêh ri ta nây lĕ gâp tâp jêh H'Lêa.$b$,false),
('bunong-vn','GEN',49,32,null,$b$Mir jêh trôm yôk ta nây bu rvăt jêh bơh phung Hitit.”$b$,true),
('bunong-vn','GEN',49,33,null,$b$Tơ lah lôch Y-Yakôb ntăm ma phung kon bu klâu păng, păng plơ̆ lâng săk ta sưng bêch, jêh ri tăch n'hâm, jêh ri hăn gŭ ndrel ma phung che păng.$b$,true),
('bunong-vn','GEN',50,1,null,$b$Y-Yôsep ut ta muh măt mbơ̆ păng, nhĭm, jêh ri chŭm$b$,true),
('bunong-vn','GEN',50,2,null,$b$Y-Yôsep ntăm ma phung Kôranh dak si oh mon păng nkra săk jăn mbơ̆ păng ma nau tâp; pô ri phung Kôranh dak si nkra săk jăn Israel.$b$,false),
('bunong-vn','GEN',50,3,null,$b$Puăn jât nar khân păng gŭ ƀư nau nây, yor lah dŭm nây yơh nar prăp nkra săk jăn ma nau tâp. Phung Êjipt nhĭm ma păng dôl tâm pơh jât nar.$b$,false),
('bunong-vn','GEN',50,4,null,$b$Tơ lah nar rngot ndrê ma păng lĕ jêh, Y-Yôsep ngơi ma ngih Pharaôn pô aơ: “Tơ lah gâp geh nau yô̆ jêh ta năp phung khân may, gâp dăn ma khân may ngơi an ma Pharaôn, lah,$b$,true),
('bunong-vn','GEN',50,5,null,$b$Mbơ̆ gâp ăn gâp sơm ton, lah: “Gâp mra khĭt, ăn may tâp gâp tâm môch gâp trah jêh tâm n'gor Kanaan.” Pô ri, aƀaơ, ăn gâp hăn tâp mbơ̆ gâp, gâp dăn ma may; jêh ri gâp mra lŏ văch.”$b$,false),
('bunong-vn','GEN',50,6,null,$b$Pharaôn lah: “Hăn hom, tâp mbơ̆ may tĭng nâm nau păng ăn may sơm ton jêh.”$b$,false),
('bunong-vn','GEN',50,7,null,$b$Pô ri Y-Yôsep hăn tâp mbơ̆ păng. Lĕ rngôch phung oh mon Pharaôn hăn ndrel ma păng, jêh ri lĕ rngôch phung bu ranh ngih păng, jêh ri lĕ rngôch phung bu bŭnh bu ranh tâm n'gor Êjipt.$b$,false),
('bunong-vn','GEN',50,8,null,$b$Lĕ phung ngih Y-Yôsep, phung oh nây păng jêh ri phung ngih mbơ̆ păng. Khân păng lơi tâm n'gor Gôsen knŏng phung kon se jê̆ khân păng, biăp jêh ri ndrôk khân păng.$b$,false),
('bunong-vn','GEN',50,9,null,$b$Geh âk ndeh seh jêh ri phung rmăk seh hăn ndrel ma păng lĕ. Khân păng jêng du phung âk ngăn.$b$,true),
('bunong-vn','GEN',50,10,null,$b$Tơ lah khân păng tât ta ntŭk bu mprah ba ta Atal kơh tĕ dak krong Yurdan ta nây khân păng nhĭm nhhiăng ma nau rngot toyh. Y-Yôsep ăn bu rngot ndrê ma mbơ̆ păng pơh nar.$b$,false),
('bunong-vn','GEN',50,11,null,$b$Tơ lah phung ƀon lan tâm n'gor nây, phung Kanaan, saơ nau rngot ndrê nây tâm ntŭk mprah ba ta Atat, khân păng lah: “Nau aơ jêng nau rngot ndrê toyh ma phung Êjipt.” Yor nây bu rnha ntŭk nây Abel Misram, ntŭk nây kơh tĕ dak krong Yurdan.$b$,false),
('bunong-vn','GEN',50,12,null,$b$Pô ri phung kon bu klâu Y-Yakôb ƀư ma păng tĭng nâm nau păng ntăm jêh.$b$,false),
('bunong-vn','GEN',50,13,null,$b$Phung kon bu klâu păng rdeng njŭn păng ta n'gor Kanaan, jêh ri tâp păng tâm trôm yôk ta mir Makpêla pa lơ Mamrê, Y-Abraham rvăt jêh ndrel ma mir bơh Êprôn bunuyh Hitit, jêng ntŭk môch.$b$,false),
('bunong-vn','GEN',50,14,null,$b$Jêh Y-Yôsep tâp mbơ̆ păng, păng plơ̆ sĭt ta n'gor Êjipt ndrel ma phung oh nâu păng jêh ri lĕ rngôch bunuyh hăn ndrel ma păng gay tâp mbơ̆ păng.$b$,true),
('bunong-vn','GEN',50,15,null,$b$Tơ lah phung oh nây Y-Yôsep saơ mbơ̆ păng khĭt jêh, khân păng lah: “Klăp lah Y-Yôsep mra tâm rmot ma he jêh ri mra mplơ̆ ma he lĕ nau mhĭk he ƀư jêh ma păng.”$b$,true),
('bunong-vn','GEN',50,16,null,$b$Pô ri khân păng njuăl ăn bu hăn lah ma Y-Yôsep: “Mbơ̆ may ntăm jêh pô aơ lor ma păng khĭt:$b$,false),
('bunong-vn','GEN',50,17,null,$b$‘Lah hom ma Y-Yôsep, gâp dăn ma may yô̆ an ma phung oh nâu may rlau nau vay jêh ri nau khân păng tih, yor nau ƀai khân păng ƀư jêh ma may.’ Aƀaơ hên dăn ma may yô̆ an nau phung oh mon Brah Ndu mbơ̆ may rlau nau vay.” Tơ lah tăng nau ngơi nây Y-Yôsep nhĭm.$b$,false),
('bunong-vn','GEN',50,18,null,$b$Phung oh nâu păng păn ta năp păng jêh ri lah: “Aơ, hên jêng oh mon may.”$b$,false),
('bunong-vn','GEN',50,19,null,$b$Ƀiă lah Y-Yôsep lah ma khân păng: “Lơi klach ôh, yor lah di lĕ gâp jêng Brah Ndu?$b$,false),
('bunong-vn','GEN',50,20,null,$b$Bi khân may, khân may mĭn ƀư ƀai ma gâp; ƀiă lah Brah Ndu ăn nau nây jêng ueh, gay ma tâm rklaih nau rêh âk bunuyh nâm bu tât jêh nar aơ.$b$,false),
('bunong-vn','GEN',50,21,null,$b$Pô ri lơi klach ôh. Gâp mra siăm khân may jêh ri phung kon jê̆ khân may.” Pô ri păng bonh leng phung oh nâu păng jêh ri ngơi nau ueh ma phung oh nâu păng.$b$,false),
('bunong-vn','GEN',50,22,null,$b$Y-Yôsep gŭ tâm n'gor Êjipt, păng jêh ri ngih mbơ̆ păng. Y-Yôsep gŭ rêh du rhiăng jât năm.$b$,true),
('bunong-vn','GEN',50,23,null,$b$Y-Yôsep saơ phung kon Y-Êphraim tât ta rnôk tal pe. Phung kon Makir lĕ, kon bu klâu Y-Manasê. Y-Yôsep chông ta kômâk păng.$b$,false),
('bunong-vn','GEN',50,24,null,$b$Y-Yôsep lah ma phung oh nâu păng: “Gâp mra ntơm khĭt, bunuyh Brah Ndu mra tâm khâl đah khân may, jêh ri păng mra njŭn leo khân may luh bơh n'gor aơ ma n'gor păng sơm ton jêh ma Y-Abraham ma Y-Isăk jêh ri ma Y-Yakôb.”$b$,true),
('bunong-vn','GEN',50,25,null,$b$Y-Yôsep ăn phung kon Israel sơm ton, lah: “Brah Ndu mra tâm khâl đah khân may, jêh ri ăn khân may rdeng nting gâp bơh aơ.”$b$,false),
('bunong-vn','GEN',50,26,null,$b$Jêh ri Y-Yôsep khĭt tơ lah păng geh du rhiăng jât năm. Bu nkra săk jăn păng ma nau tâp, jêh ri njor păng tâm bong tâm n'gor Êjipt.$b$,false);
