('bunong-vn','EXO',1,1,null,$b$Aơ jêng amoh phung kon bu klâu Y-Israel tât ta n'gor Êjipt ndrel ma Y-Yakôb, ăp nơm jêh ri ndŭl mpôl păng:$b$,true),
