('bunong-vn','EXO',1,3,null,$b$Y-Isakar, Y-Sabulôn, Y-Benjamin,$b$,false),
('bunong-vn','EXO',1,4,null,$b$Y-Dan, Y-Naptali, Y-Gat jêh ri Y-Aser.$b$,false),
('bunong-vn','EXO',1,5,null,$b$Lĕ ndŭl mpôl geh pơh jât nuyh; Y-Yôsep gŭ jêh tâm n'gor Êjipt,$b$,false),
('bunong-vn','EXO',1,6,null,$b$Y-Yôsep khĭt, nđâp lĕ rngôch phung oh nâu păng, jêh ri lĕ rngôch bunuyh rnôk nây tâm ban lĕ.$b$,false),
('bunong-vn','EXO',1,7,null,$b$Ƀiă lah phung kon sau Y-Israel deh âk kon, jêng bĭk rơ̆ , hao lơn, jêh ri jêng ktang lơn ƀa ƀơ, jêh ri n'gor nây bêng ma khân păng.$b$,false),
('bunong-vn','EXO',1,8,null,$b$Geh tay du huê hađăch mhe chiă uănh n'gor Êjipt. Păng mâu mâp năl Y-Yôsep ôh.$b$,true),
('bunong-vn','EXO',1,9,null,$b$Păng lah ma phung ƀon lan păng. Aơ, phung ƀon lan Israel jêng âk lơn jêh ri ktang lơn ma he.$b$,true),
('bunong-vn','EXO',1,10,null,$b$Kay lŏng he, ăn he ƀư ma nau blau mĭn đah khân păng, klach lah khân păng bĭk rơ̆ , jêh ri tơ lah tât nau tâm lơh, khân păng tâm rnglăp đah phung rlăng he gay tâm lơh đah he jêh ri du luh bơh n'gor.$b$,false),
('bunong-vn','EXO',1,11,null,$b$Pô ri bu dơm phung kôranh kan chiă khân păng, gay ma rêh ni khân păng ma kan jâk. Khân păng ƀư ƀon jay ma Pharaôn, ƀon Pithôm, jêh ri ƀon Ramase.$b$,false),
('bunong-vn','EXO',1,12,null,$b$Ƀiă lah lơ hô bu ƀư rêh ni khân păng, lơ hô khân păng bĭk rơ̆ jêh ri lam n'gor. Jêh ri phung Êjipt klach ma phung ƀon lan Israel.$b$,true),
('bunong-vn','EXO',1,13,null,$b$Pô ri phung Êjipt ăn phung ƀon lan Israel pah kan ŏk ngăn.$b$,false),
('bunong-vn','EXO',1,14,null,$b$Khân păng ƀư rngot ƀon lan Israel ma nau ŏk pah kan ma neh bŏk pêt, neh uk, jêh ri ăp ntil kan tâm mir. Lĕ kan bu ăn khân păng ƀư ma nau ŏk ngăn.$b$,false),
('bunong-vn','EXO',1,15,null,$b$Hađăch n'gor Êjipt ngơi ma phung bu ur djôt ndŭl Hêbrơ, amoh du huê H'Sipra jêh ri amoh nơm êng H'Puah.$b$,true),
('bunong-vn','EXO',1,16,null,$b$Păng lah: “Tơ lah khân ay djôt ndŭl phung bu ur Hêbrơ, jêh ri saơ khân păng dăch deh, tơ lah jêng bu klâu, nkhĭt lơi păng; tơ lah bu ur, rong păng ăn rêh.$b$,false),
('bunong-vn','EXO',1,17,null,$b$Ƀiă lah phung bu ur djôt ndŭl klach yơk ma Brah Ndu, jêh ri mâu ƀư ôh tĭng nâm nau hađăch Êjipt ntăm ma khân păng; khân păng om phung kon bu klâu ăn rêh.$b$,false),
('bunong-vn','EXO',1,18,null,$b$Pô ri hađăch Êjipt kuăl phung bu ur djôt ndŭl jêh ri lah ma khân păng: “Mâm ƀư khân ay ƀư pô nây, om phung kon bu klâu hôm rêh?”$b$,false),
('bunong-vn','EXO',1,19,null,$b$Phung bu ur djôt ndŭl lah ma Pharaôn: “Yor lah phung bu ur Hêbrơ mâu jêng nâm bu phung bu ur Êjipt ôh; khân păng jêng ktang jêh ri deh lor ma bu ur djôt ndŭl tât.”$b$,false),
('bunong-vn','EXO',1,20,null,$b$Jêh ri Brah Ndu ƀư ueh ma phung bu ur djôt ndŭl; jêh ri phung ƀon lan jêng bĭk rơ̆ jêh ri ktang ngăn.$b$,false),
('bunong-vn','EXO',1,21,null,$b$Yor lah phung bu ur djôt ndŭl klach yơk mbah ma Brah Ndu, pô ri Brah Ndu ăn ma khân păng ndŭl mpôl khân păng nơm.$b$,false),
('bunong-vn','EXO',1,22,null,$b$Pharaôn ntăm ma lĕ rngôch phung ƀon lan păng: “Ăn khân may klŭp tâm dak krong ăp nơm kon bu klâu phung Hêbrơ mra deh, ƀiă lah ăn ăp nơm kon bu ur om rêh.”$b$,false),
('bunong-vn','EXO',2,1,null,$b$Du huê bu klâu phung Lêvi sŏk ur du huê kon bu ur phung Lêvi.$b$,true),
('bunong-vn','EXO',2,2,null,$b$Bu ur nây ntreo jêh ri deh ma du huê kon bu klâu. Bu saơ păng jêng ueh, jêh ri pôn păng pe khay.$b$,false),
('bunong-vn','EXO',2,3,null,$b$Tơ lah păng mâu hôm dơi pôn, păng sŏk du mlâm bĭ ƀư ma mhĭng ma dak ƀlĭt bitumen jêh ri ma chai. Păng lâng kon se nây tâm bĭ jêh ri dơm bĭ nây tâm nklang rpho ta kơh dak krong.$b$,false),
('bunong-vn','EXO',2,4,null,$b$Yuh kon se gŭ ngai djê̆ gay ma gĭt moh nau mra tât ma kon se nây.$b$,false),
('bunong-vn','EXO',2,5,null,$b$Kon bu ur Pharaôn hăn ta dak krong, gay ma ŭm, jêh ri phung bu ur băl păng nsong rŏ kơh dak krong. Păng saơ bĭ tâm nklang rpho, jêh ri njuăl hăn du huê oh mon bu ur păng hăn sŏk ô băl.$b$,false),
('bunong-vn','EXO',2,6,null,$b$Tơ lah păng pơk bĭ păng saơ kon se; jêh ri aơ, kon se nhĭm. Păng geh nau yô̆ ma ô băl jêh ri lah: “Păng jêng du huê phung kon Hêbrơ.”$b$,false),
('bunong-vn','EXO',2,7,null,$b$Pô ri yuh kon se nây lah ma kon bu ur Pharaôn: “Ay ŭch lĕ gâp hăn kuăl du huê nơm rong tâm phung Hêbrơ, gay ma pu păng?”$b$,true),
('bunong-vn','EXO',2,8,null,$b$Kon bu ur Pharaôn plơ̆ lah ma păng: “Hăn hom,” pô ri bu ur druh nây hăn kuăl me kon se nây.$b$,false),
('bunong-vn','EXO',2,9,null,$b$Kon bu klâu Pharaôn lah ma păng: “Sŏk hom kon aơ jêh ri pu păng ma gâp. Gâp mra nkhôm ay.” Pô ri bu ur nây sŏk kon se jêh ri pu.$b$,false),
('bunong-vn','EXO',2,10,null,$b$Kon se nây văch ma toyh, jêh ri păng njŭn kon se nây ma kon bu ur Pharaôn, jêh ri păng jêng kon bu klâu ma kon bu ur Pharaôn. Păng tâm amoh Y-Môis, yor lah păng lah: “Gâp yơk jêh păng tă bơh dak.”$b$,false),
('bunong-vn','EXO',2,11,null,$b$Du nar tơ lah Y-Môis toyh jêh, păng hăn ta phung ƀon lan păng jêh ri saơ kan ŏk ngăn khân păng ƀư. Păng saơ du huê Êjipt dong du huê Hêbrơ, du huê tâm phung ƀon lan păng.$b$,true),
('bunong-vn','EXO',2,12,null,$b$Păng uănh ta aơ, ta ri jêh ri mâu saơ du huê bunuyh ôh. Jêh ri păng nkhĭt nơm Êjipt nây, jêh ri brôi pôn tâm choih.$b$,false),
('bunong-vn','EXO',2,13,null,$b$Păng luh đŏng nar ôi taơ, jêh ri aơ, bar hê Hêbrơ dôl tâm nhăt. Păng lah ma nơm tih: “Mâm ƀư may dong băl nơm?”$b$,false),
('bunong-vn','EXO',2,14,null,$b$Bunuyh nây plơ̆ lah: “Mbu ăn may jêng kôranh jêh ri phat dôih hên?” May mĭn nkhĭt gâp tâm ban ma may nkhĭt jêh du huê Êjipt nây lĕ?” Jêh ri Y-Môis klach jêh ri lah: “Nanê̆, bu gĭt jêh nau nây.”$b$,true),
('bunong-vn','EXO',2,15,null,$b$Tơ lah Pharaôn tăng nau nây, păng joi ŭch nkhĭt Y-Môis. Ƀiă lah Y-Môis du bơh Pharaôn jêh ri gŭ tâm n'gor Madian. Ta nây păng gŭ ta du mlâm ntu dak.$b$,true),
('bunong-vn','EXO',2,16,null,$b$Kôranh ƀư brah Madian geh pơh nuyh kon bu ur. Khân păng hăn bâk dak jêh ri mbêng mbong dak gay ma ăn biăp mbơ̆ khân păng nhêt.$b$,false),
('bunong-vn','EXO',2,17,null,$b$Phung rmăk biăp tât jêh ri nsot lơi khân păng. Ƀiă lah Y-Môis dâk gay ma n'gang khân păng jêh ri ăn biăp khân păng nhêt.$b$,true),
('bunong-vn','EXO',2,18,null,$b$Tơ lah khân păng plơ̆ sĭt ta Rênel mbơ̆ khân păng, păng lah: “Mâm ƀư khân ay sĭt ơm nar aơ?”$b$,true),
('bunong-vn','EXO',2,19,null,$b$Khân păng plơ̆ lah: “Du huê Êjipt sâm nklaih hên bơh ti phung rmăk biăp jêh ri nđâp ma păng kơl bâk an dak hên jêh ri ăn biăp hên nhêt.”$b$,false),
('bunong-vn','EXO',2,20,null,$b$Păng lah ma phung kon bu ur păng: “Mbah bu klâu nây? Mâm ƀư khân ay cha lat păng? Kuăl păng, ăn păng sông sa.”$b$,true),
('bunong-vn','EXO',2,21,null,$b$Y-Môis maak gŭ tâm ngih bunuyh nây, păng ăn Y-Môis gŭ ur sai đah kon bu ur păng H'Sêpôra.$b$,true),
('bunong-vn','EXO',2,22,null,$b$H'Sêpôra deh ma du huê kon bu klâu, jêh ri Y-Môis amoh kon păng Gêrsom; yor lah păng lah: “Gâp jêng jêh du huê gŭ jưh ƀât tâm n'gor bu năch.”$b$,false),
('bunong-vn','EXO',2,23,null,$b$Jŏ pa kơi nây hađăch Êjipt khĭt. Jêh ri phung ƀon lan Israel nter gay geh nau kơl, jêh ri Brah Ndu tăng nau khân păng nter nđêng yor nau jêng dĭk.$b$,true),
('bunong-vn','EXO',2,24,null,$b$Brah Ndu tăng nau khân păng nđêng nhhiăng jêh ri Brah Ndu kah gĭt nau păng tâm rnglăp đah Y-Abraham, Y-Isăk jêh ri Y-Yakôb.$b$,false),
('bunong-vn','EXO',2,25,null,$b$Brah Ndu saơ phung ƀon lan Israel, jêh ri Brah Ndu gĭt nau khân păng.$b$,false),
('bunong-vn','EXO',3,1,null,$b$Y-Môis chiă biăp po păng Y-Jêtrô, Kôranh ƀư brah Midian, jêh ri păng njŭn biăp pa dâng bri rdah jêh ri tât ta Yôk Brah Ndu, yôk Hôrep.$b$,true),
('bunong-vn','EXO',3,2,null,$b$Tông mpăr ueh Yêhôva tâm mpơl ma păng tâm mpiăt ŭnh ta nklang du ntŭk pôm. Y-Môis gŭ uănh, jêh ri aơ, pôm hit ŭnh, ƀiă lah ŭnh mâu sa pôm ôh.$b$,false),
('bunong-vn','EXO',3,3,null,$b$Y-Môis lah: “Gâp mra teng veh uănh nau khlay aơ, mâm ƀư ŭnh mâu sa ôh pôm.”$b$,false),
('bunong-vn','EXO',3,4,null,$b$Tơ lah Yêhôva saơ păng veh ŭch uănh, pô ri Brah Ndu kuăl păng bơh pôm jêh ri lah: “Ơ Y-Môis ơi, Y-Môis ơi” Jêh ri păng plơ̆ lah: “Aơ ta aơ gâp.”$b$,true),
('bunong-vn','EXO',3,5,null,$b$Brah Ndu lah: “Lơi văch êp ta aơ ôh, doh lơi ntâu jot may, yor lah ntŭk may gŭ râng nây jêng neh kloh ueh prăp ma Brah Ndu”.$b$,false),
('bunong-vn','EXO',3,6,null,$b$Jêh ri păng lah: “Gâp jêng Brah Ndu mbơ̆ may, Brah Ndu Y-Abraham, Brah Ndu Y-Isăk, jêh ri Brah Ndu Y-Yakôb,” Y-Môis pôn muh măt păng, yor lah păng klach uănh ma Brah Ndu.$b$,false),
('bunong-vn','EXO',3,7,null,$b$Yêhôva lah: “Gâp saơ jêh nau rêh ni phung ƀon lan gâp tâm n'gor Êjipt, jêh ri gâp tăng jêh nau khân păng nđêng nter yor phung kôranh kan khân păng; gâp gĭt năl nau rêh ni khân păng,$b$,true),
('bunong-vn','EXO',3,8,null,$b$jêh ri gâp jŭr gay ma tâm rklaih khân păng bơh ti Êjipt, jêh ri njŭn leo khân păng luh bơh n'gor nây, hăn hao tâm n'gor ueh jêh ri toyh, ta n'gor geh ndơ sông sa nhêt rmeh ler, ta ntŭk phung Kanaan, phung Hitit, phung Amôrit, phung Pêrisit, phung Hêvit jêh ri phung Jêbusit.$b$,false),
('bunong-vn','EXO',3,9,null,$b$Aơ, nau phung Israel nter nđêng hao tât ta gâp jêh, nđâp gâp saơ lĕ nau phung Êjipt ƀư rêh ni ma khân păng.$b$,true),
('bunong-vn','EXO',3,10,null,$b$Văch hom, gâp mra njuăl may hăn ta Pharaôn gay ma may dơi ăn phung ƀon lan gâp, phung kon Israel, luh bơh n'gor Êjipt.”$b$,false),
('bunong-vn','EXO',3,11,null,$b$Ƀiă lah Y-Môis lah ma Brah Ndu: “Mbu gâp jêng kŏ ăn gâp hăn ta Pharaôn, jêh ri njŭn leo phung kon Israel, du luh tă bơh n'gor Êjipt.”$b$,false),
('bunong-vn','EXO',3,12,null,$b$Brah Ndu lah: “Gâp mra gŭ ndrel ma may, jêh ri aơ nau tâm mbên ma may, gâp jêng nơm njuăl may hăn; jêh may njŭn leo phung ƀon lan luh bơh n'gor Êjipt, khân may mra pah kan ma Brah Ndu ta klơ yôk aơ.”$b$,false),
('bunong-vn','EXO',3,13,null,$b$Y-Môis lah ma Brah Ndu: “Tơ lah gâp tât ta phung kon Israel jêh ri lah ma khân păng: ‘Brah Ndu phung che khân may njuăl gâp văch ta khân may’, jêh ri tơ lah khân păng ôp gâp: ‘Mbu amoh păng?’ Moh gâp mra lah ma khân păng?”$b$,true),
('bunong-vn','EXO',3,14,null,$b$Brah Ndu lah ma Y-Môis: “Gâp JÊNG NƠM GEH LOR JÊH RI N’HO RO.” Jêh ri păng lah: “Ăn may lah pô aơ ma phung ƀon lan Israel, ‘JÊNG NƠM GEH LOR njuăl gâp văch ma khân may.’ ”$b$,false),
('bunong-vn','EXO',3,15,null,$b$Brah Ndu lah tay ma Y-Môis: “Ăn may ngơi ma phung ƀon lan Israel pô aơ, ‘Yêhôva, Brah Ndu phung che khân may, ri Brah Ndu Y-Yakôb, njuăl gâp văch ma khân may.’ Aơ yơh amoh gâp n'ho ro, aơ yơh bu mra kah gĭt ma gâp tâm lĕ rngôch rnôk.$b$,false),
('bunong-vn','EXO',3,16,null,$b$Hăn tâm rƀŭn hom phung bu bŭnh bu ranh phung Israel jêh ri lah ma khân păng. “Yêhôva, Brah Ndu phung che khân may, Brah Ndu Y-Abraham, Y-Isăk, jêh ri Y-Yakôb tâm mpơl jêh ma gâp, lah: “Gâp saơ jêh khân may, jêh ri nau bu ƀư ma khân may tâm n'gor Êjipt.$b$,false),
('bunong-vn','EXO',3,17,null,$b$Jêh ri gâp ton, gâp mra ngluh khân may bơh nau rêh ni tâm n'gor Êjipt, hăn ta n'gor phung Kanaan, phung Hitit, phung Amôrit, phung Pêrisit, phung Hêvit jêh ri phung Jêbusit, du rplay n'gor geh ndơ sông sa nhêt rmeh rmai.”$b$,false),
('bunong-vn','EXO',3,18,null,$b$Khân păng mra iăt bâr may; jêh ri ăn may hăn ndrel ma phung bu bŭnh bu ranh phung Israel ma hađăch n'gor Êjipt jêh ri lah ma păng: ‘Yêhôva Brah Ndu phung Hêbrơ, tâm mâp jêh đah hên. Aƀaơ, hên dăn ma may, ăn hên hăn pe nar hăn tâm ndrêch rdah gay ma hên dơi nhhơr ndơ ƀư brah ma Yêhôva, Brah Ndu hên.’$b$,true),
('bunong-vn','EXO',3,19,null,$b$Gâp gĭt hađăch Êjipt mâu mra ăn khân may hăn ôh tơ lah bu mâu ƀư ma du ma du mlâm ti brah.$b$,false),
('bunong-vn','EXO',3,20,null,$b$Jêh ri gâp mra yơr ti gâp jêh ri dong n'gor Êjipt ma ăp ntil nau khlay gâp mra ƀư ta nklang n'gor nây. Jêh nau nây păng mra ăn khân may hăn.$b$,false),
('bunong-vn','EXO',3,21,null,$b$Gâp mra ăn phung ƀon lan aơ geh nau yô̆ ta năp phung Êjipt; jêh ri tơ lah khân may hăn, khân may mâu mra hăn ti hŏng ôh.$b$,false),
('bunong-vn','EXO',3,22,null,$b$Ăp nơm bu ur dăn ma bu ur chiau meng păng jêh ri ma phung bu ur gŭ tâm ngih păng ndơ khlay, prăk, mah jêh ri bok ao. Khân may mra sâm nsoh phung kon bu klâu jêh ri phung kon bu ur khân may; pô ri mơ khân may pit sŏk drăp ndơ phung Êjipt.”$b$,false),
('bunong-vn','EXO',4,1,null,$b$Y-Môis plơ̆ lah: “Ƀiă lah aơ, khân păng mâu mra chroh ma gâp ôh, mâu lĕ khân păng iăt nau gâp, yor lah khân păng mra lah: ‘Yêhôva mâu mâp tâm mpơl ma may ôh.”$b$,true),
('bunong-vn','EXO',4,2,null,$b$Yêhôva lah ma păng: “Moh may geh tâm ti may?” Păng lah: “Du mlâm mâng”.$b$,false),
('bunong-vn','EXO',4,3,null,$b$Yêhôva lah: “Mƀăr lơi mâng ta neh.” Pô ri păng mƀăr mâng ta neh, jêh ri mâng nây nkhơng ma jêng du mlâm bêh. Y-Môis du ta năp păng.$b$,false),
('bunong-vn','EXO',4,4,null,$b$Yêhôva lah ma Y-Môis: “Yơr ti may jêh ri nhŭp bêh ta chiăng.” Pô ri păng yơr ti nhŭp bêh, jêh ri bêh plơ̆ jêng mâng tâm ti păng:$b$,false),
('bunong-vn','EXO',4,5,null,$b$“Nau nây gay ma khân păng chroh ma gâp Yêhôva, Brah Ndu Y-Abraham, Brah Ndu Y-Isăk, jêh ri Brah Ndu Y-Yakôb tâm mpơl jêh ma may.”$b$,false),
('bunong-vn','EXO',4,6,null,$b$Yêhôva plơ̆ lah ma păng: “Dơm ti may ta ntang ntơh may.” Păng dơm ti păng tâm ntang ntơh păng; jêh ri tơ lah păng tŏk, aơ ti păng geh phŭng, nglang nâm bu pler.$b$,true),
('bunong-vn','EXO',4,7,null,$b$Yêhôva lah: “Plơ̆ dơm ti may tâm ntang ntơh may.” Pô ri păng plơ̆ dơm ti păng tâm ntang ntơh păng; jêh ri tơ lah păng tŏk tă bơh nây, aơ păng plơ̆ jêng nâm bu nglay săk păng nơm.$b$,true),
('bunong-vn','EXO',4,8,null,$b$Brah Ndu lah: “Tơ lah khân păng mâu chroh ôh ma may, mâu ŭch chroh ma nau tâm mbên lor, klăp lah khân păng mra chroh ma nau tâm mbên tal bar aơ.$b$,false),
('bunong-vn','EXO',4,9,null,$b$Tơ lah mâu chroh ôh ma lĕ bar ntil nau mbên nây, mâu lĕ păng iăt nau may, ăn may sŏk dak bơh dak krong jêh ri nkhŭt ta neh sơh; jêh ri dak may sŏk jêh bơh dak krong nây mra jêng mham ta neh sơh.”$b$,false),
('bunong-vn','EXO',4,10,null,$b$Ƀiă lah Y-Môis lah ma Yêhôva: “Ơ Kôranh Brah gâp mâu jêng du huê bunuyh ngơi ueh ôh mâu lĕ di nglĕ lor ma nau may ngơi ma tông mpăr may, yor lah mbung gâp jêh ri mpiăt gâp ngơi mbrơi.”$b$,true),
('bunong-vn','EXO',4,11,null,$b$Yêhôva lah ma păng: “Mbu nâm njêng trôm mbung bunuyh? Jêh ri mbu ăn bunuyh jêng mlo, mâu lah tĭk, dơi saơ mâu lah chieh măt? Mâu hĕ gâp jêng, Yêhôva?$b$,false),
('bunong-vn','EXO',4,12,null,$b$Pô ri hăn hom gâp mra gŭ ndrel ma trôm mbung may, jêh ri gâp mra sâm nti may moh nau may mra ngơi.”$b$,false),
('bunong-vn','EXO',4,13,null,$b$Ƀiă lah Y-Môis lah: “Ơ kôranh Brah gâp dăn ma may, njuăl hom nơm êng hăn.”$b$,false),
('bunong-vn','EXO',4,14,null,$b$Pô ri Yêhôva hao nuih ji nuih ma Y-Môis jêh ri păng lah, Mâu di hĕ geh Y-Arôn nâu may, du huê Lêvi? Gâp gĭt păng dơi ngơi ueh. Aơ, păng văch gay tâm mâp đah may, jêh ri tơ lah păng saơ may păng mra geh nau maak tâm nuih n'hâm păng.$b$,true),
('bunong-vn','EXO',4,15,null,$b$Ăn may ngơi ma păng jêh ri dơm rplay ngơi tâm trôm mbung păng jêh ri gâp mra gŭ ndrel ma trôm mbung may jêh ri trôm mbung păng jêh ri gâp mra nti may moh nau may mra ƀư.$b$,false),
('bunong-vn','EXO',4,16,null,$b$Păng mra ngơi ma phung ƀon lan nsro ntŭk may; păng mra jêng trôm mbung ma may, jêh ri may mra jêng nâm bu Brah Ndu păng.$b$,false),
('bunong-vn','EXO',4,17,null,$b$Ăn may djôt leo mâng aơ. Ma mâng aơ may mra ƀư lĕ nau tâm mbên.”$b$,false),
('bunong-vn','EXO',4,18,null,$b$Y-Môis sĭt ta po păng Y-Jêtrô jêh ri lah: “Gâp dăn ma may, ăn gâp hăn tâm mâp đah phung oh nâu gâp ta n'gor Êjipt, gay gĭt tơ lah khân păng hôm gŭ rêh: “Y-Jêtrô lah ma Y-Môis: “Hăn đăp mpăn hom.”$b$,true),
('bunong-vn','EXO',4,19,null,$b$Yêhôva lah ma Y-Môis tâm n'gor Midian: “Plơ̆ sĭt hom ta n'gor Êjipt; yor lah lĕ rngôch bunuyh ŭch ƀư ma may, khĭt jêh.”$b$,false),
('bunong-vn','EXO',4,20,null,$b$Pô ri Y-Môis sŏk ur păng jêh ri phung kon bu klâu păng, ăn khân păng ncho seh bri, jêh ri plơ̆ sĭt ta n'gor Êjipt. Păng djôt tâm ti păng, mâng Brah Ndu.$b$,false),
('bunong-vn','EXO',4,21,null,$b$Yêhôva lah ma Y-Môis: “Tơ lah may sĭt ta n'gor Êjipt, ăn may ƀư ta năp Pharaôn lĕ rngôch nau khlay gâp ăn jêh ma may dơi ƀư. Ƀiă lah gâp mra ƀư dăng nuih n'hâm păng, pô ri păng mâu ăn phung ƀon lan hăn ôh, pô ri păng mâu ăn phung ƀon lan hăn ôh.$b$,true),
('bunong-vn','EXO',4,22,null,$b$Ăn may lah ma Pharaôn: ‘Pô aơ Yêhôva ngơi; phung Israel jêng kon bu klâu gâp deh bôk rah.$b$,false),
('bunong-vn','EXO',4,23,null,$b$Gâp lah ma may: “Ăn kon bu klâu gâp hăn gay ma păng dơi pah kan ma gâp.” Ƀiă lah may dun mâu ăn păng hăn ôh, aơ gâp mra nkhĭt kon bu klâu may deh bôk rah?”$b$,false),
('bunong-vn','EXO',4,24,null,$b$Rŏ trong ta du ntŭk, ntŭk jưh, Yêhôva tâm mâp đah Y-Môis gay ma nkhĭt păng.$b$,true),
('bunong-vn','EXO',4,25,null,$b$Ƀiă lah H'Sêpôra sŏk du mlâm lŭ hơr, koh ntâu kon bu klâu păng jêh ri klŭp ta jâng Y-Môis, lah: “Nanê̆ may jêng ma gâp du huê sai rung mham.”$b$,true),
('bunong-vn','EXO',4,26,null,$b$Pô ri Yêhôva ăn Y-Môis gŭ rêh. Dôl nây ur păng lah: “May jêng du huê sai rung mham.” Yor nau koh ntâu.$b$,false),
('bunong-vn','EXO',4,27,null,$b$Yêhôva lah ma Y-Arôn: “Hăn hom ta ndrêch rdah gay tâm mâp đah Y-Môis.” Păng hăn tâm mâp đah Y-Môis ta yôk Brah Ndu jêh ri tâm chŭm.$b$,true),
('bunong-vn','EXO',4,28,null,$b$Y-Môis mbơh ma Y-Arôn lĕ rngôch nau Yêhôva ngơi njuăl jêh păng hăn, jêh ri lĕ rngôch nau tâm mbên Yêhôva đă păng mra ƀư.$b$,false),
('bunong-vn','EXO',4,29,null,$b$Y-Môis jêh ri Y-Arôn hăn rƀŭn lĕ rngôch phung bu bŭnh bu ranh phung ƀon lan Israel.$b$,false),
('bunong-vn','EXO',4,30,null,$b$Y-Arôn nkoch bri lĕ rngôch rplay ngơi Yêhôva ngơi jêh ma Y-Môis, jêh ri păng ƀư lĕ nau tâm mbên ta năp phung ƀon lan.$b$,false),
('bunong-vn','EXO',4,31,null,$b$Jêh ri phung ƀon lan chroh. Tơ lah Yêhôva tăng khâl jêh đah phung ƀon lan Israel jêh ri saơ jêh nau rêh ni khân păng, khân păng kŭnh bôk jêh ri mbah yơk.$b$,false),
('bunong-vn','EXO',5,1,null,$b$Bah kơi ma nây Y-Môis jêh ri Y-Arôn hăn ta Pharaôn jêh ri lah: “Pô aơ Yêhôva phung Israel lah: ‘Ăn phung ƀon lan gâp hăn, gay ma khân păng dơi ƀư nau sông sa nhêt ma gâp tâm ndrêch rdah.”$b$,true),
('bunong-vn','EXO',5,2,null,$b$Ƀiă lah Pharaôn lah: “Mbu jêng Yêhôva, gay ma gâp tông bâr ma păng jêh ri ăn phung Israel hăn? Gâp mâu gĭt năl Yêhôva, jêh ri gâp mâu mra ăn phung Israel hăn ôh,”$b$,false),
('bunong-vn','EXO',5,3,null,$b$Khân păng lah: “Brah Ndu phung Hêbrơ tâm mâp jêh đah hên. Hên dăn ma may, ăn hên hăn, pe nar hăn tâm ndrêch rdah, ŭch nhhơr ndơ ƀư brah ma Yêhôva, Brah Ndu hên, klach lah păng ƀư ma hên nau ji tưp mâu lah ma đao.”$b$,true),
('bunong-vn','EXO',5,4,null,$b$Ƀiă lah hađăch Êjipt lah ma khân păng: “Ơ Y-Môis jêh ri Y-Arôn, phâm ƀư khân may ăn ƀon lan cha lơi kan khân păng? Hăn hom ma khân may.$b$,false),
('bunong-vn','EXO',5,5,null,$b$Pharaôn lah: “Aơ, phung ƀon lan aơ jêng âk tâm n'gor, jêh ri khân may ăn khân păng rlu kan.”$b$,false),
('bunong-vn','EXO',5,6,null,$b$Nar nây lĕ Pharaôn ntăm ma phung Kôranh kan jêh ri phung Kôranh chiă phung ƀon lan, lah:$b$,false),
('bunong-vn','EXO',5,7,null,$b$“Lơi ta khân may ăn ôh rhe ma phung ƀon lan prăp ƀư neh uk nâm bu lor ri. Ăn khân păng nơm hăn joi êng.$b$,false),
('bunong-vn','EXO',5,8,null,$b$Ăn khân may ntăm ma khân păng ƀư tâm ban ma khân păng ƀư lor nây lĕ, lơi ta khân may n'hŭch ôh, yor lah khân păng gŭ dơm. Yor nây khân păng nter lah: “Hăn hom he nhhơr ndơ ƀư brah ma Brah Ndu he?$b$,false),
('bunong-vn','EXO',5,9,null,$b$Ăn jâk lơn kan ma phung nây, gay ma khân păng pah kan jêh ri lơi ăn khân păng chrê ôh ma nau bu ngơi mƀruh.”$b$,false),
('bunong-vn','EXO',5,10,null,$b$Pô ri phung Kôranh kan jêh ri phung Kôranh chiă uănh lah ma phung ƀon lan: “Pô aơ nau Pharaôn lah: ‘Gâp mâu hôm ăn rhe ma khân may ôh.$b$,true),
('bunong-vn','EXO',5,11,null,$b$Hăn joi hom êng khân may nơm, sŏk rhe ta ntŭk khân may dơi saơ; ƀiă lah mâu mra n'hŭch ôh kan khân may.”$b$,false),
('bunong-vn','EXO',5,12,null,$b$Pô ri phung ƀon lan nsong lam bri Êjipt gay ma dônh jia kro ƀư rhe.$b$,false),
('bunong-vn','EXO',5,13,null,$b$Phung kôranh kan nsêch khân păng, lah: “Ƀư jêh kan khân may ăp nar nâm bu lor ri geh jêh rhe.”$b$,true),
('bunong-vn','EXO',5,14,null,$b$Bu dong phung Kôranh chiă ƀon lan Israel, phung Kôranh kan Pharaôn ăn chiă phung ƀon lan Israel, jêh ri ôp khân păng: “Mâm ƀư khân may mâu ƀư jêh nđaơ jêh ri nar aơ dŭm neh uk bu phăn jêh ăn khân may ƀư nâm bu lor?”$b$,true),
('bunong-vn','EXO',5,15,null,$b$Phung Kôranh chiă phung ƀon lan Israel hăn nter ma Pharaôn jêh ri lah: “Mâm ƀư may ƀư pô nây ma phung oh mon may?$b$,true),
('bunong-vn','EXO',5,16,null,$b$Bu mâu ăn rhe ôh ma phung oh mon may, ƀiă lah ăt bu lah ma hên, ‘Ƀư hom neh uk.” Jêh ri aơ, bu dong phung oh mon may; ƀiă lah phung ƀon lan may nơm jêng tih.”$b$,true),
('bunong-vn','EXO',5,17,null,$b$Ƀiă lah păng lah: “Khân may gŭ dơm! Khân may gŭ dơm yơh! Pô ri khân may lah: ‘Ăn he nhhơr ndơ ƀư brah ma Yêhôva!’$b$,false),
('bunong-vn','EXO',5,18,null,$b$Aƀaơ aơ, hăn pah kan hom; bu mâu mra ăn rhe ma khân may ôh, ƀiă lah khân may mra njŭn neh uk, dŭm bu ăn khân may ƀư lor ri.”$b$,false),
('bunong-vn','EXO',5,19,null,$b$Phung Kôranh chiă phung ƀon lan Israel saơ bu rêh ni ma khân păng tơ lah bu lah: “Khân may mâu mra n'hŭch ôh neh uk khân may kan khân may ƀư ăp nar.”$b$,true),
('bunong-vn','EXO',5,20,null,$b$Dôl du luh tă bơh Pharaôn, khân păng tâm mâp đah Y-Môis jêh ri Y-Arôn gŭ kâp ta trong.$b$,false),
('bunong-vn','EXO',5,21,null,$b$Khân păng lah ma Y-Môis jêh ri Y-Arôn: “Ăn Yêhôva uănh ma khân may jêh ri phat dôih, yor lah khân may ăn Pharaôn jêh ri phung oh mon păng tâm rmot ma hên. Khân may dơm jêh du mlâm đao gưm tâm ti khân păng gay ma nkhĭt hên.”$b$,true),
('bunong-vn','EXO',5,22,null,$b$Y-Môis plơ̆ sĭt ma Yêhôva, lah: “Ơ Kôranh Brah, mâm ƀư may ăn tât nau mhĭk ma phung ƀon lan aơ? Mâm ƀư may mâp njuăl gâp hăn?$b$,true),
('bunong-vn','EXO',5,23,null,$b$Yor lah ntơm bơh gâp tât ta Pharaôn ŭch ngơi tâm amoh may, păng ƀư nau mhĭk ma phung ƀon lan aơ, mâu lĕ may tâm rklaih phung ƀon lan may.”$b$,false),
('bunong-vn','EXO',6,1,null,$b$Ƀiă lah Yêhôva lah ma Y-Môis: “May mra saơ aƀaơ ro nau gâp mra ƀư ma Pharaôn; yor lah ma ti ktang păng mra tĭng phung khân păng hăn; nanê̆ ma ti ktang păng mra nsot phung Israel luh bơh n'gor păng.”$b$,true),
('bunong-vn','EXO',6,2,null,$b$Brah Ndu lah ma Y-Môis: “Gâp jêng Yêhôva.$b$,true),
('bunong-vn','EXO',6,3,null,$b$Gâp tâm mpơl jêh ma Y-Abraham, ma Y-Isăk jêh ri ma Y-Yakôb tâm ban ma Brah Ndu, Nơm Geh Lĕ Nau Brah, ƀiă lah gâp mâu mpơl ôh ma khân păng tâm amoh Yêhôva.$b$,false),
('bunong-vn','EXO',6,4,null,$b$Gâp ƀư nâp jêh nau gâp tâm rnglăp đah khân păng, gay ăn ma khân păng n'gor Kanaan, n'gor khân păng jưh jêh ƀât lât.$b$,false),
('bunong-vn','EXO',6,5,null,$b$Nđâp ma gâp tăng jêh nau phung ƀon lan Israel nter, phung Êjipt njêng khân păng jêng dĭk, jêh ri gâp kah gĭt ma nau gâp tâm rnglăp.$b$,false),
('bunong-vn','EXO',6,6,null,$b$Yor nây lah ma phung ƀon lan Israel: “Gâp jêng Yêhôva jêh ri gâp mra ăn jêng kon me khân may bơh kan jâk phung Êjipt, gâp mra tâm rklaih khân may bơh nau jêng dĭk ma khân păng, jêh ri gâp mra tâm chuai khân may ma ti gâp gŭ yơr jêh, jêh ri ma nau phat dôih toyh.$b$,false),
('bunong-vn','EXO',6,7,null,$b$Gâp mra sŏk khân may jêng phung ƀon lan gâp, gâp mra jêng Brah Ndu khân may, jêh ri khân may mra gĭt gâp yơh jêng Yêhôva, Brah Ndu khân may, nơm ăn khân may jêng kon me bơh kan jâk phung Êjipt.$b$,false),
('bunong-vn','EXO',6,8,null,$b$Gâp mra ăn khân may lăp tâm n'gor gâp ton sơm jêh ŭch ăn ma Y-Abraham, ma Y-Isăk jêh ri ma Y-Yakôb, gâp mra ăn n'gor nây jêng drăp khân may ndơn dơm. Gâp Yêhôva.”$b$,false),
('bunong-vn','EXO',6,9,null,$b$Tâm ban pô nây Y-Môis ngơi ma phung ƀon lan Israel, ƀiă lah khân păng mâu iăt nau Y-Môis ôh yor nau khân păng rngot ioh nuih n'hâm jêh ri jêng dĭk knap ngăn.$b$,false),
('bunong-vn','EXO',6,10,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',6,11,null,$b$“Hăn lăp ngơi hom đah Pharaôn hađăch Êjipt gay ma păng ăn phung ƀon lan Israel luh bơh n'gor păng.”$b$,false),
('bunong-vn','EXO',6,12,null,$b$Ƀiă lah Y-Môis plơ̆ lah ma Yêhôva: “Aơ, phung ƀon lan Israel mâu iăt gâp ôh, pô ri mâm ƀư Pharaôn dơi iăt gâp, yor lah gâp mâu dơi ngơi ueh ôh?”$b$,true),
('bunong-vn','EXO',6,13,null,$b$Ƀiă lah Yêhôva ngơi đah Y-Môis jêh ri Y-Arôn, ntăm ăn khân păng nau phung ƀon lan Israel jêh ri ma nau Pharaôn hađăch n'gor Êjipt, gay ăn phung ƀon lan Israel luh bơh n'gor Êjipt.$b$,false),
('bunong-vn','EXO',6,14,null,$b$Aơ phung Kôranh băl mpôl mbơ̆ khân păng: Phung kon bu klâu Y-Ruben, nơm Israel deh bôk rah: Y-Hanôk, Y-Palu, Y-Hêsron, jêh ri Y-Karmi. Dŭm nây phung băl mpôl Y-Ruben.$b$,true),
('bunong-vn','EXO',6,15,null,$b$Phung kon bu klâu Y-Simêôn: Y-Jêmuêl, Y-Jamin, Y-Ôhat, Y-Jakin, Y-Sôhar, jêh ri Y-Sal kon bu klâu bơh bu ur Kanaan. Dŭm nây yơh phung băl mpôl Y-Simêôn.$b$,false),
('bunong-vn','EXO',6,16,null,$b$Aơ phung kon bu klâu Y-Lêvi tĭng nâm băl mpôl khân păng: Y-Gerson, Y-Kôhat jêh ri Y-Mêrari. Năm Y-Lêvi gŭ rêh geh du rhiăng pe jât ma pơh năm.$b$,false),
('bunong-vn','EXO',6,17,null,$b$Phung kon bu klâu Y-Gersôn: Y-Lipni jêh ri Y-Simei, tĭng nâm băl mpôl khân păng.$b$,false),
('bunong-vn','EXO',6,18,null,$b$Phung kon bu klâu Y-Kôhat: Y-Amram, Y-Ishar, Y-Hêbron, jêh ri Y-Usiel. Năm Y-Kôhat gŭ rêh geh du rhiăng pe jât ma pe năm.$b$,false),
('bunong-vn','EXO',6,19,null,$b$Phung kon bu klâu Y-Mêrari: Y-Mali jêh ri Y-Musi. Dŭm nây yơh phung băl mpôl Y-Lêvi tĭng nâm băl mpôl khân păng.$b$,false),
('bunong-vn','EXO',6,20,null,$b$Y-Amram gŭ ur H'Jôkêbet, oh bu ur mbơ̆ păng nơm jêh ri păng deh ma Y-Arôn jêh ri Y-Môis, năm Y-Amram gŭ rêh geh du rhiăng pe jât ma pơh năm.$b$,false),
('bunong-vn','EXO',6,21,null,$b$Phung kon bu klâu Y-Ishar: Y-Kôrê, Y-Nêphek, jêh ri Y-Sikri.$b$,true),
('bunong-vn','EXO',6,22,null,$b$Phung kon bu klâu Y-Usiel: Y-Misael, Y-Elsaphan, jêh ri Y-Sithri.$b$,false),
('bunong-vn','EXO',6,23,null,$b$Y-Môis gŭ ur Y-Êlisêba, kon bu ur Y-Aminadap, nur Y-Nahsôn, jêh ri păng deh ma păng Y-Nadap, Y-Abihu, Y-Êlêasar, jêh ri Y-Ithamar.$b$,false),
('bunong-vn','EXO',6,24,null,$b$Phung kon bu klâu Y-Kôrê: Y-Asir, Y-Êlkana, jêh ri Y-Abiasap. Dŭm nây phung băl mpôl Y-Kôrê.$b$,false),
('bunong-vn','EXO',6,25,null,$b$Y-Êlêasar, kon bu klâu Y-Arôn, gŭ ur du huê tâm phung kon bu ur Y-Putiel, jêh ri deh ma păng Y-Phinêas. Phung nây jêng phung Kôranh tâm phung Y-Lêvi tĭng nâm băl mpôl khân păng.$b$,false),
('bunong-vn','EXO',6,26,null,$b$Aơ yơh jêng Y-Arôn jêh ri Y-Môis, ma khân păng Yêhôva lah: “Njŭn ngluh hom phung ƀon lan Israel bơh n'gor Êjipt”.$b$,false),
('bunong-vn','EXO',6,27,null,$b$Khân păng yơh, Y-Môis jêh ri Y-Arôn, ngơi ma Pharaôn hađăch Êjipt gay njŭn phung ƀon lan bơh n'gor Êjipt.$b$,true),
('bunong-vn','EXO',6,28,null,$b$Ta nar Yêhôva ngơi ma Y-Môis tâm n'gor Êjipt,$b$,true),
('bunong-vn','EXO',6,29,null,$b$Yêhôva lah ma Y-Môis: “Gâp jêng Yêhôva, lah hom ma Pharaôn hađăch Êjipt lĕ nau gâp ngơi ma may.”$b$,false),
('bunong-vn','EXO',6,30,null,$b$Ƀiă lah Y-Môis lah ma Yêhôva: “Aơ gâp geh trôm mbung ngơi mâu ueh ôh, Mâm ƀư Pharaôn dơi iăt gâp?”$b$,false),
('bunong-vn','EXO',7,1,null,$b$Yêhôva lah ma Y-Môis: “Aơ, gâp ăn may jêng nâm bu Brah Ndu ma Pharaôn, jêh ri Y-Môis nâu may mra jêng kôranh nơm mbơh lor may.$b$,true),
('bunong-vn','EXO',7,2,null,$b$Ăn may ngơi lĕ nau gâp ntăm ma may; jêh ri Y-Môis nâu may mra ngơi ma Pharaôn, gay ma păng lơi phung ƀon lan Israel luh bơh n'gor păng.$b$,false),
('bunong-vn','EXO',7,3,null,$b$Ƀiă lah gâp mra ƀư dăng nuih n'hâm Pharaôn, jêh ri nđâp tơ lah gâp mra ăn bĭk nau tâm mbên gâp jêh ri nau khlay yom gâp tâm n'gor Êjipt.$b$,false),
('bunong-vn','EXO',7,4,null,$b$Pharaôn mâu mra iăt nau may ôh. Jêh ri gâp mra dơm ti gâp ta klơ n'gor Êjipt jêh ri ngluh phung ta han gâp, phung ƀon lan gâp, phung kon bu klâu Israel, bơh n'gor Êjipt ma nau phat dôih toyh.$b$,false),
('bunong-vn','EXO',7,5,null,$b$Phung Êjipt mra gĭt gâp jêng Yêhôva tơ lah gâp yơr ti gâp ta klơ n'gor Êjipt jêh ri ngluh phung ƀon lan Israel tă bơh tâm nklang khân păng.”$b$,false),
('bunong-vn','EXO',7,6,null,$b$Y-Môis jêh ri Y-Arôn ƀư tĭng nâm bu nau Yêhôva ntăm jêh ma khân păng.$b$,false),
('bunong-vn','EXO',7,7,null,$b$Dôl nây Y-Môis geh pham jât năm, jêh ri Y-Môis geh pham jât ma pe năm, tơ lah khân păng hăn ngơi ma Pharaôn.$b$,false),
('bunong-vn','EXO',7,8,null,$b$Yêhôva lah ma Y-Môis jêh ri Y-Arôn:$b$,true),
('bunong-vn','EXO',7,9,null,$b$“Tơ lah Pharaôn ngơi ma khân may, lah: ‘Ƀư hom du ntil nau khlay yom, ăn may lah ma Y-Môis.” Sŏk mâng may jêh ri rjăng păng ta năp Pharaôn, gay ma păng jêng du mlâm bêh.”$b$,false),
('bunong-vn','EXO',7,10,null,$b$Pô ri Y-Môis jêh ri Y-Arôn hăn ta năp măt Pharaôn ƀư tĭng nâm nau Yêhôva ntăm jêh, Y-Arôn rjăng mâng păng ta năp Pharaôn jêh ri phung oh mon păng, jêh ri păng jêng du huê bêh.$b$,false),
('bunong-vn','EXO',7,11,null,$b$Jêh ri Pharaôn kuăl phung njêh, phung n'hŭm jêh ri phung rƀên n'gor Êjipt nây ƀư tâm ban lĕ ma nau khân păng ƀư rƀên.$b$,false),
('bunong-vn','EXO',7,12,null,$b$Yor lah ăp nơm khân păng rjăng mâng păng, jêh ri khân păng jêng bêh. Ƀiă lah mâng Y-Arôn rvăn lơi mâng khân păng.$b$,false),
('bunong-vn','EXO',7,13,null,$b$Nuih n'hâm Pharaôn ăt jêng dăng jêh ri păng mâu iăt phung nây ôh, tĭng nâm nau Pharô lah jêh.$b$,false),
('bunong-vn','EXO',7,14,null,$b$Yêhôva lah ma Y-Môis: “Nuih n'hâm Pharaôn jêng dăng. Păng dun mâu ăn phung Israel hăn ôh.$b$,true),
('bunong-vn','EXO',7,15,null,$b$Ăn may hăn ma Pharaôn ôi, dôl păng hăn ta dak, gŭ kâp păng ta kơh dak krong. Ăn may djôt mâng mâp tâm rgâl jêng bêh.$b$,false),
('bunong-vn','EXO',7,16,null,$b$Ăn may lah ma păng: “Yêhôva Brah Ndu phung Hêbrơ, njuăl gâp văch ta may, lah: “Ăn phung ƀon lan gâp hăn luh du, gay ma khân păng dơi pah kan ma gâp tâm bri rdah; jêh ri aơ, may ê mâp iăt ôh.”$b$,false),
('bunong-vn','EXO',7,17,null,$b$Yêhôva ngơi pô aơ, ma nau aơ may mra gĭt gâp jêng Yêhôva: Aơ, gâp mra dong dak krong Nil ma mâng gâp djôt tâm ti gâp, jêh ri dak nây mra rgâl jêng mham,$b$,false),
('bunong-vn','EXO',7,18,null,$b$Ka tâm dak krong Nil mra khĭt, jêh ri dak krong Nil mra ƀâu ôm jêh ri phung Êjipt mâu dơi nhêt dak krong ôh.”$b$,false),
('bunong-vn','EXO',7,19,null,$b$Yêhôva lah ma Y-Môis: “Lah hom ma Y-Arôn, ‘Sŏk hom mâng may jêh ri yơr hom ti may mpeh pa dak n'gor Êjipt, mơ pa dak n'hor toyh, n'hor dak jê̆, dak nglau, jêh ri dak ntu lŭng khân păng, gay ma lĕ rngôch jêng mham; jêh ri mra geh mham lam n'gor Êjipt tâm glah ƀư ma si jêh ri lŭ ăt mra geh mblum da dê lĕ rngôch.”$b$,false),
('bunong-vn','EXO',7,20,null,$b$Y-Môis jêh ri Y-Arôn ƀư tĭng nâm Yêhôva ntăm. Păng yơr mâng jêh ri dong dak tâm dak krong Nil ta năp măt Pharaôn jêh ri phung oh mon păng; jêh ri lĕ rngôch dak tâm dak krong Nil plăch jêng mham.$b$,true),
('bunong-vn','EXO',7,21,null,$b$Ka tâm dak krong Nil khĭt, dak krong ƀâu ôm; pô ri phung Êjipt mâu dơi nhêt dak krong Nil ôh; jêh ri geh mham lam bri Êjipt.$b$,true),
('bunong-vn','EXO',7,22,null,$b$Ƀiă lah phung rƀên n'gor Êjipt ƀư tâm ban lĕ ma nau khân păng blau rƀên. Pô nây nuih n'hâm Pharaôn ăt jêng dăng, jêh ri păng mâu iăt phung nây ôh, tĭng nâm Yêhôva lah jêh.$b$,false),
('bunong-vn','EXO',7,23,null,$b$Pharaôn sĭt ta ngih păng, jêh ri păng mâu chrê ma nau nây ôh.$b$,false),
('bunong-vn','EXO',7,24,null,$b$Lĕ rngôch phung Êjipt kuyh ntu êp dak krong Nil gay geh dak nhêt, yor lah khân păng mâu dơi nhêt dak krong ôh.$b$,false),
('bunong-vn','EXO',7,25,null,$b$Tăch pơh nar jêh Yêhôva dong dak krong Nil.$b$,true),
('bunong-vn','EXO',8,1,null,$b$Yêhôva lah ma Y-Môis: “Hăn hom ma Pharaôn jêh ri lah ma păng,” Yêhôva lah pô aơ: “Ăn phung ƀon lan gâp hăn du, gay ma khân păng dơi pah kan ma gâp.$b$,true),
('bunong-vn','EXO',8,2,null,$b$Ƀiă lah tơ lah may dun, mâu ăn khân păng hăn ôh, aơ gâp mra ƀư ma n'gor may ăn geh kĭt lam bri.$b$,true),
('bunong-vn','EXO',8,3,null,$b$Dak krong Nil mra bêng ler ma kĭt. Khân păng mra hao jêh ri lăp tâm ngih may, tâm jrô may bêch, tâm sưng may bêch, tâm ngih phung oh mon may, tâm ngih phung ƀon lan may, tâm năk jêh ri tâm thŭng mon piăng let may.$b$,false),
('bunong-vn','EXO',8,4,null,$b$Kĭt mra hao tât ta may, ma phung ƀon lan may jêh ri lĕ rngôch phung oh mon may.$b$,false),
('bunong-vn','EXO',8,5,null,$b$Yêhôva lah ma Y-Môis: “Ngơi hom ma Y-Arôn, yơr hom ti may djôt mâng may mơ pa dak n'hor toyh, n'hor dak jê̆, jêh ri dak nglau, jêh ri ăn kĭt hao tât ta n'gor Êjipt.”$b$,false),
('bunong-vn','EXO',8,6,null,$b$Y-Arôn yơr ti păng mơ pa dak n'gor Êjipt; jêh ri kĭt hao nkŭm n'gor Êjipt.$b$,false),
('bunong-vn','EXO',8,7,null,$b$Ƀiă lah phung rƀên ƀư tâm ban lĕ ma nau khân păng blau rƀên jêh ri ăn kĭt hao tât ta n'gor Êjipt.$b$,false),
('bunong-vn','EXO',8,8,null,$b$Pharaôn kuăl Y-Môis jêh ri Y-Arôn, lah: “Vơh vơl hom ma Yêhôva gay ma păng mprơh lơi kĭt bơh gâp jêh ri bơh phung ƀon lan gâp; jêh ri gâp mra ăn phung ƀon lan hăn nhhơr ndơ ƀư brah ma Yêhôva.”$b$,true),
('bunong-vn','EXO',8,9,null,$b$Y-Môis lah ma Pharaôn: “Ăn may geh nau maak ntăm ma gâp ndah jŏ gâp mra vơh vơl yor may, yor phung oh mon, jêh ri yor phung ƀon lan may, gay ma roh kĭt bơh may, bơh ngih may, jêh ri hôm knŏng dak krong.”$b$,true),
('bunong-vn','EXO',8,10,null,$b$Păng plơ̆ lah: “Ôi taơ” Y-Môis lah: “Ăn jêng tĭng nâm bu nau may lah, gay ma khân may gĭt mâu geh ôh nơm tâm ban ma Yêhôva, Brah Ndu hên.$b$,false),
('bunong-vn','EXO',8,11,null,$b$Kĭt mra du tă bơh may, bơh ngih may, bơh phung oh mon may, jêh ri bơh phung ƀon lan may. Khân păng mra gŭ knŏng tâm dak krong Nil.”$b$,false),
('bunong-vn','EXO',8,12,null,$b$Y-Môis jêh ri Y-Arôn du tă bơh Pharaôn; jêh ri Y-Môis vơl dăn ma Yêhôva yor kĭt tĭng nâm păng ton jêh ma Pharaôn.$b$,false),
('bunong-vn','EXO',8,13,null,$b$Yêhôva ƀư tĭng nâm Y-Môis ngơi; jêh ri khĭt tâm ngih, tâm nkual ngih, jêh ri tâm mir.$b$,true),
('bunong-vn','EXO',8,14,null,$b$Bu rƀŭn bun âk nku, jêh ri lam bri ƀâu ôm.$b$,false),
('bunong-vn','EXO',8,15,null,$b$Ƀiă lah tơ lah Pharaôn saơ geh nau rlu, păng plơ̆ dăng nuih n'hâm păng, jêh ri mâu hôm iăt nau phung nây, nâm bu Yêhôva lah jêh.$b$,false),
('bunong-vn','EXO',8,16,null,$b$Yêhôva lah ma Y-Môis: “Ngơi hom ma Y-Arôn, ‘yơr mâng may jêh ri dong ndruyh neh, gay ma păng plăch jêng mach tâm lam n'gor Êjipt.”$b$,true),
('bunong-vn','EXO',8,17,null,$b$Khân păng ƀư pô nây. Y-Arôn yơr ti păng, djôt mâng păng, dong ndruyh neh, jêh ri geh mach ta bunuyh jêh ri ta mpô mpa. Lĕ rngôch ndruyh neh plăch jêng mach tâm lam bri neh Êjipt.$b$,false),
('bunong-vn','EXO',8,18,null,$b$Phung rƀên dŏng nau khân păng blau rƀên gay ma geh mach, ƀiă lah khân păng mâu dơi ƀư nau nây ôh. Jêh ri geh mach ta bunuyh jêh ri mpô mpa.$b$,true),
('bunong-vn','EXO',8,19,null,$b$Phung rƀên lah ma Pharaôn: “Aơ yơh nglau ti Brah Ndu.” Ƀiă lah nuih n'hâm Pharaôn jêng dăng, jêh ri păng mâu iăt phung nây ôh, nâm bu Yêhôva lah jêh.$b$,false),
('bunong-vn','EXO',8,20,null,$b$Yêhôva lah ma Y-Môis: “Dâk hom ơm ôi jêh ri gŭ kâp Pharaôn dôl păng lah hăn ta dak, jêh ri lah ma păng, ‘Yêhôva ngơi pô aơ.” Ăn phung ƀon lan gâp hăn, gay ma khân păng dơi pah kan ma gâp.$b$,true),
('bunong-vn','EXO',8,21,null,$b$Tơ lah may mâu ăn phung ƀon lan gâp hăn, aơ gâp mra njuăl rhuay âk ma may, ma phung oh mon may, ma phung ƀon lan may jêh ri tâm lĕ rngôch ngih khân may. Ngih phung Êjipt mra bêng rhuay, jêh ri neh mra bêng ma rhuay lĕ.$b$,false),
('bunong-vn','EXO',8,22,null,$b$Ƀiă lah tâm nar nây gâp mra prăp êng n'gor Gôsen, ntŭk phung ƀon gâp gŭ, gay ma ta nây mâu mra geh rhuay ôh; gay ma may gĭt gâp jêng Yêhôva tâm n'gor aơ.$b$,false),
('bunong-vn','EXO',8,23,null,$b$Pô ri gâp mra prăp êng phung ƀon lan gâp đah phung ƀon lan may. Nau tâm mƀên aơ mra tât ôi taơ.”$b$,false),
('bunong-vn','EXO',8,24,null,$b$Yêhôva ƀư pô nây. Geh âk rhuay lăp tâm ngih Pharaôn jêh ri tâm ngih phung oh mon păng, jêh ri rhuay ƀư rai lam n'gor Êjipt.$b$,false),
('bunong-vn','EXO',8,25,null,$b$Pharaôn kuăl Y-Môis, jêh ri Y-Arôn, jêh ri lah: “Hăn hom khân may nhhơr ndơ ƀư brah ma Brah Ndu khân may tâm n'gor.”$b$,true),
('bunong-vn','EXO',8,26,null,$b$Ƀiă lah, lah Y-Môis lah: “Mâu di ôh ƀư pô nây; yor lah hên mra nhhơr ma Yêhôva Brah Ndu hên ndơ phung Êjipt rmot. Tơ lah hên nhhơr ta năp măt Êjipt ndơ khân păng rmot, mâu di hĕ khân păng mra klŭp hên ma lŭ?$b$,true),
('bunong-vn','EXO',8,27,null,$b$Hên mra hăn tâm pe nar tâm bri rdah jêh ri nhhơr ndơ ƀư brah ma Yêhôva Brah Ndu hên, tĭng nâm nau păng mra ntăm ma hên.”$b$,false),
('bunong-vn','EXO',8,28,null,$b$Pharaôn lah: “Gâp mra ăn khân may hăn, gay ma khân may ƀư brah ma Yêhôva Brah Ndu khân may tâm ndrêch rdah, knŏng lơi khân may du ngai ôh. Mbơh sơm hom ma gâp ƀă.$b$,false),
('bunong-vn','EXO',8,29,null,$b$Y-Môis lah: “Aơ, gâp mra du luh tă bơh may, jêh ri gâp mra dăn ma Yêhôva, gay ma rhuay âk mra du ôi taơ bơh Pharaôn bơh phung oh mon păng jêh ri bơh phung ƀon lan păng. Knŏng lơi ăn Pharaôn rlăm ôh jêh ri mâu ăn ôh phung ƀon lan hăn gay nhhơr ndơ ƀư brah ma Yêhôva”.$b$,false),
('bunong-vn','EXO',8,30,null,$b$Pô ri Y-Môis du tă bơh Pharaôn jêh ri mbơh sơm ma Yêhôva.$b$,false),
('bunong-vn','EXO',8,31,null,$b$Yêhôva ƀư tĭng nâm nau Y-Môis dăn, jêh ri păng mprơh rhuay âk bơh Pharaôn bơh phung oh mon păng, jêh ri bơh phung ƀon lan păng, mâu hôm geh du mlâm ôh.$b$,true),
('bunong-vn','EXO',8,32,null,$b$Ƀiă lah Pharaôn ăt dăng nuih đŏng tal aơ jêh ri păng mâu ăn phung ƀon lan hăn ôh.$b$,false),
('bunong-vn','EXO',9,1,null,$b$Yêhôva lah ma Y-Môis: “Hăn hom ma Pharaôn jêh ri lah ma păng,” pô aơ Yêhôva Brah Ndu ma phung Hêbrơ, lah: “Ăn phung ƀon lan gâp hăn, gay ma khân păng dơi pah kan ma gâp.$b$,true),
('bunong-vn','EXO',9,2,null,$b$Yor lah tơ lah may dun mâu ăn khân păng hăn ôh, tơ lah may ăt kân khân păng,$b$,false),
('bunong-vn','EXO',9,3,null,$b$aơ ti Yêhôva mra ƀư ma mpô mpa rong may gŭ tâm mir, seh, seh bri, seh samô, ndrôk jêh ri biăp mra geh nau ji tưp ktang ngăn.$b$,false),
('bunong-vn','EXO',9,4,null,$b$Ƀiă lah Yêhôva mra ƀư nau êng ma biăp phung Israel jêh ri ma biăp, ndrôk phung Êjipt, pô ri biăp, ndrôk phung Israel mâu mra ji khĭt ôh.”$b$,false),
('bunong-vn','EXO',9,5,null,$b$Yêhôva tâm nal nar, lah: “Ôi taơ Yêhôva mra ƀư nau nây tâm n'gor.”$b$,true),
('bunong-vn','EXO',9,6,null,$b$Jêh ri Yêhôva ƀư nau nây ôi taơ; lĕ rngôch biăp, ndrôk phung Êjipt khĭt, ƀiă lah biăp ndrôk phung Israel mâu khĭt du mlâm ôh.$b$,false),
('bunong-vn','EXO',9,7,null,$b$Pharaôn njuăl bu hăn, jêh ri aơ mâu geh du mlâm biăp ndrôk phung Israel khĭt ôh. Ƀiă lah nuih Pharaôn jêng dăng, jêh ri păng mâu ăn phung ƀon lan hăn ôh.$b$,false),
('bunong-vn','EXO',9,8,null,$b$Yêhôva lah ma Y-Môis jêh ri ma Y-Arôn: “Ăn ti khân may bêng ma buh năk, jêh ri ăn Y-Môis mbrih leo klơ trôk ta năp Pharaôn.$b$,true),
('bunong-vn','EXO',9,9,null,$b$Buh nây mra jêng ndruyh neh nkŭm lam n'gor Êjipt, jêh ri buh nây mra ƀư geh ok (toh) eh, môr plưch geh ta bunuyh jêh ri ta mpô mpa tâm lam bri n'gor Êjipt.”$b$,true),
('bunong-vn','EXO',9,10,null,$b$Pô ri khân păng sŏk buh năk jêh ri gŭ ta năp Pharaôn. Y-Môis mbrih buh năk leo klơ trôk, jêh ri geh ok, eh môr, plưch dô geh ma bunuyh jêh ri mpô mpa.$b$,false),
('bunong-vn','EXO',9,11,null,$b$Phung rƀên mâu dơi gŭ ta năp Y-Môis ôh yor ok, eh, yor lah nđâp ma phung rƀên nơm lĕ geh eh ok tâm ban ma lĕ rngôch phung Êjipt.$b$,true),
('bunong-vn','EXO',9,12,null,$b$Yêhôva ƀư dăng nuih Pharaôn, jêh ri păng mâu iăt ôh nau phung nây, tĭng nâm Yêhôva lah jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',9,13,null,$b$Yêhôva lah ma Y-Môis: “Dâk hom may ơm ôi, jêh ri gŭ ta năp Pharaôn jêh ri lah ma păng. Pô aơ Yêhôva, Brah Ndu phung Hêbrơ, lah: ‘Ăn phung ƀon lan gâp hăn, gay ma khân păng dơi pah kan ma gâp.$b$,true),
('bunong-vn','EXO',9,14,null,$b$Yor lah tal aơ gâp mra njuăl ma may lĕ rngôch nau rêh ni gâp ƀư ma nuih n'hâm may, ma phung oh mon may jêh ri ma phung ƀon lan may, gay ma khân may gĭt jêng tâm ban ma gâp tâm lam neh ntu.$b$,false),
('bunong-vn','EXO',9,15,null,$b$Tơ lah gâp yơr jêh ti gâp jêh ri dong jêh may jêh ri phung ƀon lan may ma nau ji tưp, may roh rai jêh bơh neh ntu.$b$,false),
('bunong-vn','EXO',9,16,null,$b$Ƀiă lah yor nau aơ gâp ăn khân may gŭ rêh, gay ăn khân may saơ nau brah gâp, pô nây mơ bu mra mbơh amoh gâp lam neh ntu.$b$,false),
('bunong-vn','EXO',9,17,null,$b$May ăt rlau, tâm rdâng đah phung ƀon lan gâp, jêh ri mâu ăn khân păng hăn ôh.$b$,false),
('bunong-vn','EXO',9,18,null,$b$Aơ, ôi taơ ta mông aơ gâp mra ăn trôk mih dak pler jâk, mâu mâp geh tâm ban pô nây tâm n'gor Êjipt ntơm bơh bu rdâk păng tât ta nar aơ.$b$,false),
('bunong-vn','EXO',9,19,null,$b$Yor nây ăn may ndal tĭng bu tâm rƀŭn tâm ntŭk rnơm ma biăp; ndrôk may jêh ri lĕ rngôch mpa may geh tâm mir yor lah pler mra tŭp ta klơ lĕ rngôch bunuyh jêh ri mpô mpa gŭ tâm mir bu mâu njŭn sĭt, jêh ri khân păng mra khĭt.’ ”$b$,false),
('bunong-vn','EXO',9,20,null,$b$Mbu tâm phung oh mon Pharaôn klach ma nau Yêhôva ngơi, ăn phung oh mon jêh ri biăp, ndrôk khân păng du tâm ngih.$b$,false),
('bunong-vn','EXO',9,21,null,$b$Ƀiă lah phung mâu chrê ôh ma nau Yêhôva ngơi lơi phung oh mon jêh ri biăp ndrôk khân păng gŭ tâm mir.$b$,false),
('bunong-vn','EXO',9,22,null,$b$Yêhôva lah ma Y-Môis: “Yơr ti may leo ta klơ trôk, gay ma pler mra tŭp tâm lam n'gor Êjipt ta klơ bunuyh, ta klơ mpô mpa jêh ri ta klơ ndơ bu tăm tâm mir tâm lam bri n'gor Êjipt.”$b$,true),
('bunong-vn','EXO',9,23,null,$b$Y-Môis yơr mâng leo ta klơ trôk, jêh ri Yêhôva njuăl nglaih, dak pler jêh ri geh ŭnh tŭp ta neh ntu. Yêhôva ăn trôk mih dak pler tâm n'gor Êjipt.$b$,false),
('bunong-vn','EXO',9,24,null,$b$Geh pler jêh ri ŭnh tâm rlŭk đah pler, pler jâk ngăn, mâu mâp geh ôh tâm ban pô nây tâm lam bri Êjipt ntơm bơh păng jêng du rplay n'gor bri.$b$,false),
('bunong-vn','EXO',9,25,null,$b$Pler tŭp ƀư ma lĕ rngôch mpa lam n'gor bri Êjipt, bunuyh nđâp ma mpô mpa; pler ƀư rai lĕ rngôch ndơ bu tăm tâm mir, jêh ri ƀư chôt lĕ tơm si tâm mir.$b$,false),
('bunong-vn','EXO',9,26,null,$b$Knŏng tâm n'gor bri Gôsen, ntŭk phung ƀon lan Israel gŭ, mâu geh pler ôh.$b$,true),
('bunong-vn','EXO',9,27,null,$b$Pharaôn njuăl bu hăn kuăl Y-Môis jêh ri Y-Arôn lah ma khân păng: “Tal aơ gâp ƀư tih. Yêhôva jêng sŏng srăng, gâp jêh ri phung ƀon lan gâp jêng tih.$b$,true),
('bunong-vn','EXO',9,28,null,$b$Vơh vơl hom ma Yêhôva, yor lah tŏng jêh nglaih jêh ri pler; gâp mra ăn khân may hăn, jêh ri khân may mâu mra gŭ đŏng ta aơ ôh.”$b$,false),
('bunong-vn','EXO',9,29,null,$b$Y-Môis lah ma păng: “Tơ lah gâp du luh jêh tă bơh ƀon, gâp mra yơr ti gâp ma Yêhôva;$b$,false),
('bunong-vn','EXO',9,30,null,$b$nglaih mra rlu jêh ri mâu mra geh pler ôh, gay ma may gĭt neh ntu jêng ndơ Yêhôva. Ƀiă lah gâp gĭt may jêh ri phung oh mon may ăt ê klach lĕ ma Yêhôva Brah Ndu.”$b$,false),
('bunong-vn','EXO',9,31,null,$b$(Mhay jêh ri ba orgơ rai jêh yor ba ôrgơ dôl luh, jêh ri mhay dôl kao.$b$,true),
('bunong-vn','EXO',9,32,null,$b$Ƀiă lah ba luh jêh ri ba luh bri mâu rai ôh, yor lah khân păng ăt chăt hon).$b$,false),
('bunong-vn','EXO',9,33,null,$b$Y-Môis du tă bơh Pharaôn, hăn ta mpâr ƀon; păng yơr ti păng ma Yêhôva. Nglaih jêh ri pler rlu, jêh ri trôk mâu hôm mih ôh.$b$,false),
('bunong-vn','EXO',9,34,null,$b$Tơ lah Pharaôn saơ mih, pler jêh ri nglaih rlu jêh, păng ăt ƀư tih jêh ri dăng nuih păng jêh ri phung oh mon păng.$b$,false),
('bunong-vn','EXO',9,35,null,$b$Nuih n'hâm Pharaôn jêng dăng, jêh ri păng mâu ăn phung ƀon lan Israel hăn ôh tĭng nâm Yêhôva lah jêh ma mbung Y-Môis.$b$,false),
('bunong-vn','EXO',10,1,null,$b$Yêhôva lah ma Y-Môis: “Hăn hom ma Pharaôn, yor lah gâp ƀư dăng jêh nuih n'hâm păng jêh ri nuih n'hâm phung oh mon păng, gay ma gâp dơi tâm mpơl nau mbên gâp aơ ta nklang khân păng,$b$,true),
('bunong-vn','EXO',10,2,null,$b$jêh ri gay ma khân may dơi nkoch bri ma kon khân may jêh ri ma kon sau khân may nau ma phung Êjipt, jêh ri nau mbên gâp ƀư ta nklang khân păng, gay ma khân may dơi gĭt gâp jêng Yêhôva.”$b$,false),
('bunong-vn','EXO',10,3,null,$b$Y-Môis jêh ri Y-Arôn hăn ta Pharaôn jêh ri lah ma păng: “Pô aơ Yêhôva Brah Ndu phung Hêbrơ, lah: “Ndah dĭng jŏ may mra dun, mâu ŭch ƀư tông may nơm ta năp gâp? Ăn phung ƀon lan gâp hăn, gay ma khân păng dơi pah kan ma gâp.$b$,true),
('bunong-vn','EXO',10,4,null,$b$Tơ lah may dun mâu ăn phung ƀon lan gâp hăn ôh, aơ gâp mra ăn phung krah văch ôi taơ tâm lam n'gor may.$b$,false),
('bunong-vn','EXO',10,5,null,$b$Krah nây mra nkŭm ndâp neh, pô ri bu mâu hôm dơi saơ neh ôh. Khân păng mra sa lĕ rngôch ndơ ăt hôm bơh dak pler. Khân păng mra sa lĕ rngôch tơm si hon tâm mir may.$b$,false),
('bunong-vn','EXO',10,6,null,$b$Khân păng mra ƀư bêng ngih may, ngih lĕ rngôch phung oh mon may, jêh ri lĕ rngôch phung Êjipt. Phung mbơ̆ khân may jêh ri phung che khân may mâu mâp saơ nau tâm ban pô nây ôh ntơm geh khân păng ta neh ntu tât ta nar aơ.” Jêh ri Y-Môis du tă bơh ngih Pharaôn.$b$,false),
('bunong-vn','EXO',10,7,null,$b$Phung oh mon Pharaôn lah ma păng: “Ndah dĭng jŏ bu klâu nây mra jêng dăk sân ma he? Ăn phung klâu nây hăn, gay ma khân păng dơi pah kan ma Brah Ndu Yêhôva Brah Ndu khân păng. May ê gĭt hĕ ma n'gor Êjipt rai jêh?.”$b$,true),
('bunong-vn','EXO',10,8,null,$b$Pô ri bu njŭn Y-Môis jêh ri Y-Arôn ma Pharaôn. Păng lah ma phung nây: “Hăn hom pah kan ma Brah Ndu Yêhôva khân may; ƀiă lah mbu phung mra hăn?”$b$,false),
('bunong-vn','EXO',10,9,null,$b$Y-Môis lah: “Hên mra hăn ndrel ma phung kon se hên jêh ri phung bu ranh hên, ndrel ma phung kon bu klâu jêh ri phung kon bu ur hên, ndrel ma biăp jêh ri ndrôk hên, yor lah hên mra nkra nau nhêt sa ma Yêhôva.”$b$,false),
('bunong-vn','EXO',10,10,null,$b$Pharaôn lah ma khân păng: “Ăn Yêhôva gŭ ndrel ma khân may tơ lah gâp mâp ăn jêh khân may jêh ri phung kon se khân may hăn, njrăng hom, yor lah khân may mĭn ƀư mhĭk.$b$,false),
('bunong-vn','EXO',10,11,null,$b$Mâu, hăn hom khân may knŏng phung bu klâu pah kan ma Yêhôva, yor lah nâm bu pô nây khân may ŭch.” Jêh ri bu mprơh khân păng ta năp Pharaôn.$b$,false),
('bunong-vn','EXO',10,12,null,$b$Yêhôva lah ma Y-Môis: “Yơr ti may leo ta n'gor Êjipt gay ma krah hăn ta n'gor Êjipt, sa lĕ rngôch gơ̆ tâm n'gor, lĕ rngôch ndơ hôm bơh pler.”$b$,true),
('bunong-vn','EXO',10,13,null,$b$Pô ri Y-Môis yơr mâng păng leo ta n'gor Êjipt jêh ri Yêhôva ăn sial pa lơ khôm tâm n'gor lĕ nar lĕ măng. Tơ lah tât ơm ôi sial tă pa lơ djôt krah.$b$,false),
('bunong-vn','EXO',10,14,null,$b$Krah gŭ lam n'gor Êjipt jêh ri nkŭm lam n'gor nây. Khân păng âk ngăn ngên, mâu mâp geh ôh Krah tâm ban pô nây, jêh ri mâu mra geh lĕ tâm nar Kăndơ̆ .$b$,false),
('bunong-vn','EXO',10,15,null,$b$Khân păng nkŭm lam neh kŏ neh jêng ngo. Khân păng sa lĕ gơ̆ neh jêh ri lĕ rngôch play tơm play ăt hôm bơh pler jêh ri mâu hôm geh ndơ ndrêh ôh gĭt lah tơm si mâu lah gơ̆ mir lam n'gor Êjipt.$b$,false),
('bunong-vn','EXO',10,16,null,$b$Pô ri Pharaôn kuăl ndal Y-Môis jêh ri Y-Arôn, lah: “Gâp ƀư tih jêh đah Yêhôva Brah Ndu khân may, jêh ri đah khân may.$b$,false),
('bunong-vn','EXO',10,17,null,$b$Aƀaơ gâp dăn ma may, yô̆ an nau tih gâp knŏng du tơ̆ aơ, jêh ri mbơh sơm hom ma Yêhôva Brah Ndu khân may, gay ma păng sŏk lơi bơh gâp nau khĭt aơ.”$b$,true),
('bunong-vn','EXO',10,18,null,$b$Y-Môis luh bơh ngih Pharaôn jêh ri mbơh sơm ma Yêhôva Brah Ndu.$b$,false),
('bunong-vn','EXO',10,19,null,$b$Yêhôva ăn sial khôm tă pa dâng ktang khôm lơi krah jêh ri ăn tŭp tâm dak mƀŭt chăng, mâu hôm du mlâm krah ôh tâm n'gor Êjipt.$b$,false),
('bunong-vn','EXO',10,20,null,$b$Ƀiă lah Yêhôva ƀư dăng nuih Pharaôn, jêh ri păng mâu ăn phung ƀon lan Israel hăn ôh.$b$,false),
('bunong-vn','EXO',10,21,null,$b$Yêhôva lah ma Y-Môis: “Yơr ti may leo klơ trôk gay geh nau ngo lam bri Êjipt, nau ngo klĕng.”$b$,true),
('bunong-vn','EXO',10,22,null,$b$Y-Môis yơr ti păng leo klơ trôk, jêh ri geh nau ngo mbâl tâm lam bri Êjipt dôl tâm pe nar.$b$,false),
('bunong-vn','EXO',10,23,null,$b$Bu mâu dơi tâm saơ ndrăng nơm ôh, jêh ri mâu geh nơm dâk tă bơh ntŭk păng gŭ tâm lĕ pe nar. Ƀiă lah geh nau ang tâm lĕ ntŭk phung ƀon lan Israel gŭ.$b$,false),
('bunong-vn','EXO',10,24,null,$b$Pharaôn kuăl Y-Môis jêh ri lah: “Hăn hom khân may pah kan ma Yêhôva. Ăn phung kon se jê̆ khân may hăn ndrel khân may. Knŏng ăn biăp jêh ri ndrôk khân may ăn gŭ ta aơ.”$b$,false),
('bunong-vn','EXO',10,25,null,$b$Ƀiă lah Y-Môis lah: “Ăn may ăn ma hên ndơ ƀư brah jêh ri ndơ nhhơr gŭch hên mra ƀư brah ma Yêhôva Brah Ndu hên.$b$,false),
('bunong-vn','EXO',10,26,null,$b$Biăp, ndrôk hên mra hăn ndrel ma hên, mâu mra om du pŏk nchop ôh; yor lah ƀa ƀă hên mra ŭch nhhơr ndơ nây gay pah kan ma Yêhôva Brah Ndu hên, jêh ri kŏ hên tât ta nây, hên mâu gĭt ôh moh hên mra săch pah kan ma Yêhôva.$b$,false),
('bunong-vn','EXO',10,27,null,$b$Ƀiă lah Yêhôva ƀư dăng nuih n'hâm Pharaôn, jêh ri păng mâu ăn ôh phung nây hăn.$b$,false),
('bunong-vn','EXO',10,28,null,$b$Pharaôn lah ma Y-Môis: “Du hom bơh gâp, njrăng hom! Lơi hôm văch ta năp gâp ôh yor lah ta nar may plơ̆ văch ta năp gâp may mra khĭt.”$b$,false),
('bunong-vn','EXO',10,29,null,$b$Y-Môis lah: “Di jêh nau may lah; gâp mâu mra plơ̆ văch ta năp may ôh.”$b$,false),
('bunong-vn','EXO',11,1,null,$b$Yêhôva lah ma Y-Môis: “Gâp mra lŏ ăn tât du ntil nau rêh ni ma Pharaôn jêh ri ma n'gor Êjipt. Jêh nau nây păng mra ăn khân may. Tơ lah păng mra ăn khân may hăn, păng mra nsot khân may.$b$,true),
('bunong-vn','EXO',11,2,null,$b$Ngơi hom ma phung ƀon lan gay ma ăp nơm bu klâu dăn ma phung chiau meng păng jêh ri ăp nơm bu ur dăn ma phung chiau meng păng ndơ khlay prăk jêh ri mah.”$b$,false),
('bunong-vn','EXO',11,3,null,$b$Yêhôva ăn phung ƀon lan geh nau yô̆ ta năp măt phung Êjipt. Nđâp Y-Môis nơm geh nau lư n'gâr tâm n'gor Êjipt ta năp phung oh mon Pharaôn jêh ri phung ƀon lan.$b$,false),
('bunong-vn','EXO',11,4,null,$b$Y-Môis lah: “Pô aơ Yêhôva ngơi; ta n'gul măng gâp mra rgăn n'gor Êjipt.$b$,true),
('bunong-vn','EXO',11,5,null,$b$Jêh ri lĕ rngôch kon kôranh tâm n'gor Êjipt mra khĭt; ntơm bơh kon bôk rah Pharaôn gŭ ta sưng hađăch păng, tât ta kon kôranh oh mon bu ur gŭ pa kơi mpăl, jêh ri nđâp ma kon bôk rah mpô mpa khân păng rong.$b$,false),
('bunong-vn','EXO',11,6,null,$b$Mra geh tâm lam n'gor Êjipt nau nđêng nter, nau pô nây mâu mâp geh ôh, mâu lĕ mra geh đŏng nau tâm ban pô nây.$b$,true),
('bunong-vn','EXO',11,7,null,$b$Ƀiă lah ta nklang lĕ rngôch phung ƀon lan Israel, phung bunuyh nđâp ma mpô mpa rong, mâu geh du mlâm so mra groh ôh; gay ma khân may gĭt Yêhôva kơp phung Êjipt êng đah phung Israel.$b$,false),
('bunong-vn','EXO',11,8,null,$b$Lĕ rngôch phung oh mon may aơ mra văch ta gâp, jêh ri păn mbah ta năp gâp, lah: “Hăn hom, may jêh ri lĕ rngôch phung ƀon lan tĭng may! Jêh ri nau nây gâp mra hăn.” Y-Môis luh tă bơh Pharaôn ma nau nuih ngăn.$b$,false),
('bunong-vn','EXO',11,9,null,$b$Yêhôva lah jêh ma Y-Môis: “Pharaôn mâu mra iăt nau may ôh, gay ăn nau khlay jêng âk tâm n'gor Êjipt.”$b$,true),
('bunong-vn','EXO',11,10,null,$b$Y-Môis jêh ri Y-Arôn ƀư lĕ rngôch nau khlay aơ ta năp Pharaôn; jêh ri Yêhôva ƀư dăng nuih Pharaôn. Pharaôn mâu ăn ôh phung ƀon lan Israel du luh tă bơh n'gor păng.$b$,false),
('bunong-vn','EXO',12,1,null,$b$Yêhôva lah ma Y-Môis jêh ri Y-Arôn tâm n'gor Êjipt.$b$,true),
('bunong-vn','EXO',12,2,null,$b$“Khay aơ jêng ma khân may khay tal lor lơn; păng mra jêng ma khân may khlay tal nguay tâm năm,$b$,false),
('bunong-vn','EXO',12,3,null,$b$ngơi ma lĕ rngôch phung Israel tâm rƀŭn pô aơ,” Nar tal jât khay aơ, ăn ăp nơm bu klâu sŏk du mlâm kon biăp ăp rnăk sa, du mlâm kon biăp ma ăp ngih.$b$,false),
('bunong-vn','EXO',12,4,null,$b$Tơ lah ngih djê̆ ir bunuyh ma du mlâm kon biăp, ăn bu sŏk păng ndrel ma phung chiau meng dăch lơn tĭng nâm dŭm âk bunuyh, khân may kơp biăp tĭng nâm dơi sa.$b$,false),
('bunong-vn','EXO',12,5,null,$b$Kon biăp nây mâu mra geh ntŭk mhĭk ôh, nkuăng geh du năm jêh; khân may dơi sŏk du mlâm kon biăp mâu lah du mlâm kon be.$b$,false),
('bunong-vn','EXO',12,6,null,$b$Ăn khân may mât prăp păng tât ta nar tal jât ma puăn khay aơ; jêh ri ăn lĕ rngôch phung Israel rƀŭn sreh kon biăp khân păng ta ngo suâr vâr păr vik.$b$,false),
('bunong-vn','EXO',12,7,null,$b$Ăn khân păng sŏk ƀa ƀă mham jêh ri mhĭng ta bar đah pĭt mpông, jêh ri ta rkăng klơ mpông tâm ngih khân păng sa.$b$,false),
('bunong-vn','EXO',12,8,null,$b$Măng nây lĕ khân păng mra sa nglay puăch mpĭt nđông ta ŭnh; khân păng mra sa puăch nây ma piăng let mâu geh ndrui jêh ri đah trau tăng.$b$,false),
('bunong-vn','EXO',12,9,null,$b$Lơi ta khân may sa nglay puăch ndrêh mâu lah gâm tâm dak ôh, ƀiă lah ăn khân may mpĭt nđông ta ŭnh, nđâp ma bôk păng, jâng păng jêh ri ndơ tâm trôm.$b$,false),
('bunong-vn','EXO',12,10,null,$b$Lơi ta khân may cha lat du ntil ndơ hôm tât ôi ôh, ƀiă lah tơ lah geh ndơ hôm tât ôi, ăn khân may su lơi ma ŭnh.$b$,false),
('bunong-vn','EXO',12,11,null,$b$Pô aơ, ăn khân may sa păng; khân may mra rêt rse bŭt khân may, soh ntâu jot khân may, djôt mâng jra, jêh ri sa păng ma nau ndal; păng jêng Nau Yêhôva Găn.$b$,false),
('bunong-vn','EXO',12,12,null,$b$Yor lah măng nây gâp mra nkhĭt lĕ rngôch kon bôk rah tâm n'gor Êjipt, nđâp bunuyh jêh ri mpô mpa; jêh ri gâp mra ƀư nau phat dôih tâm rdâng đah lĕ rngôch brah n'gor Êjipt. Gâp jêng Yêhôva.$b$,false),
('bunong-vn','EXO',12,13,null,$b$Mham mra jêng nau tâm mbên yor khân may ta ngih khân may gŭ. Tơ lah gâp saơ mham gâp mra găn ta klơ khân may jêh ri mâu mra geh nau ji tưp ƀư rai khân may ôh dôl gâp ƀư ma n'gor Êjipt.$b$,false),
('bunong-vn','EXO',12,14,null,$b$Nau aơ mra jêng ma khân may du nar kah gĭt. Ăn khân may prăp jêng nau nhêt sông ma Yêhôva. Tâm lĕ rngôch rnôk ăn khân may prăp nau nhêt sông aơ jêng nau ntăm n'ho ro.$b$,true),
('bunong-vn','EXO',12,15,null,$b$“Dôl tâm pơh nar ăn khân may sa kapŭng mâu geh ndrui. Ta nar tal nguay ăn khân may sŏk rdu lơi ndrui bơh ngih khân may, yor lah tơ lah bu sa piăng let geh ndrui bơh nar tal nguay tât ta nar tal pơh, ăn bu nkhĭt lơi nơm nây bơh phung Israel.$b$,false),
('bunong-vn','EXO',12,16,null,$b$Nar tal nguay ăn khân may tâm rƀŭn kloh ueh, jêh ri nar tal pơh ăn khân may geh nau tâm rƀŭn kloh ueh tâm ban lĕ. Bu mâu dơi ƀư du ntil kan ôh tâm nar nây, knŏng bu dơi nkra ndơ sông sa ma ăp nơm.$b$,false),
('bunong-vn','EXO',12,17,null,$b$Ăn khân may kah gĭt prăp Nau Nhêt sa piăng let Mâu Geh Ndrui, yor lah di nar aơ lĕ gâp ngluh khân may luh bơh n'gor Êjipt. Yor nây ăn khân may kah gĭt prăp nar aơ tâm lĕ rngôch rnôk khân may jêng nau ntăm n'ho ro,$b$,false),
('bunong-vn','EXO',12,18,null,$b$khay tal nguay, nar jât ma puăn tâm nar nây, ta ngo suâr vâr pŭr vik, ăn khân may sa piăng let mâu geh ndrui, tât ta ngo suâr vâr păr vik nar bar jât ma nguay.$b$,false),
('bunong-vn','EXO',12,19,null,$b$Dôl pơh nar lơi ăn geh ndrui ôh tâm ngih khân may; yor lah tơ lah bu sa piăng let ndrui, nơm nây ăn bu nkhĭt lơi bơh phung Israel tâm rƀŭn, gĭt lah bunuyh nây gŭ jưh ƀât lât, mâu lah bunuyh bu deh tâm n'gor.$b$,false),
('bunong-vn','EXO',12,20,null,$b$Lơi khân may sa ôh ndơ geh ndrui; tâm lĕ rngôch ntŭk khân may gŭ ăn khân may sa piăng let mâu geh ndrui.”$b$,false),
('bunong-vn','EXO',12,21,null,$b$Y-Môis kuăl lĕ rngôch phung bu bŭnh bu ranh tâm phung Israel jêh ri lah ma khân păng. “Sŏk hom kon biăp tĭng nâm rnăk sa khân may, jêh ri sreh kon biăp Nau Găn.$b$,true),
('bunong-vn','EXO',12,22,null,$b$Sŏk du nchăp hisôp, trăm tâm mham bu dơm tâm mâm, jêh ri mprah mham ta rkăng klơ mpông jêh ri ta bar đah pĭt mpông ma mham tâm mâm. Lơi ăn bu du luh bơh ngih păng tât ôi.$b$,false),
('bunong-vn','EXO',12,23,null,$b$Yor lah Yêhôva mra găn gay ma nkhĭt phung Êjipt; jêh ri tơ lah păng saơ mham ta rkăng mpông jêh ri ta pĭt bar đah mpông. Yêhôva mra găn ta klơ mpông nây, jêh ri mâu ăn ôh nơm ƀư rai lăp tâm ngih gay ma nkhĭt khân may.$b$,false),
('bunong-vn','EXO',12,24,null,$b$Ăn khân may kah gĭt prăp nau aơ jêng nau ntăm n'ho ro, ma khân may jêh ri ma phung kon sau khân may.$b$,false),
('bunong-vn','EXO',12,25,null,$b$Tơ lah khân may lăp jêh tâm n'gor Yêhôva mra ăn ma khân may tĭng nâm păng hŏ ton jêh, ăn khân may kah gĭt prăp kan aơ.$b$,false),
('bunong-vn','EXO',12,26,null,$b$Jêh ri tơ lah phung kon khân may lah ma khân may: ‘Moh ŭch rblang kan aơ?’$b$,false),
('bunong-vn','EXO',12,27,null,$b$Ăn khân may lah: “Nau aơ jêng nau ƀư brah ma Nau Yêhôva Găn, yor lah păng găn jêh ta klơ ngih phung Israel tâm n'gor Êjipt, tơ lah păng nkhĭt phung Êjipt, ƀiă lah tâm rklaih ngih he.” Phung ƀon lan kŭnh bôk jêh ri mbah yơk.$b$,false),
('bunong-vn','EXO',12,28,null,$b$Phung ƀon lan Israel hăn ƀư pô nây. Khân păng ƀư tĭng nâm Yêhôva ntăm jêh ma Y-Môis jêh ri Y-Arôn.$b$,true),
('bunong-vn','EXO',12,29,null,$b$Ta klong măng Yêhôva nkhĭt lĕ rngôch phung kon bôk rah tâm n'gor Êjipt, ntơm bơh kon bôk rah Pharaôn gŭ ta sưng hađăch tât ta kon bôk rah bu nă tâm ndrung bu nă, nđâp ma lĕ rngôch bôk rah mpô mpa rong.$b$,true),
('bunong-vn','EXO',12,30,null,$b$Pharaôn dâk dôl măng, nđâp lĕ rngôch phung oh mon păng, jêh ri lĕ rngôch phung Êjipt; jêh ri geh nau nter huy tâm n'gor Êjipt, yor lah mâu geh ôh du rplay ngih lah mâu geh bunuyh khĭt.$b$,true),
('bunong-vn','EXO',12,31,null,$b$Măng nây lĕ Pharaôn kuăl Y-Môis jêh ri Y-Arôn, lah: “Dâk hom, du hom tă bơh nklang phung ƀon lan gâp, khân may jêh ri lĕ rngôch phung ƀon lan Israel. Hăn hom pah kan ma Yêhôva tĭng nâm khân may lah jêh.$b$,false),
('bunong-vn','EXO',12,32,null,$b$Sŏk djôt leo biăp khân may jêh ri mpô mpa rong khân may, tĭng nâm khân may lah, jêh ri du hom; jêh ri mât ton an ma gâp tâm ban lĕ.”$b$,false),
('bunong-vn','EXO',12,33,null,$b$Phung Êjipt ƀư ndal phung ƀon lan gay gơnh nsot khân păng bơh n'gor, yor lah khân păng lah: “Hên mra rai lôch lĕ rngôch.”$b$,true),
('bunong-vn','EXO',12,34,null,$b$Phung ƀon lan djôt piăng let lor ê pot ndrui, kât ndơ mon piăng let tâm bok ao khân păng tuy ta săng nglik.$b$,false),
('bunong-vn','EXO',12,35,null,$b$Phung ƀon lan Israel ƀư jêh tĭng nâm nau Y-Môis ntăm. Khân păng dăn jêh ma phung Êjipt ndơ khlay prăk jêh ri mah, jêh ri bok ao.$b$,false),
('bunong-vn','EXO',12,36,null,$b$Yêhôva ăn phung ƀon lan geh nau yô̆ ta năp măt phung Êjipt, jêh ri khân păng ăn tĭng nâm phung Israel dăn. Pô ri phung Israel sŏk pit ndô ndơ phung Êjipt.$b$,true),
('bunong-vn','EXO',12,37,null,$b$Phung ƀon lan Israel sak nsong bơh ƀon Ramêsê hăn ta ƀon Sukôt, geh tâm prao rhiăng nuyh bu klâu, mâu kơp ôh phung bu ur jêh ri phung kon.$b$,true),
('bunong-vn','EXO',12,38,null,$b$Geh âk băl mpôl hăn ndrel ma khân păng; khân păng geh âk biăp jêh ri mpô mpa rong.$b$,false),
('bunong-vn','EXO',12,39,null,$b$Khân păng gŭch ƀănh mâu geh ndrui ndrel ma piăng let djôt bơh n'gor Êjipt, yor lah piăng let nây ê rlŭk ndrui ôh, yor lah bu nsot khân păng ndal bơh n'gor Êjipt, mâu hôm dơi gŭ ôh, jêh ri mâu nkra lor ndơ sông sa ma khân păng nơm ôh.$b$,false),
('bunong-vn','EXO',12,40,null,$b$Nau jŏ phung ƀon lan Israel gŭ tâm n'gor Êjipt geh puăn rhiăng pe jât năm.$b$,true),
('bunong-vn','EXO',12,41,null,$b$Lôch puăn rhiăng pe jât năm, di nar nây yơh, lĕ rngôch phung ta han Yêhôva luh bơh n'gor Êjipt.$b$,true),
('bunong-vn','EXO',12,42,null,$b$Măng nây jêng măng Yêhôva mât mơh, ŭch njŭn leo ngluh phung Israel bơh n'gor Êjipt; yor nây tâm măng nây yơh jêng măng lĕ rngôch phung ƀon lan Israel kah gĭt prăp ma Yêhôva tâm lĕ rngôch rnôk.$b$,false),
('bunong-vn','EXO',12,43,null,$b$Yêhôva lah ma Y-Môis jêh ri ma Y-Arôn: “Aơ yơh nau ntăm ma Nau Găn; mâu geh du huê bu năch mra sa păng ôh.$b$,true),
('bunong-vn','EXO',12,44,null,$b$Ƀiă lah lĕ rngôch oh mon bu rvăt ma prăk dơi sa tơ lah bu koh jêh ntâu păng.$b$,false),
('bunong-vn','EXO',12,45,null,$b$Du huê gŭ jưh ƀât jêh ri oh mon nkhôm mâu dơi sa ôh.$b$,false),
('bunong-vn','EXO',12,46,null,$b$Bu mra sa Nau Găn tâm du rplay ngih. Lơi ta khân may leo nglay pa dih ngih ôh, mâu lĕ dơi ăn khân may ƀư deh du mlâm nting.$b$,false),
('bunong-vn','EXO',12,47,null,$b$Ăn lĕ rngôch phung Israel tâm rƀŭn kah gĭt prăp.$b$,false),
('bunong-vn','EXO',12,48,null,$b$Tơ lah du huê bu năch gŭ ndrel ma khân may ŭch kah gĭt prăp Nau Găn ta năp Yêhôva, ăn lĕ rngôch bu klâu tâm ngih păng dơn nau koh ntâu, pô ri mơ ăn păng kah gĭt prăp Nau Găn, bu mra kơp păng tâm ban ma nơm bu deh tâm n'gor; ƀiă lah mâu ăn ôh du huê mâu koh ntâu sa.$b$,false),
('bunong-vn','EXO',12,49,null,$b$Mra geh du nau vay ma mbu nâm deh tâm n'gor jêh ri ma bu năch gŭ ndrel ma khân may.”$b$,false),
('bunong-vn','EXO',12,50,null,$b$Lĕ rngôch phung ƀon lan Israel ƀư pô nây, tĭng nâm Yêhôva ntăm jêh ma Y-Môis jêh ri Y-Arôn.$b$,true),
('bunong-vn','EXO',12,51,null,$b$Nar nây lĕ Yêhôva njŭn ngluh phung ƀon lan Israel bơh n'gor Êjipt, dăp nâm bu ta han.$b$,false),
('bunong-vn','EXO',13,1,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',13,2,null,$b$“Ăn may prăp an ma gâp lĕ rngôch kon bôk rah lĕ rngôch kon bôk rah tâm phung kon bu klâu Israel, nđâp bunuyh, nđâp mpô mpa jêng ndơ gâp.”$b$,false),
('bunong-vn','EXO',13,3,null,$b$Y-Môis lah ma phung ƀon lan, ăn khân may kah gĭt ma nar aơ, nar khân may luh jêh bơh n'gor Êjipt, bơh ngih jêng dĭk, yor lah ma ti brah Yêhôva ngluh jêh khân may bơh ntŭk aơ, lơi ăn bu sa piăng let ndrui ôh.$b$,true),
('bunong-vn','EXO',13,4,null,$b$Khân may luh nar aơ tâm khay puăn.$b$,false),
('bunong-vn','EXO',13,5,null,$b$Tơ lah Yêhôva ăn khân may lăp tâm n'gor phung Kanaan, phung Hivit, phung Amôrit, phung Hivit, jêh ri phung Jêbusit, ntŭk păng ton ăn jêh ăn ma phung che khân may n'gor geh ndơ sông sa nhêt rmeh ler, ăn khân may kah gĭt prăp kan aơ tâm khay aơ.$b$,true),
('bunong-vn','EXO',13,6,null,$b$Dôl tâm mpơl nar ăn khân may sa piăng let mâu geh ndrui jêh ri nar tal pơh mra geh nau sông sa nhêt ma Yêhôva.$b$,true),
('bunong-vn','EXO',13,7,null,$b$Ăn khân may sa piăng let mâu geh ndrui tâm pơh nar. Lơi ăn bu saơ piăng let ndrui ôh tâm ngih khân may, mâu lĕ ăn bu saơ ndrui tâm lam n'gor khân may.$b$,false),
('bunong-vn','EXO',13,8,null,$b$Nar nây ăn khân may lah ma kon bu klâu khân may. He ƀư nau aơ yor Yêhôva ƀư ueh jêh ma gâp tơ lah gâp du luh bơh n'gor Êjipt.$b$,false),
('bunong-vn','EXO',13,9,null,$b$Ăn khân may geh nau mbên ta ti khân may jêh ri ndơ kah gĭt ta vah vang măt khân may, gay ma nau vay Yêhôva dơi gŭ tâm trôm mbung khân may, yor lah ma ti brah Yêhôva ngluh jêh khân may bơh n'gor Êjipt.$b$,false),
('bunong-vn','EXO',13,10,null,$b$Pô ri ăn khân may kah gĭt prăp nau ntăm aơ di yăn păng ăp nơm ƀa ƀơ.$b$,false),
('bunong-vn','EXO',13,11,null,$b$“Tơ lah Yêhôva mra ăn khân may lăp tâm n'gor Kanaan, tĭng nâm păng ton ăn jêh ma khân may jêh ri ma phung che khân may, jêh ri păng mra ăn ma khân may.$b$,true),
('bunong-vn','EXO',13,12,null,$b$Ăn khân may prăp an ma Yêhôva lĕ rngôch kon bôk rah; lĕ rngôch kon bôk rah nkuăng mpô mpa rong jêng ndơ Yêhôva.$b$,false),
('bunong-vn','EXO',13,13,null,$b$Ăn khân may tâm chuai đah du mlâm kon biăp ăp mlâm kon bôk rah seh bri, jêh ri tơ lah khân may mâu tâm chuai păng ôh, ăn khân may juet lơi trô ko păng. Ăn khân may tâm chuai lĕ ăp nơm kon bôk rah bunuyh tâm phung kon bu klâu khân may.$b$,false),
('bunong-vn','EXO',13,14,null,$b$Tơ lah kon bu klâu khân may ôp khân may tâm nar kăndơ̆ . Moh nau nây ŭch rblang?’ Ăn khân may lah ma păng. Ma ti Brah Yêhôva ngluh jêh hên bơh n'gor Êjipt, bơh ngih jêng dĭk.$b$,false),
('bunong-vn','EXO',13,15,null,$b$Yor lah tơ lah Pharaôn dăng bôk mâu ăn hên hăn ôh, Yêhôva nkhĭt lĕ rngôch kon bu klâu bôk rah, kon bôk rah bunuyh nđâp ma kon bôk rah mpô mpa. Pô nây gâp nhhơr jêng ndơ ƀư brah ma Yêhôva; lĕ rngôch kon bôk rah nkuăng; ƀiă lah gâp tâm chuai lĕ rngôch kon bôk rah tâm phung kon bu klâu gâp.$b$,true),
('bunong-vn','EXO',13,16,null,$b$Ăn khân may geh nau mbên ta ti jêh ri ndơ kât ta vah vang măt khân may yor lah ma ti nau brah Yêhôva ngluh jêh hên bơh n'gor Êjipt.”$b$,false),
('bunong-vn','EXO',13,17,null,$b$Tơ lah Pharaôn ăn phung ƀon lan hăn Brah Ndu mâu njŭn leo ôh khân păng ta trong n'gor phung Philistin, nđâp tơ lah dăch kđôi lĕ; yor lah Brah Ndu lah: “Klach lah phung ƀon lan plơ̆ sĭt pa kơi tơ lah saơ nau tâm lơh jêh ri plơ̆ sĭt ta n'gor Êjipt.”$b$,true),
('bunong-vn','EXO',13,18,null,$b$Ƀiă lah Brah Ndu njŭn leo phung ƀon lan ndăch dăr ta trong bri rdah mơ pa Dak Rlai Chăng. Phung ƀon lan Israel luh bơh n'gor Êjipt djôt ndơ tâm lơh.$b$,true),
('bunong-vn','EXO',13,19,null,$b$Y-Môis djôt ndrel ma păng nting Y-Yôsep; yor lah Y-Yôsep ăn phung ƀon lan Israel ton sơm ktang ngăn, lah ma khân păng, Brah Ndu mra khâl khân may; jêh ri ăn khân may ndjôt leo ndrel ma khân may nting gâp bơh ntŭk aơ.”$b$,false),
('bunong-vn','EXO',13,20,null,$b$Khân păng hăn bơh ƀon Sukôt, jêh ri jưh ta Êtam ta n'har bri rdah.$b$,false),
('bunong-vn','EXO',13,21,null,$b$Yêhôva hăn lor pa năp khân păng dôl nôk nar tâm du n'gâng tŭk, gay njŭn leo khân păng njŏ rŏ trong, jêh ri dôl măng tâm du n'gâng tŭk, gay njŭn leo khân păng njŏ rŏ trong, jêh ri dôl măng tâm du n'gâng ŭnh, gay ma ăn ang khân păng, gay ma khân păng dơi hăn dôl nôk nar nđâp măng.$b$,false),
('bunong-vn','EXO',13,22,null,$b$N'gâng tŭk mâu du ôh pa năp phung ƀon lan dôl nôk nar, n'gâng ŭnh mâu lĕ du dôl măng.$b$,false),
('bunong-vn','EXO',14,1,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',14,2,null,$b$“Ntăm hom ma phung ƀon lan Israel, ăn khân păng plơ̆ sĭt pa kơi jêh ri jưh ta năp Pihahirôt, vah vang Mikdôl jêh ri dak rlai, ta năp Bal Sêphôn, ta ntŭk nây yơh ăn khân may jưh dăch dak rlai.$b$,false),
('bunong-vn','EXO',14,3,null,$b$Yor lah Pharaôn mra lah: ‘Phung ƀon lan Israel nhhơt bri tâm n'gor; khân păng krŭng jêh tâm bri rdah.$b$,false),
('bunong-vn','EXO',14,4,null,$b$Gâp mra ƀư dăng nuih Pharaôn, jêh ri păng mra tĭng, jêh ri gâp mra geh nau chrêk rmah yor Pharaôn jêh ri lĕ rngôch phung ta han păng; jêh ri phung Êjipt mra gĭt ma gâp jêng Yêhôva.” Phung ƀon lan Israel ƀư pô nây.$b$,false),
('bunong-vn','EXO',14,5,null,$b$Tơ lah bu mbơh ma hađăch Êjipt phung ƀon lan du jêh, nuih n'hâm Pharaôn jêh ri phung oh mon păng tâm rgâl. Khân păng lah: “Moh nau he ƀư jêh, ăn phung Israel hăn mâu hôm pah kan ma he ôh.”?$b$,true),
('bunong-vn','EXO',14,6,null,$b$Pô ri păng nkra ndeh seh păng jêh ri sŏk phung ta han păng ndrel ma păng.$b$,false),
('bunong-vn','EXO',14,7,null,$b$Păng sŏk prao rhiăng bôk ndeh seh ueh lơn, jêh ri lĕ rngôch ndeh seh êng tâm n'gor Êjipt, nđâp kôranh ta han chiă lĕ khân păng.$b$,false),
('bunong-vn','EXO',14,8,null,$b$Yêhôva ƀư dăng nuih Pharaôn hađăch Êjipt, jêh ri păng tĭng phung ƀon lan Israel dôl phung ƀon lan Israel luh ma nau janh.$b$,false),
('bunong-vn','EXO',14,9,null,$b$Phung Êjipt tĭng khân păng, lĕ rngôch seh, ndeh seh, phung rmăk seh, jêh ri phung ta han Pharaôn, jêh ri ban khân păng gŭ jưh dăch dak rlai ta Pihahirôt ta năp Baal Sêphôn.$b$,false),
('bunong-vn','EXO',14,10,null,$b$Tơ lah Pharaôn ntơm dăch, phung ƀon lan Israel n'gơr uănh, aơ phung Êjipt dôl hăn pa kơi khân păng, jêh ri phung ƀon lan Israel klach hâu ngăn. Khân păng nter ma Yêhôva.$b$,true),
('bunong-vn','EXO',14,11,null,$b$Jêh ri lah ma Y-Môis: “Yor lah mâu hĕ geh môch tâm n'gor Êjipt, pô ri may leo hên, gay ma hên khĭt tâm bri rdah?$b$,false),
('bunong-vn','EXO',14,12,null,$b$Phâm may ƀư ma hên, ăn hên luh bơh n'gor Êjipt? Mâu di hĕ, pô aơ hên lah ma may tâm n'gor Êjipt. ‘Lơi hên, ăn hên pah kan ma phung Êjipt ma khĭt tâm bri rdah.”$b$,true),
('bunong-vn','EXO',14,13,null,$b$Y-Môis lah ma phung ƀon lan: “Lơi klach ôh, gŭ nâp jêh ri kâp uănh nau Yêhôva tâm rklaih mra ăn ma khân may nar aơ; yor lah phung Êjipt khân may saơ nar aơ, khân may mâu mra saơ đŏng ôh.$b$,true),
('bunong-vn','EXO',14,14,null,$b$Yêhôva mra tâm lơh an ma khân may, jêh ri ăn khân knŏng gŭ đăp mpăn.”$b$,false),
('bunong-vn','EXO',14,15,null,$b$Yêhôva lah ma Y-Môis: “Mâm ƀư may nter ma gâp? Ntăm ma phung ƀon lan Israel ăn khân păng hăn pa năp.$b$,true),
('bunong-vn','EXO',14,16,null,$b$Yơr hom mâng may, yơr ti may mơ pa dak rlai jêh ri tâm pă păng, gay ma phung ƀon lan Israel dơi rgăn ta nklang dak rlai ta neh sơh.$b$,false),
('bunong-vn','EXO',14,17,null,$b$Gâp mra ƀư dăng nuih n'hâm phung Êjipt, pô ri khân păng mra tĭng phung Israel tâm dak rlai jêh ri gâp mra geh nau chrêk rmah yor Pharaôn jêh ri lĕ rngôch phung tahan păng, ndeh seh păng jêh ri lĕ rngôch phung rmăk seh păng.$b$,false),
('bunong-vn','EXO',14,18,null,$b$Phung Êjipt mra gĭt ma gâp jêng Yêhôva. Jêh gâp geh nau, chrêk rmah yor Pharaôn, ndeh seh păng jêh ri phung rmăk biăp păng.$b$,false),
('bunong-vn','EXO',14,19,null,$b$Jêh ri tông mpăr ueh Brah Ndu, nơm hăn lor pa năp phung Israel, hăn pa kơi khân păng; jêh ri n'gâng tŭk du ta năp khân păng jêh ri gŭ pa kơi khân păng.$b$,true),
('bunong-vn','EXO',14,20,null,$b$Păng gŭ tâm nklang phung Êjipt jêh ri phung Israel. Geh ndâr tŭk jêh ri nau ngo. Jêh ri bar phung nây mâu tâm êp ôh dôl lĕ măng.$b$,false),
('bunong-vn','EXO',14,21,null,$b$Y-Môis yơr ti păng mơ pa dak rlai nđâp sial ktang bơh lơ lĕ măng, ƀư sơh dak rlai jêh ri dak tâm pă.$b$,true),
('bunong-vn','EXO',14,22,null,$b$Phung ƀon lan Israel lăp tâm nklang dak rlai, ta neh sơh jêh ri dak jêng nâm bu mpêr pa ma jêh ri pa chiau khân păng.$b$,false),
('bunong-vn','EXO',14,23,null,$b$Phung Êjipt tĭng khân păng, lĕ rngôch seh Pharaôn ndeh seh păng jêh ri phung rmăk seh păng lăp pa kơi khân păng tâm nklang dak rlai.$b$,false),
('bunong-vn','EXO',14,24,null,$b$Ôi ơm bơh n'gâng ŭnh, jêh ri tŭk Yêhôva gŭ uănh ma phung ta han Êjipt, jêh ri nhhu phung ta han Êjipt.$b$,false),
('bunong-vn','EXO',14,25,null,$b$Păng ƀư iang jâng ndeh seh jêh ri ƀư jêr khân păng nchuăt; jêh ri phung Êjipt lah. “Ăn he du bơh phung Israel, yor lah Yêhôva tâm lơh an ma khân păng ƀư ma phung Êjipt.”$b$,false),
('bunong-vn','EXO',14,26,null,$b$Yêhôva lah ma Y-Môis: “Yơr hom ti may mơ pa dak rlai, gay ma dak nkŭm bŭk phung Êjipt, ndeh seh jêh ri phung rmăk seh khân păng.”$b$,true),
('bunong-vn','EXO',14,27,null,$b$Pô ri Y-Môis yơr ti păng mơ pa dak rlai, jêh ri dak rlai lŏ plơ̆ jêng nâm bu sa ơm. Phung Êjipt du tơ lah saơ dak hŏ dăch tât. Ƀiă lah Yêhôva nkhĭt phung Êjipt tâm nklang dak rlai.$b$,false),
('bunong-vn','EXO',14,28,null,$b$Dak plơ̆ nkŭm bŭk ndeh seh, phung rmăk seh jêh ri lĕ rngôch phung ta han Pharaôn lăp jêh tâm dak rlai, mâu klaih du huê ôh.$b$,false),
('bunong-vn','EXO',14,29,null,$b$Ƀiă lah phung ƀon lan Israel hăn ta nklang dak rlai ta neh sơh, ƀiă lah dak jêng pêr pa ma jêh ri pa chiau khân păng.$b$,false),
('bunong-vn','EXO',14,30,null,$b$Pô ri nar nây Yêhôva rklaih phung Israel bơh ti phung Êjipt, jêh ri phung Israel saơ săk jăn khĭt phung Êjipt ta kơh dak rlai.$b$,true),
('bunong-vn','EXO',14,31,null,$b$Phung Israel saơ jêh nau brah Yêhôva ƀư ma phung Êjipt, jêh ri phung ƀon lan klach yơk ma Yêhôva; jêh ri khân păng chroh ma Yêhôva jêh ri ma oh mon păng Y-Môis.$b$,true),
('bunong-vn','EXO',15,1,null,$b$Y-Môis jêh ri phung ƀon lan păng mprơ nau mprơ aơ ma Yêhôva, lah: “Gâp mra mprơ ma Yêhôva, yor lah păng dơi ma nau chrêk rmah; păng mƀăr lơi jêh tâm dak rlai seh jêh ri rmăk păng.$b$,true),
('bunong-vn','EXO',15,2,null,$b$Yêhôva jêng nau ktang gâp jêh ri nau mprơ gâp, păng yơh jêng nau tâm rklaih gâp; nơm aơ jêng Brah Ndu gâp, gâp mra tâm rnê ma păng. Păng jêng Brah Ndu mbơ̆ gâp, gâp mra yơk ma păng.$b$,true),
('bunong-vn','EXO',15,3,null,$b$Yêhôva jêng ta han blau tâm lơh; Yêhôva jêng amoh păng.$b$,true),
('bunong-vn','EXO',15,4,null,$b$Păng mƀăr jêng tâm dak rlai ndeh seh jêh ri phung ta han Pharaôn; phung kôranh ta han păng săch jêh rmok jêh tâm Dak Rlai Chăng.$b$,true),
('bunong-vn','EXO',15,5,null,$b$Ntŭk jru nkŭm bŭk jêh khân păng; khân păng ngâm jêh tâm dâng dak rlai nâm bu du mlâm lŭ.$b$,true),
('bunong-vn','EXO',15,6,null,$b$“Ti ma may, Ơ Yêhôva, geh nau ktang chrêk rmah, ti ma may, Ơ Yêhôva ƀư rai jêh nơm rlăng.$b$,false),
('bunong-vn','EXO',15,7,null,$b$Ma nau toyh rnam may, may dơi jêh đah phung tâm rdâng đah may; may njuăl jêh nau may ji nuih, jêh ri ƀư rai khân păng nâm bu ŭnh sa rhe.$b$,true),
('bunong-vn','EXO',15,8,null,$b$Ma n'hâm tă bơh trôm muh may, dak bât lơi, dak lip ndâk nâm bu pêr; ntŭk jru jêng dăng tâm nklang dak rlai.$b$,false),
('bunong-vn','EXO',15,9,null,$b$Nơm rlăng lah: “Gâp mra tĭng, gâp mra ban, gâp mra tâm pă ndơ pit sŏk, gâp mra ƀư mpay nau gâp đah khân păng. Gâp mra tŏk đao gưm, ti gâp mra ƀư rai khân păng.”$b$,true),
('bunong-vn','EXO',15,10,null,$b$May khôm jêh ma sial may, dak rlai nkŭm bŭk jêh khân păng, khân păng ngâm jêh nâm bu ndrak tâm dak ktang.$b$,true),
('bunong-vn','EXO',15,11,null,$b$Mbu brah jêng tâm ban ma may, Ơ Yêhôva? Mbu jêng tâm ban ma may, chrêk rmah tâm nau kloh ueh, nơm blau ƀư klach ma kan chrêk rmah, ƀư âk nau khlay?$b$,false),
('bunong-vn','EXO',15,12,null,$b$May yơr jêh ti ma may, neh brôi jêh khân păng.$b$,true),
('bunong-vn','EXO',15,13,null,$b$Ma nau may rŏng răp jăp may njŭn jêh phung ƀon lan may tâm chuai jêh; may gai khân păng ma nau brah may ma ntŭk kloh ueh may gŭ.$b$,false),
('bunong-vn','EXO',15,14,null,$b$Phung băl mpôl bunuyh tăng jêh, khân păng râm sâr; nau klach toyh ƀư jêh ma phung Philistin.$b$,true),
('bunong-vn','EXO',15,15,null,$b$Aƀaơ aơ phung kôranh n'gor Êđôm geh nau rŭng răng; phung kôranh n'gor Môap râm sâr; lĕ rngôch phung gŭ tâm n'gor Kanaan du.$b$,true),
('bunong-vn','EXO',15,16,null,$b$Nau klach jêh ri nau krit tât ma khân păng, yor lah nting tur may ktang, khân păng jêng mlo nâm bu du mlâm lŭ, kŏ phung ƀon lan may rgăn jêh, Ơ Yêhôva, kŏ phung ƀon lan may rvăt jêh rgăn lĕ.$b$,true),
('bunong-vn','EXO',15,17,null,$b$May mra ăn khân păng lăp, jêh ri tăm khân păng ta klơ yôk may, ntŭk may nkra jêh jêng ntŭk may gŭ, Ơ Yêhôva, ntŭk kloh ueh ti may rdâk jêh, Ơ Kôranh Brah.$b$,true),
('bunong-vn','EXO',15,18,null,$b$Yêhôva mra chiă uănh ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','EXO',15,19,null,$b$Yor lah tơ lah seh Pharaôn, ndeh seh păng jêh ri phung rmăk seh păng lăp jêh tâm dak rlai. Yêhôva mplơ̆ jêh dak rlai ta klơ khân păng. Ƀiă lah phung ƀon lan Israel hăn ta neh sơh tâm nklang dak rlai.$b$,true),
('bunong-vn','EXO',15,20,null,$b$H'Miriam kôranh nơm mbơh lor bu ur, ruh Y-Arôn, djôt du mlâm gâr jê̆, jêh ri lĕ rngôch phung bu ur tĭng groi păng djôt gâr jê̆ jêh ri kadŏ.$b$,false),
('bunong-vn','EXO',15,21,null,$b$H'Miriam mprơ ma khân păng: “Mprơ hom ma Yêhôva; yor lah păng dơi jêh ma nau chrêk rmah; păng mƀăr jêh seh jêh ri rmăk tâm dak rlai.”$b$,true),
('bunong-vn','EXO',15,22,null,$b$Y-Môis njŭn leo phung Israel pa năp bơh Dak Rlai Chăng, khân păng hăn lăp bri rdah Sur. Khân păng hăn pe nar tâm bri rdah ƀiă lah mâu saơ dak ôh.$b$,true),
('bunong-vn','EXO',15,23,null,$b$Tơ lah khân păng tât ta Mara, khân păng mâu dơi nhêt dak Mara ôh yor lah dak nây tăng. Yor nây bu rnha ntŭk nây Mara.$b$,false),
('bunong-vn','EXO',15,24,null,$b$Phung ƀon lan ngơi ƀŭk dŭk suyh ma Y-Môis, lah: “Moh he mra nhêt?”$b$,false),
('bunong-vn','EXO',15,25,null,$b$Y-Môis nter ma Yêhôva, jêh ri Yêhôva ntĭm ma păng du n'gâng tơm si. Păng nklăch tơm si nây tâm dak jêh ri dak jêng ueh. Ta nây yơh Yêhôva ăn jêh nau vay jêh ri nau ntăm ma phung ƀon lan, jêh ri ta nây Yêhôva rlong uănh khân păng.$b$,false),
('bunong-vn','EXO',15,26,null,$b$Păng lah: “Tơ lah khân may gŭ iăt nanê̆ bâr Yêhôva, Brah Ndu khân may jêh ri ƀư nau di ta năp măt păng, tơ lah khân may rkêng tôr ma nau păng ntăm jêh ri tông lĕ rngôch nau vay păng, gâp mâu ăn tât ôh ma khân may du ntil nau ji gâp ƀư jêh ma phung Êjipt, yor lah gâp jêng Yêhôva, nơm ƀư bah khân may.”$b$,false),
('bunong-vn','EXO',15,27,null,$b$Khân păng tât ta dak Êlim. Ta nây geh jât ma bar ntŭk tu dak luh jêh ri pơh jât n'gâng tơm si play đung. Khân păng jưh ta nây dăch dak.$b$,true),
('bunong-vn','EXO',16,1,null,$b$Lĕ phung tâm rƀŭn phung ƀon lan Israel hăn bơh Êlim jêh ri tât ta bri rdah Sin vah vang Êlim đah Sinai ta nar jât ma prăm, khay bar jêh ri luh bơh n'gor Êjipt.$b$,true),
('bunong-vn','EXO',16,2,null,$b$Jêh ri lĕ phung tâm rƀŭn phung ƀon lan Israel ngơi bŭk dŭk suyh ma Y-Môis jêh ri Y-Arôn tâm bri rdah.$b$,false),
('bunong-vn','EXO',16,3,null,$b$Phung ƀon lan Israel lah ma khân păng: “Ueh lơn he khĭt jêh ma ti Yêhôva tâm n'gor Êjipt dôl he gŭ dăch glah puăch jêh ri sa kŏ hơm; yor lah khân may njŭn jêh hên tâm bri rdah aơ gay ăn khĭt ma nau ji ngot lĕ rngôch phung tâm rƀŭn aơ.”$b$,false),
('bunong-vn','EXO',16,4,null,$b$Jêh ri Yêhôva lah ma Y-Môis: “Aơ gâp mra ăn piăng let bơh trôk nâm bu dak mih tŭp ma khân may. Ăn phung ƀon lan luh hăn dônh tŏng ma du nar, gay ma gâp dơi rlong uănh khân păng gĭt lah khân păng hăn tĭng nâm nau vay gâp mâu lah mâu.$b$,true),
('bunong-vn','EXO',16,5,null,$b$Nar prăm khân păng mra nkra ndơ khân păng njŭn, pô ri geh bar tơ̆ âk lơn ma khân păng dônh ăp nar.”$b$,true),
('bunong-vn','EXO',16,6,null,$b$Pô ri Y-Môis jêh ri Y-Arôn lah ma phung ƀon lan Israel. “Mhaơ aơ ăn khân may gĭt Yêhôva yơh ăn khân may luh jêh bơh n'gor Êjipt.$b$,false),
('bunong-vn','EXO',16,7,null,$b$Jêh ri ta ôi khân may mra saơ nau chrêk rmah Yêhôva, yor lah păng tăng jêh nau khân may ngơi ƀŭk dŭk suyh ma Yêhôva. Yor lah mbu hên jêng kŏ khân may ngơi ƀŭk dŭk suyh ma hên?”$b$,false),
('bunong-vn','EXO',16,8,null,$b$Y-Môis lah: “Tơ lah Yêhôva ăn ma khân may mhaơ aơ puăch sa, jêh ri ta ôi piăng let kŏ hơm, yor lah Yêhôva tăng jêh nau khân may ngơi bŭk dŭk suyh ma mbu hên jêng? Mâu di ma hên ôh may ngơi ƀŭk dŭk suyh, ƀiă lah ma Yêhôva yơh.”$b$,false),
('bunong-vn','EXO',16,9,null,$b$Y-Môis lah ma Y-Arôn: “Lah ma lĕ rngôch phung tâm rƀŭn, phung ƀon lan Israel”, văch ăn êp hom ta năp Yêhôva, yor lah păng jêh nau khân may ngơi ƀŭk dŭk suyh.”$b$,true),
('bunong-vn','EXO',16,10,null,$b$Dôl Y-Arôn ngơi ma lĕ rngôch phung tâm rƀŭn ƀon lan Israel, khân păng uănh mơ pa ndrêch rdah, jêh ri Aơ, nau chrêk rmah Yêhôva tâm mpơl tâm ndâr tŭk.$b$,false),
('bunong-vn','EXO',16,11,null,$b$Yêhôva ngơi ma Y-Môis:$b$,false),
('bunong-vn','EXO',16,12,null,$b$“Gâp tăng jêh nau phung ƀon lan Israel ngơi ƀŭk dŭk suyh. Ăn may lah ma khân păng. ‘Ta ngo suâr vâr păr vik khân may mra sa puăch, jêh ri ta ôi khân may mra hơm ma kapŭng; jêh ri khân may mra gĭt gâp jêng Yêhôva Brah Ndu khân may.’ ”$b$,false),
('bunong-vn','EXO',16,13,null,$b$Ta ngo suâr vâr păr vik sĭm gôi tât jêh ri nkŭm ntŭk khân păng jưh; jêh ri ta ôi geh dak ngom jŭm ntŭk khân păng jưh.$b$,true),
('bunong-vn','EXO',16,14,null,$b$Tơ lah dak ngom nây sơh roh jêh geh ta klơ neh tâm bri rdah geh ndơ jê̆ jê̆ nâm bu găr, ndơ jê̆ jê̆ nâm bu glo pler nglang ta klơ neh.$b$,true),
('bunong-vn','EXO',16,15,null,$b$Tơ lah phung ƀon lan Israel saơ ndơ nây, khân păng tâm lah ndrăng nơm “Moh ndơ nây?” Yor lah khân păng mâu gĭt ôh moh ndơ nây jêng. Y-Môis lah: “Ndơ nây jêng piăng let Yêhôva ăn jêh ma khân may sa.$b$,false),
('bunong-vn','EXO',16,16,null,$b$Aơ nau Yêhôva ntăm ‘Ăn ăp nơm khân may dônh piăng let nây tŏng sa; pe lit n'gul ăp nơm, tĭng nâm dŭm âk bunuyh tâm ngih bok păng.’ ”$b$,false),
('bunong-vn','EXO',16,17,null,$b$Phung ƀon lan Israel ƀư pô nây; jêh ri khân păng dônh ƀă âk lơn, ƀă djê̆ lơn.$b$,false),
('bunong-vn','EXO',16,18,null,$b$Tơ lah khân păng veh ma du ômer, jêng pe lit n'gul, mbu nâm dônh âk mâu geh rmeh ôh, jêh ri mbu nâm dônh djê̆ mâu geh pưt ôh; ăp nơm dônh tŏng ma khân păng nơm sa.$b$,false),
('bunong-vn','EXO',16,19,null,$b$Y-Môis lah ma khân păng: “Lơi ăn bu prăp ndơ nây tât ta ôi ôh.”$b$,false),
('bunong-vn','EXO',16,20,null,$b$Ƀiă lah khân păng mâu gŭ iăt ôh nau Y-Môis, ƀă bunuyh prăp păng tât ôi, jêh ri păng jêng rhai, jêh ri ƀâu chrĭ. Y-Môis ji nuih ma phung nây.$b$,false),
('bunong-vn','EXO',16,21,null,$b$Ăp ôi ăp nơm dônh tŏng ma khân păng sa; jêh ri tơ lah duh nchrat nar ndơ nây lêk yơh.$b$,false),
('bunong-vn','EXO',16,22,null,$b$Nar prao khân păng dônh bar tơ̆ âk lơn, pơh lit ma ăp nơm. Lĕ rngôch phung kôranh n'gâng tâm phung tâm rƀŭn hăn mbơh nau nây ma Y-Môis.$b$,true),
('bunong-vn','EXO',16,23,null,$b$Y-Môis lah ma khân păng: “Nau aơ Yêhôva ntăm jêh. Ôi taơ jêng nar rlu, nar Saƀat kloh ueh ma Yêhôva. Gŭch hom moh ndơ khân may gŭch, gâm hom rnâng khân may ŭch gâm, jêh ri prăp tât ôi taơ lĕ ndơ hôm.”$b$,false),
('bunong-vn','EXO',16,24,null,$b$Pô ri khân păng prăp ndơ nây tât ôi tĭng nâm Y-Môis ntăm jêh; jêh ri ndơ nây mâu ôm ôh, mâu lĕ geh rhai.$b$,false),
('bunong-vn','EXO',16,25,null,$b$Y-Môis lah: “Sa hom ndơ nây nar aơ, yor lah nar aơ jêng nar Saƀat ma Yêhôva, nar aơ khân may mâu mra saơ ôh piăng let nây pa dih.$b$,false),
('bunong-vn','EXO',16,26,null,$b$Dôl tâm prao nar may mra dônh piăng let nây, ƀiă lah nar tal pơh jêng nar Saƀat, mâu mra geh piăng let nây ôh.”$b$,false),
('bunong-vn','EXO',16,27,null,$b$Nar tal pơh geh ƀa ƀă tâm phung ƀon lan luh gay dônh piăng let nây, ƀiă lah khân păng mâu saơ ôh.$b$,false),
('bunong-vn','EXO',16,28,null,$b$Jêh ri Yêhôva lah ma Y-Môis: “Ndah dĭng jŏ khân may mra dun mâu kơt ôh nau gâp ntăm jêh nau vay gâp?$b$,false),
('bunong-vn','EXO',16,29,null,$b$Ăn khân may gĭt rbăng, Yêhôva ăn jêh ma khân may nar Saƀat; yor ri ta nar prao păng ăn ma khân may Kapŭng tŏng ma bar nar. Ăn ăp nơm gŭ ta ntŭk păng nơm, jêh ri lơi ăn bunuyh du luh ôh tă bơh ntŭk khân păng gŭ tâm nar pơh.”$b$,false),
('bunong-vn','EXO',16,30,null,$b$Pô ri phung ƀon lan rlu tâm nar pơh.$b$,false),
('bunong-vn','EXO',16,31,null,$b$Ngih Israel rnha ndơ nây “mana” Păng jêng nâm bu grăp Kôriander, nglang, jêh ri sa, nâm bu ƀănh ƀư ma dak sŭt.$b$,false),
('bunong-vn','EXO',16,32,null,$b$Y-Môis lah: “Pô aơ Yêhôva ntăm jêh: ‘Prăp an pe lit tâm lĕ rngôch rnôk khân may, gay ma khân păng saơ piăng let gâp siăm khân may tâm bri rdah tơ lah gâp ngluh khân may luh bơh n'gor Êjipt.”$b$,false),
('bunong-vn','EXO',16,33,null,$b$Y-Môis lah ma Y-Arôn: “Sŏk du mlâm yăng, dơm pe lit n'gul mana tâm yăng nây, jêh ri n'gân yăng nây ta năp Yêhôva, gay prăp păng tâm lĕ rngôch rnôk khân may.”$b$,false),
('bunong-vn','EXO',16,34,null,$b$Tĭng nâm nau Brah Ndu Yêhôva ntăm ma Y-Môis, Y-Arôn n'gân yăng nây pa năp kđar Nau Mbơh gay prăp păng.$b$,false),
('bunong-vn','EXO',16,35,null,$b$Phung ƀon lan Israel sa mana dôl tâm puăn jât năm, kŏ khân păng tât tâm n'gor geh bunuyh gŭ; khân păng sa mana kŏ tât ta n'har bri n'gor Kanaan.$b$,false),
('bunong-vn','EXO',16,36,null,$b$(Du ômer jêng du kô̆ tâm jât êpha)$b$,false),
('bunong-vn','EXO',17,1,null,$b$Lĕ phung tâm rƀŭn phung ƀon lan Israel luh hăn tă bơh bri rdah Sin, hăn tĭng nâm nau Yêhôva ntăm ma khân păng, jêh ri khân păng jưh ta Rêphidim. Ta nây mâu geh dak nhêt ôh ma phung ƀon lan.$b$,true),
('bunong-vn','EXO',17,2,null,$b$Pô ri phung ƀon lan tâm rlăch đah Y-Môis, lah: “Ăn dak ma hên nhêt.” Y-Môis lah ma khân păng: “Mâm ƀư khân may tâm rlăch đah gâp? Mâm ƀư khân may lŏng uănh Yêhôva?”$b$,false),
('bunong-vn','EXO',17,3,null,$b$Ƀiă lah phung ƀon lan ji hir dak ta nây, jêh ri ngơi ƀŭk dŭk suyh ma Y-Môis. Khân păng lah: “Mâm ƀư khân may ngluh hên bơh n'gor Êjipt gay nkhĭt hên, phung kon hên jêh ri phung mpô mpa hên rong ma nau ji hir dak?$b$,false),
('bunong-vn','EXO',17,4,null,$b$Pô ri Y-Môis nter ma Yêhôva: “Moh gâp mra ƀư ma phung ƀon lan aơ? Khân păng mƀŏng ŭch klŭp gâp ma lŭ yơh.”$b$,false),
('bunong-vn','EXO',17,5,null,$b$Yêhôva lah ma Y-Môis: “Hăn ta năp phung ƀon lan, jêh ri jă ndrel ma may ƀă phung bu bŭnh bu ranh phung Israel. Sŏk djôt ta ti lĕ mâng may dong jêh dak krong, jêh ri hăn hom.$b$,false),
('bunong-vn','EXO',17,6,null,$b$Aơ, gâp mra gŭ ta năp may ta klơ lŭ ta yôk Hôrep; ăn may dong lŭ, jêh ri dak mra luh bơh lŭ nây, gay ma phung ƀon lan dơi nhêt.” Y-Môis ƀư pô nây ta năp măt phung bu bŭnh bu ranh Israel.$b$,false),
('bunong-vn','EXO',17,7,null,$b$Păng rnha ntŭk nây Masa jêh ri Mêriba, yor lah phung ƀon lan Israel tâm rlăng jêh ri rlong uănh Yêhôva, lah: “Yêhôva gŭ ta nklang phung hên mâu lah mâu?”$b$,false),
('bunong-vn','EXO',17,8,null,$b$Phung Amalek văch tâm lơh đah phung Israel ta Rêphidim.$b$,true),
('bunong-vn','EXO',17,9,null,$b$Y-Môis lah ma Y-Yôsuê: “Săch hom bunuyh, hăn tâm lơh hom đah phung Amalek. Ôi taơ gâp mra gŭ dâk ta klơ mbon neh djôt mâng Brah Ndu.”$b$,false),
('bunong-vn','EXO',17,10,null,$b$Pô ri Y-Yôsuê ƀư tĭng nâm nau Y-Môis lah ma păng, tâm lơh đah phung Amalek. Y-Môis, Y-Arôn jêh ri Y-Hur hao ta klơ mbon neh.$b$,false),
('bunong-vn','EXO',17,11,null,$b$Tơ lah Y-Môis yơr ti păng, phung Israel dơi; tơ lah păng n'glưh ti păng phung Amalek dơi.$b$,false),
('bunong-vn','EXO',17,12,null,$b$Ƀiă lah ti Y-Môis hŏ dăch rgănh. Khân păng sŏk du mlâm lŭ, dơm tâm dâng păng, jêh ri Y-Môis gŭ ta klơ lŭ nây. Y-Arôn jêh ri Y-Hur kuăn rdâng ti păng, du huê pa chiau, du huê pa ma, pô ri ti păng gŭ nâp tât ta nhâp nar.$b$,false),
('bunong-vn','EXO',17,13,null,$b$Jêh ri Y-Yôsuê dŏng măt đao gưm dơi đah Amalek jêh ri phung ƀon lan păng.$b$,true),
('bunong-vn','EXO',17,14,null,$b$Yêhôva lah ma Y-Môis: “Chih nau aơ tâm ndrom sămƀŭt ntâu gay kah gĭt jêh ri răk nau aơ ma Y-Yôsuê, nau gâp mra ƀư kŏ bu mâu hôm kah gĭt ôh, ma Amalek ta neh ntu.”$b$,true),
('bunong-vn','EXO',17,15,null,$b$Y-Môis rdâk nơng ƀư brah jêh ri rnha nơng nây Yêhôva Jêng N'ha Kơ Gâp.$b$,false),
('bunong-vn','EXO',17,16,null,$b$Bu yơr jêh ti ta n'ha kơ Yêhôva, Yêhôva mra geh nau tâm lơh đah phung Amalek tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','EXO',18,1,null,$b$Y-Jêtrô, Kôranh ƀư brah Midian, po Y-Môis, tăng lĕ nau Brah Ndu ƀư an jêh ma Y-Môis jêh ri ma phung ƀon lan păng Israel. Phâm nau Yêhôva ngluh phung Israel bơh n'gor Êjipt.$b$,true),
('bunong-vn','EXO',18,2,null,$b$Y-Jêtrô po Y-Môis rom jêh H'Sêpôra ur Y-Môis jêh ri Y-Môis ăn păng sĭt.$b$,false),
('bunong-vn','EXO',18,3,null,$b$Păng rom lĕ bar hê kon bu klâu H'Sêpôra, amoh du huê Y-Gersôn yor lah Y-Môis lah jêh: “Gâp jêng du huê gŭ jưh ƀât lât tâm n'gor bu năch.”$b$,false),
('bunong-vn','EXO',18,4,null,$b$Amoh du huê êng đŏng Y-Êliêser yor lah păng lah: “Brah Ndu mbơ̆ gâp kơl jêh gâp, jêh ri tâm rklaih gâp bơh đao gưm Pharaôn.”$b$,false),
('bunong-vn','EXO',18,5,null,$b$Y-Jêtrô, po Y-Môis ndrel ma phung kon bu klâu jêh ri ur Y-Môis văch ta bri rdah ta ntŭk Y-Môis jưh ta yôk Brah Ndu.$b$,true),
('bunong-vn','EXO',18,6,null,$b$Tơ lah bu mbơh ma Y-Môis: “Po may Y-Jêtrô văch ta may ndrel ma ur may jêh ri nđăp ma bar hê kon bu klâu ur may.”$b$,false),
('bunong-vn','EXO',18,7,null,$b$Y-Môis hăn luh gay tâm mâp đah po păng păn ta neh jêh ri chŭm. Păng ôp ma nau ngăch prăl khân păng, jêh ri lăp tâm ngih bok Y-Môis.$b$,true),
('bunong-vn','EXO',18,8,null,$b$Y-Môis nkoch bri ma po păng lĕ nau Yêhôva ƀư jêh ma Pharaôn jêh ri ma phung Êjipt yor phung Israel, lĕ rngôch nau rêh ni tât ta ma khân păng rŏ trong, jêh ri phâm nau Yêhôva tâm rklaih khân păng.$b$,false),
('bunong-vn','EXO',18,9,null,$b$Y-Jêtrô răm maak yor lĕ nau ueh Yêhôva ƀư ma phung Israel tâm nau păng tâm rklaih jêh khân păng bơh ti phung Êjipt.$b$,false),
('bunong-vn','EXO',18,10,null,$b$Jêh ri Y-Jêtrô lah: “Mât ton ma Yêhôva, nơm tâm rklaih jêh khân may bơh ti phung Êjipt jêh ri bơh ti Pharaôn.$b$,false),
('bunong-vn','EXO',18,11,null,$b$Aƀaơ gâp gĭt Yêhôva jêng toyh lơn ma lĕ rngôch brah êng, yor lah păng tâm rklaih phung ƀon lan bơh ti phung Êjipt tơ lah phung Êjipt ƀư ma khân păng ma nau sưr.”$b$,true),
('bunong-vn','EXO',18,12,null,$b$Y-Jêtrô nhhơr ma Brah Ndu ndơ nhhơr gŭch jêh ri ndơ ƀư brah. Y-Arôn jêh ri lĕ rngôch phung bu bŭnh bu ranh Israel văch sông sa ma po Y-Môis ta năp Brah Ndu.$b$,true),
('bunong-vn','EXO',18,13,null,$b$Ta ôi Y-Môis dâk ŭch phat dôih phung ƀon lan, jêh ri phung ƀon lan gŭ ta năp Y-Môis ntơm bơh ôi tât mhaơ.$b$,true),
('bunong-vn','EXO',18,14,null,$b$Tơ lah po păng saơ Y-Môis ƀư lĕ nau Y-Môis ƀư ma phung ƀon lan, păng lah: “Moh nau may ƀư aơ ma phung ƀon lan? Mâm ƀư êng du huê may gŭ, jêh ri lĕ rngôch phung ƀon lan gŭ râng ta năp may ntơm bơh ôi tât mhaơ?$b$,false),
('bunong-vn','EXO',18,15,null,$b$Y-Môis lah ma po păng: “Yor lah phung ƀon lan văch ta gâp ŭch ôp ma Brah Ndu.$b$,true),
('bunong-vn','EXO',18,16,null,$b$Tơ lah khân păng geh nau, khân păng văch ta gâp; jêh ri gâp ngơi an dôih khân păng, jêh ri gâp rblang nau vay Brah Ndu, jêh ri nau păng ngơi dôih.”$b$,true),
('bunong-vn','EXO',18,17,null,$b$Po Y-Môis lah ma păng: “Nau may ƀư nây mâu ueh ôh.$b$,false),
('bunong-vn','EXO',18,18,null,$b$May ƀư rgănh may nơm jêh ri may mra ƀư rgănh phung ƀon lan tâm ban lĕ, yor lah kan nây jâk ngăn ma may, êng du huê may mâu dơi ƀư ôh.$b$,true),
('bunong-vn','EXO',18,19,null,$b$Aƀaơ iăt hom, gâp mra nkah may jêh ri ăn Brah Ndu gŭ ndrel ma may. Ăn may jêng nơm tâm tang ma phung ƀon lan ta năp Brah Ndu.$b$,false),
('bunong-vn','EXO',18,20,null,$b$Ăn may nti ma khân păng nau ntăm jêh ri nau phat dôih, jêh ri ăn khân păng gĭt trong khân păng mra tĭng ndô̆ jêh ri kan khân păng mra ƀư.$b$,false),
('bunong-vn','EXO',18,21,null,$b$Jêh ri săch hom bơh phung ƀon lan phung bu klâu geh nau dơi, blau klach yơk ma Brah Ndu, sŏng srăng, rmot ma nau blŏl drăp. Ăn phung nây jêng Kôranh ma du rbăn nuyh, ma du rhiăng nuyh, ma prăm jât nuyh, jêh ri ma jât nuyh khân păng.$b$,false),
('bunong-vn','EXO',18,22,null,$b$Ăn khân păng phat dôih phung ƀon lan mro, ăn khân păng njŭn ta năp may lĕ rngôch dôih dak toyh, jêh ri ăn phung kôranh nây ngơi dôih jê̆ jê̆. Pô ri kan may n'gơch lơn, jêh ri khân păng mra kơl tuy ndrel ma may.$b$,false),
('bunong-vn','EXO',18,23,null,$b$Tơ lah may ƀư pô nây, jêh ri Brah Ndu ntăm nau nây lĕ, may dơi ƀư jêh lĕ kan, jêh ri lĕ rngôch phung ƀon lan aơ mra tât ma nau đăp mpăn ma ntŭk khân păng ŭch hăn.”$b$,true),
('bunong-vn','EXO',18,24,null,$b$Pô ri Y-Môis tông bâr po păng jêh ri ƀư lĕ nau păng lah jêh ma păng.$b$,true),
('bunong-vn','EXO',18,25,null,$b$Y-Môis săch phung bu klâu geh nau dơi bơh tâm nklang lĕ phung Israel, jêh ri dơm khân păng jêng kôranh ma phung ƀon lan, kôranh ma du rbăn nuyh, ma du rhiăng nuyh, ma prăm jât nuyh jêh ri ma jât nuyh.$b$,false),
('bunong-vn','EXO',18,26,null,$b$Khân păng phat dôih phung ƀon lan ƀa ƀơ. Khân păng njŭn ta năp Y-Môis nau dôih jêr, jêh ri khân păng ngơi êng khân păng nơm lĕ rngôch dôih dak jê̆ jê̆.$b$,false),
('bunong-vn','EXO',18,27,null,$b$Y-Môis ăn po păng hăn jêh ri Y-Jêtrô hăn sĭt ta n'gor păng nơm.$b$,false),
('bunong-vn','EXO',19,1,null,$b$Pe khay pa kơi jêh khân păng luh bơh n'gor Êjipt, ta nar nây yơh phung ƀon lan Israel tât ta bri rdah Sinai,$b$,true),
('bunong-vn','EXO',19,2,null,$b$Luh bơh Rephidim, khân păng tât ta bri rdah Sinai, jêh ri khân păng jưh tâm bri rdah ta năp yôk.$b$,false),
('bunong-vn','EXO',19,3,null,$b$Y-Môis hao yôk ma Brah Ndu, jêh ri Yêhôva kuăl păng bơh yôk, lah: “Ăn may ngơi ma ngih Y-Yakôb pô aơ jêh ri lah ma phung ƀon lan Israel:$b$,false),
('bunong-vn','EXO',19,4,null,$b$“Khân may saơ jêh nau gâp ƀư ma phung Êjipt, jêh ri phâm gâp yơk jêh khân may ma năr klang jêh ri njŭn leo jêh khân may ma gâp nơm.$b$,false),
('bunong-vn','EXO',19,5,null,$b$Pô ri aƀaơ, tơ lah khân may tông bâr gâp jêh ri ndjôt prăp nau gâp tâm rnglăp, khân may mra jêng ndơ gâp nơm ta nklang lĕ rngôch ƀon lan; yor lah lĕ neh ntu jêng ndơ gâp.$b$,true),
('bunong-vn','EXO',19,6,null,$b$Khân may mra jêng ma gâp du rplay ƀon bri hađăch phung kôranh ƀư brah jêh ri du phung mpôl băl kloh ueh. Pô ri jêng ăn nau may ngơi ma phung kon Israel.”$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','EXO',19,7,null,$b$Pô ri Y-Môis văch kuăl phung bu ranh phung ƀon lan, jêh ri păng tâm mpơl ma bu lĕ nau ngơi Yêhôva ntăm ăn jêh ma păng.$b$,true),
('bunong-vn','EXO',19,8,null,$b$Lĕ rngôch phung ƀon lan lah ndrel n'grŭp. “Hên mra ƀư lĕ nau Yêhôva lah jêh.” Y-Môis njŭn mbơh ma Yêhôva nau phung ƀon lan ngơi.$b$,false),
('bunong-vn','EXO',19,9,null,$b$Jêh ri Yêhôva lah ma Y-Môis: “Aơ gâp hăn ma may tâm ndâr tŭk mbâl, gay ma phung ƀon lan tăng tơ lah gâp ngơi ma may, jêh ri chroh ma may mro.” Y-Môis mbơh ma Yêhôva nau ƀon lan ngơi.$b$,false),
('bunong-vn','EXO',19,10,null,$b$Yêhôva lah ma Y-Môis: “Hăn hom ma phung ƀon lan, prăp an khân păng nar aơ jêh ri ôi taơ ăn khân păng pih lơi kho ao khân păng.$b$,false),
('bunong-vn','EXO',19,11,null,$b$Ăn khân păng njrăng ma nar tal pe; yor lah nar tal pe Yêhôva mra jŭr văch ta klơ yôk Sinai ta năp măt lĕ rngôch phung ƀon lan.$b$,false),
('bunong-vn','EXO',19,12,null,$b$Ăn khân may tâm nal n'har jŭm yôk ma phung ƀon lan, ăn may lah: ‘Njrăng hom khân may, lơi hao ta klơ yôk ôh, mâu lah dơi pah n'har yôk. Mbu nâm pah yôk mra khĭt.$b$,false),
('bunong-vn','EXO',19,13,null,$b$Bu mâu mra pah nơm ƀư pô nây ma ti ôh, ƀiă lah mra klŭp păng ma lŭ mâu lah pănh ma hăr, gĭt lah mpô mpa mâu lah bunuyh, păng mâu mra gŭ rêh ôh. Tơ lah tăng bâr nŭng nke biăp nkuăng bu mra uh jŏ, ăn khân păng hăn dăch yôk.”$b$,false),
('bunong-vn','EXO',19,14,null,$b$Pô ri Y-Môis jŭr tă bơh yôk hăn ta phung ƀon lan, jêh ri prăp an phung ƀon lan. Khân păng jưh kho ao khân păng.$b$,false),
('bunong-vn','EXO',19,15,null,$b$Păng lah ma phung ƀon lan: “Ăn khân may njrăng ma nar tal pe; lơi ta khân may bêch ndrel ma du huê bu ur ôh.”$b$,true),
('bunong-vn','EXO',19,16,null,$b$Nar tal pe, ta ôi, geh nglaih lơp jêh ri ndâr tŭk mbâl ta klơ yôk; bu tăng bâr nŭng huy ngăn, pô ri lĕ rngôch phung ƀon lan gŭ tâm ntŭk jưh râm sâr.$b$,false),
('bunong-vn','EXO',19,17,null,$b$Jêh ri Y-Môis njŭn leo phung ƀon lan du luh bơh ntŭk jưh hăn tâm mâp đah Brah Ndu; jêh ri khân păng gŭ njâng yôk.$b$,false),
('bunong-vn','EXO',19,18,null,$b$Lĕ yôk Sinai bêng ma nhhŭk ŭnh, yor Yêhôva jŭr gŭ ta nây tâm nklang ŭnh. Nhhuk ŭnh nây hao leo klơ nâm bu nhhŭk ŭnh bơh năk toyh jêh ri lĕ yôk n'gơ ngăn.$b$,true),
('bunong-vn','EXO',19,19,null,$b$Tơ bâr nŭng lơ hô nteh, Y-Môis ngơi, jêh ri Brah Ndu plơ̆ lah ma păng ma bâr nglaih.$b$,true),
('bunong-vn','EXO',19,20,null,$b$Pô ri Yêhôva jŭr ta kô yôk Sinai, jêh ri Yêhôva kuăl Y-Môis ăn hao ta klơ yôk. Jêh ri Y-Môis hao yôk lĕ.$b$,false),
('bunong-vn','EXO',19,21,null,$b$Yêhôva lah ma Y-Môis: ‘Jŭr hăn hom ma phung ƀon lan ăn khân păng njrăng, klach lah khân păng sâl uănh Yêhôva, jêh ri âk tâm phung khân păng rai yot.$b$,false),
('bunong-vn','EXO',19,22,null,$b$Ăn nđâp phung kôranh ƀư brah lĕ, phung văch êp Yêhôva, prăp an khân păng nơm, klach lah Yêhôva ƀư ma khân păng.”$b$,false),
('bunong-vn','EXO',19,23,null,$b$Y-Môis lah ma Yêhôva: “Phung ƀon lan mâu dơi hao ta klơ yôk Sinai ôh, yor lah may nơm ntăm jêh ma hên, lah: ‘Ƀư n'har jŭm yôk, jêh ri prăp an yôk nây,’ ”$b$,false),
('bunong-vn','EXO',19,24,null,$b$Yêhôva lah ma păng: “Hăn jŭr hom jêh ri plơ̆ hao ndrel ma Y-Arôn, ƀiă lah lơi ăn phung kôranh ƀư brah jêh ri phung ƀon lan sâl hao leo ma Yêhôva ôh, klach lah Yêhôva ƀư ma khân păng.”$b$,true),
('bunong-vn','EXO',19,25,null,$b$Pô ri Y-Môis jŭr hăn ta phung ƀon lan jêh ri lah nau nây ma khân păng.$b$,false),
('bunong-vn','EXO',20,1,null,$b$Jêh ta nây Brah Ndu lah lĕ nau aơ, păng lah:$b$,true),
('bunong-vn','EXO',20,2,null,$b$“Gâp jêng Brah Ndu kôranh Brah khân may, jêng nơm ngluh lơi khân may tă bơh ngih bu nă tâm n'gor Êjipt.$b$,false),
('bunong-vn','EXO',20,3,null,$b$Lơi ta kơt brah êng ôh.$b$,true),
('bunong-vn','EXO',20,4,null,$b$Lơi ta trah rup ƀư jêng amoh Brah Ndu, lơi ta ƀư rup kơt mpa tâm trôk, tâm neh ntu, mâu lah tâm dak tâm dâng neh,$b$,true),
('bunong-vn','EXO',20,5,null,$b$Lơi ta yơk mbah mâu lah rhŏ ma rup nây, gâp tâm rmot ma mbu nâm tĭng brah êng, gâp ntŭp nau gâp tâm rmal ma khân păng tât sau, tât se,$b$,false),
('bunong-vn','EXO',20,6,null,$b$ƀiă lah mbu nâm rŏng ma gâp jêh ri iăt nau gâp ntăm, gâp mra rŏng ma păng ƀa ƀơ tât rbăn bông nuyh.$b$,false),
('bunong-vn','EXO',20,7,null,$b$Lơi ta ngơi pâl amoh săk Brah Ndu, kôranh Brah khân may, yor lah Brah Ndu tâm rmal mbu nâm dŏng amoh păng blă blơ.$b$,true),
('bunong-vn','EXO',20,8,null,$b$Kah gĭt nar pơh jêng nar rlu prăp ma Brah Ndu.$b$,true),
('bunong-vn','EXO',20,9,null,$b$Ăn khân may ƀư lĕ kan ma khân may tâm prao nar,$b$,false),
('bunong-vn','EXO',20,10,null,$b$ƀiă lah nar pơh jêng nar rlu prăp ma Brah Ndu, kôranh Brah khân may. Tâm nar nây khân may mâu dơi pah kan ôh, khân may nđâp ma kon bu ur, bu klâu, dĭk bu ur, bu klâu, mâu lah ndrôk rpu khân may, jêh ri bu năch bu nĭng gŭ tâm ƀon khân may mâu dơi lĕ ƀư du ntil kan tâm nar pơh nây. Yor lah tâm prao nar Brah Ndu rhăk njêng trôk, neh ntu, dak mƀŭt, jêh ri lĕ rngôch mpa gŭ tâm khân păng, ƀiă lah tâm nar pơh păng rlu. Yor ri Kôranh Brah ăn bu yơk nar pơh jêh ri prăp nar nây ma păng nơm.$b$,false),
('bunong-vn','EXO',20,11,null,$b$Yor lah tâm prao nar Brah Ndu rhăk njêng trôk neh ntu, dak rlai jêh ri lĕ rngôch mpa geh tâm khân păng, jêh ri păng rlu nar pơh. Yor ri Yêhôva mât ton ma nar pơh nây jêh ri prăp an nar pơh jêng nar kloh ueh.$b$,false),
('bunong-vn','EXO',20,12,null,$b$Yơk ma me mbơ̆ , gay ma khân may dơi gŭ jŏ năm tâm bri Brah Ndu, Kôranh Brah khân may, hŏ ăn jêh ma khân may.$b$,true),
('bunong-vn','EXO',20,13,null,$b$Lơi ta nkhĭt bu.$b$,true),
('bunong-vn','EXO',20,14,null,$b$Lơi ta văng tĭr$b$,true),
('bunong-vn','EXO',20,15,null,$b$Lơi ta ntŭng$b$,false),
('bunong-vn','EXO',20,16,null,$b$Lơi ta ngơi nchơt ma phung chiau meng khân may,$b$,false),
('bunong-vn','EXO',20,17,null,$b$Lơi ta kơnh ngih vâl bu, jêh ri mâu lĕ dơi kơnh ma ur bu, dĭk bu, seh, ndrôk bu, mâu lah moh ntil êng êng ndơ khân păng.”$b$,false),
('bunong-vn','EXO',20,18,null,$b$Tơ lah lĕ rngôch phung ƀon lan tăng nglaih jêh ri bâr nŭng, saơ lơp jêh ri yôk luh nhhŭk ŭnh, khân păng sâr săk jăn jêh ri trơn gŭ ngai,$b$,false),
('bunong-vn','EXO',20,19,null,$b$khân păng lah ma Y-Môis: “Ăn may nơm ngơi ma hên, jêh ri hên mra gŭ iăt; ƀiă lah lơi ăn ôh Brah Ndu ngơi ma hên, klach lah hên mra khĭt.”$b$,false),
('bunong-vn','EXO',20,20,null,$b$Y-Môis lah ma phung ƀon lan: “Lơi klach ôh yor lah Brah Ndu văch jêh ŭch rlong uănh khân may, gay ma khân may klach ma păng, pô nây mơ khân may mâu ƀư tih ôh.”$b$,true),
('bunong-vn','EXO',20,21,null,$b$Phung ƀon lan lơ hô gŭ ngai, Y-Môis hăn dăch ndâr tŭk krăk, ntŭk Brah Ndu gŭ.$b$,false),
('bunong-vn','EXO',20,22,null,$b$Yêhôva lah ma Y-Môis: “Ăn may ngơi pô aơ ma phung Israel: ‘Khân may nơm saơ gâp ngơi tă bơh trôk.$b$,true),
('bunong-vn','EXO',20,23,null,$b$Lơi ƀư ôh ma khân may nơm rup brah ma prăk mâu lah ma mah, gay ma tâm rnglăp gâp đah khân păng.$b$,false),
('bunong-vn','EXO',20,24,null,$b$Ăn khân may rdâk du rplay nơng neh ma gâp, jêh ri ƀư brah ta klơ nây mpa nhhơr gŭch, mpa nhhơr ma nau đăp mpăn, biăp jêh ri ndrôk khân may. Ta ăp ntŭk bu ăn gâp kah gĭt amoh gâp, gâp mra văch ta khân may jêh ri ăn nau ueh uĭn ma khân may.$b$,false),
('bunong-vn','EXO',20,25,null,$b$Tơ lah khân may rdâk du rplay nơng ƀư brah, lŭ ma gâp lơi ƀư păng ma lŭ trah, (mon) ôh; yor lah tơ lah khân may dŏng ndơ prăp trah, khân may ƀư ƀơ̆ nơng nây.$b$,false),
('bunong-vn','EXO',20,26,null,$b$Lơi ta hao nơng gâp ma gung ôh, klach mpơl nau rhôk khân may.$b$,false),
('bunong-vn','EXO',21,1,null,$b$Aơ, nau ntăm ăn may tâm mpơl ma khân păng.$b$,true),
('bunong-vn','EXO',21,2,null,$b$Tơ lah khân may rvăt dĭk Hêbrơ, păng mra pah kan prao năm, jêh ri năm tal pơh păng mra sĭt kon me mâu geh trok rnoh rvăt ôh.$b$,false),
('bunong-vn','EXO',21,3,null,$b$Tơ lah păng lăp jêh êng; păng mra luh êng; tơ lah păng lăp geh ndrel ma ur, nđâp ur păng mra luh ndrel ma păng.$b$,false),
('bunong-vn','EXO',21,4,null,$b$Tơ lah kôranh văng ur ma păng jêh ri ur păng deh kon bu klâu mâu lah bu ur, ur jêh ri phung kon păng mra jêng ndơ kôranh păng, jêh ri păng mra luh êng păng.$b$,false),
('bunong-vn','EXO',21,5,null,$b$Ƀiă lah tơ lah dĭk lah rah vah: ‘Gâp rŏng ma Kôranh gâp, ur gâp jêh ri phung kon gâp, gâp mâu ŭch jêng kon me ôh.’$b$,false),
('bunong-vn','EXO',21,6,null,$b$Dôl nây Kôranh păng mra njŭn leo păng ta năp Brah Ndu, jêh ri kôranh păng ăn păng hăn ta mpông sâng toyh mâu lah ta n'gâng mpông; jêh ri kôranh păng mra chuh tôr păng ma mâng mplônh (mplanh) jêh ri dĭk nây mra pah kan ma kôranh păng lôch nau rêh păng.$b$,false),
('bunong-vn','EXO',21,7,null,$b$Tơ lah du huê bunuyh tăch kon bu ur păng jêng dĭk, păng mâu mra jêng kon me ôh nâm bu phung dĭk bu klâu kon me.$b$,true),
('bunong-vn','EXO',21,8,null,$b$Tơ lah păng mâu blau ƀư maak ma kôranh păng, nơm chôk jêh păng gŭ ur, păng dơi ăn bu chuai păng; ƀiă lah kôranh păng mâu dơi tăch đưn ma bu năch ôh, yor lah păng mâu gŭ răp jăp đah kôranh păng ôh.$b$,false),
('bunong-vn','EXO',21,9,null,$b$Tơ lah păng chôk gŭ kon bu klâu păng, păng mra ƀư đah kôranh păng mra ƀư ma dĭk bu ur di tĭng nâm nau di ma phung bu ur.$b$,false),
('bunong-vn','EXO',21,10,null,$b$Tơ lah păng sŏk du huê bu ur êng, păng mâu dơi n'hŭch ôh bơh bu ur lor ndơ sông sa, bok ao, mâu lah nau vay păng jêng bu ur.$b$,true),
('bunong-vn','EXO',21,11,null,$b$Jêh ri tơ lah păng mâu ƀư ôh pe ndơ nây ma bu ur nây, păng mra jêng kon me dơm dam mâu trôk rnoh rvăt ôh.$b$,false),
('bunong-vn','EXO',21,12,null,$b$Bu nâm dong du huê bunuyh kŏ khĭt, bu mra nkhĭt păng.$b$,true),
('bunong-vn','EXO',21,13,null,$b$Ƀiă lah tơ lah păng mâu gŭ kâp ôh, ƀiă lah Brah Ndu ăn păng tŭp tâm ti bu, pô ri gâp mra ntĭm ntŭk du rplay ƀon ntŭk păng dơi du krap.$b$,false),
('bunong-vn','EXO',21,14,null,$b$Ƀiă lah tơ lah du huê ƀư ma nơm êng ma nau ŭch tâm nkhĭt bu, ăn khân may têk lơi păng bơh nơng gâp ŭch ăn păng khĭt.$b$,false),
('bunong-vn','EXO',21,15,null,$b$Mbu nâm dong mbơ̆ mâu lah me păng, ăn bu nkhĭt lơi păng.$b$,true),
('bunong-vn','EXO',21,16,null,$b$Mbu nâm ntŭng du huê bunuyh jêh ri tăch đưn, mâu lah tơ lah bu saơ bunuyh nây tâm ti păng, ăn bu nkhĭt lơi păng.$b$,true),
('bunong-vn','EXO',21,17,null,$b$Mbu nâm rak rtăp mbơ̆ mâu lah me păng nơm, ăn bu nkhĭt lơi păng.$b$,true),
('bunong-vn','EXO',21,18,null,$b$Tơ lah phung bunuyh tâm ndjrel, jêh ri du dong nkhơng bu êng ma lŭ mâu lah tŭr ma ti, mâu tât khĭt ôh, ƀiă lah kŏ păng mâu dơi dâk;$b$,false),
('bunong-vn','EXO',21,19,null,$b$tơ lah păng dâk jêh ri nsong jra mâng jra, pô ri nơm dong nây mra klaih; jêh ri knŏng păng ntrok nar păng roh kan, jêh ri păng ăn bu săm păng ăn bah.$b$,false),
('bunong-vn','EXO',21,20,null,$b$Tơ lah du huê dong dĭk păng ma mâng, bu klâu mâu lah bu ur, jêh ri dĭk păng khĭt, ăn bu tâm rmal păng.$b$,true),
('bunong-vn','EXO',21,21,null,$b$Ƀiă lah tơ lah păng ăt hôm rêh du nar mâu lah bar nar, lơi ăn bu rmal păng ôh, yor lah dĭk nây mra jêng nâm bu prăk păng.$b$,false),
('bunong-vn','EXO',21,22,null,$b$Tơ lah phung bunuyh tâm nhăt jêh ri geh tom du huê bu ur bŭn, jêh ri bu ur rlêh, ƀiă lah mâu geh nau mhĭk êng ôh, sai bu ur nây mra kuh nơm ƀư ma ur păng, jêh ri păng mra jan dôih tĭng nâm phung kôranh phat dôih lah.$b$,true),
('bunong-vn','EXO',21,23,null,$b$Ƀiă lah tơ lah geh nau mhĭk êng tât jêh ri ăn khân may tâm nsro nau rêh ma nau rêh,$b$,false),
('bunong-vn','EXO',21,24,null,$b$măt ntrok măt, sêk ntrok sêk, ti ntrok ti, jâng ntrok jâng,$b$,false),
('bunong-vn','EXO',21,25,null,$b$ntŭk ŭnh sa ntrok ntŭk ŭnh sa, ntŭk sôt ntrok ntŭk sôt, ntŭk bŭr ntrok ntŭk bŭr.$b$,false),
('bunong-vn','EXO',21,26,null,$b$Tơ lah du huê dong ƀư roh măt dĭk păng, bu klâu mâu lah bu ur, păng mra ăn dĭk păng jêng kon me măt roh jêng nsro rnoh rvăt dĭk.$b$,true),
('bunong-vn','EXO',21,27,null,$b$Tơ lah păng ƀư deh du mlâm sêk dĭk păng, bu klâu mâu lah bu ur, păng mra ăn dĭk păng jêng kon me, sêk roh jêng nsro rnoh rvăt dĭk.$b$,false),
('bunong-vn','EXO',21,28,null,$b$Tơ lah du mlâm ndrôk tâm du huê bu klâu mâu lah bu ur kŏ khĭt, ăn bu nkhĭt lơi ndrôk nây ma lŭ, jêh ri bu mâu mra sa ôh puăch păng; ƀiă lah ndrôk mra klaih.$b$,true),
('bunong-vn','EXO',21,29,null,$b$Ƀiă lah tơ lah ndrôk nây lor ri vay rduh tâm bu, jêh ri bu mbơh jêh nau nây ma nơm păng, ƀiă lah păng mâu mâp mât mray ôh tơ lah ndrôk nây tâm khĭt du huê bunuyh, bu ur mâu lah bu klâu, ăn bu klŭp ma lŭ nkhĭt lơi ndrôk nây nđâp ma nơm ndrôk nkhĭt lơi lĕ.$b$,false),
('bunong-vn','EXO',21,30,null,$b$Tơ lah mpôl băl nơm khĭt đă nơm ndrôk jan dôih, nơm ndrôk mra jan dôih tĭng nâm rnoh mpôl băl nơm khĭt lah.$b$,false),
('bunong-vn','EXO',21,31,null,$b$Tơ lah ndrôk tâm du huê kon bu klâu mâu lah bu ur, ăn bu ƀư tĭng nâm nau vay nây.$b$,false),
('bunong-vn','EXO',21,32,null,$b$Tơ lah ndrôk tâm du huê dĭk bu klâu mâu lah bu ur, ăn nơm ndrôk ăn puăn rhiăng sĭn jât ma nguay gram prăk, ma kôranh dĭk jêh ri ăn bu klŭp lŭ nkhĭt lơi ndrôk.$b$,false),
('bunong-vn','EXO',21,33,null,$b$Tơ lah du huê bunuyh pơk trôm ntu mâu lah kuyh ntu jêh ri mâu nkŭm lơi, jêh ri du mlâm ndrôk mâu lah du mlâm seh bri tŭp tâm ntu nây,$b$,true),
('bunong-vn','EXO',21,34,null,$b$nơm ntu nây mra trok rnoh ma nơm ndrôk; bi seh bri khĭt nơm ntu mra sŏk ma păng nơm.$b$,false),
('bunong-vn','EXO',21,35,null,$b$Tơ lah ndrôk du huê bunuyh, tâm ndrôk du huê bunuyh êng kŏ khĭt, ăn khân păng tăch ndrôk rêh jêh ri tâm pă rnoh. Ăn khân păng pă nđâp ma ndrôk khĭt jêh.$b$,false),
('bunong-vn','EXO',21,36,null,$b$Ƀiă lah tơ lah bu gĭt ndrôk nây lor vay tâm, jêh ri nơm păng mâu mâp mât chiă păng ôh, nơm păng mra nsro ndrôk tâm ban, bi ndrôk khĭt nây sŏk ma păng nơm.$b$,false),
('bunong-vn','EXO',22,1,null,$b$Tơ lah du huê bunuyh ntŭng du mlâm ndrôk, mâu lah du mlâm biăp, jêh ri păng nkhĭt mâu lah tăch đưn, păng mra trok prăm mlâm ndrôk tâm du mlâm ndrôk, jêh ri puăn mlâm biăp tâm du mlâm biăp,$b$,true),
('bunong-vn','EXO',22,2,null,$b$tơ lah bu nhŭp bunuyh ntŭng dôl păng ntŭng lăp jêh ri dong păng kŏ khĭt, mâu mra geh ôh nau rung mham ma nơm nkhĭt bu nây;$b$,false),
('bunong-vn','EXO',22,3,null,$b$ƀiă lah tơ lah nar luh jêh bu mra jêng tih tơ lah bu nkhĭt nơm ntŭng. Păng mra mplơ̆ ndơ păng ntŭng; tơ lah păng mâu geh ndơ ôh, bu mra tăch păng yor ndơ păng ntŭng.$b$,false),
('bunong-vn','EXO',22,4,null,$b$Tơ lah mpô mpa păng ntŭng jêh gĭt lah ndrôk, gĭt lah seh bri; mâu lah hôm rêh tâm ti păng, păng mra lŏ trôk bar tơ̆ .$b$,false),
('bunong-vn','EXO',22,5,null,$b$Tơ lah du huê bunuyh ăn mpô mpa păng rong nsong sa tâm mir mâu du ntŭk đang play kriăk ƀâu nơm êng, mâu lah mpô mpa păng nsong sa ndơ mir nơm êng, păng mra trok ma ndơ ueh lơn tâm mir păng mâu lah tâm đang play kriăk ƀâu păng.$b$,true),
('bunong-vn','EXO',22,6,null,$b$Tơ lah geh ŭnh sa lok jêh ri n'ho rêng sa ba bu êng bun lơi jêh, mâu lah ba ăt hôm ta tơm, mâu lah ŭnh sa lĕ du lôk mir, nơm su ŭnh nây mra trok ăn nŭm.$b$,true),
('bunong-vn','EXO',22,7,null,$b$Tơ lah du huê bunuyh ăn du huê bunuyh êng mât prăk mâu lah drăp ndơ ƀiă lah bu ntŭng lơi bơh ngih nơm mât mray, nơm ntŭng mra trok bar đưn tơ lah geh bu nhŭp păng.$b$,true),
('bunong-vn','EXO',22,8,null,$b$Tơ lah bu mâu geh nhŭp ôh bunuyh ntŭng, nơm ngih nây mra nhhơr păng nơm ta năp Brah Ndu, gay ma mpơl gĭt lah păng sŏk ndơ phung chiau meng păng.$b$,false),
('bunong-vn','EXO',22,9,null,$b$Tâm lĕ rngôch nau ƀư, nau ndơm di ma ndrôk, seh bri, biăp, bok ao, mâu lah ndơ êng roh, ma nau nây bu mra lah: ‘Ndơ aơ, ndơ gâp yơh’ pô ri dôih bar đah nây mra tât ta năp Brah Ndu. Nơm Brah Ndu tâm rmal mra trok bar tơ̆ ma nơm chiau meng păng.$b$,true),
('bunong-vn','EXO',22,10,null,$b$Tơ lah du huê bunuyh jao ma nơm chiau meng păng du mlâm seh bri, du mlâm ndrôk, du mlâm biăp, mâu lah mpô mpa rong êng ăn bu chiă, ƀiă lah mpô mpa nây khĭt, deh jâng, mâu lah bu nhŭp rlu mâu geh nơm saơ ôh,$b$,true),
('bunong-vn','EXO',22,11,null,$b$nau ton sơm ma amoh Yêhôva mra di ma bar đah; jêh ri nơm chiă mra mbơh ma păng mâu mâp pah bi ôh mpô mpa nơm chiau meng păng. Nơm mpô mpa mra dơn nau ton sơm nây, jêh ri nơm chiă mâu mra trok ôh.$b$,false),
('bunong-vn','EXO',22,12,null,$b$Ƀiă lah tơ lah bu ntŭng bơh ngih păng, păng mra trok ma nơm mpa.$b$,false),
('bunong-vn','EXO',22,13,null,$b$Tơ lah geh mpa sa hêk mpa păng chiă, ăn păng njŭn ndơ nây jêng nau mbơh; păng mâu mra trok ôh mpa bu sa hêk jêh.$b$,false),
('bunong-vn','EXO',22,14,null,$b$Tơ lah du huê bunuyh chan mpa rong nơm chiau meng păng, jêh ri mpa nây deh jâng mâu lah khĭt dôl nơm păng ndŭt kơi, păng mra trok ndơ nây.$b$,false),
('bunong-vn','EXO',22,15,null,$b$Tơ lah nơm păng ta năp mâu mra geh nau tâm trok ôh, tơ lah păng nkhôm mpa nây, rnoh nkhôm nây tŏng yơh.$b$,false),
('bunong-vn','EXO',22,16,null,$b$Tơ lah du huê bu klâu ndơm du huê bu ur druh ê geh nơm ƀư mpuăt ndrôi ôh, jêh ri păng bêch ndrel đah bu ur nây, păng mra ăn drăp lup văng ma bu ur nây, jêh ri n'ho sŏk bu ur nây jêng ur păng.$b$,true),
('bunong-vn','EXO',22,17,null,$b$Tơ lah mbơ̆ bu ur nây dun, mâu ăn păng sŏk ƀư ur ôh, păng mra ăn prăk dŭm rnoh lup văng ma phung bu ur druh.$b$,false),
('bunong-vn','EXO',22,18,null,$b$Lơi ta cha lơi du huê bu ur n'hŭm gŭ rêh ôh.$b$,true),
('bunong-vn','EXO',22,19,null,$b$Mbu nâm tâm geh đah mpô mpa, ăn bu nkhĭt lơi păng.$b$,true),
('bunong-vn','EXO',22,20,null,$b$Mbu nâm ƀư brah ma brah êng mâu tăp ma Yêhôva ôh ăn bu nkhĭt lơi păng.$b$,true),
('bunong-vn','EXO',22,21,null,$b$Lơi ƀư ƀai ma du huê bu năch, mâu dơi tŭn jot păng, yor lah khân may jêng bu năch jêh tâm n'gor Êjipt.$b$,true),
('bunong-vn','EXO',22,22,null,$b$Lơi tŭn jot ôh bu ur ndrô mâu lah ma kon đơi.$b$,false),
('bunong-vn','EXO',22,23,null,$b$Tơ lah khân may tŭn jot khân păng, jêh ri khân may nter ma gâp, nanê̆ gâp mra tăng nau păng nter;$b$,false),
('bunong-vn','EXO',22,24,null,$b$nau gâp ji nuih mra hit, jêh ri gâp mra nkhĭt khân may ma đao gưm. Ur khân may mra jêng bu ur ndrô jêh ri phung kon khân may mra jêng kon đơi.$b$,false),
('bunong-vn','EXO',22,25,null,$b$Tơ lah khân may ăn phung o ach tâm phung ƀon lan gâp chan prăk, lơi ƀư ôh ma păng nâm bu du huê nơm sa drăp, mâu dơi khân may sa kao ma păng.$b$,true),
('bunong-vn','EXO',22,26,null,$b$Tơ lah khân may sŏk bok ao nơm chiau meng khân may ndŭl mpôl tâm nkât nkol, ăn khân may mplơ̆ lơi bok ao nây lor ma nar nhâp;$b$,false),
('bunong-vn','EXO',22,27,null,$b$yor lah păng geh knŏng bok nây nkŭm săk jăn păng. Moh ndơ păng soh dôl păng lâng săk? Tơ lah păng mra nter ma gâp, gâp mra tăng păng, yor lah gâp blau yô̆.$b$,false),
('bunong-vn','EXO',22,28,null,$b$Lơi suai rak Brah Ndu ôh, mâu lĕ dơi rtăp rak ma du huê Kôranh phung ƀon lan khân may.$b$,false),
('bunong-vn','EXO',22,29,null,$b$Lơi ta nkai ôh nhhơr kô̆ tâm jât play kao geh bơh mir khân may jêh ri play kriăk ƀâu khân may. Ăn ma gâp kon bu klâu khân may deh bôk rah.$b$,true),
('bunong-vn','EXO',22,30,null,$b$Ăn khân may ƀư tâm ban lĕ ma ndrôk jêh ri biăp khân may. Păng mra gŭ pơh nar đah me păng, nar pham khân may mra ăn păng ma gâp.$b$,false),
('bunong-vn','EXO',22,31,null,$b$Ăn khân may jêng bunuyh kloh ueh prăp ăn ma gâp; yor nây lơi sa ôh nglay puăch mpa êng kăp hêk tâm mir, ăn khân may mƀăr ndơ nây ma so.$b$,true),
('bunong-vn','EXO',23,1,null,$b$Lơi nkoch bri nau mƀruh ôh. Lơi tâm rnglăp ôh đah bunuyh ƀai ŭch nkoch nau mƀruh.$b$,true),
('bunong-vn','EXO',23,2,null,$b$Lơi ta tĭng kơt phung âk gay ƀư nau mhĭk ôh; jêh ri tơ lah may jêng nơm mbơh tâm du ntil dôih dak, lơi gŭ mpeh ma phung âk ôh gay ma nsak lơi nau sŏng.$b$,false),
('bunong-vn','EXO',23,3,null,$b$Mâu lĕ dơi gŭ mpeh ma du huê bunuyh o ach tơ lah păng geh dôih dak.$b$,false),
('bunong-vn','EXO',23,4,null,$b$Tơ lah may mâp đah ndrôk nơm rlăng may, mâu lah seh bri păng nhhơt, ăn may têk njŭn sĭt ma nơm păng.$b$,true),
('bunong-vn','EXO',23,5,null,$b$Tơ lah may saơ seh bri nơm rlăng may cha lôt yor rdeng ndơ jâk ir, lơi cha lơi nơm rlăng ôh ƀiă lah ăn may kơl ndâk seh nây, mâu dơi cha lơi ôh.$b$,false),
('bunong-vn','EXO',23,6,null,$b$Lơi ta nsak nau khư tâm dôih bunuyh o ach.$b$,true),
('bunong-vn','EXO',23,7,null,$b$Ăn may gŭ ngai đah nau mƀruh, jêh ri lơi ta nkhĭt ôh phung sŏng srăng jêh ri phung sŏng, yor lah gâp mâu mra kơp sŏng ôh phung ƀai.$b$,false),
('bunong-vn','EXO',23,8,null,$b$Lơi dơn ôh drăp bu blŏl, yor lah drăp bu blŏl mra ƀư chieh măt phung kôranh, jêh ri nsak dôih dak phung sŏng.$b$,false),
('bunong-vn','EXO',23,9,null,$b$Lơi tŭn jot phung bu năch ôh; khân may gĭt jêh nuih n'hâm phung bu năch, yor lah khân may jêng bu năch jêh tâm n'gor Êjipt.$b$,true),
('bunong-vn','EXO',23,10,null,$b$Dôl tâm prao năm ăn khân may tuch ba tâm mir khân may, jêh ri khân may mra kăch.$b$,true),
('bunong-vn','EXO',23,11,null,$b$Ƀiă lah năm tal pơh ăn khân may cha lơi mir rlu jêh ri mâu tŭch tăm ôh, gay ma phung o tâm phung ƀon lan khân may dơi sông sa; jêh ri mpô mpa dơi sa ndơ klen. Ăn khân may ƀư tâm ban lĕ ma play kriăk ƀâu jêh ri ma đang play Ôlivơ khân may;$b$,false),
('bunong-vn','EXO',23,12,null,$b$Dôl tâm prao nar ăn khân may pah kan, ƀiă lah nar pơh, ăn khân may rlu; gay ma ndrôk jêh ri seh bri khân may dơi rlu lĕ, jêh ri kon bu klâu oh mon bu ur khân may jêh ri phung bu năch dơi mpăn jêng tay suan rlu.$b$,false),
('bunong-vn','EXO',23,13,null,$b$Ăn khân may kâp njrăng tĭng ndô̆ lĕ nau gâp lah jêh ma khân may; jêh ri lơi rnha amoh phung brah êng ôh, lơi ăn bu tăng nau nây tă bơh trôm mbung khân may ôh.$b$,false),
('bunong-vn','EXO',23,14,null,$b$Pe tơ̆ ăp năm ăn khân may ƀư nau nhêt sông yơk ma gâp.$b$,true),
('bunong-vn','EXO',23,15,null,$b$Ăn khân may ƀư Nau Nhêt sông ma piăng let Mâu geh Ndrui; tĭng nâm gâp hŏ ntăm jêh, khân may mra sa piăng let mâu geh ndrui dôl tâm pơh nar tâm nal jêh tâm khay puăn, yor khay nây yơh khân may luh jêh bơh n'gor Êjipt. Lơi ăn du huê mpơl ta năp gâp ma ti dơm ôh.$b$,false),
('bunong-vn','EXO',23,16,null,$b$Ăn khân may kah gĭt prăp nau nhêt sông Yăn Kăch geh play kao geh bơh kan khân may tuch tăm jêh tâm mir. Ăn khân may kah gĭt Prăp Rep ta lôch năm tơ lah khân may huai sŏk bơh mir rplay khân may pah kan.$b$,true),
('bunong-vn','EXO',23,17,null,$b$Pe tơ̆ ăp năm ăn lĕ rngôch phung bu klâu khân may tâm mpơl ta năp kôranh Brah Yêhôva.$b$,false),
('bunong-vn','EXO',23,18,null,$b$Lơi nhhơr ôh mham mpa ƀư brah yơk ma gâp ma piăng let geh ndrui, jêh ri lơi prăp ngi păng kŏ tât ang ôi ôh.$b$,true),
('bunong-vn','EXO',23,19,null,$b$Ăn khân may ndjôt leo ta ngih Yêhôva Brah Ndu khân may play ueh lơn bơh rplay kao neh khân may. “Lơi gâm kon be tâm dak toh ma păng ôh.$b$,false),
('bunong-vn','EXO',23,20,null,$b$Aơ, gâp njuăl du huê oh mon ueh ta năp khân may, gay ma n'gang khân may rŏ trong jêh ri ŭch ăn khân may lăp ta ntŭk gâp nkra jêh.$b$,true),
('bunong-vn','EXO',23,21,null,$b$Njrăng jêh ri gŭ iăt bâr păng. Lơi tâm rdâng dah păng ôh, yor lah păng mâu mra yô̆ an ôh nau khân rlau nau vay, yor lah Amoh gâp gŭ tâm păng.$b$,false),
('bunong-vn','EXO',23,22,null,$b$Ƀiă lah tơ lah khân may gŭ iăt bâr păng jêh ri ƀư lĕ nau gâp mra lah, pô ri gâp mra jêng rlăng đah phung rlăng khân may, jêh ri nơm rdâng đah phung tâm rdâng đah khân may.$b$,true),
('bunong-vn','EXO',23,23,null,$b$Tông mpăr ueh gâp mra hăn ta năp khân may jêh ri khân may lăp n'gor Amôrit, phung Hitit, phung Pêrisit, phung Kanaan, phung Hivit jêh ri phung Jêbusit, jêh ri gâp mra ƀư rai khân păng.$b$,true),
('bunong-vn','EXO',23,24,null,$b$Lơi păn mbah ôh ta năp phung brah khân păng, mâu lĕ pah kan ma khân păng, mâu lĕ kơt kan khân păng, ƀiă lah ăn khân may ƀư rai khân păng jêh ri nchah lơi rup brah khân păng.$b$,true),
('bunong-vn','EXO',23,25,null,$b$Ăn khân may pah kan ma Yêhôva Brah Ndu khân may jêh ri gâp mra mât ton ma ndơ sông sa jêh ri dak khân may nhêt; jêh ri gâp mra sŏk lơi nau ji kuet bơh tâm nklang khân may.$b$,false),
('bunong-vn','EXO',23,26,null,$b$Tâm n'gor khân may mâu mra geh bu ur rlêh kon ôh, mâu lah mpô mpa rlêh kon, mâu lĕ geh bu ur mâu bă, mâu lah mpô mpa mâu deh kon. Gâp mra ăn nŭm năm khân may gŭ rêh.$b$,false),
('bunong-vn','EXO',23,27,null,$b$Gâp mra ăn phung êng klach ta năp khân may, jêh ri gâp mra ƀư uh ah lĕ rngôch ƀon lan khân may mra mâp, jêh ri gâp mra ăn lĕ rngôch phung rlăng khân may du bơh khân may.$b$,false),
('bunong-vn','EXO',23,28,null,$b$Gâp mra njuăl ong sŭt hăn lor ma khân may, jêh ri khân păng mra nsot phung Hitit, phung Kanaan, jêh ri phung Hitit bơh ta năp khân may.$b$,false),
('bunong-vn','EXO',23,29,null,$b$Gâp mâu mra nsot ôh khân păng tă bơh năp khân may tâm du năm, klach lah n'gor jêng bri rdah mpa bri jêng bĭk ƀư ma khân may.$b$,true),
('bunong-vn','EXO',23,30,null,$b$Ƀrư̆ ƀrư̆ gâp mra nsot khân păng tă bơh năp khân may, kŏ khân may mra jêng âk lơn jêh ri sŏk pha n'gor bri.$b$,false),
('bunong-vn','EXO',23,31,null,$b$Gâp mra ƀư n'har bri khân may bơh Dak Rlai Chăng tât ta dak rlai phung Philistin, jêh ri bơh bri rdah tât ta Dak Krong Ơphrat; yor lah gâp mra jao tâm ti khân may phung bunuyh gŭ tâm n'gor nây. Jêh ri khân may mra nsot khân păng ta năp khân may nơm.$b$,true),
('bunong-vn','EXO',23,32,null,$b$Lơi ƀư ôh nau tâm rnglăp đah khân păng, mâu lah đah phung brah khân păng.$b$,false),
('bunong-vn','EXO',23,33,null,$b$Khân păng mâu mra gŭ ôh tâm n'gor khân may, klach lah khân păng ăn khân may ƀư tih đah gâp. Yor lah tơ lah khân may pah kan ma phung brah khân păng, nau nây mra jêng dăk sân ma khân may.”$b$,false),
('bunong-vn','EXO',24,1,null,$b$Yêhôva lah ma Y-Môis: “Hăn hao hom ma Yêhôva, may jêh ri Y-Arôn. Y-Nadap, Y-Abihu, jêh ri pơh jât nuyh bu bŭnh bu ranh phung Israel, jêh ri ăn khân may yơk mbah bơh ngai.$b$,true),
('bunong-vn','EXO',24,2,null,$b$Êng huê Y-Môis mra văch êp Yêhôva, ƀiă lah phung êng mâu dơi văch dăch ôh, phung ƀon lan mâu lĕ dơi hao ndrel ma păng.”$b$,false),
('bunong-vn','EXO',24,3,null,$b$Y-Môis văch mbơh lĕ rngôch nau Yêhôva ngơi jêh ri lĕ rngôch nau ntăm. Lĕ rngôch phung ƀon lan plơ̆ lah ma du bâr. “Hên mra ƀư lĕ nau Yêhôva lah jêh.”$b$,true),
('bunong-vn','EXO',24,4,null,$b$Y-Môis chih lĕ rngôch nau Yêhôva ngơi. Păng dâk bêch ôi ơm rdâk du rplay nơng ta njâng yôk jêh ri rdâk jât ma bar mlâm lŭ tĭng nâm rnoh jât ma bar mpôl băl, Israel.$b$,false),
('bunong-vn','EXO',24,5,null,$b$Păng njuăl hăn phung bu klâu dôl dal Israel nhhơr ma Yêhôva mpa nhhơr gŭch jêh ri ƀư brah ma ndrôk jêng ndơ nhhơr ma nau đăp mpăn.$b$,false),
('bunong-vn','EXO',24,6,null,$b$Y-Môis sŏk n'gul mham dơm tâm mâm, jêh ri n'gul mham êng păng nkhŭt ta nơng.$b$,true),
('bunong-vn','EXO',24,7,null,$b$Păng sŏk ndrom sămƀŭt nau tâm rnglăp jêh ri uănh ta năp lĕ rngôch phung ƀon lan. Khân păng lah: “Hên mra ƀư lĕ rngôch nau Yêhôva lah jêh, jêh ri hên mra tông.”$b$,true),
('bunong-vn','EXO',24,8,null,$b$Y-Môis sŏk mham jêh ri djrah ta klơ phung ƀon lan, jêh ri lah: “Aơ, mham nau tâm rnglăp Yêhôva ƀư jêh đah khân may tĭng nâm lĕ nau ngơi aơ.”$b$,true),
('bunong-vn','EXO',24,9,null,$b$Y-Môis hao ndrel ma Y-Arôn, Y-Nadap, Y-Abihu, jêh ri pơh jât nuyh phung bu ranh phung Israel.$b$,true),
('bunong-vn','EXO',24,10,null,$b$Khân păng saơ Brah Ndu Israel geh tâm dâng jêng păng nâm bu du trong lâng ƀư ma lŭ Saphir jêh ri ang nâm bu trôk.$b$,false),
('bunong-vn','EXO',24,11,null,$b$Păng mâu yơr ôh ti păng ma phung bu bŭnh bu ranh phung Israel; khân păng saơ Brah Ndu jêh ri khân păng sông sa jêh ri nhêt.$b$,false),
('bunong-vn','EXO',24,12,null,$b$Yêhôva lah ma Y-Môis: “Hao hom ma gâp ta klơ yôk jêh ri gŭ kâp ta nây. Gâp mra ăn kađar lŭ ma may, nau vay jêh ri nau gâp ntăm chih jêh gay ma may sâm nti khân păng.”$b$,true),
('bunong-vn','EXO',24,13,null,$b$Pô ri Y-Môis dâk ndrel ma Y-Yôsuê, bunuyh pah kan ma păng, jêh ri Y-Môis hao ta klơ yôk Brah Ndu.$b$,false),
('bunong-vn','EXO',24,14,null,$b$Păng lah ma phung bu bŭnh bu ranh: “Gŭ kâp hên ta aơ tât hên mra plơ̆ sĭt ma khân may. Aơ, Y-Môis jêh ri Y-Hur gŭ ndrel ma khân may. Tơ lah du huê geh dôih dak ăn nơm nây hăn ma khân păng.”$b$,false),
('bunong-vn','EXO',24,15,null,$b$Y-Môis hao ta klơ yôk, jêh ri ndâr nkŭm yôk.$b$,true),
('bunong-vn','EXO',24,16,null,$b$Nau chrêk rmah Yêhôva gŭ klơ yôk Sinai jêh ri ndâr nkŭm păng prao nar. Nar tal pơh păng kuăl Y-Môis bơh tâm nklang ndâr.$b$,false),
('bunong-vn','EXO',24,17,null,$b$Uănh ma nau chrêk rmah Yêhôva nâm bu ŭnh sa hit ta klơ kô yôk ta năp măt phung ƀon lan Israel.$b$,false),
('bunong-vn','EXO',24,18,null,$b$Y-Môis lăp tâm ndâr jêh ri hao ta klơ yôk. Y-Môis gŭ ta klơ yôk puăn jât nar jêh ri puăn jât năng.$b$,false),
('bunong-vn','EXO',25,1,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',25,2,null,$b$“Ngơi hom ma phung ƀon lan Israel, ăn khân păng djôt leo ndơ nhhơr ma gâp. Ăn may sŏk an ndơ nây ma gâp bơh lĕ rngôch phung bunuyh nhhơr ma nuih n'hâm ŭch.$b$,false),
('bunong-vn','EXO',25,3,null,$b$Aơ, ndơ nhhơr may mra dơm sŏk tă bơh khân păng: Mah, prăk, kông bok nhom dak piâk,$b$,true),
('bunong-vn','EXO',25,4,null,$b$chăng krăk, mhay rhên; jêh ri rsau be.$b$,false),
('bunong-vn','EXO',25,5,null,$b$Ntâu biăp nkuăng nkra jêh, ntâu ka toyh, jêh ri tơm si akasi;$b$,false),
('bunong-vn','EXO',25,6,null,$b$dak play Ôlivơ ma ŭnh jrêng; ndơ ƀâu kah ma dak ƀâu kah prăp tŏ jêh ri prăp ma ndơ ƀâu kah;$b$,false),
('bunong-vn','EXO',25,7,null,$b$lŭ ônik jêh ri âk lŭ khlay êng gay lĭr dơm ta ao êphôt jêh ri ta bok văn ntang ntơh ao păng.$b$,false),
('bunong-vn','EXO',25,8,null,$b$Ăn khân păng ƀư ma gâp du ntŭk kloh ueh, gay ma gâp dơi gŭ tâm nklang khân păng.$b$,false),
('bunong-vn','EXO',25,9,null,$b$Ăn khân may ƀư ngih bok tĭng nâm rup jêh ri rup ndơ dŏng ta nây tĭng nâm lĕ nau gâp mra ntĭm an ma may.$b$,false),
('bunong-vn','EXO',25,10,null,$b$Ăn khân păng ƀư du rplay hip ma si akasi, njok păng bar hăt n'gul rkăng păng du hăt n'gul jêh ri prêh păng du hăt n'gul.$b$,true),
('bunong-vn','EXO',25,11,null,$b$Ăn may pot păng ma mah kloh; ăn may pot tâm trôm jêh ri pa dih, jêh ri ƀư năp păng n'găp jŭm ma mah.$b$,true),
('bunong-vn','EXO',25,12,null,$b$Ăn may tŏ ƀư puăn rvang ma mah ma păng, jêh ri may dơm rvang nây ta puăn mlâm jâng păng, du đah bar rvang jêh ri du đah êng bar rvang lĕ.$b$,false),
('bunong-vn','EXO',25,13,null,$b$Ăn may ƀư mâng tung ma si Akasi pot ma mah.$b$,false),
('bunong-vn','EXO',25,14,null,$b$Ăn may nsro mâng tâm trôm rvang ta pĭt hip nây gay tung păng.$b$,false),
('bunong-vn','EXO',25,15,null,$b$Mâng nây mra gŭ mro tâm trôm rvang ta hip, bu mâu mra tŏk lơi păng ôh.$b$,false),
('bunong-vn','EXO',25,16,null,$b$Ăn may dơm tâm hip nau mbơh gâp mra ăn ma may.$b$,true),
('bunong-vn','EXO',25,17,null,$b$Ăn ƀư du mlâm ndrŭp jêng ntŭk yô̆ an ma mah kloh; njok păng bar hăt n'gul, rkăng du hăt n'gul.$b$,false),
('bunong-vn','EXO',25,18,null,$b$Ăn may ƀư bar rup Chêrubim ma mah; ăn may ƀư păng ma mah bu chiăr, dơm ta bar ntŭk ta pĭt ntŭk yô̆ an.$b$,false),
('bunong-vn','EXO',25,19,null,$b$Ƀư hom du mlâm rup Chêrubim ta du ntŭk ta pĭt, jêh ri du mlâm rup Chêrubim ta du ntŭk pĭt êng. Ăn may ƀư rup Chêrubim du ngrăng đah ntŭk yô̆ an ta bar ntŭk pĭt.$b$,false),
('bunong-vn','EXO',25,20,null,$b$Phung Chêrubim mra ling năr khân păng leo klơ, nkŭm ma nar khân păng jêh ri muh măt khân tâm mƀŏng ndrel. Phung Chêrubim mra uănh mơ pa ntŭk yô̆ an.$b$,false),
('bunong-vn','EXO',25,21,null,$b$Ăn may dơm ntŭk yô̆ an nây ta klơ hip; jêh ri tâm hip nây may mra dơm nau mbơh gâp mra ăn ma may.$b$,false),
('bunong-vn','EXO',25,22,null,$b$Ta nây gâp mra tâm mâp đah may, jêh ri ta klơ ntŭk yô̆ an ta vah vang rup Chêrubim gŭ ta klơ hip nau tâm rnglăp nây, gâp mra ngơi ma may lĕ rngôch nau gâp mra ntăm ma phung ƀon lan Israel.$b$,false),
('bunong-vn','EXO',25,23,null,$b$Ăn may du rplay sưng ma si akasi, njol bar hăt rkăng du hăt, jêh ri prêh păng du hăt n'gul.$b$,true),
('bunong-vn','EXO',25,24,null,$b$Ăn may mblum păng ma mah kloh, jêh ri ƀư năp n'găp jŭm bâr ma mah.$b$,false),
('bunong-vn','EXO',25,25,null,$b$Ăn may veh jŭm sưng nây du mpang ti, ta pĭt ntŭk veh nây ăn may ƀư năp ma mah ăn jŭm.$b$,true),
('bunong-vn','EXO',25,26,null,$b$Ăn may ƀư păng puăn rvang ma mah jêh ri dơm rvang ta puăn njônh ta puăn jâng păng.$b$,false),
('bunong-vn','EXO',25,27,null,$b$Rvang mra gŭ dăch ta pĭt năp, jêng ntŭk nsro mâng prăp tung sưng.$b$,false),
('bunong-vn','EXO',25,28,null,$b$Ăn may ƀư mâng tung ma si akasi, jêh ri mblum ma mah, gay dŏng tung sưng nây.$b$,false),
('bunong-vn','EXO',25,29,null,$b$Ăn may ƀư ma sưng nây ngan pala, khăl, ngan prăp dơ ndơ ƀâu n'hôl jêh ri chrĕ prăp dŏng nkhŭt ndơ nhhơr. Ăn may ƀư ndơ nây ma mah kloh.$b$,false),
('bunong-vn','EXO',25,30,null,$b$Ăn may dơm ta klơ sưng nây piăng let nhhơr ma Brah Ndu gŭ ƀa ƀơ ta năp gâp.$b$,false),
('bunong-vn','EXO',25,31,null,$b$Ăn may ƀư jâng jrêng ma mah kloh; jâng jrêng nây bu mra ƀư ma mah chiăr jâng păng, săk păng, kachok păng, bôk păng jêh ri kao păng mra jêng tâm du ngrăng.$b$,true),
('bunong-vn','EXO',25,32,null,$b$Prăm mlâm n'gĭng mra luh ta meng, pe mlâm mơ du đah jêh ri pe mlâm mơ du đah êng.$b$,false),
('bunong-vn','EXO',25,33,null,$b$Du n'gĭng geh du mlâm kachok ƀư nâm bu play aman dê, du mlâm bôk jêh ri kao păng; jêh ri ta n'gĭng êng geh pe mlâm kachok ƀư play amandê, du mlâm bôk jêh ri kao păng; lĕ prăm mlâm n'gĭng luh tă bơh jâng jrêng nây mra jêng tâm ban.$b$,false),
('bunong-vn','EXO',25,34,null,$b$Ta n'gâng ŭnh jrêng mra geh puăn mlâm kachok ƀư nâm bu play amandê, du mlâm bôk jêh ri play păng;$b$,true),
('bunong-vn','EXO',25,35,null,$b$mra geh du mlâm bôk tâm dâng ăp bar mlâm n'gĭng luh ta bar đah pĭt jâng lĕ rngôch geh prao mlâm n'gĭng.$b$,false),
('bunong-vn','EXO',25,36,null,$b$Bôk khân păng jêh ri n'gĭng khân păng mra jêng du ngrăng, lĕ nây bu mra chiăr tâm du ngrăng mah kloh.$b$,false),
('bunong-vn','EXO',25,37,null,$b$Ăn may ƀư pơh mlâm ŭnh kađen ma păng, bu mra ndâk ŭnh kađen gay ma ang ta năp păng.$b$,false),
('bunong-vn','EXO',25,38,null,$b$Ndơ ƀư khĭt ŭnh jêh ri khăl djôt ndơ nây ăn bu ƀư ma mah kloh.$b$,true),
('bunong-vn','EXO',25,39,null,$b$Bu mra dŏng du talâng mah kloh prăp ƀư păng ndrel ma lĕ rngôch ndơ dŏng ma păng.$b$,false),
('bunong-vn','EXO',25,40,null,$b$Njrăng hom ăn may ƀư nâm bu rup ntơp ăn ma may ta klơ yôk.$b$,false),
('bunong-vn','EXO',26,1,null,$b$Ăn may ƀư ngih bok ma jât blah bok mbâl ƀư ma mhay rhên jêh ri bok nhom dak piâk, dak chăng krăk, jêh ri chăng rhưch. Ăn may tanh rup Chêrubim ta bok nây ma nau njêh ngăn.$b$,true),
('bunong-vn','EXO',26,2,null,$b$Jong ăp blah bok nây mra geh bar jât ma pham hăt, dĭ rgăn ăp blah bok nây mra geh puăn hăt. Lĕ rngôch bok nây mra geh rnâng tâm ban.$b$,false),
('bunong-vn','EXO',26,3,null,$b$Prăm blah tâm bok nây mra ndop ndrel, prăm blah êng tâm ban lĕ mra ndop ndrel.$b$,true),
('bunong-vn','EXO',26,4,null,$b$Ăn may ƀư rse brai piâk ta pĭt bok ăn lôch ntŭk tâm ndop tal lor, jêh ri ăn may ƀư lĕ ta pĭt bok lôch ntŭk ndop tal bar.$b$,true),
('bunong-vn','EXO',26,5,null,$b$Ăn may ƀư prăm jât rse brai ma bok tal lor, jêh ri ăn may ƀư prăm jât rse brai ta pĭt bok tal bar; rse brai mra tâm di ndrăng păng.$b$,false),
('bunong-vn','EXO',26,6,null,$b$Ăn may ƀư prăm jât ndơ nkăp ma mah, jêh ri ăn may tâm ndop bok mbâl nây tâm mâp ndrel khêp đah ndơ nkĕp gay ma ngih bok mra lam du blah.$b$,false),
('bunong-vn','EXO',26,7,null,$b$Ăn may ƀư bok mbâl ma rsau be jêng bok nkŭm ta klơ ngih bok. Ăn may ƀư jât ma nguay blah bok tâm ban pô nây.$b$,true),
('bunong-vn','EXO',26,8,null,$b$Jong ăp blah bok nây mra geh pe jât hăt, dĭ rgăn ăp blah bok puăn hăt; lĕ rngôch jât ma nguay blah bok nây mra geh rnâng tâm ban.$b$,false),
('bunong-vn','EXO',26,9,null,$b$Ăn may ndop êng êng prao blah bok nây jêh ri prao blah êng, tâm ban lĕ. Jêh ri ăn may n'grup bar bok tal prao ta năp ngih bok nây.$b$,false),
('bunong-vn','EXO',26,10,null,$b$Ăn may ƀư prăm mbrai rse brai ta pĭt bok ăn lôch ntŭk ndop tal lor.$b$,false),
('bunong-vn','EXO',26,11,null,$b$Ăn may ƀư prăm jât ndơ nkĕp ma kông, jêh ri ăn may nglăp ndơ nkĕp nây tâm rvang rse brai, pô ri tâm ndop ngih bok gay ma păng jêng glom lam nguay.$b$,true),
('bunong-vn','EXO',26,12,null,$b$Kô̆ bok mbâl rmeh, nguay ma n'gul hôm, mra ƀư mbrai pa kơi ngih bok$b$,false),
('bunong-vn','EXO',26,13,null,$b$Du hăt đah aơ jêh ri du hăt đah tĕ, kô̆ hôm bơh nau jong bok mbâl ma ngih bok mra ƀư mbrai ta meng ngih bok mơ đah aơ jêh ri mơ đah rĭ gay nkŭm păng.$b$,false),
('bunong-vn','EXO',26,14,null,$b$Ăn may ƀư ngih bok ma ndơ nkŭm klơ ma ntâu biăp nkuăng nkra jêh, jêh ri ma ntâu ka toyh.$b$,false),
('bunong-vn','EXO',26,15,null,$b$Ăn may ƀư ƀa ƀă kađar ma ngih bok ma si akasi, ăn dơm khân păng rdâk.$b$,true),
('bunong-vn','EXO',26,16,null,$b$Jong kađar nây jât hăt jêh ri dĭ rgăn păng du hăt n'gul;$b$,false),
('bunong-vn','EXO',26,17,null,$b$mra geh ta ăp kađar bar bôk prăp tâm ntrŭp gay ma tâm rnglăp ndrel. Ăn may ƀư tâm ban da dê ma lĕ rngôch kađar ngih bok.$b$,false),
('bunong-vn','EXO',26,18,null,$b$Pô aơ ăn may ƀư kađar ngih bok; bar jât pŏk kađar mơ bah rđŭng;$b$,false),
('bunong-vn','EXO',26,19,null,$b$puăn jât rnơl ma prăk tâm dâng bar jât pŏk kađar bar mlâm rnơl tâm dâng du pŏk kađar prăp ma bar bôk tâm ntrŭp păng,$b$,false),
('bunong-vn','EXO',26,20,null,$b$jêh ri bar mlâm rnơl tâm dâng kađar êng prăp ma bar bŏk tâm ntrŭp păng; bar jât pŏk kađar đah tĕ ngih bok mpeh ma mpư̆ yôk,$b$,false),
('bunong-vn','EXO',26,21,null,$b$jêh ri rnơl khân păng ma prăk puăn jât mlâm, bar mlâm tâm dâng du pŏk kađar jêh ri bar mlâm tâm dâng du pŏk êng.$b$,false),
('bunong-vn','EXO',26,22,null,$b$Prao pŏk kađar pa kơi ngih bok mơ pa dâng;$b$,true),
('bunong-vn','EXO',26,23,null,$b$bar pŏk kađar ta njônh ngih bok pa kơi.$b$,false),
('bunong-vn','EXO',26,24,null,$b$Khân păng mra jêng n'grup bar bơh tâm dâng, ƀiă lah rnglăp ndrel ta klơ đah du rvang; mra jêng pô nây ma bar njônh.$b$,false),
('bunong-vn','EXO',26,25,null,$b$Mra geh pham pŏk kađar ndrel ma jât ma prao mlâm rnơl prăk khân păng; bar mlâm rnơl tâm dâng du pŏk kađar jêh ri bar tâm dâng du pŏk êng.$b$,true),
('bunong-vn','EXO',26,26,null,$b$Ăn may ƀư mâng nđăng ma si akasi, prăm mlâm prăp ma kađar mơ du đah pĭt ngih bok;$b$,true),
('bunong-vn','EXO',26,27,null,$b$prăm mlâm mâng nđăng prăp ma kađar ta pĭt đah rĭ ngih bok, jêh ri prăm mlâm mâng nđăng prăp ma kađar pa kơi ngih bok pa dâng.$b$,false),
('bunong-vn','EXO',26,28,null,$b$Mâng nđăng ta nklang mra rkăng kađar bơh bôl aơ tât bôl ri.$b$,false),
('bunong-vn','EXO',26,29,null,$b$Ăn may mblum kađar ma mah, jêh ri ƀư rvang ma mah prăp nsro mâng nđăng; jêh ri ăn may mblum mâng nđăng ma mah lĕ.$b$,false),
('bunong-vn','EXO',26,30,null,$b$Ăn may rdâk ngih bok tĭng nâm rup tâm mpơl jêh ma may ta klơ yôk.$b$,false),
('bunong-vn','EXO',26,31,null,$b$Ăn may nching ƀư du blah bok piâk, chăng krăk, jêh ri chăng rhưch, jêh ri mhay rhên. Ăn bu tanh păng ma nau njêh ngăn ndrel ma rup Chêrubim.$b$,true),
('bunong-vn','EXO',26,32,null,$b$Ăn may dơm păng ta puăn mlâm meh ma si akasi mblum ma mah. Meh nĕ geh nglĕ knuăk mah, tăm ta puăn mlâm rnơl prăk.$b$,false),
('bunong-vn','EXO',26,33,null,$b$Ăn may nching bok, nching nây ma ndơ nkĕp, jêh ri ăn may tung leo hip nau tâm rnglăp tâm trôm bok nching. Bok nching mra tâm pă ma may jrô kloh ueh đah jrô kloh ueh lơn.$b$,false),
('bunong-vn','EXO',26,34,null,$b$Ăn may dơm ntŭk yô̆ an ta klơ hip nau tâm rnglăp tâm jrô kloh ueh lơn.$b$,false),
('bunong-vn','EXO',26,35,null,$b$Ăn may dơm sưng pa dih bok nching, jêh ri dơm jâng jrêng jêh ri dơm jâng jrêng ta pĭt rđŭng ngih bok, mơ pa hŏng sưng; jêh ri ăn may dơm sưng mơ pĭt mpư̆ yôk.$b$,false),
('bunong-vn','EXO',26,36,null,$b$Ăn may ƀư ntŭk lăp ngih bok du blah bok mphiar piâk, chăng krăk, chăng rhưch, jêh ri mhay rhên, ăn bu cheh păng.$b$,true),
('bunong-vn','EXO',26,37,null,$b$Ma bok mphiar nây ăn may ƀư prăm mlâm meh akasi mblum ma mah, jêh ri ăn may tŏ nkra ma khân păng prăm mlâm rnơl kông.$b$,false),
('bunong-vn','EXO',27,1,null,$b$Ăn may ƀư nơng ma tơm si akasi; jong njok păng prăm hăt jêh ri huy rgăn păng prăm hăt, nơng nây mra jêng blon jêh jong păng pe hăt.$b$,true),
('bunong-vn','EXO',27,2,null,$b$Ăn may ƀư nke ta puăn njônh păng; nke mra jêng du ngrăng đah nơng, jêh ri ăn ma ndop ma kông.$b$,false),
('bunong-vn','EXO',27,3,null,$b$Ăn may ƀư nơng glah dơm buh, ndroh, mâm, n'hoi srang jêh ri ndơ dơm sa ônh hâng. Ăn may ƀư lĕ rngôch ndơ dŏng nây mra kông.$b$,false),
('bunong-vn','EXO',27,4,null,$b$Ăn may ƀư ma nơng nây du pŏk dreh kông tanh srang; jêh ri ăn may dơm puăn mlâm rvang kông puăn njônh pĭt dreh nây.$b$,false),
('bunong-vn','EXO',27,5,null,$b$Ăn may dơm păng tâm dâng năp nơng bơh tâm dâng tât ta n'gul nơng.$b$,false),
('bunong-vn','EXO',27,6,null,$b$Ăn may ƀư mâng tung nơng ma si akasi jêh ri ndop ma kông.$b$,false),
('bunong-vn','EXO',27,7,null,$b$Bu mra nsro mâng tung tâm trôm rvang, jêh ri mâng tung mra gŭ mơ bar đah pĭt nơng gay dŏng tung păng.$b$,false),
('bunong-vn','EXO',27,8,null,$b$Ăn may ƀư nơng trôm hŏng ma âk pŏk kađar, tĭng nâm tâm mpơl jêh ma may ta klơ yôk.$b$,false),
('bunong-vn','EXO',27,9,null,$b$Ăn may ƀư nkual ngih bok, Mpeh pa rđŭng nkual mra geh bok mhay rhên, dĭ rgăn khân păng du rhiăng hăt ma du đah.$b$,true),
('bunong-vn','EXO',27,10,null,$b$Meh khân păng mra geh bar jât mlâm tăm ta klơ bar jât mlâm rnơl kông, nglĕ knuăk meh jêh ri rse rêt khân păng mra ƀư ma prăk.$b$,true),
('bunong-vn','EXO',27,11,null,$b$Mpeh pa mpư̆ yôk mra geh bok lĕ, dĭ rgăn păng du rhiăng hăt, ndrel ma bar jât mlâm meh jêh ri bar jât mlâm rnơl khân păng ƀư ma kông, nglĕ knuăk meh jêh ri rse rêt khân păng mra ƀư ma prăk.$b$,false),
('bunong-vn','EXO',27,12,null,$b$Mpeh pa dâng nkual mra geh bok, dĭ rgăn prăm jât hăt ndrel ma jât mlâm meh jêh ri jât mlâm rnơl.$b$,false),
('bunong-vn','EXO',27,13,null,$b$Mpeh pa lơ nkual, dĭ rgăn prăm jât hăt.$b$,false),
('bunong-vn','EXO',27,14,null,$b$Bok ta du đah mpông pêr mra geh jât ma prăm hăt, ndrel ma pe mlâm meh jêh ri pe mlâm rnơl.$b$,false),
('bunong-vn','EXO',27,15,null,$b$Jêh ri ta đah rĭ mra geh bok jât ma prăm hăt, ndrel ma pe mlâm meh jêh ri pe mlâm rnơl.$b$,true),
('bunong-vn','EXO',27,16,null,$b$Ma mpông pêr nkual mra geh du blah bok mphiar geh bar jât hăt ƀư ma bok piâk, chăng krăk, chăng rhưch, jêh ri ma mhay rhên kan bu cheh, ndrel ma puăn mlâm meh jêh ri puăn mlâm rnơl.$b$,false),
('bunong-vn','EXO',27,17,null,$b$Lĕ rngôch meh jŭm nkual mra geh rse rêt ma prăk, nglĕ knuăk ma prăk, jêh ri rnơl kông.$b$,false),
('bunong-vn','EXO',27,18,null,$b$Jong njok nkual nây mra jêng du rhiăng hăt, dĭ rgăn prăm jât hăt, jêh ri jong păng prăm hăt, ndrel ma bok mhay rhên jêh ri rnơl kông.$b$,true),
('bunong-vn','EXO',27,19,null,$b$Lĕ rngôch ndơ dŏng ma lĕ kan ngih bok, lĕ rngôch mâng pêr păng, jêh ri lĕ rngôch mâng pêr nkual mra ƀư ma kông.$b$,false),
('bunong-vn','EXO',27,20,null,$b$Ăn may ntăm ma phung ƀon lan Israel djôt leo ma may dak play Ôlivơ kloh ăn lêk hăch jêh prăp dŏng ma jâng jrêng, gay ma ŭnh kađen hit ƀa ƀơ.$b$,true),
('bunong-vn','EXO',27,21,null,$b$Tâm ngih bok nau tâm rƀŭn pa dih bok nching ta năp nau mbơh. Y-Arôn jêh ri phung kon bu klâu păng mra mât mray păng ntơm bôk măng tât ôi ta năp Yêhôva. Nau nây mra jêng nau vay n'ho ro, phung ƀon lan Israel mra tông tâm lĕ rngôch rnôk.$b$,false),
('bunong-vn','EXO',28,1,null,$b$Ăn nâu may Y-Arôn văch ta may ndrel ma phung kon bu klâu păng bơh ta nklang phung ƀon lan Israel, gay prăp khân păng ma kan gâp, jêng phung kôranh ƀư brah: Y-Arôn jêh ri phung kon bu klâu păng Y-Nadap, Y-Abihu, Y-Êlêasar, jêh ri Y-Ithamar.$b$,true),
('bunong-vn','EXO',28,2,null,$b$Ăn may ƀư ma Y-Arôn nâu may bok ao kloh ueh prăp ma nau chrêk rmah jêh ri nau ueh.$b$,false),
('bunong-vn','EXO',28,3,null,$b$Ăn may ngơi ma lĕ rngôch phung njêh, ma phung gâp ăn jêh nau blau mĭn gay ma khân păng ƀư bok ao Y-Arôn, gay prăp ma păng jêng kan kôranh ƀư brah gâp.$b$,false),
('bunong-vn','EXO',28,4,null,$b$Aơ, bok ao khân păng mra ƀư, du blah bok văn ntang ntơh, du blah ao Êphôt, du blah ao jâr, du blah ao mbâl cheh, du rplay môk kưn, jêh du njăr rse vân bŭt. Khân păng mra ƀư bok ao kloh ueh ma Y-Arôn nâu may jêh ri ma phung kon bu klâu păng, gay ma khân păng pah kan gâp jêng phung kôranh ƀư brah.$b$,false),
('bunong-vn','EXO',28,5,null,$b$Khân păng mra dŏng mah, bok nhom piâk, chăng krăk, chăng rhưch jêh ri mhay rhên.$b$,false),
('bunong-vn','EXO',28,6,null,$b$Ma nau njêh ăn khân păng ƀư ao êphôt ma mah, bok piâk, chăng krăk, chăng rhưch jêh ri mhay rhên.$b$,false),
('bunong-vn','EXO',28,7,null,$b$Ao êphôt mra geh bar blah bok nkŭm, mra tâm ndop ndrel ma bar pĭt păng, tâm ban pô nây khân păng mra tâm iang.$b$,false),
('bunong-vn','EXO',28,8,null,$b$Rse bŭt bu tanh ma nau njêh ta ao êphôt gay rêt păng, bu mra ƀư nâm bu mah bok piâk, chăng krăk, chăng rhưch jêh ri mhay rhên.$b$,false),
('bunong-vn','EXO',28,9,null,$b$Ăn may sŏk bar mlâm lŭ ônik jêh ri chih kach ta nây amoh phung kon bu klâu Israel.$b$,false),
('bunong-vn','EXO',28,10,null,$b$Prao amoh khân păng ta du mlâm lŭ, jêh ri prao amoh phung êng ta du mlâm lŭ tal bar, tĭng nâm di ntrong me deh ma khân păng.$b$,false),
('bunong-vn','EXO',28,11,null,$b$Ăn may chih kach amoh phung kon bu klâu Israel ta bar mlâm lŭ tâm ban ma bunuyh blau njêh chih kach ta ndơ tâp pŏng. Ăn may rvang khân păng ma năp mah.$b$,false),
('bunong-vn','EXO',28,12,null,$b$Ăn may dơm bar mlâm lŭ nây ta bok nkŭm săng nglik ao êphôt, jêng lŭ ăn kah gĭt ma phung kon bu klâu Israel, jêh ri Y-Arôn mra văn amoh khân păng ta bar đah săng nglik păng jêng nau kah gĭt ta năp Yêhôva.$b$,false),
('bunong-vn','EXO',28,13,null,$b$Ăn may rvang khân păng ma năp mah.$b$,false),
('bunong-vn','EXO',28,14,null,$b$Jêh ri bar njăr rse rvăk jê̆ rhên ma mah chrêk may mra păch nâm bu rse buănh vah, jêh ri ăn may tâm iang rse rvăk păch nây ta năp.$b$,false),
('bunong-vn','EXO',28,15,null,$b$Ăn may văn bok ntang ntơh nau phat dôih ma nau njêh; ăn may ƀư păng nâm bu ao êphôt ma mah, bok piâk, chăng krăk, chăng rhưch, jêh ri mhay rhên.$b$,true),
('bunong-vn','EXO',28,16,null,$b$Păng mra jêng blon jêh ri bar hăt, jong păng n'gul hăt jêh ri dĭ găn n'gul hăt lĕ.$b$,false),
('bunong-vn','EXO',28,17,null,$b$Ăn may lĭr ta păng puăn mbor lŭ khlay: Mbor nguay, du găr Sardôn, du găr tơpas, du găr êmêrôt;$b$,false),
('bunong-vn','EXO',28,18,null,$b$mbor tal bar, du găr êskabuk, du găr saphir, du găr diamôn;$b$,false),
('bunong-vn','EXO',28,19,null,$b$mbor tal pe du găr ôpal; du găr agat, du găr amêtis;$b$,false),
('bunong-vn','EXO',28,20,null,$b$mbor tal puăn, du găr bêril, du găr ônik, du găr jaspidi. Lĕ găr lŭ nây ăn may lĭr tâm năp mah,$b$,false),
('bunong-vn','EXO',28,21,null,$b$mra geh jât ma bar găr tĭng nâm amoh phung kon bu klâu Israel, bu mra kach khân păng nâm bu ndơ tâp pŏng, ăp găr lŭ geh amoh tâm phung jât ma bar mpôl băl.$b$,false),
('bunong-vn','EXO',28,22,null,$b$Ăn may ƀư ta bok văn ntang ntơh rse rvăk rhên ma mah chrêk, păch nâm bu rse vah.$b$,true),
('bunong-vn','EXO',28,23,null,$b$Ăn may ƀư ta bok văn ntang ntơh bar mlâm rvang mah,$b$,false),
('bunong-vn','EXO',28,24,null,$b$jêh ri dơm bar mlâm rvang nây ta bar đah pĭt rvang bok văn ntang ntơh nây.$b$,false),
('bunong-vn','EXO',28,25,null,$b$Ăn may nsro bar njăr rse vah mah tâm bar mlâm rvang ta bar đah pĭt bok văn ntang ntơh.$b$,false),
('bunong-vn','EXO',28,26,null,$b$Ăn may ƀư bar mlâm rvang mah, dơm ta bar đah pĭt bok văn ntang ntơh tâm trôm kŏ ma ao êphôt.$b$,false),
('bunong-vn','EXO',28,27,null,$b$Jêh ri ăn may ƀư bar mlâm rvang mah. Ăn may kât păng mơ tâm dâng ta bok nkŭm săng nglik ao êphôt êp ntŭk tâm ntrŭp ta klơ rse bŭt ao êphôt tanh ma nau njêh.$b$,false),
('bunong-vn','EXO',28,28,null,$b$Bu mra kât bok văn ntang ntơh ta rvang păng ma rvang ao êphôt ma rse vah piâk, gay ma bok văn ntang ntơh gŭ ta klơ rse bŭt ao êphôt bu tanh ma nau njêh, gay ma lơi rlât ôh bơh ao êphôt.$b$,false),
('bunong-vn','EXO',28,29,null,$b$Tơ lah Y-Arôn lăp tâm ntŭk kloh ueh, păng mra djôt amoh phung kon bu klâu Israel tâm bok văn ntang ntơh nau phat dôih ta klơ play nuih păng, gay jêng du nau kah gĭt ƀa ƀơ ta năp Yêhôva.$b$,false),
('bunong-vn','EXO',28,30,null,$b$Ăn may dơm tâm bok văn ntang ntơh nau phat dôih Urim jêh ri Thumim; jêh ri khân păng mra gŭ ta klơ play nuih Y-Arôn tơ lah păng lăp ta năp Yêhôva. Pô ri Y-Arôn mra djôt ƀa ƀơ ta klơ play nuih păng nau phat dôih phung ƀon lan Israel ta năp Yêhôva.$b$,true),
('bunong-vn','EXO',28,31,null,$b$Ăn may ƀư ao jâr êphôt ma bok piâk da dê.$b$,false),
('bunong-vn','EXO',28,32,null,$b$Mra geh trôm ntrŭp bôk, jêh ri jŭm trôm nây mra sră nâm bu trôm bu rmăn, gay ma lơi ăn sat ôh.$b$,false),
('bunong-vn','EXO',28,33,null,$b$Ăn may ƀư jŭm pĭt ao tâm dâng play pom gra nat piâk, chăng krăk, chăng rhưch gay tâm nsrah ma rlêm mah,$b$,false),
('bunong-vn','EXO',28,34,null,$b$du găr rlêm mah jêh ri du găr pom gra nat, du găr rlêm mah jêh ri du găr pom gra nat ta jŭm pĭt ao.$b$,false),
('bunong-vn','EXO',28,35,null,$b$Y-Arôn mra soh ao nây ma kan păng. Tơ lah păng mra lăp tâm ntŭk kloh ueh ta năp Yêhôva, jêh ri tơ lah păng luh bơh ntŭk nây, bu mra tăng nteh rlêm, klach lah păng khĭt.$b$,false),
('bunong-vn','EXO',28,36,null,$b$Ăn may ƀư du pŏk jê̆ mah chrêk, jêh ri ăn may treh koch ta nây nâm bu, bu koch du ndơ tâp pŏng. ‘PRĂP AN MA YÊHÔVA.’$b$,true),
('bunong-vn','EXO',28,37,null,$b$Ăn may kât păng ma rse vah piâk pa năp kưn.$b$,false),
('bunong-vn','EXO',28,38,null,$b$“Ndơ nây mra gŭ ta kleng Y-Arôn jêh ri Y-Arôn mra tuy nau kue phung ƀon lan Israel ƀư dôl khân păng nhhơr ndơ kloh ueh. Ndơ nây mra gŭ ƀa ƀơ ta kleng păng gay ma Yêhôva dơn khân păng.$b$,false),
('bunong-vn','EXO',28,39,null,$b$Ăn may tanh ao mbâl cheh ma mhay rhên. Ăn may ƀư du rplay môk kưn ma mhay rhên, jêh ri ăn may ƀư du njăr rse bŭt cheh.$b$,true),
('bunong-vn','EXO',28,40,null,$b$Ma phung kon bu klâu Y-Arôn, ăn khân may ƀư ao jâr khân păng soh, ntâu jot jêh ri đon prăp ma nau chrêk rmah jêh ri ma nau ueh.$b$,true),
('bunong-vn','EXO',28,41,null,$b$Ăn may sâm soh an ao nây ma nâu may Y-Arôn jêh ri ma phung kon bu klâu păng ndrel ma păng. Ăn may tŏ dak ƀâu kah ta khân păng, prăp ăn khân păng, jêh ri ƀư kloh ueh khân păng gay ma khân păng dơi pah kan ma gâp jêng phung kôranh ƀư brah.$b$,false),
('bunong-vn','EXO',28,42,null,$b$Ăn may ƀư ma khân păng kho gleh ma mhay rhên, gay ma nkŭm nau bêch kuh rhôk khân păng; kho nây bơh kŭr bŭt tât tơm blu.$b$,false),
('bunong-vn','EXO',28,43,null,$b$Y-Arôn jêh ri phung kon bu klâu păng mra soh kho nây tơ lah khân păng lăp tâm ngih bok nau tâm rƀŭn, mâu lah tơ lah khân păng hăn êp nơng gay pah kan tâm ntŭk kloh ueh, klach lah khân păng ƀư tih khân păng nơm jêh ri khĭt. Nau aơ jêng nau vay n'ho ro ma Y-Arôn jêh ri ma phung kon sau păng kăndơ̆ .$b$,false),
('bunong-vn','EXO',29,1,null,$b$Ăn may ƀư pô aơ gay prăp an khân păng, gay ma khân păng dơi pah kan phung kôranh ƀư brah ma gâp. Sŏk hom du mlâm ndrôk nkuăng ndăm jêh ri bar mlâm biăp nkuăng mâu geh ntŭk ƀơ̆ ôh,$b$,true),
('bunong-vn','EXO',29,2,null,$b$Piăng let mâu geh ndrui, ƀănh mâu geh ndrui pĕt mon ma dak play Ôlivơ. Ăn may ƀư piăng let nây ma rnih muy ba ƀlê.$b$,false),
('bunong-vn','EXO',29,3,null,$b$Ăn may dơm ndơ nây tâm du mlâm bĭ jêh ri njŭn păng ndrel ma ndrôk nkuăng jêh ri bar mlâm biăp nkuăng nây.$b$,true),
('bunong-vn','EXO',29,4,null,$b$Ăn may njŭn Y-Arôn jêh ri phung kon bu klâu păng ta năp mpông bloh ngih bok nau tâm rƀŭn, jêh ri may ŭm an khân păng.$b$,false),
('bunong-vn','EXO',29,5,null,$b$Ăn may sŏk sâm soh ma kho ao jêh ri sâm soh Y-Arôn ma ao jâr, ao jâr êphôt, ao êphôt bok văn ntang ntơh jêh ri ăn may rêt an păng ma rse bŭt êphôt tanh ma mhay rhên.$b$,false),
('bunong-vn','EXO',29,6,null,$b$Ăn may sâm ndô an môk kưn ta bôk păng jêh ri dơm đon hađăch kloh ueh ta klơ môk kưn.$b$,false),
('bunong-vn','EXO',29,7,null,$b$Ăn may sŏk dak si ƀâu kah prăp tŏ, kêt ta klơ bôk păng, jêh ri tŏ păng,$b$,false),
('bunong-vn','EXO',29,8,null,$b$jêh ri ăn may njŭn leo phung kon bu klâu păng jêh ri sâm soh khân păng ma ao jâr.$b$,false),
('bunong-vn','EXO',29,9,null,$b$Ăn may rêt rse bŭt ma khân păng jêh ri sâm ndô môk ma khân păng. Kan phung Kôranh ƀư brah jêng kan khân păng ma nau vay gŭ n'ho ro. Tâm ban pô nây lĕ may mra prăp an Y-Arôn jêh ri phung kon bu klâu păng.$b$,false),
('bunong-vn','EXO',29,10,null,$b$Jêh ri ăn may têk njŭn ndrôk nkuăng ta năp ngih bok nau tâm rƀŭn. Y-Arôn jêh ri phung kon bu klâu păng mra pah ti khân păng ta klơ bôk ndrôk.$b$,true),
('bunong-vn','EXO',29,11,null,$b$Ăn may sreh ndrôk nkuăng ta năp Yêhôva ta mpông ngih bok nau tâm rƀŭn.$b$,false),
('bunong-vn','EXO',29,12,null,$b$Ăn may sŏk bơh mham ndrôk nkuăng jêh ri mhĭng mham nây ta nke nơng ƀư brah ma nglau ti may, jêh ri ăn may nkhŭt mham hôm ta jâng nơng.$b$,false),
('bunong-vn','EXO',29,13,null,$b$Ăn may sŏk lĕ ngi ndâr khân păng, jêh ri gŭch ta klơ nơng.$b$,false),
('bunong-vn','EXO',29,14,null,$b$Ƀiă lah ăn may gŭch pa dih mpâr ƀon nglay ndrôk nkuăng, ntâu jêh ri ek păng; păng jêng mpa ƀư brah ma nau tih,$b$,false),
('bunong-vn','EXO',29,15,null,$b$Jêh ri ăn may sŏk du mlâm biăp nkuăng, jêh ri Y-Arôn nđâp ma phung kon bu klâu păng mra pah ti khân păng ta klơ bôk biăp nkuăng nây.$b$,false),
('bunong-vn','EXO',29,16,null,$b$Ăn may sreh biăp nkuăng jêh ri sŏk mham păng, djrah păng jŭm nơng nây.$b$,false),
('bunong-vn','EXO',29,17,null,$b$Jêh ri ăn may koh biăp nkuăng âk rngơl, rao proch klơm jêh ri jâng păng, jêh ri dơm khân păng ndrel ma rngơl păng jêh ri bôk păng.$b$,false),
('bunong-vn','EXO',29,18,null,$b$Ăn may gŭch lĕ biăp nkuăng nây ta klơ nơng. Păng jêng mpa nhhơr gŭch ma Yêhôva, ƀâu kah, mpa nhhơr đah ŭnh ma Yêhôva.$b$,false),
('bunong-vn','EXO',29,19,null,$b$Ăn may sŏk biăp nkuăng hôm; Y-Arôn jêh ri phung kon bu klâu păng mra pah ti khân păng ta klơ bôk biăp nkuăng.$b$,true),
('bunong-vn','EXO',29,20,null,$b$Ăn may sreh biăp nkuăng nây; ăn may sŏk bơh mham păng ăn may mhĭng ta klơ tôr ma phung kon bu klâu păng ta nglau me ti ma khân păng jêh ri ta nglau me jâng ma khân păng jêh ri ăn may djrah mham hôm jŭm ta nơng.$b$,false),
('bunong-vn','EXO',29,21,null,$b$Jêh ri ăn may sŏk ƀă mham ta klơ ta klơ nơng jêh ri dak si ƀâu kah, prăp tŏ, jêh ri ma ndơ nây ăn may djrah ta Y-Arôn jêh ri bok ao păng, ta phung kon bu klâu păng jêh ri bok ao khân păng ndrel ma păng. Pô ri păng jêh ri bok ao păng mra kloh ueh, nđâp ma phung kon bu klâu păng jêh ri bok ao khân păng ndrel ma păng.$b$,false),
('bunong-vn','EXO',29,22,null,$b$Ăn may sŏk tâm ban lĕ ngi biăp nkuăng, chiăng lay păng, ngi ndâr proch klơm, ntŭk mlâm toyh tâm proch klơm, bar găr play leh jêh ri ndâr ngi nkŭm khân păng, jêh ri nglu ma (yor lah păng jêng du mlâm biăp nkuăng prăp ăn)$b$,true),
('bunong-vn','EXO',29,23,null,$b$jêh ri sŏk bơh bĭ piăng let mâu geh ndrui gŭ ta năp Yêhôva du glo piăng let, du glo ƀănh let dak play Ôlivơ jêh ri du glo ƀănh n'hơ.$b$,false),
('bunong-vn','EXO',29,24,null,$b$Ăn may dơm lĕ ndơ nây tâm ti Y-Arôn jêh ri tâm ti phung kon bu klâu păng jêh ri ăn khân may yơk ryeng păng jêng ndơ nhhơr ryeng ta năp Yêhôva.$b$,false),
('bunong-vn','EXO',29,25,null,$b$Jêh ri ăn may sŏk lơi ndơ nây bơh ti khân păng, jêh ri su ndơ nây ta klơ nơng, ntop đŏng ma mpa nhhơr gŭch, jêng ndơ ƀâu kah ta năp Yêhôva. Păng jêng mpa nhhơr đah ŭnh ma Yêhôva.$b$,false),
('bunong-vn','EXO',29,26,null,$b$Ăn may sŏk ntang ntơh biăp nkuăng ma nau prăp an Y-Arôn, jêh ri ryeng păng jêng mpa nhhơr ryeng ta năp Yêhôva. Ndơ nây mra jêng rngơl ma may.$b$,true),
('bunong-vn','EXO',29,27,null,$b$Ăn may prăp an ntang ntơh mpa nhhơr ryeng jêh ri nglu jêng rngơl ma phung kôranh ƀư brah bu ryeng jêh, jêh ri nhhơr bơh biăp nhhơr nau prăp an, yor ndơ nây jêng ndơ Y-Arôn jêh ri phung kon bu klâu păng.$b$,false),
('bunong-vn','EXO',29,28,null,$b$Ndơ nây mra jêng ndơ Y-Arôn jêh ri phung kon bu klâu păng, jêng nau vay n'ho ro bơh phung ƀon lan Israel, yor lah păng jêng rngơl kôranh ƀư brah phung ƀon lan Israel nhhơr bơh mpa khân păng nhhơr ma nau đăp mpăn, jêng mpa khân păng nhhơr ma Yêhôva.$b$,false),
('bunong-vn','EXO',29,29,null,$b$Bok ao kloh ueh Y-Arôn mra cha lat ma phung kon bu klâu păng. Khân păng mra soh tơ lah bu tŏ dak si ƀâu kah ta khân păng jêh ri prăp an ma khân păng.$b$,true),
('bunong-vn','EXO',29,30,null,$b$Kon bu klâu ntrok păng mra soh bok ao nây pơh nar, tơ lah păng lăp tâm ngih bok nau tâm rƀŭn gay ƀư kan tâm ntŭk kloh ueh.$b$,false),
('bunong-vn','EXO',29,31,null,$b$Ăn may sŏk biăp nkuăng ma nau prăp ăn, jêh ri gâm nglay păng tâm ntŭk kloh.$b$,true),
('bunong-vn','EXO',29,32,null,$b$Y-Arôn jêh ri phung kon bu klâu păng mra sa ta mpông ngih bok nau tâm rƀŭn nglay puăch biăp nkuăng jêh ri piăng let tâm bĭ.$b$,true),
('bunong-vn','EXO',29,33,null,$b$Khân păng mra sa mpa nây dŏng jêh ma nau ƀư kloh nau tih, gay prăp ăn jêh ri ƀư kloh ueh khân păng, ƀiă lah mâu geh du huê bu năch dơi sa mpa nây ôh, yor lah ndơ nây jêng kloh ueh.$b$,false),
('bunong-vn','EXO',29,34,null,$b$Tơ lah hôm nglay puăch ma nau prăp an mâu lah piăng let tât ôi, ăn may su lơi ma ŭnh moh mpa hôm. Bu mâu dơi sa ndơ nây ôh, yor lah ndơ nây jêng kloh ueh.$b$,false),
('bunong-vn','EXO',29,35,null,$b$Ăn may ƀư pô nây ma Y-Arôn jêh ri ma phung kon bu klâu păng, tĭng nâm lĕ rngôch nau gâp ntăm jêh ma may. Ăn may ƀư nau prăp an khân păng dôl pơh nar.$b$,true),
('bunong-vn','EXO',29,36,null,$b$Ăn may nhhơr ăp nar du mlâm ndrôk nkuăng jêng ndơ ƀư brah ma nau tih gay ƀư kloh nau tih. Tâm ban lĕ ăn nhhơr ndơ nhhơr ma nau tih yor nơng, tơ lah may ƀư nau ƀư kloh ma nơng, jêh ri ăn may tŏ nơng nây gay prăp an nơng.$b$,true),
('bunong-vn','EXO',29,37,null,$b$Dôl tâm pơh nar ăn may ƀư nau ƀư kloh nơng nây jêh ri prăp an păng, jêh ri nơng mra kloh ueh lơn. Moh ndơ di ta nơng jêng kloh ueh.$b$,false),
('bunong-vn','EXO',29,38,null,$b$Aơ, mpa ăn may nhhơr ta klơ nơng; bar mlâm kon biăp geh du năm ăp nar ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','EXO',29,39,null,$b$Ăn may nhhơr bar mlâm kon biăp nây tâm ôi, jêh ri du mlâm êng tâm mhaơ.$b$,false),
('bunong-vn','EXO',29,40,null,$b$Ăn may nhhơr ndrel ma kon biăp tal lor du kô̆ tâm jât rnih muy piăch mon tâm du kô̆ tâm puăn dak play Ôlivơ ƀư lêk jêh, jêh ri du kô̆ tâm puăn dak play kriăk ƀâu jêng ndơ nhhơr nkhŭt.$b$,false),
('bunong-vn','EXO',29,41,null,$b$Ăn may nhhơr kon biăp tal bar ta mhaơ, ndrel ma ndơ nhhơr rnih muy jêh ri ndơ nhhơr nkhŭt nâm bu ta ôi, jêng ndơ ƀâu kah, ndơ nhhơr ăn ŭnh sa ma Yêhôva.$b$,false),
('bunong-vn','EXO',29,42,null,$b$Păng mra ndơ nhhơr gŭch ƀa ƀơ tâm lĕ rngôch rnôk khân may ta mpông ngih bok nau tâm rƀŭn ta năp Yêhôva. Ta nây yơh gâp mra tâm mâp đah khân may, ŭch ngơi ma khân may.$b$,false),
('bunong-vn','EXO',29,43,null,$b$Ta nây gâp mra tâm mâp đah phung ƀon lan Israel, jêh ri ntŭk nây mra jêng kloh ueh ma nau chrêk rmah gâp.$b$,true),
('bunong-vn','EXO',29,44,null,$b$Gâp mra prăp an ngih bok nau tâm rƀŭn jêh ri nơng. Gâp mra prăp an tâm ban lĕ, Y-Arôn jêh ri phung kon bu klâu păng, gay ma khân păng pah kan ma gâp jêng phung kôranh ƀư brah.$b$,false),
('bunong-vn','EXO',29,45,null,$b$Jêh ri gâp mra gŭ ta nklang phung ƀon lan Israel, jêh ri jêng Brah Ndu khân păng.$b$,true),
('bunong-vn','EXO',29,46,null,$b$Jêh ri khân păng mra gĭt gâp jêng Yêhôva Brah Ndu khân păng, nơm ngluh jêh khân păng bơh n'gor Êjipt, gay ma gâp dơi gŭ ta nklang khân păng.$b$,true),
('bunong-vn','EXO',30,1,null,$b$Ăn may ƀư du rplay nơng gŭch mpa ƀâu kah ma si akasi,$b$,true),
('bunong-vn','EXO',30,2,null,$b$jong njok păng geh du hăt jêh ri dĭ rgăn păng du hăt lĕ, ăn păng jêng blon, jêh ri jong păng bar hăt. Nke păng mra jêng du ngrăng đah păng.$b$,false),
('bunong-vn','EXO',30,3,null,$b$Ăn may nhom păng ma mah chrêk ntŭk ta klơ jŭm rŏ pĭt jêh ri nke; jêh ri ăn may ƀư năp ma mah jŭm păng.$b$,false),
('bunong-vn','EXO',30,4,null,$b$Ăn may ƀư tâm dâng năp bar rvang mah ta bar đah pĭt. Ăn may dơm rvang nây ta bar đah pĭt gay dơi nsro mâng prăp tung păng.$b$,false),
('bunong-vn','EXO',30,5,null,$b$Ăn may ƀư mâng tung nây ma tơm si akasi; jêh ri pot păng ma mah.$b$,false),
('bunong-vn','EXO',30,6,null,$b$Ăn may dơm nơng ta năp bok nching gŭ êp hip nau tâm rnglăp, ta năp ntŭk yô̆ an gŭ ta klơ nau mbơh. Ta nây gâp mra tâm mâp đah may.$b$,true),
('bunong-vn','EXO',30,7,null,$b$Y-Arôn mra gŭch mpa ƀâu kah ta nây; păng mra gŭch mpa nây ăp ôi tơ lah păng nkra ŭnh kađen.$b$,true),
('bunong-vn','EXO',30,8,null,$b$Păng mra gŭch lĕ mpa nây ta măng tơ lah păng nkra ŭnh kađen. Păng jêng mpa ƀâu kah mro ta năp Yêhôva tâm lĕ rngôch rnôk khân may.$b$,false),
('bunong-vn','EXO',30,9,null,$b$Lơi gŭch ôh ta klơ nơng nây mpa ƀâu kah mâu kloh, mâu lĕ nhhơr mpa nhhơr gŭch, ndơ nhhơr rnih muy, mâu lah ndơ nhhơr nkhŭt.$b$,false),
('bunong-vn','EXO',30,10,null,$b$Du tơ̆ ăp năm Y-Arôn mra ƀư nau ƀư kloh nau tih ta nke păng ma mham mpa ƀư brah ƀư kloh nau tih, păng mra ƀư kloh nau tih ta nây du tơ̆ ăp năm tâm lĕ rngôch rnôk khân may. Păng jêng mpa kloh ueh lơn ma Yêhôva.$b$,false),
('bunong-vn','EXO',30,11,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',30,12,null,$b$“Tơ lah may kơp phung ƀon lan Israel, ăp nơm khân păng mra rvăt bơh Yêhôva nau tâm chuai păng nơm tơ lah may kơp khân păng, gay ma lơi ăn geh nau ji tưp ndrăng phung khân păng tơ lah may kơp khân păng.$b$,false),
('bunong-vn','EXO',30,13,null,$b$Ăp nơm phung bu kơp mra ăn n'gul sêkel (pham gram prăk) tĭng nâm Sêkel bơh jrô kloh ueh (du Sêkel jêng bar jât gêra), pham gram prăk jêng ndơ nhhơr ma Yêhôva.$b$,true),
('bunong-vn','EXO',30,14,null,$b$Ăp nơm bu kơp bơh nơm geh bar jât năm rlơ̆ klơ mra ăn ndơ nhhơr nây ma Yêhôva.$b$,false),
('bunong-vn','EXO',30,15,null,$b$Bunuyh ndrŏng mâu mra rvăt âk lơn ôh, jêh ri bunuyh trơi mâu mra nkhŭt djê̆ lơn ma pham gram prăk lĕ, tơ lah khân may ăn ndơ nhhơr ma Yêhôva gay ƀư kloh khân may nơm ma nau tih.$b$,false),
('bunong-vn','EXO',30,16,null,$b$Ăn may sŏk dơn bơh phung ƀon lan Israel prăk ma nau ƀư kloh nau tih, jêh ri dŏng prăk nây ma kan tâm ngih bok nau tâm rƀŭn, gay jêng ndơ ăn Yêhôva kah gĭt ma phung ƀon lan Israel, gay ƀư kloh khân may nơm ma nau tih.$b$,false),
('bunong-vn','EXO',30,17,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',30,18,null,$b$“Ăn may ƀư tâm ban lĕ ma kông du mlâm thŭng dak prăp rao, jêh ri jâng păng ma kông lĕ. Ăn may dơm păng vah vang ngih bok nau tâm rƀŭn jêh ri nơng, jêh ri ăn may nkhŭt dak tâm thŭng nây.$b$,false),
('bunong-vn','EXO',30,19,null,$b$Ma dak nây Y-Arôn jêh ri phung kon bu klâu păng mra rao jâng ti.$b$,false),
('bunong-vn','EXO',30,20,null,$b$Tơ lah khân păng lăp tâm ngih bok nau tâm rƀŭn, mâu lah tơ lah khân păng hăn dăch nơng gay pah kan gŭch ma ŭnh mpa nhhơr ma Yêhôva, khân păng mra rao jâng ti ma dak klach lah khân păng khĭt.$b$,true),
('bunong-vn','EXO',30,21,null,$b$Pô nây khân păng rao jâng ti khân păng klach lah khân păng khĭt. Nau nây mra jêng nau vay n'ho ro ma păng jêh ri ma phung kon sau păng tâm lĕ rngôch rnôk.”$b$,false),
('bunong-vn','EXO',30,22,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',30,23,null,$b$“Sŏk hom mpa ƀâu kah ueh lơn, pham jât ma bar kilô dak si tăng, dak, puăn jât ma nguay kilô nâm bu ntĭt n'gul nây Sinamôn ƀâu kah jêh ri puăn jât ma nguay rpho ƀâu kah,$b$,false),
('bunong-vn','EXO',30,24,null,$b$pham jât ma bar kilô kas, tĭng nâm Sêkel bơh jrô kloh ueh jêh ri prăm lit dak play Ôlivơ.$b$,false),
('bunong-vn','EXO',30,25,null,$b$Ăn may ƀư ma ndơ nây du ntil dak ƀâu kah prăp ma nau tŏ kloh ueh, jêng dak ƀâu kah tâm lŭk tĭng nâm nau vay phung nkra dak ƀâu kah. Păng mra jêng dak ƀâu kah prăp ma nau tŏ kloh ueh.$b$,false),
('bunong-vn','EXO',30,26,null,$b$Ăn may tŏ dak ƀâu kah nây ta ngih bok nau tâm rƀŭn jêh ri hip nau tâm rnglăp.$b$,false),
('bunong-vn','EXO',30,27,null,$b$Sưng nđâp lĕ rngôch ndơ dŏng ma păng, jâng jrêng nđâp lĕ rngôch ndơ dŏng ma păng, jêh ri nơng gŭch mpa ƀâu kah.$b$,false),
('bunong-vn','EXO',30,28,null,$b$Nơng mpa nhhơr gŭch nđâp lĕ rngôch ndơ dŏng ma păng, jêh ri thŭng dak nđâp jâng păng.$b$,false),
('bunong-vn','EXO',30,29,null,$b$Ăn may prăp an khân păng, gay ma khân păng mra jêng kloh ueh lơn. Moh ndơ di ma khân păng mra jêng kloh ueh.$b$,false),
('bunong-vn','EXO',30,30,null,$b$Ăn may tŏ dak ƀâu kah ta Y-Arôn, jêh ri ta phung kon bu klâu păng, jêh ri prăp ăn khân păng, gay ma khân păng dơi pah kan ma gâp tâm kan phung Kôranh ƀư brah.$b$,false),
('bunong-vn','EXO',30,31,null,$b$Ăn may lah ma phung ƀon lan Israel. Ndơ aơ mra jêng ma gâp dak ƀâu kah prăp ma nau tŏ kloh ueh tâm lĕ rngôch rnôk khân may.$b$,false),
('bunong-vn','EXO',30,32,null,$b$Lơi ăn bu nkhŭt ôh păng ta săk jăn du huê bunuyh ƀon lan, mâu lĕ khân may dơi ƀư dak ƀâu kah êng tĭng nâm mbuch tâm ban pô nây. Păng jêng kloh ueh, jêh ri ăn khân may uănh ma păng jêng kloh ueh lĕ.$b$,false),
('bunong-vn','EXO',30,33,null,$b$Bu nâm tâm rlŭk tâm ban, mâu lah mbu dơm păng ta du huê bunuyh bu năch, ăn bu nkhĭt păng.”$b$,false),
('bunong-vn','EXO',30,34,null,$b$Yêhôva lah ma Y-Môis: “Sŏk hom ndơ ƀâu kah Stakê, Ônika, gal ba num, ndơ ƀâu kah njŭng jêh ri kloh (ăp ntil mra veh rnâng tâm ban).$b$,true),
('bunong-vn','EXO',30,35,null,$b$Ăn may ƀư ma ndơ nây du ntil ndơ ƀâu kah, kah ma boh rsang jêh ri kloh ueh.$b$,false),
('bunong-vn','EXO',30,36,null,$b$Ăn may ƀư lêk jê̆ pô nây, jêh ri dơm du kô̆ ta năp nau mbơh tâm ngih bok nau tâm rƀŭn ta ntŭk gâp mra tâm mâp đah khân may. Păng mra jêng kloh ueh lơn ma khân may.$b$,false),
('bunong-vn','EXO',30,37,null,$b$Ndơ ƀâu kah nây khân may mâu dơi ƀư prăp ma khân may nơm ôh tĭng nâm rnâng nây. Ăn khân may uănh păng jêng kloh ueh prăp ma Yêhôva.$b$,false),
('bunong-vn','EXO',30,38,null,$b$Mbu nâm mra ƀư nâm bu pô nây, gay dŏng ma păng nơm, ăn bu nkhĭt păng.”$b$,true),
('bunong-vn','EXO',31,1,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',31,2,null,$b$“Ăn may gĭt gâp kuăl jêh Y-Bêsalel kon bu klâu Y-Uri, kon bu klâu Y-Hur, bơh ndŭl mpôl Y-Yuđa,$b$,false),
('bunong-vn','EXO',31,3,null,$b$gâp mbêng jêh păng ma Brah Huêng Ueh Brah Ndu, ma nau njêh, nau gĭt rbăng, nau gĭt mĭn, jêh ri nau njêh tâm lĕ rngôch kan ƀư.$b$,false),
('bunong-vn','EXO',31,4,null,$b$Gâp ăn păng dơi njêng nkra ndơ, ƀư kan ma mah, prăk jêh ri kông$b$,false),
('bunong-vn','EXO',31,5,null,$b$koch chih lŭ prăp koh trah si jêh ri ƀư ăp ntil kan n'hĭ mblum.$b$,false),
('bunong-vn','EXO',31,6,null,$b$Jêh ri gâp ăn Y-Ôhôliap kon bu klâu Y-Ahisamak bơh ndŭl mpôl Dan jêng nơm kơl păng. Gâp ăn jêh nau blau mĭn ma lĕ rngôch phung njêh, gay ma khân păng dơi ƀư lĕ nau gâp ntăm jêh ma may;$b$,false),
('bunong-vn','EXO',31,7,null,$b$ngih bok nau tâm rƀŭn, hip nau tâm rnglăp, ntŭk yô̆ an gŭ ta klơ păng, jêh ri lĕ rngôch ndơ dŏng ma ngih bok,$b$,false),
('bunong-vn','EXO',31,8,null,$b$sưng nđâp ma ndơ dŏng ma păng, jâng jrêng mah kloh nđâp lĕ rngôch ndơ dŏng ma păng, nơng gŭch mpa ƀâu kah,$b$,false),
('bunong-vn','EXO',31,9,null,$b$nơng mpa nhhơr gŭch nđâp lĕ rngôch ndơ dŏng ma păng, thŭng dak ndrel ma jâng păng,$b$,false),
('bunong-vn','EXO',31,10,null,$b$bok ao ƀư ma nau njêh, bok ao kloh ueh kôranh ƀư brah Y-Arôn jêh ri bok ao phung kon bu klâu păng dŏng ma kan Kôranh ƀư brah,$b$,false),
('bunong-vn','EXO',31,11,null,$b$dak ƀâu kah prăp tŏ, jêh ri ndơ ƀâu kah prăp ma jrô kloh ueh. Khân păng mra ƀư lĕ tĭng nâm nau gâp ntăm jêh ma khân may.”$b$,false),
('bunong-vn','EXO',31,12,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',31,13,null,$b$“Ngơi hom ma phung ƀon lan Israel, ‘Ăn khân may kah gĭt prăp lĕ rngôch nar Saƀat gâp, yor lah nau nây jêng nau tâm mbên gâp đah khân may tâm lĕ rngôch rnôk khân may, gay ma khân may dơi gĭt ma gâp jêng Yêhôva, nơm ƀư kloh ueh khân may.$b$,false),
('bunong-vn','EXO',31,14,null,$b$Ăn khân may kah gĭt prăp nar Saƀat, yor lah păng jêng nar kloh ueh ma khân may. Mbu nâm ƀư ƀơ̆ nar Saƀat, ăn bu nkhĭt păng; jêh ri mbu nâm pah kan du ntil tâm nar nây, ăn bu nkhĭt lơi păng.$b$,false),
('bunong-vn','EXO',31,15,null,$b$Ăn bu pah kan dôl tâm prao nar, ƀiă lah nar pơh jêng nar Saƀat, nar rlu kloh ueh ma Yêhôva. Mbu nâm pah du ntil kan nar Saƀat, ăn bu nkhĭt păng.$b$,false),
('bunong-vn','EXO',31,16,null,$b$Pô ri phung ƀon lan Israel mra prăp nar Saƀat, gay yơk ma nar Saƀat tâm lĕ rngôch rnôk khân păng jêng nau tâm rnglăp n'ho ro.$b$,true),
('bunong-vn','EXO',31,17,null,$b$Nau nây jêng nau tâm mbên gâp đah phung ƀon lan Israel n'ho ro, yor lah tâm prao nar Yêhôva rhăk trôk jêh ri neh ntu, jêh ri ta nar pơh păng rlu kan jêh ri mpăn tay suan.$b$,false),
('bunong-vn','EXO',31,18,null,$b$Dôl gŭ ta yôk Sinai, Yêhôva ntăm jêh ma Y-Môis lĕ ntil nau vay, ăn ma păng bar pŏk kađar Nau Mbơh Jêng nanê̆ ” jêng bar pŏk kađar lŭ tă Brah Ndu dŏng nglau ti păng nơm chih jêh lĕ ntil nau vay.$b$,false),
('bunong-vn','EXO',32,1,null,$b$Tơ lah phung ƀon lan saơ Y-Môis jŏ jŭr tă bơh yôk, khân păng tâm rƀŭn jŭm Y-Môis jêh ri lah ma păng: “Ƀư ma he rup brah mra hăn pa năp he; yor lah Y-Arôn nây, nơm ngluh jêh he bơh n'gor Êjipt, he mâu gĭt ôh moh nau tât jêh ma păng,”$b$,true),
('bunong-vn','EXO',32,2,null,$b$Y-Arôn lah ma khân păng: “Doh lơi thek mah ta tôr ur khân may, kon bu klâu khân may, jêh ri kon bu ur khân may, jêh ri ndơp ăn ma gâp.”$b$,false),
('bunong-vn','EXO',32,3,null,$b$Pô ri lĕ rngôch phung ƀon lan doh thek khân păng ta tôr jêh ri ndơp leo ma Y-Arôn.$b$,false),
('bunong-vn','EXO',32,4,null,$b$Y-Arôn sŏk dơn ndơ nay bơh ti khân păng, păng nkra ndơ nây ma ndơ trah, jêh ri tŏ njêng rup kon ndrôk. Jêh ri khân păng lah: “Ơ phung Israel, Aơ brah khân may, nơm ngluh jêh khân may bơh n'gor Êjipt.”$b$,false),
('bunong-vn','EXO',32,5,null,$b$Tơ lah Y-Arôn saơ nau nây, păng rdâk du mlâm nơng ta năp păng; jêh ri păng nter mbơh: “Ôi taơ bu mra geh nau sông nhêt yơk mbah ma Yêhôva.”$b$,false),
('bunong-vn','EXO',32,6,null,$b$Ôi taơ khân păng kah bêch, ơm ôi, jêh ri khân păng nhhơr mpa nhhơr gŭch jêh ri mpa nhhơr ma nau đăp mpăn. Phung ƀon lan gŭ gay ma nhêt sông, jêh ri khân păng dâk ŭch pâl.$b$,false),
('bunong-vn','EXO',32,7,null,$b$Yêhôva lah ma Y-Môis: “Jŭr hom, yor lah phung ƀon lan may, phung may ngluh jêh bơh n'gor Êjipt, ƀư ƀơ̆ jêh khân păng nơm.$b$,false),
('bunong-vn','EXO',32,8,null,$b$Khân păng ngăch nkhah du jêh đah trong gâp ntăm jêh ma khân păng. Khân păng tŏ njêng jêh ma khân păng nơm du mlâm rup kon ndrôk. Khân păng mbah yơk ma rup nây, jêh ri nhhơr mpa ƀư brah ma păng, jêh ri khân păng lah; ‘Ơ phung Israel, aơ brah khân may, nơm ngluh jêh khân may bơh n'gor Êjipt.’ ”$b$,false),
('bunong-vn','EXO',32,9,null,$b$Yêhôva lah ma Y-Môis; “Gâp saơ jêh phung ƀon lan aơ jêng du phung ƀon lan dăng bôk.$b$,false),
('bunong-vn','EXO',32,10,null,$b$Pô ri aƀaơ, lơi gâp, gay ma nau gâp ji nuih dơi hit đah khân păng jêh ri gâp ƀư rai khân păng; ƀiă lah gâp mra njêng bơh may du ndŭl mpôl toyh.$b$,false),
('bunong-vn','EXO',32,11,null,$b$Ƀiă lah Y-Môis vơh vơl ma Yêhôva Brah Ndu păng, lah: “Ơ Yêhôva, mâm ƀư nau may nuih hit đah phung ƀon lan may, phung may ngluh jêh bơh n'gor Êjipt ma nau brah toyh jêh ri ma ti ktang may?$b$,false),
('bunong-vn','EXO',32,12,null,$b$Mâm phung Êjipt mra lah: ‘Ma nau mĭn ŭch ƀư mhĭk yơh, păng ngluh jêh, gay ma nkhĭt lơi tâm yôk yơh, jêh ri ƀư rai khân păng bơh neh ntu? Lơi hom nau may ji nuih duh jêh ri tâm rgâl nau mĭn may ŭch ƀư mhĭk ma phung ƀon lan may.$b$,false),
('bunong-vn','EXO',32,13,null,$b$Ăn may kah gĭt ma Y-Abraham, Y-Isăk jêh ri Y-Israel, phung oh mon may ma khân păng yơh may ton sơm jêh đah may nơm, lah: ‘Gâp mra ăn bĭk phung kon sau khân may, nâm bu mănh tâm trôk, jêh ri gâp mra ăn ma phung kon sau khân may lĕ neh n'gor aơ gâp ngơi jêh ma khân may, jêh ri khân păng mra dơm n'ho ro.”$b$,false),
('bunong-vn','EXO',32,14,null,$b$Jêh ri Yêhôva tâm rgâl nau păng mĭn gay ƀư mhĭk ma phung ƀon lan păng.$b$,false),
('bunong-vn','EXO',32,15,null,$b$Y-Môis n'gĭl jêh ri jŭr yôk, djôt bar pŏk kađar nau mbơh, kađar nây geh nau mbơh bar đah.$b$,true),
('bunong-vn','EXO',32,16,null,$b$Kađar nây jêng kan Brah Ndu, jêh ri nau chih jêng nau Brah Ndu chih, tor jêh ta kađar nây.$b$,false),
('bunong-vn','EXO',32,17,null,$b$Tơ lah Y-Yôsuê tăng bâr phung ƀon lan nter, păng lah ma Y-Môis, geh nteh nau tâm lơh tâm nkual.”$b$,false),
('bunong-vn','EXO',32,18,null,$b$Ƀiă lah Y-Môis lah: “Mâu di bâr nter phung dơi, mâu lĕ di bâr nter phung roh, ƀiă lah bâr phung mprơ yơh gâp tăng.”$b$,false),
('bunong-vn','EXO',32,19,null,$b$Jêh ri tơ lah păng tât êp ntŭk nkual, păng saơ kon ndrôk jêh ri kadŏ, Nau ji nuih Y-Môis hit ro, jêh ri păng klŭp kađar bơh ti păng jêh ri nchah lơi ta jâng yôk.$b$,false),
('bunong-vn','EXO',32,20,null,$b$Y-Môis sŏk rup ndrôk khân păng ƀư jêh ri su ma ŭnh, păng ƀư hăch jêng rmuy jêh ri nkhŭt rmuy nây tâm dak, jêh ri ăn phung ƀon lan Israel nhêt.$b$,false),
('bunong-vn','EXO',32,21,null,$b$Y-Môis lah ma Y-Arôn: “Moh phung ƀon lan aơ ƀư jêh ma may kŏ tât may ăn tât nau tih toyh ma khân păng?”$b$,true),
('bunong-vn','EXO',32,22,null,$b$Y-Arôn lah: “Lơi ăn nau ji nuih kôranh gâp hit ôh. May gĭr phung ƀon lan aơ rŏng ma nau tih.$b$,false),
('bunong-vn','EXO',32,23,null,$b$Yor lah khân păng lah ma gâp: ‘Ăn may ƀư ma he rup brah mra hăn pa năp he; yor lah Y-Môis nây, ngluh jêh he bơh n'gor Êjipt, he mâu gĭt ôh moh nau tât ma păng,$b$,true),
('bunong-vn','EXO',32,24,null,$b$gâp lah ma khân păng, ‘Mbu nâm geh mah, ăn khân păng doh lơi.’ Pô ri khân păng ăn mah nây ma gâp, jêh ri gâp klŭp mah nây tâm ŭnh, jêh ri bơh nây luh kon ndrôk aơ.”$b$,false),
('bunong-vn','EXO',32,25,null,$b$Tơ lah Y-Môis saơ phung ƀon lan nau mpăn tĭng nâm bu nau khân păng ŭch, mâu geh nơm chiă uănh khân păng ôh (yor lah Y-Arôn ăn khân păng nau mpăn jêng nau bêk khân păng ta nklang phung rlăng), dôl nây Y-Môis gŭ râng ta bôk mpông pêr nkual jêh ri lah:$b$,true),
('bunong-vn','EXO',32,26,null,$b$“Mbu nâm mpeh ma Yêhôva, ăn văch ta gâp. Jêh ri lĕ rngôch phung kon bu klâu Lêvi tâm rƀŭn ndrel păng.$b$,false),
('bunong-vn','EXO',32,27,null,$b$Păng lah ma phung nây: “Yêhôva Brah Ndu Israel lah pô aơ: ‘Ăn ăp nơm khân may cheng đao gưm păng ta meng, nchuăt rgăn tâm nkual ntơm bơh mpông pêr tât mpông pêr ri, jêh ri ăn ăp nơm nkhĭt oh nâu păng, băl păng jêh ri nơm chiau meng păng.’ ”$b$,false),
('bunong-vn','EXO',32,28,null,$b$Phung kon bu klâu Lêvi ƀư tĭng nâm nau Y-Môis ntăm nây; jêh ri tâm pe rbăn bunuyh tâm phung ƀon lan khĭt nar nây.$b$,false),
('bunong-vn','EXO',32,29,null,$b$Y-Môis lah: “Nar aơ khân may prăp jêh khân may nơm ma Yêhôva ăp nơm ma rnoh mham kon bu klâu păng jêh ri oh nâu păng, gay ma Yêhôva ăn ma khân may nau ueh uĭn nar aơ.”$b$,false),
('bunong-vn','EXO',32,30,null,$b$Ta ôi Y-Môis lah ma phung ƀon lan. “Khân may ƀư jêh du nau tih toyh. Aƀaơ gâp mra hăn hao ta Yêhôva. Klăp lah gâp dơi ƀư nau kloh ma nau tih khân may.”$b$,false),
('bunong-vn','EXO',32,31,null,$b$Pô ri Y-Môis plơ̆ sĭt ma Yêhôva jêh ri lah: “Ƀaih, phung ƀon lan aơ ƀư jêh du nau tih toyh. Khân păng ƀư jêh brah ma khân păng nơm ma mah.$b$,false),
('bunong-vn','EXO',32,32,null,$b$Ƀiă lah aƀaơ tơ lah may ŭch yô̆ an nau tih khân păng, ƀiă lah tơ lah mâu ŭch ôh, gâp dăn ma may jut lơi amoh gâp bơh ndrom sămƀŭt may chih jêh.$b$,false),
('bunong-vn','EXO',32,33,null,$b$Ƀiă lah Yêhôva lah ma Y-Môis: “Mbu nâm ƀư tih jêh đah gâp, gâp jut lơi amoh păng bơh ndrom sămƀŭt gâp.$b$,false),
('bunong-vn','EXO',32,34,null,$b$Aƀaơ aơ, hăn hom, njŭn phung ƀon lan ta ntŭk gâp lah jêh ma may. Aơ, oh mon ueh gâp mra hăn lor ma may. Ƀiă lah ta nar gâp plơng har, gâp mra tâm rmal khân păng yor nau tih khân păng ƀư jêh.”$b$,false),
('bunong-vn','EXO',32,35,null,$b$Yêhôva ƀư ma phung ƀon lan ma nau ji tưp, yor lah khân păng ƀư jêh kon ndrôk Y-Arôn tŏ.$b$,false),
('bunong-vn','EXO',33,1,null,$b$Yêhôva lah ma Y-Môis: “Hăn hom tă bơh aơ, may jêh ri phung ƀon lan may ngluh jêh bơh n'gor Êjipt, hăn hom ta n'gor gâp ton ma Y-Abraham, Y-Isăk, jêh ri Y-Yakôb, lah: ‘Gâp mra ăn n'gor nây ma phung kon sau khân may’.$b$,true),
('bunong-vn','EXO',33,2,null,$b$Gâp mra njuăl du huê tông mpăr ueh lor ma khân may, jêh ri gâp mra nsot phung Kanaan, phung Amôrit, phung Hitit, phung Pêrisit, phung Hivit, jêh ri phung Jêbusit.$b$,false),
('bunong-vn','EXO',33,3,null,$b$Hăn hao hom ta n'gor geh ndơ sông sa nhêt rmeh ler, ƀiă lah gâp mâu mra hăn ôh ta nklang khân may, klach lah gâp ƀư rai khân may rŏ trong; yor lah khân may jêng du phung ƀon lan dăng bôk.”$b$,false),
('bunong-vn','EXO',33,4,null,$b$Tơ lah jêh phung ƀon lan tăng nau mhe mhan mhĭk nây, khân păng ndrê klâng; jêh ri mâu geh du huê nkrơ̆ ôh.$b$,false),
('bunong-vn','EXO',33,5,null,$b$Yor lah Yêhôva lah jêh ma Y-Môis: “Lah hom ma phung ƀon lan Israel, khân may jêng phung ƀon lan dăng bôk. Tơ lah gâp hăn ta nklang khân may knŏng ƀât lât, gâp ŭch ƀư rai khân may. Pô ri doh hom aƀaơ ndơ nkrơ̆ khân may, gay ma gâp gĭt, moh gâp mra ƀư ma khân may.”$b$,true),
('bunong-vn','EXO',33,6,null,$b$Yor nây sŏk ntơm bơh yôk Hôrep phung ƀon lan Israel doh lơi lĕ ndrăp nkrơ̆ khân păng.$b$,true),
('bunong-vn','EXO',33,7,null,$b$Y-Môis vay ƀư ngih bok jêh ri rdâk păng pa dih nkual ngai djê̆. Păng rnha ngih bok nau tâm rƀŭn; jêh ri ăp nơm mbu joi Yêhôva hăn ta ngih bok nau tâm rƀŭn pa dih nkual.$b$,true),
('bunong-vn','EXO',33,8,null,$b$Tơ lah Y-Môis luh hăn ta ngih bok nây, lĕ rngôch phung ƀon lan dâk gŭ râng, ăp nơm gŭ râng ta mpông ngih bok păng, jêh ri tĭng uănh Y-Môis kŏ păng lăp jêh tâm ngih bok.$b$,false),
('bunong-vn','EXO',33,9,null,$b$Tơ lah Y-Môis lăp jêh tâm ngih bok, n'gâng ndâr tŭk jŭr ta mpông ngih bok jêh ri Yêhôva ngơi ma Y-Môis.$b$,false),
('bunong-vn','EXO',33,10,null,$b$Tơ lah lĕ rngôch phung ƀon lan saơ n'gâng ndâr tŭk gŭ ta mpông ngih bok lĕ rngôch phung ƀon lan dâk jêh ri mbah yơk, ăp nơm ta mpông ngih bok păng nơm.$b$,false),
('bunong-vn','EXO',33,11,null,$b$Pô ri yơh Yêhôva vay ngơi ma Y-Môis ta năp muh măt, tâm ban ma du huê bunuyh ngơi ma mĭt jiăng păng. Tơ lah Y-Môis plơ̆ sĭt ta nkual, oh mon păng dôl ndăm, Y-Yôsuê kon bu klâu Y-Nun, mâu luh ôh bơh ngih bok.$b$,true),
('bunong-vn','EXO',33,12,null,$b$Y-Môis lah ma Yêhôva: “Aơ, may lah jêh ma gâp: ‘Ăn may njŭn leo phung ƀon lan aơ, ƀiă lah may mâu ăn gâp gĭt ôh mbu may mra njuăl hăn ndrel ma gâp. Pô aơ may lah, ‘Gâp năl may ma amoh may, jêh ri may geh jêh nau yô̆ ta năp măt gâp.’$b$,true),
('bunong-vn','EXO',33,13,null,$b$Pô ri aƀaơ, gâp vơl dăn ma may, tơ lah gâp geh jêh nau yô̆ ta năp măt may, mpơl hom trong may ma gâp, gay ma gâp dơi gĭt năl may jêh ri geh nau yô̆ ta năp măt may. Ăn may kơp phung ndŭl mpôl aơ jêng ƀon lan may lĕ.$b$,false),
('bunong-vn','EXO',33,14,null,$b$Yêhôva lah: ‘Gâp nơm mra hăn ndrel ma may, jêh ri gâp mra ăn nau rlu ma may.”$b$,false),
('bunong-vn','EXO',33,15,null,$b$Y-Môis lah ma păng: “Tơ lah may nơm mâu hăn ndrel ma gâp ôh, lơi ăn hên hăn du bơh ntŭk aơ ôh.$b$,false),
('bunong-vn','EXO',33,16,null,$b$Yor lah, mâm bu mra gĭt ngăn ma gâp geh nau yô̆ ta năp măt may, gâp jêh ri phung ƀon lan may? Mâu di hĕ ma nau may hăn ndrel ma hên, pô ri hên mra jêng phung êng, gâp jêh ri phung ƀon lan may, bơh lĕ rngôch phung ƀon lan êng gŭ ta klơ neh aơ?”$b$,false),
('bunong-vn','EXO',33,17,null,$b$Yêhôva lah ma Y-Môis: “Gâp mra ƀư nau may lah ma gâp nây, yor lah may geh jêh nau yô̆ ta năp măt gâp, jêh ri gâp gĭt năl may ma amoh may nơm.”$b$,true),
('bunong-vn','EXO',33,18,null,$b$Y-Môis lah: “Gâp dăn ma may, tâm mpơl hom ma gâp nau chrêk rmah may.”$b$,false),
('bunong-vn','EXO',33,19,null,$b$Păng lah: “Gâp mra ăn lĕ nau ueh rgăn ta năp may, jêh ri gâp mra mbơh amoh gâp, ‘Yêhôva’ ta năp may. Gâp mra yô̆ ma mbu nâm gâp yô̆, gâp mra ƀư ueh ma mbu nâm gâp mra ƀư ueh.”$b$,false),
('bunong-vn','EXO',33,20,null,$b$Păng lah: “Ƀiă lah may mâu dơi saơ muh măt gâp ôh; yor lah bunuyh mâu dơi ôh saơ gâp jêh ri gâp gŭ rêh.”$b$,true),
('bunong-vn','EXO',33,21,null,$b$Yêhôva lah: “Aơ, geh du ntŭk dăch gâp, jêh ri may mra gŭ ta klơ lŭ.$b$,false),
('bunong-vn','EXO',33,22,null,$b$Jêh ri dôl nau chrêk rmah gâp mra găn, gâp mra dơm may tâm trôm lŭ, jêh ri gâp mra nkŭm may ma ti gâp kŏ jêh gâp rgăn.$b$,false),
('bunong-vn','EXO',33,23,null,$b$Jêh ri gâp mra rhuăt lơi ti gâp, jêh ri may mra saơ ndŭr kơi gâp, ƀiă lah mâu saơ muh măt gâp ôh.$b$,false),
('bunong-vn','EXO',34,1,null,$b$Yêhôva lah ma Y-Môis: “Trah hom bar pŏk kađar lŭ nâm bu kađar tal lor; jêh ri gâp mra chih ta klơ kađar nây nau ngơi geh ta kađar tal lor, ndơ may nchah jêh.$b$,true),
('bunong-vn','EXO',34,2,null,$b$Gŭ kâp bơh ơm jêh ri hao hom yôk Sinai ta ôi, jêh ri nhhơr may nơm ta nây ta năp gâp ta klơ kô yôk.$b$,false),
('bunong-vn','EXO',34,3,null,$b$Lơi ăn geh bunuyh hao ndrel ma may ôh, mâu lĕ ăn geh bunuyh lam yôk, mâu lĕ dơi ăn biăp ndrôk sa gơ̆ tâm yôk nây.$b$,false),
('bunong-vn','EXO',34,4,null,$b$Pô ri Y-Môis trah bar pŏk kađar lŭ nâm bu kađar tal lor. Păng dâk ơm ôi jêh ri hao ta yôk Sinai, tĭng nâm nau Yêhôva ntăm jêh ma păng, jêh ri ndjôt bar pŏk kađar lŭ.$b$,false),
('bunong-vn','EXO',34,5,null,$b$Yêhôva jŭr tâm ndâr gŭ ta nây ndrel ma păng, jêh ri mbơh amoh Yêhôva.$b$,false),
('bunong-vn','EXO',34,6,null,$b$Yêhôva rgăn ta năp păng jêh ri mbơh: “Yêhôva, Yêhôva, Brah Ndu bêng ma nau ueh jêh ri gĭt yô̆, mâu gơnh nuih ôh, ndrŏng ma nau rŏng răp jăp.$b$,false),
('bunong-vn','EXO',34,7,null,$b$Păng prăp nau rŏng răp jăp ma âk rbăn bunuyh, yô̆ an nau kue, nau rlau nau vay, jêh ri nau tih; ƀiă lah păng mâu kơp sŏng ôh bunuyh tih, ntŭp nau tâm rmal nau kue phung mbơ̆ ma phung kon jêh ri ma phung sau se kŏ tât ta rnôk tal pe jêh ri tal puăn”.$b$,true),
('bunong-vn','EXO',34,8,null,$b$Y-Môis kŭnh bôk ro ta neh jêh ri mbah yơk.$b$,true),
('bunong-vn','EXO',34,9,null,$b$Păng lah: “Ơ Kôranh Brah, aƀaơ aơ tơ lah gâp geh nau yô̆ ta năp măt may, gâp dăn ma nau ăn Kôranh Brah hăn ta nklang phung hên, nđâp tơ lah khân păng jêng phung ƀon lan đăng bôk kđôi; jêh ri yô̆ an ma nau kue jêh ri nau tih hên, jêh ri ăn hên jêng drăp may dơn.”$b$,false),
('bunong-vn','EXO',34,10,null,$b$Păng lah: “Aơ, gâp ƀư du nau tâm rnglăp: Gâp mra ƀư ta năp lĕ rngôch phung ƀon lan may kan khlay ngăn, bu mâu mâp ƀư tâm neh ntu mâu lah tâm du ndŭl mpôl, lĕ rngôch phung ƀon lan gŭ jŭm may mra saơ kan Yêhôva; yor lah ma may yơh gâp mra ƀư kan tâm nhhu.$b$,true),
('bunong-vn','EXO',34,11,null,$b$Njrăng, ƀư hom nau gâp ntăm ma khân may nar aơ: Aơ gâp mra nsot tă bơh ta năp khân may phung Amôrit, phung Kanaan, phung Hitit, phung Pêrisit, phung Hivit jêh ri phung Jêbusit.$b$,true),
('bunong-vn','EXO',34,12,null,$b$Njrăng hom ma khân may nơm, klach lah khân may ƀư nau tâm rnglăp đah bunuyh n'gor khân may mra lăp, klach lah nau nây mra jêng dăk sân ta nklang khân may.$b$,false),
('bunong-vn','EXO',34,13,null,$b$Ăn khân may ƀư rai lơi nơng khân păng jêh ri ƀư chah lơi meh khân păng mbah yơk, jêh ri kăl lơi rup brah Asêrim khân păng.$b$,false),
('bunong-vn','EXO',34,14,null,$b$Lơi mbah yơk ôh ma brah êng, yor lah Yêhôva, amoh păng Nơm Rhăk, jêng Brah Ndu, Nơm Blau Ntôn.$b$,false),
('bunong-vn','EXO',34,15,null,$b$Klach lah khân may ƀư nau tâm rnglăp đah phung bunuyh gŭ tâm n'gor nây, jêh ri tơ lah khân păng ƀư nau văng tĭr đah phung brah khân păng, jêh ri ƀư brah ma brah khân păng, jêh ri du huê jă khân may jêh ri khân may sa hĕ ndơ khân păng ƀư brah,$b$,false),
('bunong-vn','EXO',34,16,null,$b$jêh ri khân may sŏk đơ phung kon bu ur khân păng ma phung kon bu klâu khân may, jêh ri phung kon bu ur khân păng ƀư nau văng tĭr đah phung brah khân păng jêh ri njŭn leo phung kon bu klâu khân may ƀư nau văng tĭr đah phung brah khân păng.$b$,false),
('bunong-vn','EXO',34,17,null,$b$Lơi tŏ rup brah ma khân may nơm ôh.$b$,true),
('bunong-vn','EXO',34,18,null,$b$Ăn khân may kah gĭt prăp nau Nhêt Sông Piăng Let Mâu Geh Ndrui. Tĭng nâm gâp ntăm jêh ma khân may, ăn khân may sa piăng let mâu geh ndrui dôl tâm pơh nar ta yăn tâm nal jêh tâm khay puăn; yor lah tâm khay puăn khân may luh bơh n'gor Êjipt.$b$,true),
('bunong-vn','EXO',34,19,null,$b$Lĕ rngôch mpa deh kon lor lơn jêng ndơ gâp, lĕ rngôch kon nkuăng deh bôk rah tâm ndrôk biăp khân may.$b$,true),
('bunong-vn','EXO',34,20,null,$b$Ăn khân may tâm chuai kon seh bri deh lor lơn đah du mlâm kon biăp. Tơ lah khân may mâu tâm chuai păng ôh, ăn khân may juet lơi trô ko păng. Ăn khân may tâm chuai lĕ rngôch phung kon bu klâu khân may deh bôk rah. Lơi ăn du huê nhhơ ta năp măt gâp ma ti dơm ôh.$b$,false),
('bunong-vn','EXO',34,21,null,$b$Ăn khân may pah kan prao nar ƀiă lah ăn khân may rlu nar pơh; ăn khân may rlu nar Saƀat dôl yăn kai jêh ri yăn kăch.$b$,true),
('bunong-vn','EXO',34,22,null,$b$Ăn khân may kah gĭt prăp Nau Nhêt Ma Nar Ver, nâm bu ntĭt rplay kao bơh nau kăch ba ƀlê, nđâp ma Nau Nhêt sông kăch Roih ta lôch năm.$b$,false),
('bunong-vn','EXO',34,23,null,$b$Pe tơ̆ ăp năm ăn lĕ rngôch phung kon bu klâu khân may tâm mpơl ta năp Yêhôva Brah Ndu, Brah Ndu phung Israel.$b$,false),
('bunong-vn','EXO',34,24,null,$b$Yor lah gâp mra nsot phung mpôl băl tă bơh ta năp khân may, jêh ri gâp mra ƀư dĭ n'har bri khân may; mâu lĕ bu mra kơnh ma neh khân may, dôl khân may hăn nhhơ khân may nơm ta năp Yêhôva Brah Ndu khân may pe tơ̆ ăp năm.$b$,false),
('bunong-vn','EXO',34,25,null,$b$Lơi nhhơr ôh mham mpa ƀư brah yơk ma gâp ma ndrui; mâu lĕ ăn hôm tât ôi mpa ƀư brah ma Nau Nhêt Sông Nau Găn.$b$,true),
('bunong-vn','EXO',34,26,null,$b$Ăn khân may djôt leo ma Yêhôva Brah Ndu khân may play ueh lơn bơh rplay kao neh khân may. Lơi gâm kon be tâm mham me păng ôh.”$b$,true),
('bunong-vn','EXO',34,27,null,$b$Yêhôva lah ma Y-Môis: “Chih hom nau ngơi aơ, yor lah di tĭng nâm nau ngơi aơ yơh gâp ƀư jêh nau tâm rnglăp đah may jêh ri đah phung Israel.”$b$,true),
('bunong-vn','EXO',34,28,null,$b$Păng gŭ ta nây ndrel ma Yêhôva puăn jât nar jêh ri puăn jât măng; păng mâu sa mpa, mâu lĕ păng nhêt dak. Jêh ri Yêhôva chih ta kađar nau ngơi ma nau tâm rnglăp jât ntil nau vay.$b$,false),
('bunong-vn','EXO',34,29,null,$b$Tơ lah Y-Môis jŭr tă bơh yôk Sinai djôt bar pŏk kađar nau mbơh tâm ti păng. Y-Môis mâu gĭt ôh ma ntâu muh măt păng sol ang yor lah păng tâm ngơi ndrel jêh đah Yêhôva.$b$,true),
('bunong-vn','EXO',34,30,null,$b$Tơ lah Y-Arôn jêh ri lĕ rngôch phung ƀon lan Israel saơ Y-Môis, aơ ntâu muh măt păng sol ang, jêh ri khân păng klach hăn êp ta Y-Môis.$b$,false),
('bunong-vn','EXO',34,31,null,$b$Ƀiă lah Y-Môis kuăl khân păng, jêh ri Y-Arôn jêh ri lĕ rngôch phung Kôranh n'gâng tâm phung tâm rƀŭn hăn êp păng jêh ri Y-Môis ngơi ndrel đah khân păng.$b$,false),
('bunong-vn','EXO',34,32,null,$b$Jêh nau nây lĕ rngôch phung ƀon lan Israel hăn êp păng, jêh ri păng ăn ma phung nây lĕ rngôch nau ntăm Yêhôva lah jêh ma păng ta klơ yôk Sinai.$b$,false),
('bunong-vn','EXO',34,33,null,$b$Tơ lah Y-Môis lôch jêh ngơi đah khân păng, păng nkŭm bok ta muh măt păng.$b$,false),
('bunong-vn','EXO',34,34,null,$b$Ƀiă lah tơ lah Y-Môis lăp ta năp Yêhôva ŭch ngơi đah păng, păng sŏk lơi bok nkŭm kŏ păng lah, jêh ri tơ lah păng luh păng mbơh ma phung ƀon lan Israel moh nau Yêhôva ntăm jêh ma păng.$b$,false),
('bunong-vn','EXO',34,35,null,$b$Phung ƀon lan Israel saơ muh măt Y-Môis, jêh ri ntâu muh măt păng sol ang. Y-Môis plơ̆ nkŭm bok ta muh măt păng tât păng lăp ŭch ngơi đah Yêhôva.$b$,true),
('bunong-vn','EXO',35,1,null,$b$Y-Môis kuăl lĕ rngôch phung ƀon lan Israel tâm rƀŭn, jêh ri păng lah: “Aơ nau Yêhôva ntăm ăn khân ay may ƀư.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','EXO',35,2,null,$b$Ăn khân may pah kan prao nar, ƀiă lah nar pơh mra jêng nar Saƀat kloh ueh prăp rlu ma Yêhôva. Mbu nâm ƀư du ntil kan nây, bu mra nkhĭt păng.$b$,true),
('bunong-vn','EXO',35,3,null,$b$Lơi sĭnh ŭnh ôh lam tâm ntŭk khân may gŭ dôl nar Saƀat.”$b$,false),
('bunong-vn','EXO',35,4,null,$b$Y-Môis lah ma phung ƀon lan Israel tâm rƀŭn: “Aơ nau Yêhôva ntăm jêh:$b$,true),
('bunong-vn','EXO',35,5,null,$b$Sŏk hom tă bơh khân may ndơ nhhơr ma Yêhôva. Mbu nâm geh nuih n'hâm lŏng, ăn păng njŭn ndơ nhhơr ma Yêhôva, mah, prăk jêh ri kông;$b$,false),
('bunong-vn','EXO',35,6,null,$b$bok nhom dak piâk, chăng krăk, chăng rhưch bok mhay rhên; rsau be,$b$,false),
('bunong-vn','EXO',35,7,null,$b$ntâu biăp nkuăng nkra jêh, ntâu ka toyh; tơm si akasi,$b$,false),
('bunong-vn','EXO',35,8,null,$b$dak play Ôlivơ ma ŭnh jrêng,$b$,false),
('bunong-vn','EXO',35,9,null,$b$ndơ ƀâu kah ma dak ƀâu kah prăp tŏ jêh ri prăp ma ndơ ƀâu kah lŭ ônik jêh ri âk lŭ khlay êng gay lĭr dơm ta ao êphôt jêh ri ta bok văn ntang ntơh.$b$,false),
('bunong-vn','EXO',35,10,null,$b$Ăn ăp nơm bunuyh blau njêh tâm phung kon bu klâu văch jêh ri ƀư lĕ rngôch ndơ Yêhôva ntăm jêh.$b$,true),
('bunong-vn','EXO',35,11,null,$b$Ngih bok păng jêh ri ndơ nkŭm păng, ndơ nkăp, kađar, mâng nđăng, meh jêh ri rnơl;$b$,false),
('bunong-vn','EXO',35,12,null,$b$hip nau tâm rnglăp nđâp mâng tung păng, ntŭk yô̆ an, jêh ri bok nching;$b$,false),
('bunong-vn','EXO',35,13,null,$b$sưng nđâp mâng tung păng, jêh ri lĕ rngôch ndơ dŏng ma păng, jêh ri piăng let nhhơr ma Brah Ndu;$b$,false),
('bunong-vn','EXO',35,14,null,$b$jâng jrêng ma nau ang jêh ri ndơ dŏng ma păng, ŭnh kađen păng jêh ri dak play Ôlivơ ma ŭnh kađen;$b$,false),
('bunong-vn','EXO',35,15,null,$b$nơng gŭch mpa ƀâu kah nđâp mâng tung păng, dak ƀâu kah prăp tŏ, jêh ri ndơ ƀâu kah; jêh ri bok nching ta mpông lăp ngih bok;$b$,false),
('bunong-vn','EXO',35,16,null,$b$nơng mpa nhhơr gŭch ma dreh kông tanh srang, nđâp mâng tung păng, jêh ri lĕ rngôch ndơ dŏng ma păng, thŭng dak nđâp ndơ păng;$b$,false),
('bunong-vn','EXO',35,17,null,$b$bok mbâl chăng tâm nkual meh nđâp ma rnơl păng, jêh ri bok chăng ta mpông pêr lăp nkual;$b$,false),
('bunong-vn','EXO',35,18,null,$b$mâng pêr ngih bok, mâng pêr nkual, jêh ri rse khân păng buănh;$b$,false),
('bunong-vn','EXO',35,19,null,$b$bok ao ƀư ma nau njêh prăp ma kan tâm jrô kloh ueh, bok ao kloh ueh Kôranh ƀư brah Y-Arôn, jêh ri bok ao phung kon bu klâu păng prăp ma kan phung Kôranh ƀư brah.”$b$,false),
('bunong-vn','EXO',35,20,null,$b$Jêh ri lĕ rngôch phung ƀon lan Israel tâm rƀŭn luh du ta năp Y-Môis.$b$,true),
('bunong-vn','EXO',35,21,null,$b$Lĕ rngôch phung geh nuih n'hâm sŭk nsôr jêh ri geh nau ŭch ueh văch jêh ri djôt ndơ nhhơr ma Yêhôva, prăp ma kan ƀư ngih bok nau tâm rƀŭn, nđâp ma lĕ kon păng, jêh ri prăp ma bok ao kloh ueh.$b$,false),
('bunong-vn','EXO',35,22,null,$b$Pô ri phung kon bu klâu nđâp phung bu ur văch lĕ, lĕ rngôch mbu nâm geh nuih n'hâm gay djôt leo mblo tôr, rgên ti (năl), rgên tâp pŏng, kông dok ta ti ăp ntil ndơ ƀư ma mah, ăp nơm njŭn mah prăp nhhơr ma Yêhôva.$b$,false),
('bunong-vn','EXO',35,23,null,$b$Lĕ rngôch phung bok nhom piâk, chăng krăk, chăng rhŏnh, mhay rhên, rsau be, ntâu biăp nkuăng nkra jêh, jêh ri ntâu ka toyh djôt leo lĕ.$b$,false),
('bunong-vn','EXO',35,24,null,$b$Lĕ rngôch phung dơi nhhơr prăk jêh ri kông njŭn ndơ nây ma Yêhôva. Lĕ rngôch phung tơm si akasi dơi dŏng ma kan njŭn nhhơr lĕ.$b$,false),
('bunong-vn','EXO',35,25,null,$b$Lĕ rngôch phung blau kan rui ma ti khân păng nơm, djôt leo ndơ khân păng ƀư, brai nhom dak piâk, chăng krăk, chăng rhưch jêh ri mhay rhên;$b$,false),
('bunong-vn','EXO',35,26,null,$b$Lĕ bu ur geh nuih n'hâm sŭk nsôr rui rsau be.$b$,false),
('bunong-vn','EXO',35,27,null,$b$Phung Kôranh n'gâng ndjôt leo lŭ ônik jêh ri lŭ khlay prăp ƀlĭr dơm ta ao êphôt jêh ri ta ao bok văn tang ntơh;$b$,false),
('bunong-vn','EXO',35,28,null,$b$ndơ ƀâu kah jêh ri dak play Ôlivơ prăp ăn ŭnh jrêng jêh ri ma dak ƀâu kah.$b$,false),
('bunong-vn','EXO',35,29,null,$b$Lĕ rngôch bu ur kon bu klâu phung ƀon lan Israel geh nuih n'hâm sŭk nsôr ŭch kơl kan Yêhôva ntăm ma Y-Môis djôt leo ndơ nhhơr ma Yêhôva tĭng nâm khân păng ŭch.$b$,false),
('bunong-vn','EXO',35,30,null,$b$Y-Môis lah ma phung ƀon lan Israel: “Ăn khân may gĭt Yêhôva kuăl jêh ma amoh Y-Bêsalel, kon bu klâu Y-Uri, kon bu klâu Y-Hur, bơh ndŭl mpôl Yuđa.$b$,true),
('bunong-vn','EXO',35,31,null,$b$Păng mbêng jêh ma Brah Huêng Ueh Brah Ndu, ma nau njêh, nau gĭt rbăng, nau blau mĭn jêh ri nau njêh tâm lĕ rngôch kan ƀư,$b$,false),
('bunong-vn','EXO',35,32,null,$b$dơi njêng ndơ, ƀư kan ma mah, prăk jêh ri kông,$b$,false),
('bunong-vn','EXO',35,33,null,$b$tor kach lŭ prăp n'hĭ mblum, kan trah si jêh ri ƀư ăp ntil nau njêh.$b$,false),
('bunong-vn','EXO',35,34,null,$b$Bu ăn ma păng nau dơi sâm nti, păng jêh ri Y-Ôhôliap kon bu klâu Y-Ahisamak bơh ndŭl mpôl Dan.$b$,false),
('bunong-vn','EXO',35,35,null,$b$Păng mbêng jêh bu ma nau njêh n'hŭ, dơi ƀư ăp ntil bu dơi ƀư; kan trah, kan kach, kan cheh, bok piâk, chăng krăk, chăng rhưch jêh ri mhay rhên, jêh ri ăp ntil kan tanh bu ƀư mâu lah njêng mhe.”$b$,true),
('bunong-vn','EXO',36,1,null,$b$Y-Besalel jêh ri Y-Ôhôliap jêh ri lĕ rngôch bunuyh Yêhôva ăn jêh nau blau mĭn jêh ri nau gĭt rbăng dơi gĭt lĕ kan ƀư ntŭk kloh ueh mra pah kan tĭng nâm lĕ nau Yêhôva ntăm jêh.$b$,true),
('bunong-vn','EXO',36,2,null,$b$Y-Môis kuăl Y-Bêsalel, Y-Ôhôliap jêh ri lĕ rngôch phung bunuyh blau njêh geh nau mĭn Yêhôva dơm jêh nau njêh, lĕ rngôch phung geh nuih n'hâm sŭk nsôr khân păng hăn pah kan.$b$,true),
('bunong-vn','EXO',36,3,null,$b$Khân păng sŏk dơn lĕ rngôch ndơ nhhơr phung ƀon lan Israel njŭn jêh prăp pah kan jrô kloh ueh. Ăp ôi ăt bu njŭn ma Y-Môis ndơ nhhơr ma nau ŭch.$b$,false),
('bunong-vn','EXO',36,4,null,$b$Pô ri lĕ rngôch phung njêh ƀư lĕ rngôch kan ma jrô kloh ueh, ăp nơm văch bơh nau păng gŭ ƀư,$b$,true),
('bunong-vn','EXO',36,5,null,$b$jêh ri lah ma Y-Môis: “Phung ƀon lan njŭn âk rmeh lơn ma kan Yêhôva ntăm jêh ăn ƀư.”$b$,false),
('bunong-vn','EXO',36,6,null,$b$Pô ri Y-Môis ntăm, jêh ri bu mbơh tâm lĕ nkual. “Lơi ăn kon bu klâu mâu lah bu ur nhhơr ma jrô kloh ueh ôh.” Pô ri bu buay mâu hôm ăn phung ƀon lan njŭn đŏng ndơ nhhơr ôh;$b$,false),
('bunong-vn','EXO',36,7,null,$b$yor lah ndơ geh jêh jêng tŏng, nđâp ma rmeh lĕ ma lĕ kan.$b$,false),
('bunong-vn','EXO',36,8,null,$b$Lĕ rngôch phung njêh n'hŭ ƀư ngih bok ma jât blah bok mhay rhên, bok piâk, chăng krăk chăng rhưch, geh rup Chêrubim ma nau njêh ngăn.$b$,true),
('bunong-vn','EXO',36,9,null,$b$Nau jong ăp blah bok mbâl geh bar jât ma sĭn hăt, jêh ri dĭ rgăn ăp blah bok mbâl geh puăn hăt; lĕ rngôch blah bok nây rnâng veh tâm ban.$b$,false),
('bunong-vn','EXO',36,10,null,$b$Păng tâm ndop ndrel prăm blah bok mbâl, jêh ri păng tâm ndop ndrel lĕ prăm blah bok êng.$b$,false),
('bunong-vn','EXO',36,11,null,$b$Păng ƀư rse trôm ntôr piâk ta pĭt bok ta lôch ntŭk ndop tal lor. Păng ƀư tâm ban lĕ ta pĭt bok ta lôch ntŭk ndop tal bar.$b$,false),
('bunong-vn','EXO',36,12,null,$b$Păng ƀư prăm jât rse trôm ntôr ma bok tal lor jêh ri păng ƀư prăm jât rse trôm ntôr ta pĭt bok tal bar; rse trôm ntôr ăn tâm di ndrăng păng.$b$,false),
('bunong-vn','EXO',36,13,null,$b$Păng ƀư prăm jât ndơ nkĕp; jêh ri ngih bok jêng glom lĕ.$b$,false),
('bunong-vn','EXO',36,14,null,$b$Păng ƀư bok mbâl ma rsau be jêng bok nkŭm ta klơ ngih bok; păng ƀư jât ma nguay blah bok mbâl.$b$,false),
('bunong-vn','EXO',36,15,null,$b$Nau jong ăp blah bok nây geh pe jât hăt, dĭ rgăn ăp blah bok puăn hăt, lĕ rngôch jât ma nguay blah bok nây geh rnâng veh du ai tâm ban.$b$,true),
('bunong-vn','EXO',36,16,null,$b$Păng tâm ndop êng êng prăm blah tâm bok nây, jêh ri prao blah êng tâm ban lĕ.$b$,false),
('bunong-vn','EXO',36,17,null,$b$Păng ƀư prăm jât rse trôm ntôr ta pĭt bok ăn lôch ntŭk tâm ndop tal lor, jêh ri păng ƀư prăm jât rse trôm ntôr ta pĭt ntŭk ndop tal bar.$b$,false),
('bunong-vn','EXO',36,18,null,$b$Păng ƀư prăm jât ndơ nkĕp ma kông gay tâm ndop ngih bok gay ma păng glom lĕ.$b$,false),
('bunong-vn','EXO',36,19,null,$b$Păng ƀư ma ngih bok ndơ nkŭm ma ntâu biăp nkuăng nkra jêh, jêh ri ndơ nkŭm ma ntâu ka toyh.$b$,true),
('bunong-vn','EXO',36,20,null,$b$Păng ƀư kađar ma ngih bok ma tơm si akasi dơm ndâk.$b$,true),
('bunong-vn','EXO',36,21,null,$b$Jong kađar nây jât hăt jêh ri dĭ păng du hăt ma n'gul.$b$,false),
('bunong-vn','EXO',36,22,null,$b$Ăp kađar geh bar bôk prăp tâm ntrŭp gay tâm rnglăp ndrel. Pô ri păng ƀư ma lĕ rngôch tâm ngih bok.$b$,false),
('bunong-vn','EXO',36,23,null,$b$Pô aơ păng ƀư kađar ma ngih bok; bar jât pŏk kađar mơ bah rđŭng;$b$,true),
('bunong-vn','EXO',36,24,null,$b$păng ƀư puăn jât rnơl ma prăk tâm dâng bar jât pŏk kađar, bar bar mlâm rnơl tâm dâng kađar prăp ma bar bôk tâm ntrŭp păng jêh ri bar mlâm rnơl tâm dâng kađar êng prăp ma bar bôk tâm ntrŭp păng.$b$,false),
('bunong-vn','EXO',36,25,null,$b$Păng ƀư bar jât pŏk kađar đah tĕ ngih bok mpeh ma mpư̆ ,$b$,false),
('bunong-vn','EXO',36,26,null,$b$jêh ri puăn jât mlâm rnơl khân păng ma prăk, bar mlâm tâm dâng du pŏk kađar, jêh ri bar mlâm tâm dâng pŏk êng.$b$,false),
('bunong-vn','EXO',36,27,null,$b$Păng ƀư prao pŏk kađar pa kơi ngih bok mơ pa dâng.$b$,true),
('bunong-vn','EXO',36,28,null,$b$Păng ƀư bar pŏk kađar ta njônh ngih bok pa kơi.$b$,false),
('bunong-vn','EXO',36,29,null,$b$Khân păng jêng n'grup bar tâm dâng, ƀiă lah rnglăp ndrel ta klơ ma du rvang, pô ri păng ƀư ma lĕ du ntŭk njônh.$b$,false),
('bunong-vn','EXO',36,30,null,$b$Geh pham pŏk kađar ndrel ma jât ma prao rnơl prăk khân păng, bar mlâm tâm dâng ăp pŏk kađar.$b$,false),
('bunong-vn','EXO',36,31,null,$b$Păng ƀư prăm mlâm mâng nđăng ma si akasi prăp ma kađar mơ du đah pŭng ngih bok,$b$,false),
('bunong-vn','EXO',36,32,null,$b$Jêh ri prăm mlâm mâng nđăng prăp ma kađar mơ pa pŭng đah rĭ ngih bok, jêh ri prăm mlâm mâng nđăng prăp ma kađar pa kơi ngih bok mơ pa dâng.$b$,false),
('bunong-vn','EXO',36,33,null,$b$Păng ƀư mâng nđăng ta nklang rgăn lĕ kađar bơh pĭt aơ tât ta pĭt rĭ.$b$,false),
('bunong-vn','EXO',36,34,null,$b$Păng mblum lĕ rngôch kađar ma mah jêh ri păng ƀư rvang ma mah prăp nsro mâng nđăng, jêh ri pot mâng nđăng ma mah lĕ.$b$,false),
('bunong-vn','EXO',36,35,null,$b$Păng ƀư du blah bok nching ma bok piâk, chăng krăk, chăng rhưch jêh ri mhay rhên, geh rup chêrubim ma nau njêh ngăn.$b$,true),
('bunong-vn','EXO',36,36,null,$b$Păng ƀư ma bu puăn mlâm meh akasi mblum ma mah, jêh ri păng tŏ an puăn mlâm rnơl prăk.$b$,true),
('bunong-vn','EXO',36,37,null,$b$Păng ƀư ma ntŭk lăp ngih bok du blah bok mphiar piâk, chăng krăk jêh ri chăng rhưch jêh ri mhay rhên kan cheh;$b$,true),
('bunong-vn','EXO',36,38,null,$b$jêh ri prăm mlâm meh nđăp ma ndơ nkuăk păng, jêh ri păng mblum ma mah ta chiông jêh ri rse rêt păng, ƀiă lah prăm mlâm rnơl khân păng bu ƀư ma kông.$b$,false),
('bunong-vn','EXO',37,1,null,$b$Y-Bêsalel ƀư hip nau tâm rnglăp ma si akasi, jong păng bar hăt n'gul, dĭ găn păng du hăt n'gul jêh ri prêh păng du hăt n'gul.$b$,true),
('bunong-vn','EXO',37,2,null,$b$Păng mblum ma mah kloh tâm trôm jêh ri pa dih, jêh ri păng ƀư năp rmăn jŭm păng ma mah.$b$,false),
('bunong-vn','EXO',37,3,null,$b$Păng tŏ puăn rvang ma mah dơm ta puăn njônh du đah bar rvang jêh ri du đah êng bar rvang lĕ.$b$,false),
('bunong-vn','EXO',37,4,null,$b$Păng ƀư mâng tung ma si akasi, jêh ri mblum ma mah.$b$,false),
('bunong-vn','EXO',37,5,null,$b$Nsro mâng tung tâm rvang ta meng hip prăp tung păng.$b$,false),
('bunong-vn','EXO',37,6,null,$b$Păng ƀư du ntŭk prăp yô̆ an ma mah kloh; jong păng bar hăt n'gul dĭ găn păng du hăt n'gul.$b$,false),
('bunong-vn','EXO',37,7,null,$b$Păng ƀư bar rup Chêrubim ma mah bu chiăr ta bar pĭt lôch ntŭk yô̆ an,$b$,false),
('bunong-vn','EXO',37,8,null,$b$du mlâm rup Chêrubim ta du pĭt lôch jêh ri du mlâm rup Chêrubim ta du pĭt êng đŏng. Păng ƀư rup Chêrubim du ngrăng đah ntŭk yô̆ an ta bar pĭt lôch.$b$,false),
('bunong-vn','EXO',37,9,null,$b$Rup Chêrubim pơk năr khân păng mơ pa lơ, nkŭm ma năr khân păng ntŭk yô̆ an, jêh ri muh măt khân păng tâm nkra. Mah măt Chêrubim uănh ta ntŭk yô̆ an.$b$,true),
('bunong-vn','EXO',37,10,null,$b$Păng ƀư sưng ma si akasi, jong păng bar hăt, dĭ rgăn du hăt, jêh ri prêh păng du hăt n'gul.$b$,true),
('bunong-vn','EXO',37,11,null,$b$Păng mblum ma mah chrêk jêh ri ƀư năp rmăn jŭm păng ma mah.$b$,false),
('bunong-vn','EXO',37,12,null,$b$Păng veh jŭm păng du mpang ti, ta pĭt ntŭk veh nây păng ƀư năp ma mah jŭm păng.$b$,false),
('bunong-vn','EXO',37,13,null,$b$Păng tŏ ƀư puăn rvang ma mah, jêh ri dơm rvang nây ta puăn njônh ta puăn mlâm jâng păng.$b$,false),
('bunong-vn','EXO',37,14,null,$b$Rvang nây gŭ dăch ta pĭt năp jêng ntŭk nsro mâng prăp tung sưng.$b$,true),
('bunong-vn','EXO',37,15,null,$b$Păng ƀư mâng tung ma tơm si akasi, jêh ri mblum ma mah, gay ŭch dŏng tung sưng nây.$b$,false),
('bunong-vn','EXO',37,16,null,$b$Păng ƀư ndơ dŏng ta klơ sưng, ngan jam jêh ri ngan rleo dơ ndơ ƀâu kah, ngan grưng jêh ri nông prăp dŏng nkhŭt ndơ nhhơr. Bu ƀư păng ma mah chrêk.$b$,false),
('bunong-vn','EXO',37,17,null,$b$Păng ƀư jâng jrêng ma mah chrêk, păng ƀư jâng jrêng ma mah bu chiăr, jâng păng, săk păng, ka chok păng, play păng jêh ri kao păng jêng tâm du njăr ngrăng.$b$,true),
('bunong-vn','EXO',37,18,null,$b$Geh prao mlâm n'gĭng luh ta meng, pe mlâm nthan n'gĭng jâng jrêng mơ du đah, jêh ri pe mlâm n'gĭng jâng jrêng mơ du đah êng.$b$,false),
('bunong-vn','EXO',37,19,null,$b$Du mlâm n'gĭng pe mlâm kachok ƀư tâm ban ma play amandê, du rplay jêh ri kao păng, jêng tâm ban lĕ ma prao mlâm n'gĭng luh bơh jâng jrêng.$b$,true),
('bunong-vn','EXO',37,20,null,$b$Ta n'gâng ŭnh jrêng geh puăn mlâm kachok tâm ban ma play amandê, du rplay jêh ri kao păng.$b$,false),
('bunong-vn','EXO',37,21,null,$b$Geh du mlâm tâm dâng bar mlâm n'gĭng tâm du ngrăng nây, pô ri yơh ma prao mlâm n'gĭng luh bơh jâng jrêng nây.$b$,false),
('bunong-vn','EXO',37,22,null,$b$Play khân păng jêh ri n'gĭng khân păng jêng du ngrăng, lĕ nây chiăr tâm du ngrăng mah chrêk.$b$,false),
('bunong-vn','EXO',37,23,null,$b$Păng ƀư pơh ŭnh kađen ma păng, ndơ ƀư nhhât ŭnh păng, jêh ri khăl djôt ndơ nây păng ƀư ma mah chrêk.$b$,true),
('bunong-vn','EXO',37,24,null,$b$Păng dŏng puăn jât ma sĭn kilô mah chrêk prăp ƀư păng ndrel ma lĕ rngôch ndơ dŏng ma păng.$b$,false),
('bunong-vn','EXO',37,25,null,$b$Păng ƀư nơng gŭch mpa ƀâu kah ma si akasi; jong păng du hăt, dĭ găn păng du hăt, puăn blon jêh ri prêh păng bar hăt, nke păng jêng du njrăng đah păng.$b$,true),
('bunong-vn','EXO',37,26,null,$b$Păng mblum ma mah chrêk, ntŭk ta klơ, ta meng jŭm păng jêh ri nke; jêh ri păng ƀư năp ma mah chrêk jŭm păng.$b$,false),
('bunong-vn','EXO',37,27,null,$b$Păng ƀư tâm dâng năp bar rvang mah mơ bar đah pĭt gay ma nsro mâng tung păng.$b$,false),
('bunong-vn','EXO',37,28,null,$b$Păng ƀư mâng tung ma si akasi, jêh ri mblum păng ma mah.$b$,false),
('bunong-vn','EXO',37,29,null,$b$Păng ƀư dak ƀâu kah ma nau tŏ prăp ăn, jêh ri ndơ ƀâu kah kloh jêh ri njŭng, tĭng nâm nau vay phung nkra ndơ ƀâu kah.$b$,true),
('bunong-vn','EXO',38,1,null,$b$Păng ƀư nơng mpa nhhơr gŭch ma si akasi, jong păng prăm hăt, puăn blon, jêh ri prêh păng pe hăt.$b$,true),
('bunong-vn','EXO',38,2,null,$b$Păng ƀư nke puăn njônh păng, ta nây jêng du ngrăng đah nơng, jêh ri păng mblum ma kông.$b$,false),
('bunong-vn','EXO',38,3,null,$b$Păng ƀư lĕ rngôch ndơ dŏng ma nơng, glah dơ buh, ndroh, ngan grưng, n'hoi srang, jêh ri ndơ dơ sa ônh hâng. Păng ƀư lĕ rngôch ndơ dŏng nây ma kông.$b$,false),
('bunong-vn','EXO',38,4,null,$b$Păng ƀư ma nơng nây du blah dreh kông tanh srang păng dơm tă, tâm dâng năp tât ta nklang nơng.$b$,true),
('bunong-vn','EXO',38,5,null,$b$Păng tŏ ƀư puăn mlâm rvang kông ta puăn njônh dreh kông nây prăp nsro mâng tung.$b$,false),
('bunong-vn','EXO',38,6,null,$b$Păng ƀư mâng tung ma si akasi, jêh ri mblum păng ma kông.$b$,false),
('bunong-vn','EXO',38,7,null,$b$Păng nsro mâng tung tâm trôm rvang ta bar đah pĭt nơng gay dŏng tung păng. Păng ƀư nơng trôm hŏng ma âk pŏk kađar.$b$,true),
('bunong-vn','EXO',38,8,null,$b$Păng ƀư thŭng dak jêh ri jâng păng ma kông nchrâng muh măt phung bu ur pah kan ta mpông lăp ngih bok nau tâm rƀŭn nhhơr jêh.$b$,true),
('bunong-vn','EXO',38,9,null,$b$Păng ƀư nkual ngih bok mơ pa rđŭng nkual geh bok ma mhay rhên, dĭ păng du rhiăng hăt.$b$,true),
('bunong-vn','EXO',38,10,null,$b$Meh păng geh bar jât mlâm, rnơl khân păng geh bar jât mlâm ƀư ma kông, nkuăk meh jêh ri rse rêt păng ƀư ma prăk.$b$,false),
('bunong-vn','EXO',38,11,null,$b$Mơ pa mpư̆ geh du rhiăng hăt, meh păng bar jât mlâm, rnơl khân păng bar jât mlâm ƀư ma kông nkuăk meh jêh ri rse rêt păng ƀư ma prăk.$b$,false),
('bunong-vn','EXO',38,12,null,$b$Mơ pa dâng nkual geh bok dĭ găn păng prăm jât hăt, meh păng geh jât mlâm, rnơl khân păng geh jât mlâm, nkuăk meh jêh ri rse rêt păng ƀư ma prăk.$b$,false),
('bunong-vn','EXO',38,13,null,$b$Mơ pa lơ nkual, rgăn prăm jât hăt.$b$,false),
('bunong-vn','EXO',38,14,null,$b$Bok pa đah mpông pêr geh jât ma prăm hăt, meh păng geh pe mlâm jêh ri rnơl khân păng geh pe mlâm.$b$,false),
('bunong-vn','EXO',38,15,null,$b$Jêh ri ta đah ri jêng tâm ban, đah aơ, đah rĭ mpông pêr nkual geh bok jât ma prăm hăt, meh păng geh pe mlâm jêh ri rnơl khân păng geh pe mlâm.$b$,false),
('bunong-vn','EXO',38,16,null,$b$Lĕ rngôch bok jŭm rvăch nkual bu ƀư ma mhay rhên.$b$,false),
('bunong-vn','EXO',38,17,null,$b$Rnơl ma meh bu ƀư ma kông, nkuăk meh jêh ri rse rêt păng bu ƀư ma prăk. Lĕ rngôch meh ntŭk nkual geh rse rêt ƀư ma prăk.$b$,false),
('bunong-vn','EXO',38,18,null,$b$Bok mphiar mpông pêr nkual jêng kan cheh ƀư ma bok piâk chăng krăk chăng rhưch, jêh ri mhay rhên. Jong păng geh bar jât hăt prêh jêh ri dĭ găn păng geh prăm hăt tĭng nâm bok nkual.$b$,false),
('bunong-vn','EXO',38,19,null,$b$Meh khân păng geh puăn mlâm, nđâp rnơl khân păng geh puăn mlâm ƀư ma kông, nkuăk khân păng ndơ mblum chiông khân păng, jêh ri rse rêt khân păng bu ƀư ma prăk.$b$,false),
('bunong-vn','EXO',38,20,null,$b$Lĕ rngôch n'gâng n'gar ngih bok jêh ri ma ntŭk nkual jŭm rvăch bu ƀư ma kông.$b$,false),
('bunong-vn','EXO',38,21,null,$b$Aơ rnoh kơp ndơ dŏng ma ngih bok, nâm bu ntĭt ngih bok ma nau mbơh, bu kơp jêh tĭng nâm nau Y-Môis ntăm, prăp ma kan phung Lêvi mât mray, tĭng nâm Y-Ithamar kon bu klâu Kôranh ƀư brah Y-Arôn gai.$b$,true),
('bunong-vn','EXO',38,22,null,$b$Y-Bêsalel kon bu klâu Y-Uri, kon bu klâu Y-Hur, bơh ndŭl mpôl Yuđa ƀư lĕ ndơ Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',38,23,null,$b$Nơm kơl păng jêng Y-Ôhôliap kon bu klâu Y-Ahisamak, bơh ndŭl mpôl Dan, nơm njêh blau kach, blau njêng ndơ mhe jêh ri blau cheh bok piâk, chăng krăk, chăng rhưch jêh ri mhay rhên.$b$,true),
('bunong-vn','EXO',38,24,null,$b$Lĕ rngôch mah dŏng jêh ma kan ƀư jrô kloh ueh, nâm bu ntĭt mah bu nhhơr, geh du rbăn pe rhiăng pe jât ma pe kilô tĭng nâm Sêkel bơh jrô kloh ueh.$b$,true),
('bunong-vn','EXO',38,25,null,$b$Prăk bơh phung bu kơp jêh tâm phung tâm rƀŭn geh puăn rbăn sĭn rhiăng bar jât ma sĭn kilô, tĭng nâm Sêkel bơh jrô kloh ueh.$b$,false),
('bunong-vn','EXO',38,26,null,$b$Pô nây jêng n'gul Sêkel ăp nơm tĭng nâm Sêkel bơh jrô kloh ueh, ma ăp nơm kon bu klâu bu kơp jêh ntơm bơh bar jât năm rlơ̆ klơ geh prao rhiăng ma pe rbăn prăm rhiăng prăm jât nuyh kon bu klâu.$b$,false),
('bunong-vn','EXO',38,27,null,$b$Puăn rbăn sĭn rhiăng kilô prăk dŏng prăk tŏ rnơl ma ntŭk kloh ueh, jêh ri rnơl ma bok mphiar, du rhiăng mlâm rnơl ma puăn rbăn sĭn rhiăng kilô, puăn rhiăng sĭn jât kilô ma du mlâm rnơl.$b$,false),
('bunong-vn','EXO',38,28,null,$b$Jêh ri ma bar jât ma sĭn kilô prăk păng ƀư nglĕ nkuăk ma meh, mblum chiông păng jêh ri ƀư rse rêt ma khân păng.$b$,false),
('bunong-vn','EXO',38,29,null,$b$Kông bu nhhơr geh pe rbăn puăn rhiăng prao jât ma sĭn kilô.$b$,true),
('bunong-vn','EXO',38,30,null,$b$Ma kông nây păng ƀư rnơl ma mpông lăp ngih bok nau tâm rƀŭn, nơng kông nđâp dreh păng jêh ri lĕ rngôch ndơ dŏng ma nơng,$b$,false),
('bunong-vn','EXO',38,31,null,$b$rnơl tâm nkual jŭm rvăch, rnơl ma mpông pêr nkual, jêh ri lĕ rngôch mâng n'gar ma ngih bok, nđâp mâng ntŭk nkual jŭm rvăch.$b$,false),
('bunong-vn','EXO',39,1,null,$b$Ma bok nhom dak piâk, chăng krăk, chăng rhưch khân păng ƀư bok ao ma nau njêh prăp ma kan tâm jrô kloh ueh; khân păng ƀư bok ao kloh ueh ma Y-Arôn tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,true),
('bunong-vn','EXO',39,2,null,$b$Păng ƀư ao êphôt ma mah, bok ĭr, chăng krăk, chăng bok sut, jêh ri mhay rhên.$b$,false),
('bunong-vn','EXO',39,3,null,$b$Bu chiăr du rlat mah n'hơ jêh ri koh ăn jêng brai, gay tanh ndrel ma bok ĭr, chăng krăk, sut chăng, jêh ri mhay rhên ma nau njêr n'hŭ.$b$,false),
('bunong-vn','EXO',39,4,null,$b$Khân păng ƀư bar blah bok nkŭm săng nglik ndop ndrel đah bar bôl ao êphôt.$b$,false),
('bunong-vn','EXO',39,5,null,$b$Rse vân bŭt bu tanh ma rse mhay ta ao êphôt gay rêt păng, khân păng ƀư tâm ban nâm bu ao jêh ri tâm krêp đah ao, bu ƀư păng ma mah, bok ĭr, chăng krăk, sut chăng, jêh ri mhay rhên tĭng nâm Yêhôva ntĭnh ma Y-Môis.$b$,false),
('bunong-vn','EXO',39,6,null,$b$Khân păng nkra lŭ ônik, tâm lĭr tâm năp ndor mah, nsêr nâm bu ndơ tâp pŏng, tĭng nâm amoh phung kon bu klâu Y-Israel.$b$,true),
('bunong-vn','EXO',39,7,null,$b$Khân păng dơm lĕ ndơ nây ta bok nkŭm săng nglik ao êphôt, jêng lŭ kah gĭt ma phung kon bu klâu Y-Israel, tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.$b$,true),
('bunong-vn','EXO',39,8,null,$b$Khân păng nkra njêng bok văn ntang ntơh ma rse mhay nâm bu ao êphôt ma mah, bok ĭr, chăng krăk, sut chăng, jêh ri mhay rhên.$b$,true),
('bunong-vn','EXO',39,9,null,$b$Bok ƀư ao tâm ban dĭ jong. Khân păng nkra njêng bok văn ntang ntơh ndop bar, jong du hăt n'gul, jêh ri dĭ păng du hăt n'gul.$b$,false),
('bunong-vn','EXO',39,10,null,$b$Khân păng tâm lĭr geh puăn grong lŭ khlay: Grong tal nguay, du găr sardôn, du găr tôpas, du găr êmêrôt;$b$,false),
('bunong-vn','EXO',39,11,null,$b$grong tal bar, du găr êskabuk, du găr saphir, du găr diamôn;$b$,false),
('bunong-vn','EXO',39,12,null,$b$grong tal pe, du găr ôpal, du găr agat, du găr amêtis;$b$,false),
('bunong-vn','EXO',39,13,null,$b$grong tal puăn, du găr bêril, du găr ônik, du găr jaspidi. Lŭ khlay nây bu lĭr tâm ndor năp mah.$b$,false),
('bunong-vn','EXO',39,14,null,$b$Geh jât ma bar găr tĭng nâm amoh phung kon bu klâu Y-Israel. Ăp ntil găr lŭ khlay bu geh nsêr du amoh tâm jât ma bar ndŭl mpôl Israel nâm bu bu nsêr ndơ tâp pŏng.$b$,false),
('bunong-vn','EXO',39,15,null,$b$Jêh ma nây, ta klơ bok văn ntang ntơh khân păng nkra njêng rse rvăk rhên ma mah chrêk, buănh nâm bu rse bu vah.$b$,true),
('bunong-vn','EXO',39,16,null,$b$Khân păng ƀư bar ndor năp ma mah, khân păng dơm bar mlâm rvang nây ta bar đah pĭt bok văn ntang ntơh.$b$,true),
('bunong-vn','EXO',39,17,null,$b$Khân păng nsro bar rtai (njăr) rse vah mah tâm bar mlâm rvang ta bar đah pĭt bok văn ntang ntơh.$b$,false),
('bunong-vn','EXO',39,18,null,$b$Khân păng kât bôl bar njăr rse vah pa năp bar rvang năp gŭ ta bok nkŭm săng nglik ao êphôt.$b$,false),
('bunong-vn','EXO',39,19,null,$b$Khân păng ƀư đŏng bar mlâm rvang mah, dơm khân păng ta bar đah pĭt bok văn ntang ntơh tâm trôm nkrêp đah ao êphôt.$b$,false),
('bunong-vn','EXO',39,20,null,$b$Khân păng ƀư tay bar mlâm rvang mah, dơm khân păng tâm nâm mpeh tâm dâng ta bok nkŭm săng nglik ao êphôt mpeh mơ pa năp êp ntŭk n'har tâm mâp ta klơ rse vân bŭt ao êphôt tanh ma nau njêh n'hŭ.$b$,false),
('bunong-vn','EXO',39,21,null,$b$Khân păng kât bok văn ntang ntơh ta rvang păng đah rvang ao êphôt ma rse vah ĭr, gay ma bok văn ntang ntơh gŭ ta klơ rse vân bŭt ao êphôt bu tanh ma nau njêh n'hŭ, gay ma bok văn ntang ntơh mâu rlât ôh bơh ao êphôt, tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.$b$,true),
('bunong-vn','EXO',39,22,null,$b$Păng ƀư ao jâr êphôt tanh ma bok ĭr da dê.$b$,true),
('bunong-vn','EXO',39,23,null,$b$Trôm ta nklang ao jâr păng bu khăt jŭm nâm bu trôm bu tăk gor ao loih, gay lơi ăn prek ôh.$b$,false),
('bunong-vn','EXO',39,24,null,$b$Khân păng ƀư jŭm bôl ao tâm dâng play pom gra nat ĭr, chăng krăk, sut chăng, jêh ri mhay rhên.$b$,false),
('bunong-vn','EXO',39,25,null,$b$Khân păng ƀư rlêm ma mah chrêk, jêh ri tâm nsrah đah play pom gra nat jŭm bôl ao tâm dâng,$b$,false),
('bunong-vn','EXO',39,26,null,$b$du găr rlêm mah jêh ri du găr play pom gra nat, du găr rlêm mah du găr play pom gra nat jŭm bôl ao prăp ma pah kan, tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',39,27,null,$b$Khân păng tanh ao jâr ma mhay rhên ma Y-Arôn jêh phung kon bu klâu păng,$b$,true),
('bunong-vn','EXO',39,28,null,$b$kưn ma mhay rhên, đon ma mhay rhên, jêh ri kho ma mhay rhên,$b$,false),
('bunong-vn','EXO',39,29,null,$b$jêh ri rse vân bŭt ma mhay rhên ĭr, chăng krăk, jêh ri sut chăng, cheh chiăk, tĭng nâm Yêhôva ntĭnh jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',39,30,null,$b$Khân păng ƀư ma mah chrêk du plơp kađar jê̆ đon hađăch kloh ueh. Khân păng tor ta nây tâm ban ma bu tor ndơ tâp pŏng: “PRĂP ĂN MA YÊHÔVA.”$b$,true),
('bunong-vn','EXO',39,31,null,$b$Bu kât păng ma du njăr rse vah piâk, gay kât păng ta năp môk kưn, tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',39,32,null,$b$Pô ri lôch jêh lĕ kan ƀư ngih bok nau tâm rƀŭn. Phung ƀon lan Israel ƀư lĕ jêh tĭng nâm nau Yêhôva ntăm ma Y-Môis.$b$,true),
('bunong-vn','EXO',39,33,null,$b$Khân păng njŭn ngih bok ma Y-Môis, ngih bok jêh ri lĕ rngôch ndơ nkăp, kađar, mâng nđăng, meh, jêh ri rnơl păng;$b$,true),
('bunong-vn','EXO',39,34,null,$b$ndơ nkŭm ma ntâu biăp nkuăng nkra jêh, jêh ri ndơ nkŭm ntâu ka toyh jêh ri bok nching;$b$,false),
('bunong-vn','EXO',39,35,null,$b$hip nau tâm rnglăp nđâp mâng tung păng jêh ri nđâp ntŭk yô̆ an;$b$,false),
('bunong-vn','EXO',39,36,null,$b$sưng jêh ri lĕ rngôch ndơ dŏng ma păng, jêh ri piăng let nhhơr ma Brah Ndu;$b$,false),
('bunong-vn','EXO',39,37,null,$b$jâng jrêng mah chrêk jêh ri nđâp ma ŭnh kađen păng, nâm bu ntĭt ŭnh kađen nây nkra jêh,$b$,false),
('bunong-vn','EXO',39,38,null,$b$ndơ dŏng ma păng jêh ri dak play Ôlivơ ma ŭnh kađen; nơng mah, dak ƀâu kah prăp tŏ, ndơ ƀâu kah, jêh ri bok mphiar ta mpông lăp ngih bok.$b$,false),
('bunong-vn','EXO',39,39,null,$b$Nơng kông nđâp ma dreh, kông tanh srang păng, mâng tung păng jêh ri lĕ rngôch ndơ dŏng ma păng; thŭng dak nđâp jâng păng;$b$,false),
('bunong-vn','EXO',39,40,null,$b$bok mbâl nching ta nkual, meh nđâp rnơl păng, jêh ri bok mphiar ta mpông pêr lăp nkual, rse vah, mâng n'gar jêh ri lĕ rngôch ndơ dŏng kan ma ngih bok, ma ngih bok nau tâm rƀŭn;$b$,false),
('bunong-vn','EXO',39,41,null,$b$bok ao ƀư ma nau njêh prăp ma kan tâm jrô kloh ueh, bok ao kloh ueh Kôranh ƀư brah Y-Arôn jêh ri bok ao ma phung kon bu klâu păng prăp ma kan phung Kôranh ƀư brah.$b$,false),
('bunong-vn','EXO',39,42,null,$b$Phung ƀon lan Israel ƀư lĕ rngôch kan nây tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,true),
('bunong-vn','EXO',39,43,null,$b$Y-Môis sek uănh lĕ rngôch kan, jêh ri aơ, khân păng ƀư jêh nau nây tĭng nâm Yêhôva ntăm jêh. Jêh ri tĭng nâm Yêhôva ntăm jêh. Jêh ri Y-Môis mât ton ma khân păng.$b$,true),
('bunong-vn','EXO',40,1,null,$b$Yêhôva lah ma Y-Môis:$b$,true),
('bunong-vn','EXO',40,2,null,$b$“Nar nguay tâm khay nguay, ăn may rdâk ngih bok nau tâm rƀŭn.$b$,false),
('bunong-vn','EXO',40,3,null,$b$Ăn may dơm ta nây hip nau tâm rnglăp, jêh ri pôn hip tâm bok nching.$b$,false),
('bunong-vn','EXO',40,4,null,$b$Ăn may njŭn sưng jêh ri nkra ăn di ndơ dơm ta klơ. Ăn may njŭn jâng jrêng jêh ri nkra ŭnh kađen.$b$,false),
('bunong-vn','EXO',40,5,null,$b$Ăn may dơm nơng mah gŭch mpa ƀâu kah ta năp hip nau tâm rnglăp, jêh ri nching bok nching ta mpông lăp ngih bok.$b$,false),
('bunong-vn','EXO',40,6,null,$b$Ăn may dơm nơng mpa nhhơr gŭch ta năp mpông lăp ngih bok nau tâm rƀŭn.$b$,false),
('bunong-vn','EXO',40,7,null,$b$Ăn may dơm thŭng dak vah vang ngih bok nau tâm rƀŭn đah nơng, jêh ri dơm dak tâm nây.$b$,false),
('bunong-vn','EXO',40,8,null,$b$Ăn may rdâk nkual rvăch jŭm, jêh ri nching bok nching ta mpông pêr nkual.$b$,false),
('bunong-vn','EXO',40,9,null,$b$Ăn may sŏk dak ƀâu kah prăp tŏ, jêh ri tŏ ngih bok jêh ri lĕ rngôch ndơ tâm păng. Ăn may prăp an păng nđâp lĕ rngôch ndơ dŏng ma păng, jêh ri păng mra jêng kloh ueh.$b$,false),
('bunong-vn','EXO',40,10,null,$b$Ăn may tŏ nơng nhhơr gŭch jêh ri lĕ rngôch ndơ dŏng ma păng, jêh ri prăp an nơng; jêh ri nơng mra jêng kloh ueh lơn.$b$,false),
('bunong-vn','EXO',40,11,null,$b$Ăn may tŏ dak ƀâu kah ta thŭng dak nđâp jâng păng, jêh ri prăp an păng.$b$,false),
('bunong-vn','EXO',40,12,null,$b$Jêh nau nây ăn may njŭn Y-Arôn nđâp phung kon bu klâu păng ma mpông ngih bok nau tâm rƀŭn, jêh ri sâm ŭm khân păng ma dak.$b$,false),
('bunong-vn','EXO',40,13,null,$b$Ăn may sâm nsoh Y-Arôn ma bok ao kloh ueh jêh ri tŏ dak ƀâu kah ta păng prăp an păng, gay ma păng dơi pah kan ma gâp jêng Kôranh ƀư brah.$b$,false),
('bunong-vn','EXO',40,14,null,$b$Ăn may njŭn phung kon bu klâu păng jêh ri may sâm nsoh an khân păng ma ao jâr.$b$,false),
('bunong-vn','EXO',40,15,null,$b$Jêh ri tŏ dak ƀâu kah ma khân păng, nâm bu may tŏ jêh ma mbơ̆ khân păng, gay ma khân păng dơi pah kan ma gâp jêng phung Kôranh ƀư brah. Nau tŏ dak ƀâu kah nây gay ƀư nanê̆ ma khân păng nau jêng Kôranh ƀư brah ƀa ƀơ tâm lĕ rngôch rnôk khân păng.$b$,false),
('bunong-vn','EXO',40,16,null,$b$Pô ri Y-Môis ƀư lĕ rngôch nau Yêhôva ntăm ma păng.$b$,true),
('bunong-vn','EXO',40,17,null,$b$Nar nguay tâm khay nguay năm bar khân păng ƀư jêh nau rdâk ngih bok.$b$,false),
('bunong-vn','EXO',40,18,null,$b$Y-Môis rdâk ngih bok; păng dơm rnơl păng, rdâk kađar păng, dơm mâng nđăng păng, jêh ri rdâk meh păng.$b$,false),
('bunong-vn','EXO',40,19,null,$b$Păng ling bok ta klơ ngih bok, jêh ri păng nkŭm bok ta klơ tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',40,20,null,$b$Păng sŏk kađar nau mbơh jêh ri dơm păng tâm hip, păng nsro mâng tung ta hip jêh ri dơm ndrŭp ntŭk yô̆ an ta klơ hip.$b$,false),
('bunong-vn','EXO',40,21,null,$b$Păng njŭn hip tâm ngih bok jêh ri nching bok nching pôn hip nau tâm rnglăp tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',40,22,null,$b$Păng dơm sưng tâm ngih bok nau tâm rƀŭn mơ pa mpư̆ ngih bok pa dih bok nching.$b$,false),
('bunong-vn','EXO',40,23,null,$b$Păng dăp piăng let di mbor ta năp Yêhôva tĭng nâm nau Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',40,24,null,$b$Păng dơm jâng jrêng tâm ngih bok nau tâm rƀŭn mơ đah sưng mơ pa rđŭng ngih bok,$b$,false),
('bunong-vn','EXO',40,25,null,$b$jêh ri păng nkra ŭnh kađen ta năp Yêhôva tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',40,26,null,$b$Păng dơm nơng mah tâm ngih bok nau tâm rƀŭn ta năp bok nching.$b$,false),
('bunong-vn','EXO',40,27,null,$b$Păng gŭch ta klơ nây mpa ƀâu kah tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',40,28,null,$b$Păng nching bok nching ta mpông lăp ngih bok.$b$,true),
('bunong-vn','EXO',40,29,null,$b$Păng dơm nơng mpa nhhơr gŭch ta mpông lăp ngih bok nau tâm rƀŭn jêh ri păng nhhơr ta klơ nây mpa nhhơr gŭch jêh ri ndơ nhhơr rnih muy tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',40,30,null,$b$Păng dơm thŭng dak ta vah vang ngih bok nau tâm rƀŭn jêh ri nơng, jêh ri păng nkhŭt dak ta nây prăp rao.$b$,false),
('bunong-vn','EXO',40,31,null,$b$Y-Môis, Y-Arôn jêh ri lĕ rngôch kon bu klâu păng rao jêng ti ta nây.$b$,false),
('bunong-vn','EXO',40,32,null,$b$Tơ lah khân păng lăp ngih bok nau tâm rƀŭn jêh ri tơ lah khân păng hăn dăch nơng, khân păng rao lơi, tĭng nâm Yêhôva ntăm jêh ma Y-Môis.$b$,false),
('bunong-vn','EXO',40,33,null,$b$Păng rdâk nkual jŭm rvăch ngih bok jêh ri nơng, jêh ri păng nching bok mpông lăp nkual. Pô ri Y-Môis ƀư lôch kan nây.$b$,false),
('bunong-vn','EXO',40,34,null,$b$Jêh ri ndâr nkŭm ngih bok nau tâm rƀŭn, jêh ri nau chrêk rmah Yêhôva ƀư bêng ngih bok.$b$,true),
('bunong-vn','EXO',40,35,null,$b$Y-Môis mâu dơi lăp ôh tâm ngih bok nau tâm rƀŭn, yor lah ndâr gŭ ta klơ, jêh ri nau chrêk rmah Yêhôva ƀư bêng ngih bok.$b$,false),
('bunong-vn','EXO',40,36,null,$b$Dôl lĕ nau khân păng sak nsong, tơ lah ndâr hao du bơh klơ ngih bok, phung ƀon lan Israel hăn pa năp.$b$,false),
('bunong-vn','EXO',40,37,null,$b$Ƀiă lah tơ lah ndâr mâu hao du ôh khân păng mâu hăn ôh kŏ tât nar ndâr hao du klơ.$b$,false),
('bunong-vn','EXO',40,38,null,$b$Yor lah dôl lĕ nar khân păng sak nsong ndâr Yêhôva gŭ ta klơ ngih bok dôl nar, jêh ri geh ŭnh tâm nây dôl măng, ta năp măt lĕ rngôch ngih Israel.$b$,false);
